  function createEducationDocumentTemplate(definition, index = 0) {
    const fields = definition.markers.map((name, fieldIndex) => ({
      id: `${definition.id}-field-${fieldIndex + 1}`,
      position: definition.fieldPositions?.[name] || fieldIndex + 1,
      name,
      formula: definition.formulas?.[name] || educationDocumentTemplateFieldFormulaMap[name] || "",
      hideEmpty: false,
      custom: true
    }));
    return {
      id: definition.id,
      title: definition.title,
      templateUrl: definition.templateUrl || "",
      templatePath: definition.templatePath,
      fileName: definition.fileName,
      fileNameTemplate: definition.fileNameTemplate,
      saveFolderTemplate: definition.saveFolderTemplate || studentDocumentsFolderTemplateMarker,
      generationFormat: normalizeDocumentGenerationFormat(definition.generationFormat),
      generationFormatVersion: String(definition.generationFormatVersion || ""),
      useCustomDocumentProperties: "1",
      fields,
      originalFields: fields.map((field) => ({ ...field })),
      fieldsMode: "document-markers",
      source: definition.templateUrl ? "link" : "file",
      documentKind: definition.documentKind || "education",
      programTypes: definition.programTypes || [],
      createdAt: "2026-06-20T00:00:00.000Z",
      lastInspectedSignature: "",
      updatedAt: ""
    };
  }

