  function getDefaultDocumentTemplates() {
    return [
      createDefaultDocumentTemplate(),
      createLegalEntityApplicationDocumentTemplate(),
      ...employeeContractDocumentTemplates.map(createEmployeeContractDocumentTemplate),
      createEmployeeActDocumentTemplate(),
      ...educationDocumentTemplateDefinitions.map(createEducationDocumentTemplate),
      createEducationDocumentTemplate(studyCertificateDocumentTemplateDefinition, educationDocumentTemplateDefinitions.length),
      createEducationDocumentTemplate(postalEnvelopeDocumentTemplateDefinition, educationDocumentTemplateDefinitions.length + 1),
      ...orderDocumentTemplateDefinitions.map((definition, index) => (
        createEducationDocumentTemplate(definition, educationDocumentTemplateDefinitions.length + index + 2)
      ))
    ];
  }

  function getDefaultDocumentSaveFolderTemplate(documentTemplate = {}) {
    const configured = String(documentTemplate?.saveFolderTemplate || "").trim();
    const templateId = String(documentTemplate?.id || "").trim();
    const documentKind = String(documentTemplate?.documentKind || "").trim();
    const programTypes = Array.isArray(documentTemplate?.programTypes)
      ? documentTemplate.programTypes.map((value) => normalizeEducationProgramType(value))
      : [];
    if (
      (templateId === "education-document-diploma-ppp"
        || (documentKind === "education" && programTypes.includes("ППП")))
      && /^(?:АИС Допобразование[\\/]+Документы[\\/]+)?Дипломы ПП$/iu.test(configured)
    ) {
      return "Документы/Дипломы ПП";
    }
    if (
      (templateId === "education-document-certificate-kpk"
        || (documentKind === "education" && programTypes.includes("КПК")))
      && /^(?:АИС Допобразование[\\/]+Документы[\\/]+)?Удостоверения ПК$/iu.test(configured)
    ) {
      return "Документы/Удостоверения ПК";
    }
    if (
      (templateId === "education-document-certificate-dop-pro"
        || (documentKind === "education"
          && (programTypes.includes("ПРО") || programTypes.includes("ДОП"))))
      && /^(?:АИС Допобразование[\\/]+Документы[\\/]+)?Сертификаты мероприятия$/iu.test(configured)
    ) {
      return "Документы/Сертификаты мероприятия";
    }
    if (
      (templateId === postalEnvelopeDocumentTemplateId || documentKind === "postalEnvelope")
      && configured === studentDocumentsFolderTemplateMarker
    ) {
      return downloadsFolderTemplateMarker;
    }
    if (
      (templateId === "document-enrollment-order" || documentKind === "enrollmentOrder")
      && /^Документы[\\/]Приказы на зачисление$/iu.test(configured)
    ) {
      return "Документы/Приказы о зачислении";
    }
    if (configured) return configured;
    const defaultsById = {
      [postalEnvelopeDocumentTemplateId]: downloadsFolderTemplateMarker,
      "document-enrollment-order": "Документы/Приказы о зачислении",
      "document-expulsion-order": "Документы/Приказы об отчислении",
      "education-document-diploma-ppp": "Документы/Дипломы ПП",
      "education-document-certificate-kpk": "Документы/Удостоверения ПК",
      "education-document-certificate-dop-pro": "Документы/Сертификаты мероприятия"
    };
    if (defaultsById[templateId]) return defaultsById[templateId];
    if (documentKind === "postalEnvelope") return downloadsFolderTemplateMarker;
    if (documentKind === "enrollmentOrder") return "Документы/Приказы о зачислении";
    if (documentKind === "expulsionOrder") return "Документы/Приказы об отчислении";
    if (documentKind === "education") {
      if (programTypes.includes("ППП")) return "Документы/Дипломы ПП";
      if (programTypes.includes("КПК")) return "Документы/Удостоверения ПК";
      if (programTypes.includes("ПРО") || programTypes.includes("ДОП")) return "Документы/Сертификаты мероприятия";
    }
    return studentDocumentsFolderTemplateMarker;
  }

  function normalizeDocumentGenerationFormat(value) {
    return String(value || "").trim().toLowerCase() === "docx" ? "docx" : "pdf";
  }

  function getDefaultDocumentEmailDeliveryMode(documentTemplate = {}) {
    const documentKind = String(documentTemplate?.documentKind || "").trim();
    return documentKind === "contract" || documentKind === "education" ? "student" : "off";
  }

  function normalizeDocumentEmailDeliveryMode(value, documentTemplate = {}) {
    const mode = String(value || "").trim().toLowerCase();
    return ["off", "student", "system"].includes(mode)
      ? mode
      : getDefaultDocumentEmailDeliveryMode(documentTemplate);
  }

  function normalizeDocumentEmailTemplateValues(value) {
    if (!value || typeof value !== "object" || Array.isArray(value)) return {};
    return Object.fromEntries(
      Object.entries(value)
        .map(([name, templateValue]) => [
          String(name || "").replace(/^\[|\]$/g, "").trim(),
          String(templateValue ?? "")
        ])
        .filter(([name]) => name)
    );
  }

  function getDefaultDocumentEmailSubjectTemplate(documentTemplate = {}) {
    const documentKind = String(documentTemplate?.documentKind || "").trim();
    if (documentKind === "contract") return "Договор на обучение: #ФИО_обуч#";
    if (documentKind === "education") return "Документ об образовании: #ФИО#";
    if (documentKind === "employeeContract") return "Договор: #ФИО#";
    if (documentKind === "employeeAct") return "Акт от ООО Цифровизация Плюс";
    return "";
  }

  function getDefaultDocumentEmailMessageTemplate(documentTemplate = {}) {
    const documentKind = String(documentTemplate?.documentKind || "").trim();
    if (documentKind === "contract") {
      return "Направляем договор на обучение.\n\nС уважением,\nООО «Цифровизация Плюс»";
    }
    if (documentKind === "education") {
      return "Направляем документ об образовании.\n\nС уважением,\nООО «Цифровизация Плюс»";
    }
    if (documentKind === "employeeContract") {
      return "#ИО#, здравствуйте!\n\nНаправляем Вам договор. Проверьте его, пожалуйста, подпишите и отправьте в ответном письме.\n\nС уважением,\nООО «Цифровизация Плюс»";
    }
    if (documentKind === "employeeAct") {
      return "#ИО#, здравствуйте!\n\nОтправляем Вам на подпись акт об оказанных услугах на дату #ТекДата#.\n\nПроверьте его, пожалуйста. Если всё в порядке, подпишите и отправьте в ответном письме.\n\nС уважением,\nООО «Цифровизация Плюс»";
    }
    return "";
  }

