      sharedStatePendingCount ? `Ожидают выгрузки: ${sharedStatePendingCount}` : "",
      sharedStateUpdatedBy ? `Последнее изменение: ${sharedStateUpdatedBy}` : "",
      sharedStateUpdatedAt ? formatDateTimeRu(sharedStateUpdatedAt) : ""
