  function fitMainRegistryTablesToViewport() {
    const viewport = window.visualViewport;
    const viewportHeight = Math.max(0, Number(viewport?.height) || window.innerHeight || document.documentElement.clientHeight);
    const viewportBottom = (Number(viewport?.offsetTop) || 0) + viewportHeight;
    document.querySelectorAll("[data-main-registry]").forEach((registry) => {
      const tableWrap = registry.querySelector(".table-wrap");
      if (!tableWrap) return;
      const tableTop = tableWrap.getBoundingClientRect().top;
      const tableSiblings = Array.from(tableWrap.parentElement?.children || []);
      const followingHeight = tableSiblings
        .slice(tableSiblings.indexOf(tableWrap) + 1)
        .reduce((height, element) => {
          const style = window.getComputedStyle(element);
          if (style.display === "none" || ["absolute", "fixed"].includes(style.position)) return height;
          return height
            + element.getBoundingClientRect().height
            + (Number.parseFloat(style.marginTop) || 0)
            + (Number.parseFloat(style.marginBottom) || 0);
        }, 0);
      const registryStyle = window.getComputedStyle(registry);
      const bottomPadding = Number.parseFloat(registryStyle.paddingBottom) || 0;
      const availableHeight = Math.floor(viewportBottom - tableTop - followingHeight - bottomPadding - 10);
      tableWrap.style.setProperty("--registry-table-max-height", `${Math.max(108, availableHeight)}px`);
    });
  }

  function scheduleMainRegistryTableViewportFit() {
    if (mainRegistryViewportFitFrame) window.cancelAnimationFrame(mainRegistryViewportFitFrame);
    mainRegistryViewportFitFrame = window.requestAnimationFrame(() => {
      mainRegistryViewportFitFrame = 0;
      fitMainRegistryTablesToViewport();
    });
  }

  function focusPendingContractTemplateField() {
    const fieldId = state.pendingContractTemplateFieldFocus;
    if (!fieldId) return;
    state.pendingContractTemplateFieldFocus = "";
    window.setTimeout(() => {
      const button = document.querySelector(`.contract-template-document-fields-panel [data-action='select-contract-document-token'][data-contract-field-id="${CSS.escape(fieldId)}"]`);
      if (!button) return;
      button.focus({ preventScroll: true });
      button.scrollIntoView({ block: "nearest", inline: "nearest" });
    });
  }

  function renderView() {
    if (!canAccessView(state.view)) return renderDashboard();
    if (state.view === "dashboard") return renderDashboard();
    if (state.view === "statistics") return renderStatistics();
    if (state.view === "issuedDocuments") return renderIssuedDocumentsRegistry();
    if (state.view === "documentConstructor") return renderDocumentConstructor();
    if (state.view === "settings") return renderSettings();
    if (state.view === "admin") return renderAdmin();
    const config = configs[state.view];
    if (!config) {
      state.view = "dashboard";
      return renderDashboard();
    }
    return renderCollection(config);
  }

  function statisticsDateParts(value) {
    const timestamp = parseTableSortDate(value);
    if (timestamp === null) return null;
    const date = new Date(timestamp);
    return {
      year: String(date.getUTCFullYear()),
      month: String(date.getUTCMonth() + 1).padStart(2, "0"),
      key: `${date.getUTCFullYear()}-${String(date.getUTCMonth() + 1).padStart(2, "0")}`
    };
  }

  function getStatisticsFinanceRows() {
    const studentsById = new Map((state.data.collections.students || [])
      .map((student) => [String(student.id || ""), student]));
    const enrichStudentRow = (row) => {
      const student = studentsById.get(String(row.sourceId || "")) || null;
      return {
        ...row,
        program: String(student?.program || row.context || "Не задано").trim() || "Не задано",
        source: String(student?.source || "Не задано").trim() || "Не задано",
        studentId: String(student?.id || row.sourceId || ""),
        studentUid: String(student?.uid || row.uid || "")
      };
    };
    const income = getFinanceReceiptRows().map(enrichStudentRow);
    const direct = getFinanceDirectExpenseRows().map((row) => {
      const enriched = enrichStudentRow(row);
      return {
        ...enriched,
        expenseGroup: "Прямые затраты",
        expenseType: String(row.context || "Не задано").trim() || "Не задано"
      };
    });
    const general = getFinanceGeneralExpenseRows().map((row) => ({
      ...row,
      program: "",
      source: "",
      studentId: "",
      studentUid: "",
      expenseGroup: "Общие затраты",
      expenseType: String(row.context || "Не задано").trim() || "Не задано"
    }));
    return { income, direct, general };
  }

  function statisticsRowMatches(row, options = {}) {
    const filters = state.statistics.filters;
    const date = statisticsDateParts(row.date);
    if (filters.year && date?.year !== filters.year) return false;
    if (filters.month && date?.month !== filters.month) return false;
    if (filters.program && row.program !== filters.program) return false;
    if (filters.source && row.source !== filters.source) return false;
    if (options.expense && filters.expenseType && row.expenseType !== filters.expenseType) return false;
    const query = String(filters.query || "").trim().toLocaleLowerCase("ru-RU");
    if (options.query && query) {
      const haystack = [
        row.date, row.category, row.uid, row.subject, row.context, row.description,
        row.program, row.source, row.expenseGroup, row.expenseType, row.amount
      ].join(" ").toLocaleLowerCase("ru-RU");
      if (!haystack.includes(query)) return false;
    }
    return true;
  }

  function formatStatisticsInteger(value) {
    return new Intl.NumberFormat("ru-RU", { maximumFractionDigits: 0 }).format(Number(value) || 0);
  }

  function statisticsMonthLabel(key) {
    const [year, month] = String(key || "").split("-").map(Number);
    if (!year || !month) return key || "—";
    return new Intl.DateTimeFormat("ru-RU", { month: "short", year: "2-digit", timeZone: "UTC" })
      .format(new Date(Date.UTC(year, month - 1, 1)))
      .replace(" г.", "");
  }

  function sortStatisticsMonthSeries(series = [], limit = 24) {
    const sorted = series
      .slice()
      .sort((left, right) => String(right?.key || "").localeCompare(String(left?.key || "")));
    const normalizedLimit = Math.max(0, Math.floor(Number(limit) || 0));
    return normalizedLimit ? sorted.slice(0, normalizedLimit) : sorted;
  }

  function buildStatisticsMonthlySeries(incomeRows = [], expenseRows = []) {
    const grouped = new Map();
    const ensure = (key) => {
      if (!grouped.has(key)) grouped.set(key, { key, income: 0, direct: 0, general: 0, expenses: 0 });
      return grouped.get(key);
    };
    incomeRows.forEach((row) => {
      const key = statisticsDateParts(row.date)?.key;
      if (key) ensure(key).income += Number(row.amount || 0);
    });
    expenseRows.forEach((row) => {
      const key = statisticsDateParts(row.date)?.key;
      if (!key) return;
      const item = ensure(key);
      const amount = Math.abs(Number(row.amount || 0));
      if (row.expenseGroup === "Общие затраты") item.general += amount;
      else item.direct += amount;
      item.expenses += amount;
    });
    const result = [...grouped.values()]
      .map((item) => ({ ...item, label: statisticsMonthLabel(item.key) }));
    return sortStatisticsMonthSeries(result, state.statistics.filters.year ? 12 : 24);
  }

  function renderStatisticsKpis(items = []) {
    return `
      <div class="statistics-kpi-grid ${items.length > 4 ? "is-dense" : ""}">
        ${items.map((item) => `
          <article class="statistics-kpi-card tone-${escapeAttr(item.tone || "teal")}">
            <span>${escapeHtml(item.label)}</span>
            <strong>${escapeHtml(item.value)}</strong>
            ${item.note ? `<small>${escapeHtml(item.note)}</small>` : ""}
          </article>
        `).join("")}
      </div>
    `;
  }

  function renderStatisticsSeriesChart(series = [], metrics = [], options = {}) {
    if (!series.length || !metrics.length) {
      return `<div class="empty-state compact"><span>Нет данных для выбранного периода.</span></div>`;
    }
    const maxValue = Math.max(
      ...series.flatMap((item) => metrics.map((metric) => Math.abs(Number(item[metric.key] || 0)))),
      1
    );
    const valueLabel = (value) => options.money
      ? formatStatisticsInteger(Number(value || 0) / 1000)
      : formatStatisticsInteger(value);
    return `
      <div class="statistics-chart">
        <div class="statistics-chart-scroll">
          <div class="statistics-chart-columns" style="--statistics-series-count:${Math.max(1, series.length)}">
            ${series.map((item) => `
              <div class="statistics-chart-period">
                <div class="statistics-chart-bars" style="grid-template-columns:repeat(${metrics.length}, minmax(16px, 1fr))">
                  ${metrics.map((metric) => {
                    const value = Number(item[metric.key] || 0);
                    const height = value ? Math.max(4, (Math.abs(value) / maxValue) * 100) : 0;
                    return `
                      <span class="statistics-chart-bar-column" style="--statistics-bar-height:${height}%" title="${escapeAttr(`${metric.label}: ${options.money ? money(value) : formatStatisticsInteger(value)}`)}">
                        <span class="statistics-chart-bar-area">
                          <small>${escapeHtml(valueLabel(value))}</small>
                          <i class="tone-${escapeAttr(metric.tone)}" style="height:${height}%"></i>
                        </span>
                      </span>
                    `;
                  }).join("")}
                </div>
                <span>${escapeHtml(item.label || statisticsMonthLabel(item.key))}</span>
              </div>
            `).join("")}
          </div>
        </div>
        <div class="statistics-chart-legend">
          ${metrics.map((metric) => `<span><i class="tone-${escapeAttr(metric.tone)}"></i>${escapeHtml(metric.label)}</span>`).join("")}
        </div>
      </div>
    `;
  }

  function renderStatisticsInstallDownloadChart(series = [], metrics = []) {
    if (!series.length || !metrics.length) {
      return `<div class="empty-state compact"><span>Нет данных для выбранного периода.</span></div>`;
    }
    const orderedSeries = sortStatisticsMonthSeries(
      series,
      state.statistics.filters.year ? 12 : 24
    );
    const maxValue = Math.max(
      ...orderedSeries.flatMap((item) => metrics.map((metric) => Math.max(0, Number(item[metric.key] || 0)))),
      1
    );
    return `
      <div class="statistics-comparison-chart">
        <div class="statistics-comparison-chart-main">
          <div class="statistics-chart-legend statistics-comparison-chart-legend" aria-label="Показатели графика">
            <strong>Действие</strong>
            ${metrics.map((metric) => `<span><i class="tone-${escapeAttr(metric.tone)}"></i>${escapeHtml(metric.label)}</span>`).join("")}
          </div>
          <div class="statistics-comparison-chart-scroll">
            <div class="statistics-comparison-chart-periods" style="--statistics-series-count:${Math.max(1, orderedSeries.length)}">
              ${orderedSeries.map((item) => `
                <div class="statistics-comparison-chart-period">
                  <div class="statistics-comparison-chart-bars" style="grid-template-columns:repeat(${metrics.length}, minmax(13px, 1fr))">
                    ${metrics.map((metric) => {
                      const value = Math.max(0, Number(item[metric.key] || 0));
                      const height = value ? Math.max(4, (value / maxValue) * 100) : 0;
                      const valueText = formatStatisticsInteger(value);
                      return `
                        <span class="statistics-comparison-bar-column" title="${escapeAttr(`${metric.label}: ${valueText}`)}">
                          <small>${value ? escapeHtml(valueText) : ""}</small>
                          <span class="statistics-comparison-bar-area">
                            <i class="tone-${escapeAttr(metric.tone)}" style="height:${height}%"></i>
                          </span>
                        </span>
                      `;
                    }).join("")}
                  </div>
                  <span>${escapeHtml(item.label || statisticsMonthLabel(item.key))}</span>
                </div>
              `).join("")}
            </div>
          </div>
        </div>
        <aside class="statistics-comparison-totals" aria-label="Итоги выбранного периода">
          ${metrics.map((metric) => `
            <div class="statistics-comparison-total tone-${escapeAttr(metric.tone)}">
              <span>${escapeHtml(metric.label)}</span>
              <strong>${escapeHtml(formatStatisticsInteger(metric.total))}</strong>
            </div>
          `).join("")}
        </aside>
      </div>
    `;
  }

  function renderStatisticsLocationChart(series = [], totals = {}) {
    const orderedSeries = [...series]
      .filter((item) => Number(item.installs || 0) > 0 || Number(item.removals || 0) > 0)
      .sort((left, right) => (
        Number(right.installs || 0) - Number(left.installs || 0)
        || Number(right.removals || 0) - Number(left.removals || 0)
        || String(left.label || "").localeCompare(String(right.label || ""), "ru", { sensitivity: "base" })
      ));
    if (!orderedSeries.length) {
      return `<div class="empty-state compact"><span>Нет данных по городам для выбранного периода.</span></div>`;
    }
    const visibleSeries = orderedSeries.slice(0, 30);
    const maxValue = Math.max(
      ...visibleSeries.flatMap((item) => [Number(item.installs || 0), Number(item.removals || 0)]),
      1
    );
    const barHeight = (value) => value ? Math.max(3, Math.round((Number(value) / maxValue) * 185)) : 0;
    const negativeAreaHeight = Math.max(
      62,
      barHeight(Math.max(...visibleSeries.map((item) => Number(item.removals || 0)), 0)) + 18
    );
    return `
      <div class="statistics-location-chart">
        <div class="statistics-location-chart-main">
          <div class="statistics-chart-legend statistics-comparison-chart-legend" aria-label="Показатели графика">
            <strong>Действие</strong>
            <span><i></i>Установки</span>
            <span><i class="tone-red"></i>Удаления</span>
            ${orderedSeries.length > visibleSeries.length ? `<small>Показано ${visibleSeries.length} из ${orderedSeries.length} городов</small>` : ""}
          </div>
          <div class="statistics-location-chart-scroll">
            <div class="statistics-location-chart-periods" style="--statistics-location-count:${Math.max(1, visibleSeries.length)};--statistics-negative-height:${negativeAreaHeight}px">
              ${visibleSeries.map((item) => {
                const installs = Math.max(0, Number(item.installs || 0));
                const removals = Math.max(0, Number(item.removals || 0));
                const installHeight = barHeight(installs);
                const removalHeight = barHeight(removals);
                return `
                  <div class="statistics-location-chart-period" title="${escapeAttr(`${item.label}: установки ${formatStatisticsInteger(installs)}, удаления ${formatStatisticsInteger(removals)}`)}">
                    <div class="statistics-location-positive">
                      ${installs ? `<small>${escapeHtml(formatStatisticsInteger(installs))}</small>` : ""}
                      <i style="height:${installHeight}px"></i>
                    </div>
                    <span class="statistics-location-baseline" aria-hidden="true"></span>
                    <div class="statistics-location-negative">
                      <i style="height:${removalHeight}px"></i>
                      ${removals ? `<small>${escapeHtml(formatStatisticsInteger(removals))}</small>` : ""}
                    </div>
                    <span class="statistics-location-label">${escapeHtml(item.label)}</span>
                  </div>
                `;
              }).join("")}
            </div>
          </div>
        </div>
        <aside class="statistics-comparison-totals" aria-label="Итоги выбранного периода">
          <div class="statistics-comparison-total"><span>Установки</span><strong>${escapeHtml(formatStatisticsInteger(totals.installs))}</strong></div>
          <div class="statistics-comparison-total tone-red"><span>Удаления</span><strong>${escapeHtml(formatStatisticsInteger(totals.removals))}</strong></div>
        </aside>
      </div>
    `;
  }

  function compactStatisticsItems(items = [], limit = 7) {
    const sorted = items
      .filter((item) => Number(item.value) > 0)
      .sort((left, right) => Number(right.value) - Number(left.value));
    if (sorted.length <= limit) return sorted;
    const visible = sorted.slice(0, Math.max(1, limit - 1));
    visible.push({
      label: "Прочие",
      value: sorted.slice(Math.max(1, limit - 1)).reduce((sum, item) => sum + Number(item.value || 0), 0)
    });
    return visible;
  }

  function renderStatisticsDonut(title, items = [], options = {}) {
    const compact = compactStatisticsItems(items, options.limit || 7);
    const total = compact.reduce((sum, item) => sum + Number(item.value || 0), 0);
    if (!total) return `<div class="empty-state compact"><span>Нет данных для диаграммы.</span></div>`;
    const colors = ["#158070", "#2f6fed", "#e4a11b", "#c84c4c", "#7b61c9", "#3e9b45", "#64748b"];
    let cursor = 0;
    const segments = compact.map((item, index) => {
      const start = cursor;
      cursor += (Number(item.value) / total) * 100;
      return `${colors[index % colors.length]} ${start.toFixed(2)}% ${cursor.toFixed(2)}%`;
    }).join(",");
    const formatValue = options.money ? money : formatStatisticsInteger;
    return `
      <div class="statistics-donut-layout">
        <div class="statistics-donut" style="background:conic-gradient(${segments})" role="img" aria-label="${escapeAttr(title)}">
          <span><strong>${escapeHtml(formatValue(total))}</strong><small>всего</small></span>
        </div>
        <div class="statistics-donut-legend">
          ${compact.map((item, index) => `
            <span title="${escapeAttr(item.label)}"><i style="background:${colors[index % colors.length]}"></i><b>${escapeHtml(item.label)}</b><em>${escapeHtml(formatValue(item.value))}</em></span>
          `).join("")}
        </div>
      </div>
    `;
  }

  function renderStatisticsRanking(items = [], options = {}) {
    const rows = items
      .filter((item) => Number(item.value) > 0)
      .sort((left, right) => Number(right.value) - Number(left.value))
      .slice(0, options.limit || 12);
    if (!rows.length) return `<div class="empty-state compact"><span>Нет данных для выбранного периода.</span></div>`;
    const max = Math.max(...rows.map((item) => Number(item.value || 0)), 1);
    const formatValue = options.money ? money : formatStatisticsInteger;
    return `
      <div class="statistics-ranking">
        ${rows.map((item) => `
          <div class="statistics-ranking-row" title="${escapeAttr(item.label)}">
            <span>${escapeHtml(item.label)}</span>
            <span class="statistics-ranking-track"><i style="width:${Math.max(3, (Number(item.value) / max) * 100)}%"></i></span>
            <strong>${escapeHtml(formatValue(item.value))}</strong>
          </div>
        `).join("")}
      </div>
    `;
  }

  function calculateStatisticsSalesProfitability(incomeTotal, expenseTotal) {
    const income = Number(incomeTotal);
    const expenses = Number(expenseTotal);
    if (!Number.isFinite(income) || income <= 0) return null;
    const normalizedExpenses = Number.isFinite(expenses) ? expenses : 0;
    return Math.round(((income - normalizedExpenses) / income) * 1000) / 10;
  }

  function buildStatisticsIncomeReport() {
    const finance = getStatisticsFinanceRows();
    const income = finance.income.filter((row) => statisticsRowMatches(row));
    const expenses = [...finance.direct, ...finance.general]
      .filter((row) => statisticsRowMatches(row, { expense: false }));
    const incomeTotal = income.reduce((sum, row) => sum + Number(row.amount || 0), 0);
    const expenseTotal = expenses.reduce((sum, row) => sum + Math.abs(Number(row.amount || 0)), 0);
    const profit = incomeTotal - expenseTotal;
    const studentIds = new Set(income.map((row) => row.studentId || row.studentUid || row.subject).filter(Boolean));
    const sourceStudents = new Map();
    income.forEach((row) => {
      const source = row.source || "Не задано";
      if (!sourceStudents.has(source)) sourceStudents.set(source, new Set());
      sourceStudents.get(source).add(row.studentId || row.studentUid || row.subject || row.id);
    });
    const programs = new Map();
    income.forEach((row) => {
      const name = row.program || "Не задано";
      if (!programs.has(name)) programs.set(name, { program: name, income: 0, students: new Set() });
      const item = programs.get(name);
      item.income += Number(row.amount || 0);
      item.students.add(row.studentId || row.studentUid || row.subject || row.id);
    });
    return {
      income,
      expenses,
      incomeTotal,
      expenseTotal,
      profit,
      salesProfitability: calculateStatisticsSalesProfitability(incomeTotal, expenseTotal),
      studentCount: studentIds.size,
      monthly: buildStatisticsMonthlySeries(income, expenses),
      sources: [...sourceStudents.entries()].map(([label, values]) => ({ label, value: values.size })),
      programs: [...programs.values()]
        .map((item) => ({ program: item.program, students: item.students.size, income: item.income }))
        .sort((left, right) => right.income - left.income)
    };
  }

  function renderStatisticsIncome() {
    const report = buildStatisticsIncomeReport();
    return `
      ${renderStatisticsKpis([
        { label: "Суммарные доходы", value: money(report.incomeTotal), note: "Фактические поступления", tone: "teal" },
        { label: "Количество слушателей", value: formatStatisticsInteger(report.studentCount), note: "С поступлениями в периоде", tone: "blue" },
        { label: "Суммарные затраты", value: money(report.expenseTotal), note: "Прямые и общие", tone: "amber" },
        { label: "Финансовый результат", value: money(report.profit), note: "Доходы за вычетом затрат", tone: report.profit < 0 ? "red" : "green" },
        {
          label: "Средняя рентабельность продаж",
          value: report.salesProfitability === null ? "—" : percent(report.salesProfitability),
          note: "Прибыль / фактические поступления",
          tone: report.salesProfitability === null ? "blue" : (report.salesProfitability < 0 ? "red" : "green")
        }
      ])}
      <div class="statistics-two-column">
        <section class="panel statistics-visual-panel statistics-wide-panel">
          <div class="panel-head"><div><p class="eyebrow">Динамика</p><h2>Доходы и затраты по месяцам, тыс. руб.</h2></div></div>
          ${renderStatisticsSeriesChart(report.monthly, [
            { key: "income", label: "Доходы", tone: "teal" },
            { key: "direct", label: "Прямые затраты", tone: "red" },
            { key: "general", label: "Общие затраты", tone: "amber" }
          ], { money: true })}
        </section>
        <section class="panel statistics-visual-panel">
          <div class="panel-head"><div><p class="eyebrow">Клиенты</p><h2>Источники заявок</h2></div></div>
          ${renderStatisticsDonut("Источники заявок", report.sources)}
        </section>
      </div>
      <section class="panel statistics-table-panel">
        <div class="panel-head"><div><p class="eyebrow">Программы</p><h2>Доходы по программам</h2></div><span class="statistics-row-count">${report.programs.length}</span></div>
        ${report.programs.length ? `
          <div class="table-wrap statistics-table-wrap">
            <table class="data-table statistics-table">
              <thead><tr><th>Программа</th><th>Слушателей</th><th class="statistics-number-cell">Доход</th></tr></thead>
              <tbody>${report.programs.map((row) => `
                <tr><td>${escapeHtml(row.program)}</td><td>${formatStatisticsInteger(row.students)}</td><td class="statistics-number-cell">${money(row.income)}</td></tr>
              `).join("")}</tbody>
            </table>
          </div>
        ` : `<div class="empty-state compact"><span>Нет поступлений для выбранных условий.</span></div>`}
      </section>
    `;
  }

  function buildStatisticsExpenseReport() {
    const finance = getStatisticsFinanceRows();
    const rows = [...finance.direct, ...finance.general]
      .filter((row) => statisticsRowMatches(row, { expense: true, query: true }))
      .sort((left, right) => (parseTableSortDate(right.date) || 0) - (parseTableSortDate(left.date) || 0));
    const direct = rows.filter((row) => row.expenseGroup === "Прямые затраты");
    const general = rows.filter((row) => row.expenseGroup === "Общие затраты");
    const total = rows.reduce((sum, row) => sum + Math.abs(Number(row.amount || 0)), 0);
    const groupBy = (key) => {
      const grouped = new Map();
      rows.forEach((row) => {
        const label = String(row[key] || "Не задано").trim() || "Не задано";
        grouped.set(label, (grouped.get(label) || 0) + Math.abs(Number(row.amount || 0)));
      });
      return [...grouped.entries()].map(([label, value]) => ({ label, value }));
    };
    return {
      rows,
      directTotal: direct.reduce((sum, row) => sum + Math.abs(Number(row.amount || 0)), 0),
      generalTotal: general.reduce((sum, row) => sum + Math.abs(Number(row.amount || 0)), 0),
      total,
      categories: groupBy("expenseType"),
      counterparties: groupBy("subject"),
      monthly: buildStatisticsMonthlySeries([], rows)
    };
  }

  function renderStatisticsExpenses() {
    const report = buildStatisticsExpenseReport();
    const pagination = getTablePagination("statisticsExpenses", report.rows.length);
    const pageRows = report.rows.slice(pagination.start, pagination.end);
    return `
      ${renderStatisticsKpis([
        { label: "Всего затрат", value: money(report.total), note: `${formatStatisticsInteger(report.rows.length)} операций`, tone: "red" },
        { label: "Прямые затраты", value: money(report.directTotal), note: "По слушателям и программам", tone: "amber" },
        { label: "Общие затраты", value: money(report.generalTotal), note: "Физлица и организации", tone: "blue" },
        { label: "Средняя операция", value: money(report.rows.length ? report.total / report.rows.length : 0), note: "В выбранном периоде", tone: "teal" }
      ])}
      <div class="statistics-two-column">
        <section class="panel statistics-visual-panel">
          <div class="panel-head"><div><p class="eyebrow">Структура</p><h2>Виды затрат</h2></div></div>
          ${renderStatisticsRanking(report.categories, { money: true, limit: 10 })}
        </section>
        <section class="panel statistics-visual-panel">
          <div class="panel-head"><div><p class="eyebrow">Контрагенты</p><h2>Крупнейшие получатели</h2></div></div>
          ${renderStatisticsRanking(report.counterparties, { money: true, limit: 10 })}
        </section>
      </div>
      <section class="panel statistics-table-panel">
        <div class="panel-head"><div><p class="eyebrow">Детализация</p><h2>Операции затрат</h2></div><span class="statistics-row-count">${report.rows.length}</span></div>
        ${pageRows.length ? `
          <div class="table-wrap statistics-table-wrap">
            <table class="data-table statistics-table">
              <thead><tr><th>Дата</th><th>Раздел</th><th>Вид затрат</th><th>Слушатель / контрагент</th><th>Описание</th><th class="statistics-number-cell">Сумма</th></tr></thead>
              <tbody>${pageRows.map((row) => `
                <tr>
                  <td>${escapeHtml(dateRu(row.date) || "—")}</td>
                  <td>${escapeHtml(row.expenseGroup)}</td>
                  <td>${escapeHtml(row.expenseType)}</td>
                  <td>${escapeHtml(row.subject || "—")}</td>
                  <td>${escapeHtml(row.description || row.program || "—")}</td>
                  <td class="statistics-number-cell">${money(Math.abs(Number(row.amount || 0)))}</td>
                </tr>
              `).join("")}</tbody>
            </table>
          </div>
          ${renderTablePagination("statisticsExpenses", report.rows.length, pagination)}
        ` : `<div class="empty-state compact"><span>Операции не найдены.</span></div>`}
      </section>
    `;
  }

  function getFilteredStatisticsDownloadEvents() {
    const filters = state.statistics.filters;
    return (state.statistics.downloads.data?.events || []).filter((event) => (
      (!filters.year || String(event.year) === filters.year)
      && (!filters.month || String(event.month).padStart(2, "0") === filters.month)
    ));
  }

  function statisticsMonthLongLabel(month) {
    const monthIndex = Math.max(1, Math.min(12, Number(month) || 1)) - 1;
    const label = new Intl.DateTimeFormat("ru-RU", { month: "long", timeZone: "UTC" })
      .format(new Date(Date.UTC(2020, monthIndex, 1)));
    return label ? `${label.charAt(0).toLocaleUpperCase("ru-RU")}${label.slice(1)}` : "—";
  }

  function statisticsDownloadDateSortValue(row = {}) {
    const year = Math.floor(Number(row.year));
    const month = Math.floor(Number(row.month));
    const day = Math.floor(Number(row.day));
    if (year >= 2000 && year <= 2100 && month >= 1 && month <= 12 && day >= 1 && day <= 31) {
      return (year * 10000) + (month * 100) + day;
    }
    const match = String(row.date || "").match(/^(\d{4})-(\d{2})-(\d{2})/u);
    return match ? Number(`${match[1]}${match[2]}${match[3]}`) : 0;
  }

  function formatStatisticsDownloadDate(row = {}) {
    const value = statisticsDownloadDateSortValue(row);
    if (!value) return "—";
    const source = String(value).padStart(8, "0");
    return `${source.slice(6, 8)}.${source.slice(4, 6)}.${source.slice(0, 4)}`;
  }

  function getFilteredStatisticsDownloadDetails() {
    const filters = state.statistics.filters;
    const query = String(filters.downloadQuery || "").trim().toLocaleLowerCase("ru-RU");
    const rows = (state.statistics.assistant.data?.downloadDetails || []).filter((row) => {
      if (filters.year && String(row.year) !== filters.year) return false;
      if (filters.month && String(row.month).padStart(2, "0") !== filters.month) return false;
      if (!query) return true;
      return [
        row.id,
        formatStatisticsDownloadDate(row),
        row.year,
        statisticsMonthLongLabel(row.month),
        row.day,
        row.location,
        row.organization,
        row.email,
        row.version,
        row.action
      ].some((value) => String(value || "").toLocaleLowerCase("ru-RU").includes(query));
    });
    const sort = state.statistics.downloadDetailSort || { key: "id", dir: "desc" };
    const column = statisticsDownloadDetailColumns.find((item) => item.key === sort.key)
      || statisticsDownloadDetailColumns[0];
    const direction = sort.dir === "asc" ? 1 : -1;
    return [...rows].sort((left, right) => {
      const comparison = column.date
        ? statisticsDownloadDateSortValue(left) - statisticsDownloadDateSortValue(right)
        : (column.numeric
          ? (Number(left[column.key] || 0) - Number(right[column.key] || 0))
          : String(left[column.key] || "").localeCompare(String(right[column.key] || ""), "ru", {
            numeric: true,
            sensitivity: "base"
          }));
      return comparison ? comparison * direction : Number(right.id || 0) - Number(left.id || 0);
    });
  }

  function renderStatisticsDownloadSortHeader(column) {
    const sort = state.statistics.downloadDetailSort || { key: "id", dir: "desc" };
    const active = sort.key === column.key;
    const indicator = active ? (sort.dir === "asc" ? "↑" : "↓") : "↕";
    const direction = active && sort.dir === "asc" ? "по возрастанию" : "по убыванию";
    return `
      <button
        class="statistics-table-sort-button ${active ? "is-active" : ""}"
        data-action="sort-statistics-downloads"
        data-sort-key="${escapeAttr(column.key)}"
        type="button"
        title="Сортировать ${active ? direction : "по этому столбцу"}"
      >
        <span>${escapeHtml(column.label)}</span>
        <span class="statistics-table-sort-indicator" aria-hidden="true">${indicator}</span>
      </button>
    `;
  }

  function buildStatisticsAssistantReport() {
    const filters = state.statistics.filters;
    const assistantData = state.statistics.assistant.data || {};
    const assistantMonths = (assistantData.monthly || []).filter((row) => (
      (!filters.year || String(row.year) === filters.year)
      && (!filters.month || String(row.month).padStart(2, "0") === filters.month)
    ));
    const downloadEvents = getFilteredStatisticsDownloadEvents();
    const monthly = new Map();
    const files = new Map();
    const versions = new Map();
    const locations = new Map();
    let generated = 0;
    let downloaded = 0;
    (assistantData.versions || []).forEach((row) => {
      if (
        (filters.year && String(row.year) !== filters.year)
        || (filters.month && String(row.month).padStart(2, "0") !== filters.month)
      ) return;
      const label = String(row.label || "Без версии").trim() || "Без версии";
      versions.set(label, (versions.get(label) || 0) + Number(row.value || 0));
    });
    (assistantData.locations || []).forEach((row) => {
      if (
        (filters.year && String(row.year) !== filters.year)
        || (filters.month && String(row.month).padStart(2, "0") !== filters.month)
      ) return;
      const label = String(row.label || "Не указано").trim() || "Не указано";
      if (!locations.has(label)) locations.set(label, { label, installs: 0, removals: 0 });
      locations.get(label).installs += Number(row.installs || 0);
      locations.get(label).removals += Number(row.removals || 0);
    });
    downloadEvents.forEach((event) => {
      const key = `${event.year}-${String(event.month).padStart(2, "0")}`;
      if (event.kind === "downloaded") {
        if (!monthly.has(key)) {
          monthly.set(key, {
            key,
            label: statisticsMonthLabel(key),
            downloads: 0
          });
        }
        monthly.get(key).downloads += Number(event.count || 0);
        files.set(event.file, (files.get(event.file) || 0) + Number(event.count || 0));
        downloaded += Number(event.count || 0);
      } else {
        generated += Number(event.count || 0);
      }
    });
    return {
      installs: assistantMonths.reduce((sum, row) => sum + Number(row.installs || 0), 0),
      removals: assistantMonths.reduce((sum, row) => sum + Number(row.removals || 0), 0),
      actionsTotal: Number(assistantData.summary?.actions || 0),
      generated,
      downloaded,
      monthly: sortStatisticsMonthSeries([...monthly.values()], filters.year ? 12 : 24),
      files: [...files.entries()].map(([label, value]) => ({ label, value })),
      actions: Array.isArray(assistantData.actions) ? assistantData.actions : [],
      versions: [...versions.entries()].map(([label, value]) => ({ label, value })),
      locations: [...locations.values()],
      downloadDetails: getFilteredStatisticsDownloadDetails()
    };
  }

  function renderStatisticsAssistant() {
    const report = buildStatisticsAssistantReport();
    const downloads = state.statistics.downloads;
    const assistant = state.statistics.assistant;
    const downloadPagination = getTablePagination("statisticsDownloads", report.downloadDetails.length);
    const downloadDetailRows = report.downloadDetails.slice(downloadPagination.start, downloadPagination.end);
    const assistantUpdatedAt = formatDateTimeRu(assistant.data?.refreshedAt || "");
    const selectedPeriod = [state.statistics.filters.month, state.statistics.filters.year]
      .filter(Boolean).join(".") || "За весь период";
    return `
      <div class="statistics-source-note">
        <strong>Источники данных</strong>
        <span>Ассистент и детализация: обновляемые MySQL-запросы модели Power BI${assistantUpdatedAt ? `, получено ${escapeHtml(assistantUpdatedAt)}` : ""}. Скачивания файлов: текущая база сайта.</span>
      </div>
      ${renderStatisticsKpis([
        { label: "Установки Ассистента", value: assistant.loading ? "…" : formatStatisticsInteger(report.installs), note: selectedPeriod, tone: "teal" },
        { label: "Удаления Ассистента", value: assistant.loading ? "…" : formatStatisticsInteger(report.removals), note: selectedPeriod, tone: "red" },
        { label: "Действия в Ассистенте", value: assistant.loading ? "…" : formatStatisticsInteger(report.actionsTotal), note: "Весь журнал Power BI", tone: "blue" },
        { label: "Скачано файлов", value: downloads.loading ? "…" : formatStatisticsInteger(report.downloaded), note: downloads.error ? "Источник временно недоступен" : `${formatStatisticsInteger(report.generated)} ссылок сформировано`, tone: "amber" }
      ])}
      ${assistant.error ? `<div class="statistics-inline-error" role="alert">${escapeHtml(assistant.error)}</div>` : ""}
      ${downloads.error ? `<div class="statistics-inline-error" role="alert">${escapeHtml(downloads.error)}</div>` : ""}
      <div class="statistics-two-column">
        <section class="panel statistics-visual-panel statistics-wide-panel">
          <div class="panel-head"><div><p class="eyebrow">Динамика</p><h2>Скачивания по месяцам</h2></div></div>
          ${downloads.loading
            ? `<div class="statistics-loading"><span class="auth-spinner" aria-hidden="true"></span><span>Получение актуальной статистики…</span></div>`
            : renderStatisticsInstallDownloadChart(report.monthly, [
              { key: "downloads", label: "Скачивания", tone: "blue", total: report.downloaded }
            ])}
        </section>
        <section class="panel statistics-visual-panel">
          <div class="panel-head"><div><p class="eyebrow">Версии</p><h2>Установки версий Ассистента</h2></div></div>
          ${assistant.loading
            ? `<div class="statistics-loading"><span class="auth-spinner" aria-hidden="true"></span><span>Обновление версий…</span></div>`
            : renderStatisticsDonut("Версии Ассистента", report.versions, { limit: 7 })}
        </section>
      </div>
      <section class="panel statistics-table-panel statistics-download-detail-panel">
        <div class="panel-head">
          <div><p class="eyebrow">Power BI</p><h2>Детальная информация о скачиваниях</h2></div>
          <span class="statistics-row-count">${formatStatisticsInteger(report.downloadDetails.length)}</span>
        </div>
        ${assistant.loading
          ? `<div class="statistics-loading"><span class="auth-spinner" aria-hidden="true"></span><span>Получение детализации…</span></div>`
          : (downloadDetailRows.length ? `
            <div class="table-wrap statistics-table-wrap">
              <table class="data-table statistics-table statistics-download-table">
                <thead><tr>${statisticsDownloadDetailColumns.map((column) => `<th>${renderStatisticsDownloadSortHeader(column)}</th>`).join("")}</tr></thead>
                <tbody>${downloadDetailRows.map((row) => `
                  <tr>
                    <td class="statistics-number-cell">${formatStatisticsInteger(row.id)}</td>
                    <td class="statistics-date-cell">${escapeHtml(formatStatisticsDownloadDate(row))}</td>
                    <td class="statistics-ellipsis-cell" title="${escapeAttr(row.location || "Не указано")}">${escapeHtml(row.location || "—")}</td>
                    <td class="statistics-ellipsis-cell" title="${escapeAttr(row.organization || "Не указано")}">${escapeHtml(row.organization || "—")}</td>
                    <td class="statistics-ellipsis-cell" title="${escapeAttr(row.email || "Не указано")}">${escapeHtml(row.email || "—")}</td>
                    <td>${escapeHtml(row.version || "—")}</td>
                    <td>${escapeHtml(row.action || "—")}</td>
                  </tr>
                `).join("")}</tbody>
              </table>
            </div>
            ${renderTablePagination("statisticsDownloads", report.downloadDetails.length, downloadPagination)}
          ` : `<div class="empty-state compact"><span>Скачивания для выбранных условий не найдены.</span></div>`)}
      </section>
      <section class="panel statistics-visual-panel">
        <div class="panel-head"><div><p class="eyebrow">География</p><h2>Установки и удаления Ассистента по городам</h2></div></div>
        ${assistant.loading
          ? `<div class="statistics-loading"><span class="auth-spinner" aria-hidden="true"></span><span>Обновление географии…</span></div>`
          : renderStatisticsLocationChart(report.locations, { installs: report.installs, removals: report.removals })}
      </section>
      <div class="statistics-two-column">
        <section class="panel statistics-visual-panel">
          <div class="panel-head"><div><p class="eyebrow">Использование</p><h2>Популярные действия</h2></div></div>
          ${assistant.loading
            ? `<div class="statistics-loading"><span class="auth-spinner" aria-hidden="true"></span><span>Обновление действий…</span></div>`
            : renderStatisticsRanking(report.actions, { limit: 12 })}
        </section>
        <section class="panel statistics-visual-panel">
          <div class="panel-head"><div><p class="eyebrow">Файлы</p><h2>Структура скачиваний</h2></div></div>
          ${downloads.loading
            ? `<div class="statistics-loading"><span class="auth-spinner" aria-hidden="true"></span><span>Обновление…</span></div>`
            : renderStatisticsRanking(report.files, { limit: 12 })}
        </section>
      </div>
    `;
  }

  function getStatisticsFilterOptions() {
    const finance = getStatisticsFinanceRows();
    const years = new Set(
      (state.statistics.assistant.data?.years || []).map((year) => String(year))
    );
    [...finance.income, ...finance.direct, ...finance.general].forEach((row) => {
      const year = statisticsDateParts(row.date)?.year;
      if (year) years.add(year);
    });
    (state.statistics.downloads.data?.years || []).forEach((year) => years.add(String(year)));
    return {
      years: [...years].sort((left, right) => right.localeCompare(left)),
      programs: unique((state.data.collections.students || [])
        .map((student) => String(student.program || "").trim()).filter(Boolean))
        .sort((left, right) => left.localeCompare(right, "ru", { sensitivity: "base" })),
      sources: unique((state.data.collections.students || [])
        .map((student) => String(student.source || "").trim()).filter(Boolean))
        .sort((left, right) => left.localeCompare(right, "ru", { sensitivity: "base" })),
      expenseTypes: unique([...finance.direct, ...finance.general]
        .map((row) => row.expenseType).filter(Boolean))
        .sort((left, right) => left.localeCompare(right, "ru", { sensitivity: "base" }))
    };
  }

  function renderStatistics() {
    const filters = state.statistics.filters;
    const options = getStatisticsFilterOptions();
    const tabs = getOrderedTabs("statistics", statisticsTabs);
    const activeTab = statisticsTabs.some((tab) => tab.id === state.statistics.tab)
      ? state.statistics.tab
      : "income";
    const monthNames = Array.from({ length: 12 }, (_, index) => ({
      value: String(index + 1).padStart(2, "0"),
      label: new Intl.DateTimeFormat("ru-RU", { month: "long", timeZone: "UTC" })
        .format(new Date(Date.UTC(2020, index, 1)))
    }));
    return `
      <section class="statistics-page" data-statistics-page>
        <section class="panel statistics-controls-panel">
          <div class="statistics-heading">
            <div><p class="eyebrow">Аналитика учебного центра</p><h2>Интерактивная статистика</h2></div>
            <div class="statistics-heading-actions">
              ${activeTab === "assistant" ? `<button class="ghost-button" data-action="refresh-statistics-data" type="button" ${state.statistics.downloads.loading || state.statistics.assistant.loading ? "disabled" : ""}>Обновить данные</button>` : ""}
              <button class="ghost-button" data-action="export-statistics" type="button">Экспорт CSV</button>
            </div>
          </div>
          <nav class="statistics-tabs" data-orderable-tabs="statistics" role="tablist" aria-label="Разделы статистики">
            ${tabs.map((tab) => `
              <button class="${activeTab === tab.id ? "active" : ""}" data-action="switch-statistics-tab" data-statistics-tab="${escapeAttr(tab.id)}" data-orderable-tab="${escapeAttr(tab.id)}" data-orderable-tab-default-index="${tab.defaultTabIndex}" type="button" role="tab" aria-selected="${activeTab === tab.id ? "true" : "false"}">${escapeHtml(tab.label)}</button>
            `).join("")}
          </nav>
          <div class="statistics-filters">
            <label><span>Год</span><select data-statistics-filter="year"><option value="">Все годы</option>${options.years.map((year) => `<option value="${escapeAttr(year)}" ${filters.year === year ? "selected" : ""}>${escapeHtml(year)}</option>`).join("")}</select></label>
            <label><span>Месяц</span><select data-statistics-filter="month"><option value="">Все месяцы</option>${monthNames.map((month) => `<option value="${month.value}" ${filters.month === month.value ? "selected" : ""}>${escapeHtml(month.label)}</option>`).join("")}</select></label>
            ${activeTab !== "assistant" ? `
              <label class="statistics-filter-wide"><span>Программа</span><select data-statistics-filter="program"><option value="">Все программы</option>${options.programs.map((program) => `<option value="${escapeAttr(program)}" ${filters.program === program ? "selected" : ""}>${escapeHtml(program)}</option>`).join("")}</select></label>
              <label><span>Источник</span><select data-statistics-filter="source"><option value="">Все источники</option>${options.sources.map((source) => `<option value="${escapeAttr(source)}" ${filters.source === source ? "selected" : ""}>${escapeHtml(source)}</option>`).join("")}</select></label>
            ` : ""}
            ${activeTab === "expenses" ? `
              <label><span>Вид затрат</span><select data-statistics-filter="expenseType"><option value="">Все виды</option>${options.expenseTypes.map((type) => `<option value="${escapeAttr(type)}" ${filters.expenseType === type ? "selected" : ""}>${escapeHtml(type)}</option>`).join("")}</select></label>
              <label class="statistics-filter-wide"><span>Поиск</span><input data-statistics-filter="query" value="${escapeAttr(filters.query)}" placeholder="Контрагент, описание, сумма" autocomplete="off"></label>
            ` : ""}
            ${activeTab === "assistant" ? `
              <label class="statistics-filter-wide"><span>Поиск в скачиваниях</span><input data-statistics-filter="downloadQuery" value="${escapeAttr(filters.downloadQuery)}" placeholder="ID, город, организация, email, версия" autocomplete="off"></label>
            ` : ""}
            <button class="ghost-button statistics-reset-button" data-action="reset-statistics-filters" type="button">Сбросить</button>
          </div>
        </section>
        <div class="statistics-report">
          ${activeTab === "expenses"
            ? renderStatisticsExpenses()
            : (activeTab === "assistant" ? renderStatisticsAssistant() : renderStatisticsIncome())}
        </div>
      </section>
    `;
  }

  async function loadStatisticsDownloads(options = {}) {
    const downloads = state.statistics.downloads;
    if (downloads.loading || (downloads.loaded && !options.force)) return;
    downloads.loading = true;
    downloads.error = "";
    if (state.view === "statistics") render();
    try {
      const response = await fetch(photoApiUrl("/api/statistics/downloads"), {
        credentials: "same-origin",
        cache: "no-store",
        headers: { "X-Requested-With": "AIS-Web" }
      });
      const payload = await response.json().catch(() => ({}));
      if (!response.ok) throw new Error(payload.error || `Ошибка сервера: ${response.status}`);
      downloads.data = payload;
      downloads.loaded = true;
    } catch (error) {
      downloads.error = error.message || "Не удалось получить статистику скачиваний.";
      downloads.loaded = true;
    } finally {
      downloads.loading = false;
      if (state.view === "statistics") render();
    }
  }

  async function loadStatisticsAssistant(options = {}) {
    const assistant = state.statistics.assistant;
    if (assistant.loading || (assistant.loaded && !options.force)) return;
    assistant.loading = true;
    assistant.error = "";
    if (state.view === "statistics") render();
    try {
      const response = await fetch(photoApiUrl("/api/statistics/assistant"), {
        credentials: "same-origin",
        cache: "no-store",
        headers: { "X-Requested-With": "AIS-Web" }
      });
      const payload = await response.json().catch(() => ({}));
      if (!response.ok) throw new Error(payload.error || `Ошибка сервера: ${response.status}`);
      assistant.data = payload;
      assistant.loaded = true;
    } catch (error) {
      assistant.error = error.message || "Не удалось получить статистику Ассистента.";
      assistant.loaded = true;
    } finally {
      assistant.loading = false;
      if (state.view === "statistics") render();
    }
  }

  function loadStatisticsData(options = {}) {
    return Promise.all([
      loadStatisticsAssistant(options),
      loadStatisticsDownloads(options)
    ]);
  }

  function exportStatisticsReport() {
    const tab = state.statistics.tab;
    let fileSuffix = tab;
    let content = "";
    if (tab === "income") {
      const rows = buildStatisticsIncomeReport().programs;
      content = [
        ["Программа", "Слушателей", "Доход"].map(csvCell).join(";"),
        ...rows.map((row) => [row.program, row.students, row.income].map(csvCell).join(";"))
      ].join("\n");
    } else if (tab === "expenses") {
      const rows = buildStatisticsExpenseReport().rows;
      content = [
        ["Дата", "Раздел", "Вид затрат", "Слушатель / контрагент", "Описание", "Сумма"].map(csvCell).join(";"),
        ...rows.map((row) => [row.date, row.expenseGroup, row.expenseType, row.subject, row.description, Math.abs(Number(row.amount || 0))].map(csvCell).join(";"))
      ].join("\n");
    } else {
      const report = buildStatisticsAssistantReport();
      content = [
        ["ID", "Дата", "Город", "Организация", "Email", "Версия", "Действие"].map(csvCell).join(";"),
        ...report.downloadDetails.map((row) => [
          row.id,
          formatStatisticsDownloadDate(row),
          row.location,
          row.organization,
          row.email,
          row.version,
          row.action
        ].map(csvCell).join(";")),
        "",
        ["Популярные действия Ассистента", "Количество"].map(csvCell).join(";"),
        ...report.actions.map((row) => [row.label, row.value].map(csvCell).join(";")),
        "",
        ["Скачанный файл", "Количество"].map(csvCell).join(";"),
        ...report.files.map((row) => [row.label, row.value].map(csvCell).join(";"))
      ].join("\n");
      fileSuffix = "assistant-downloads";
    }
    download(
      `statistics-${fileSuffix}-${new Date().toISOString().slice(0, 10)}.csv`,
      `\ufeff${content}`,
      "text/csv;charset=utf-8"
    );
  }

  function bindStatisticsEvents() {
    if (state.view !== "statistics") return;
    document.querySelectorAll("[data-action='switch-statistics-tab']").forEach((button) => {
      button.addEventListener("click", () => {
        const tab = String(button.dataset.statisticsTab || "");
        if (!statisticsTabs.some((item) => item.id === tab) || tab === state.statistics.tab) return;
        state.statistics.tab = tab;
        state.tablePages.statisticsExpenses = 1;
        state.tablePages.statisticsDownloads = 1;
        render();
      });
    });
    document.querySelectorAll("[data-statistics-filter]").forEach((control) => {
      const apply = () => {
        const key = String(control.dataset.statisticsFilter || "");
        if (!Object.prototype.hasOwnProperty.call(state.statistics.filters, key)) return;
        state.statistics.filters[key] = control.value;
        state.tablePages.statisticsExpenses = 1;
        state.tablePages.statisticsDownloads = 1;
        render();
      };
      control.addEventListener("change", apply);
      if (control.matches("input")) {
        control.addEventListener("keydown", (event) => {
          if (event.key !== "Enter") return;
          event.preventDefault();
          apply();
        });
      }
    });
    document.querySelector("[data-action='reset-statistics-filters']")?.addEventListener("click", () => {
      state.statistics.filters = {
        year: String(new Date().getFullYear()),
        month: "",
        program: "",
        source: "",
        expenseType: "",
        query: "",
        downloadQuery: ""
      };
      state.tablePages.statisticsExpenses = 1;
      state.tablePages.statisticsDownloads = 1;
      render();
    });
    document.querySelectorAll("[data-action='sort-statistics-downloads']").forEach((button) => {
      button.addEventListener("click", () => {
        const key = String(button.dataset.sortKey || "");
        if (!statisticsDownloadDetailColumns.some((column) => column.key === key)) return;
        const current = state.statistics.downloadDetailSort || { key: "id", dir: "desc" };
        const column = statisticsDownloadDetailColumns.find((item) => item.key === key);
        state.statistics.downloadDetailSort = current.key === key
          ? { key, dir: current.dir === "asc" ? "desc" : "asc" }
          : { key, dir: column?.numeric || column?.date ? "desc" : "asc" };
        state.tablePages.statisticsDownloads = 1;
        render();
      });
    });
    document.querySelector("[data-action='export-statistics']")?.addEventListener("click", exportStatisticsReport);
    document.querySelector("[data-action='refresh-statistics-data']")?.addEventListener("click", () => {
      loadStatisticsData({ force: true });
    });
  }

  function renderDashboard() {
    const students = state.data.collections.students;
    const direct = sumBy(getAllDirectExpenses(), "amount");
    const general = sumBy(state.data.collections.generalExpenses, "amount");
    const revenue = sumBy(students, "paidAmount");
    const profitSummary = calculateDashboardStudentProfitSummary(students);
    const financeSeries = buildFinanceSeries();
    const receivable = Math.round(
      students.reduce((sum, student) => sum + calculateDashboardStudentReceivable(student), 0) * 100
    ) / 100;
    const statusCounts = countBy(students, "status");
    const studentStatusItems = getOrderedDashboardStudentStatuses().map((status) => ({
      label: status,
      count: Number(statusCounts[status]) || 0
    }));
    const maxStatus = Math.max(...studentStatusItems.map((item) => item.count), 1);
    const dueSoon = students
      .filter((item) => String(item.status || "").trim() === "Учится" && item.endDate)
      .sort((a, b) => new Date(a.endDate) - new Date(b.endDate))
      .slice(0, 5)
      .map((item) => ({ ...item, daysRemaining: calculateDaysUntilDate(item.endDate) }));
    const pendingIssuedDocuments = getIssuedDocumentRows()
      .filter((row) => row.frdoKey === "pending");
    const pendingIssuedDocumentDays = pendingIssuedDocuments
      .map((row) => row.remainingDays)
      .filter((days) => Number.isFinite(days));
    const overdueIssuedDocumentsCount = pendingIssuedDocuments
      .filter((row) => Number.isFinite(row.remainingDays) && row.remainingDays < 0)
      .length;
    const nearestFrdoDays = pendingIssuedDocumentDays.length
      ? Math.min(...pendingIssuedDocumentDays)
      : null;
    const frdoDeadlineDays = getIssuedDocumentDeadlineDays();
    const frdoWidgetTone = pendingIssuedDocuments.length === 0
      ? "is-success"
      : (nearestFrdoDays !== null && nearestFrdoDays < 10
        ? "is-danger"
        : (nearestFrdoDays !== null && nearestFrdoDays < 20 ? "is-warning" : ""));
    const frdoDeadlineLabel = pendingIssuedDocuments.length === 0
      ? "Все документы выгружены"
      : (nearestFrdoDays === null
        ? "Для расчёта срока укажите дату выдачи"
        : (nearestFrdoDays < 0
          ? `Просрочено на ${Math.abs(nearestFrdoDays)} дн.`
          : (nearestFrdoDays === 0 ? "Срок истекает сегодня" : `До ближайшего срока: ${nearestFrdoDays} дн.`)));
    const frdoDaysIndicatorLabel = pendingIssuedDocuments.length === 0
      ? "Новых задач нет"
      : (nearestFrdoDays === null
        ? "Ближайший срок не рассчитан"
        : (nearestFrdoDays < 0
          ? `Просрочено дней: ${Math.abs(nearestFrdoDays)}`
          : `Осталось дней: ${nearestFrdoDays}`));

    return `
      ${pendingIssuedDocuments.length ? `
      <button
        class="panel dashboard-frdo-widget ${frdoWidgetTone}"
        data-view-shortcut="issuedDocuments"
        data-issued-document-scope="pending"
        type="button"
        title="Открыть документы, ожидающие выгрузки в ФРДО"
      >
        <span class="dashboard-frdo-widget-heading">
          <span class="eyebrow">ФРДО</span>
          <strong>Документы к выгрузке</strong>
          <small>Норматив: ${frdoDeadlineDays} дней с даты выдачи</small>
        </span>
        <span class="dashboard-frdo-widget-count">
          <strong>${pendingIssuedDocuments.length}</strong>
          <small>документов</small>
          <small class="dashboard-frdo-widget-overdue ${overdueIssuedDocumentsCount ? "has-overdue" : ""}">Просрочено: <strong>${overdueIssuedDocumentsCount}</strong></small>
        </span>
        <span class="dashboard-frdo-widget-deadline">
          <strong>${escapeHtml(frdoDeadlineLabel)}</strong>
          <small>${escapeHtml(frdoDaysIndicatorLabel)}</small>
        </span>
        <span class="dashboard-frdo-widget-open" aria-hidden="true">↗</span>
      </button>
      ` : ""}

      <section class="panel">
        <div class="panel-head">
          <div>
            <p class="eyebrow">Контроль сроков</p>
            <h2>Ближайшие окончания обучения</h2>
          </div>
        </div>
        ${miniTable(dueSoon, ["name", "program", "endDate", "balance", "daysRemaining"], {
          config: "students",
          headers: {
            name: "Слушатель",
            program: "Программа",
            endDate: "Дата окончания",
            balance: "Остаток",
            daysRemaining: "Срок"
          },
          warningKey: "daysRemaining",
          warningBelow: 10
        })}
      </section>

      <div class="split-layout">
        <section class="panel" data-dashboard-student-statuses>
          <div class="panel-head">
            <div>
              <p class="eyebrow">Заявки и обучение</p>
              <h2>Статусы слушателей</h2>
            </div>
            <div class="dashboard-status-head-actions">
              <button class="ghost-button dashboard-student-import-button" data-action="open-student-applications-import" type="button">Импорт слушателей</button>
              <button class="icon-button" data-view-shortcut="students" type="button" title="Открыть слушателей">↗</button>
            </div>
          </div>
          <div class="bar-list dashboard-status-list" data-dashboard-status-list>
            ${studentStatusItems.map(({ label, count }) => `
              <button
                class="bar-row bar-row-link ${label === "На зачисление" && count > 0 ? "is-alert" : ""} ${count === 0 ? "is-empty" : ""}"
                data-student-status-shortcut="${escapeAttr(label)}"
                data-dashboard-student-status-item="${escapeAttr(label)}"
                type="button"
                draggable="true"
                title="Открыть слушателей со статусом «${escapeAttr(label)}». Для изменения порядка удерживайте Shift и перетащите строку"
              >
                <span>${escapeHtml(label)}</span>
                <span class="bar-track"><i style="width:${count > 0 ? Math.max(8, (count / maxStatus) * 100) : 0}%"></i></span>
                <strong>${count}</strong>
              </button>
            `).join("")}
          </div>
        </section>

        <section class="panel">
          <div class="panel-head">
            <div>
              <p class="eyebrow">Финансы</p>
              <h2><button class="dashboard-panel-title-link" data-action="open-finance-details" data-finance-metric="all" type="button" title="Открыть детализацию поступлений и затрат">Поступления и затраты</button></h2>
            </div>
            <button class="icon-button" data-action="open-finance-details" data-finance-metric="all" type="button" title="Открыть детализацию поступлений и затрат">↗</button>
          </div>
          <div class="finance-summary">
            <button class="finance-summary-row" data-action="open-finance-details" data-finance-metric="revenue" type="button"><span>Внесено слушателями</span><strong>${money(revenue)}</strong></button>
            <button class="finance-summary-row is-receivable" data-action="open-finance-details" data-finance-metric="receivable" type="button"><span>Дебиторская задолженность</span><strong>${money(receivable)}</strong></button>
            <button class="finance-summary-row" data-action="open-finance-details" data-finance-metric="direct" type="button"><span>Прямые затраты</span><strong>${money(direct)}</strong></button>
            <button class="finance-summary-row" data-action="open-finance-details" data-finance-metric="general" type="button"><span>Общие затраты</span><strong>${money(general)}</strong></button>
            <button class="finance-summary-row finance-summary-profit ${profitSummary.profit < 0 ? "is-negative" : ""}" data-action="open-finance-details" data-finance-metric="profit" type="button">
              <span class="finance-summary-label"><span>Прибыль</span><small>Средняя прибыльность: ${percent(profitSummary.averageProfitability)}</small></span>
              <strong>${money(profitSummary.profit)}</strong>
            </button>
          </div>
          ${renderFinanceChart(financeSeries)}
        </section>
      </div>
    `;
  }

  function isStudentEligibleForReceivable(record) {
    const status = String(record?.status || "").trim().toLocaleLowerCase("ru-RU");
    if (status === "учится") return true;
    if (!["отчислен", "архив"].includes(status)) return false;
    return hasStudentEducationDocumentIssued(record);
  }

  function calculateDashboardStudentReceivable(record) {
    if (!isStudentEligibleForReceivable(record)) return 0;
    if (!String(record?.enrollmentDate || "").trim()) return 0;
    const contractAmount = Number(record?.contractAmount || 0);
    if (!Number.isFinite(contractAmount) || contractAmount <= 0) return 0;
    const detailedPayments = sumStudentPayments(record);
    const storedPayments = Number(record?.paidAmount || 0);
    const received = detailedPayments > 0
      ? detailedPayments
      : (Number.isFinite(storedPayments) ? storedPayments : 0);
    return Math.max(0, Math.round((contractAmount - received) * 100) / 100);
  }

  function calculateDashboardStudentProfit(record) {
    const detailedIncome = sumStudentPayments(record);
    const storedIncome = Number(record?.paidAmount || 0);
    const income = Math.round((detailedIncome > 0
      ? detailedIncome
      : (Number.isFinite(storedIncome) ? storedIncome : 0)) * 100) / 100;
    const expenses = Math.round(sumStudentExpenses(record) * 100) / 100;
    const profit = Math.round((income - expenses) * 100) / 100;
    const profitability = income > 0
      ? Math.round((profit / income) * 1000) / 10
      : null;
    return { income, expenses, profit, profitability };
  }

  function calculateDashboardStudentProfitSummary(students = []) {
    const results = students.map((student) => calculateDashboardStudentProfit(student));
    const profit = Math.round(results.reduce((sum, item) => sum + item.profit, 0) * 100) / 100;
    const profitabilityValues = results
      .map((item) => item.profitability)
      .filter((value) => Number.isFinite(value));
    const averageProfitability = profitabilityValues.length
      ? Math.round((profitabilityValues.reduce((sum, value) => sum + value, 0) / profitabilityValues.length) * 10) / 10
      : 0;
    return { profit, averageProfitability };
  }

  function calculateDaysUntilDate(value) {
    const endTime = parseTableSortDate(value);
    if (endTime === null) return "";
    const today = new Date();
    const todayTime = Date.UTC(today.getFullYear(), today.getMonth(), today.getDate());
    return Math.round((endTime - todayTime) / 86400000);
  }

  function isStudentTrainingDeadlinePassed(record) {
    if (String(record?.status || "").trim() !== "Учится") return false;
    const daysRemaining = calculateDaysUntilDate(record?.extendedEndDate || record?.endDate);
    return Number.isFinite(daysRemaining) && daysRemaining < 0;
  }

  function getFinanceMetricLabel(metric = state.financeDetails.metric) {
    return financeDetailMetrics.find((item) => item.key === metric)?.label || "Все операции";
  }

  function getFinanceReceiptRows() {
    return (state.data.collections.students || []).flatMap((student) => {
      const paymentRows = Array.from({ length: 8 }, (_, index) => {
        const number = index + 1;
        const amount = Number(student[`payment${number}Amount`] || 0);
        if (!amount) return null;
        return {
          id: `revenue:${student.id || student.uid}:${number}`,
          date: student[`payment${number}Date`] || student.applicationDate || student.startDate || "",
          category: "Поступление",
          uid: student.uid || "",
          subject: student.name || "",
          context: student.program || "",
          description: student[`payment${number}Note`] || `Оплата ${number}`,
          amount,
          sourceConfig: "students",
          sourceId: student.id || ""
        };
      }).filter(Boolean);
      const expectedAmount = Number(student.paidAmount || 0);
      const detailedAmount = paymentRows.reduce((sum, row) => sum + row.amount, 0);
      const difference = Math.round((expectedAmount - detailedAmount) * 100) / 100;
      if (!paymentRows.length && expectedAmount) {
        paymentRows.push({
          id: `revenue:${student.id || student.uid}:total`,
          date: student.applicationDate || student.startDate || student.endDate || "",
          category: "Поступление",
          uid: student.uid || "",
          subject: student.name || "",
          context: student.program || "",
          description: "Итоговая внесённая сумма",
          amount: expectedAmount,
          sourceConfig: "students",
          sourceId: student.id || ""
        });
      } else if (paymentRows.length && Math.abs(difference) >= 0.01) {
        paymentRows.push({
          id: `revenue:${student.id || student.uid}:adjustment`,
          date: student.applicationDate || student.startDate || student.endDate || "",
          category: "Поступление",
          uid: student.uid || "",
          subject: student.name || "",
          context: student.program || "",
          description: "Корректировка до итоговой внесённой суммы",
          amount: difference,
          sourceConfig: "students",
          sourceId: student.id || ""
        });
      }
      return paymentRows;
    });
  }

  function getFinanceReceivableRows() {
    return (state.data.collections.students || []).flatMap((student) => {
      const amount = calculateDashboardStudentReceivable(student);
      if (!amount) return [];
      const contractAmount = Number(student.contractAmount || 0);
      const paidAmount = Math.max(0, contractAmount - amount);
      return [{
        id: `receivable:${student.id || student.uid}`,
        date: student.enrollmentDate || student.contractDate || student.startDate || "",
        category: "Дебиторская задолженность",
        uid: student.uid || "",
        subject: student.name || "",
        context: student.program || "",
        description: `Сумма договора: ${money(contractAmount)}; внесено: ${money(paidAmount)}`,
        amount,
        sourceConfig: "students",
        sourceId: student.id || ""
      }];
    });
  }

  function getFinanceDirectExpenseRows() {
    const linkedRows = (state.data.collections.students || []).flatMap((student) => (
      (Array.isArray(student.directExpenses) ? student.directExpenses : []).map((expense, index) => ({
        id: `direct:student:${student.id || student.uid}:${expense.id || index}`,
        date: expense.date || "",
        category: "Прямые затраты",
        uid: student.uid || expense.uid || "",
        subject: student.name || "",
        context: expense.type || student.program || "",
        description: expense.note || "",
        amount: Number(expense.amount || 0),
        sourceConfig: "students",
        sourceId: student.id || ""
      }))
    ));
    const unlinkedRows = (state.data.collections.directExpenses || []).map((expense, index) => ({
      id: `direct:unlinked:${expense.id || index}`,
      date: expense.date || "",
      category: "Прямые затраты",
      uid: expense.uid || "",
      subject: expense.note || "Без привязки к слушателю",
      context: expense.type || "",
      description: expense.note || "",
      amount: Number(expense.amount || 0),
      sourceConfig: "directExpenses",
      sourceId: expense.id || ""
    }));
    return [...linkedRows, ...unlinkedRows].filter((row) => row.amount);
  }

  function getFinanceGeneralExpenseRows() {
    return (state.data.collections.generalExpenses || []).map((expense, index) => ({
      id: `general:${expense.id || index}`,
      date: expense.date || expense.paid || "",
      category: "Общие затраты",
      uid: "",
      subject: expense.counterparty || "",
      context: expense.workType || "",
      description: expense.description || expense.otherExpenses || "",
      amount: Number(expense.amount || 0),
      sourceConfig: "generalExpenses",
      sourceId: expense.id || ""
    })).filter((row) => row.amount);
  }

  function getFinanceStudentProfitRows() {
    return (state.data.collections.students || []).flatMap((student) => {
      const result = calculateDashboardStudentProfit(student);
      if (result.income === 0 && result.expenses === 0) return [];
      return [{
        id: `profit:${student.id || student.uid}`,
        date: student.endDate || student.startDate || student.applicationDate || "",
        category: "Прибыль",
        uid: student.uid || "",
        subject: student.name || "",
        context: student.program || "",
        description: `Доходы: ${money(result.income)}; расходы: ${money(result.expenses)}; прибыльность: ${result.profitability === null ? "—" : percent(result.profitability)}`,
        amount: result.profit,
        sourceConfig: "students",
        sourceId: student.id || ""
      }];
    });
  }

  function getFinanceDetailRows(metric = state.financeDetails.metric) {
    if (metric === "revenue") return getFinanceReceiptRows();
    if (metric === "receivable") return getFinanceReceivableRows();
    if (metric === "direct") return getFinanceDirectExpenseRows();
    if (metric === "general") return getFinanceGeneralExpenseRows();
    if (metric === "profit") return getFinanceStudentProfitRows();
    return [
      ...getFinanceReceiptRows(),
      ...getFinanceDirectExpenseRows().map((row) => ({ ...row, amount: -Math.abs(row.amount) })),
      ...getFinanceGeneralExpenseRows().map((row) => ({ ...row, amount: -Math.abs(row.amount) }))
    ];
  }

  function getFilteredFinanceDetailRows() {
    const details = state.financeDetails;
    const query = String(details.query || "").trim().toLocaleLowerCase("ru-RU");
    const fromTime = details.dateFrom ? parseTableSortDate(details.dateFrom) : null;
    const toTime = details.dateTo ? parseTableSortDate(details.dateTo) : null;
    const filtered = getFinanceDetailRows(details.metric).filter((row) => {
      const rowTime = parseTableSortDate(row.date);
      if (fromTime !== null && (rowTime === null || rowTime < fromTime)) return false;
      if (toTime !== null && (rowTime === null || rowTime > toTime)) return false;
      if (!query) return true;
      return [row.date, row.category, row.uid, row.subject, row.context, row.description, row.amount]
        .some((value) => String(value ?? "").toLocaleLowerCase("ru-RU").includes(query));
    });
    const sort = details.sort || { key: "date", dir: "desc" };
    const direction = sort.dir === "asc" ? 1 : -1;
    return filtered.sort((left, right) => {
      if (sort.key === "date") {
        const leftDate = parseTableSortDate(left.date);
        const rightDate = parseTableSortDate(right.date);
        if (leftDate === null && rightDate !== null) return 1;
        if (leftDate !== null && rightDate === null) return -1;
        if (leftDate !== null && rightDate !== null && leftDate !== rightDate) {
          return (leftDate - rightDate) * direction;
        }
      }
      if (sort.key === "amount") return (Number(left.amount || 0) - Number(right.amount || 0)) * direction;
      return String(left[sort.key] || "").localeCompare(String(right[sort.key] || ""), "ru") * direction;
    });
  }

  function renderFinanceDetailsSortButton(key, label) {
    const sort = state.financeDetails.sort || {};
    const marker = sort.key === key ? (sort.dir === "asc" ? " ↑" : " ↓") : "";
    return `<button data-action="sort-finance-details" data-key="${escapeAttr(key)}" type="button">${escapeHtml(label)}${marker}</button>`;
  }

  function renderFinanceDetailsDialog() {
    const rows = getFilteredFinanceDetailRows();
    const pagination = getTablePagination("financeDetails", rows.length);
    const pageRows = rows.slice(pagination.start, pagination.end);
    const total = Math.round(rows.reduce((sum, row) => sum + Number(row.amount || 0), 0) * 100) / 100;
    const metricLabel = getFinanceMetricLabel();
    return `
      <div class="modal-backdrop finance-details-backdrop ${state.modal ? "is-background" : ""}" data-action="close-finance-details" ${state.modal ? 'aria-hidden="true"' : ""}>
        <section class="modal finance-details-modal" role="dialog" aria-modal="${state.modal ? "false" : "true"}" aria-label="Детализация поступлений и затрат">
          <header class="modal-head">
            <div>
              <p class="eyebrow">Финансы</p>
              <h2>Поступления и затраты</h2>
              <small>${escapeHtml(metricLabel)}</small>
            </div>
            <button class="icon-button" data-action="close-finance-details" type="button" title="Закрыть" aria-label="Закрыть">×</button>
          </header>
          <div class="finance-details-content">
            <div class="finance-details-tabs" role="tablist" aria-label="Раздел финансов">
              ${financeDetailMetrics.map((metric) => `
                <button class="${state.financeDetails.metric === metric.key ? "active" : ""}" data-action="select-finance-detail-metric" data-finance-metric="${metric.key}" type="button" role="tab" aria-selected="${state.financeDetails.metric === metric.key ? "true" : "false"}">${escapeHtml(metric.label)}</button>
              `).join("")}
            </div>
            <div class="toolbar finance-details-toolbar">
              <label class="search-box finance-details-search">
                <span>⌕</span>
                <input name="financeDetailsQuery" value="${escapeAttr(state.financeDetails.query)}" placeholder="Поиск по операциям" autocomplete="off">
              </label>
              <label class="finance-details-date-filter"><span>Дата с</span><input name="financeDetailsDateFrom" type="date" value="${escapeAttr(state.financeDetails.dateFrom)}"></label>
              <label class="finance-details-date-filter"><span>по</span><input name="financeDetailsDateTo" type="date" value="${escapeAttr(state.financeDetails.dateTo)}"></label>
              <button class="ghost-button" data-action="reset-finance-detail-filters" type="button">Сбросить</button>
              <button class="ghost-button" data-action="export-finance-details" type="button">CSV</button>
            </div>
            <div class="finance-details-summary" role="status">
              <span>Найдено записей: <strong>${rows.length}</strong></span>
              <span>${state.financeDetails.metric === "receivable" ? "Задолженность по выборке" : "Итого по выборке"}: <strong class="${total < 0 ? "is-negative" : ""}">${money(total)}</strong></span>
            </div>
            ${rows.length ? `
              <div class="table-wrap finance-details-table-wrap">
                <table class="data-table finance-details-table">
                  <thead><tr>
                    <th>${renderFinanceDetailsSortButton("date", "Дата")}</th>
                    <th>${renderFinanceDetailsSortButton("category", "Категория")}</th>
                    <th>${renderFinanceDetailsSortButton("uid", "UID")}</th>
                    <th>${renderFinanceDetailsSortButton("subject", "Слушатель / контрагент")}</th>
                    <th>${renderFinanceDetailsSortButton("context", "Программа / вид затрат")}</th>
                    <th>${renderFinanceDetailsSortButton("description", "Описание")}</th>
                    <th class="finance-details-amount-head">${renderFinanceDetailsSortButton("amount", "Сумма")}</th>
                  </tr></thead>
                  <tbody>
                    ${pageRows.map((row) => `
                      <tr>
                        <td>${escapeHtml(dateRu(row.date) || "—")}</td>
                        <td>${escapeHtml(row.category || "—")}</td>
                        <td>${escapeHtml(row.uid || "—")}</td>
                        <td>${row.sourceId ? `<button class="table-edit-link" data-action="open-finance-detail-source" data-row-id="${escapeAttr(row.id)}" type="button">${escapeHtml(row.subject || "Открыть запись")}</button>` : escapeHtml(row.subject || "—")}</td>
                        <td>${escapeHtml(row.context || "—")}</td>
                        <td>${escapeHtml(row.description || "—")}</td>
                        <td class="finance-details-amount ${Number(row.amount) < 0 ? "is-negative" : "is-positive"}">${money(row.amount)}</td>
                      </tr>
                    `).join("")}
                  </tbody>
                </table>
              </div>
              ${renderTablePagination("financeDetails", rows.length, pagination)}
            ` : `<div class="empty-state"><strong>Записей нет</strong><span>Измените фильтры или период.</span></div>`}
          </div>
        </section>
      </div>
    `;
  }

  function openFinanceDetails(metric = "all") {
    const validMetric = financeDetailMetrics.some((item) => item.key === metric) ? metric : "all";
    state.financeDetails = {
      open: true,
      metric: validMetric,
      query: "",
      dateFrom: "",
      dateTo: "",
      sort: { key: "date", dir: "desc" }
    };
    state.tablePages.financeDetails = 1;
    render();
  }

  function closeFinanceDetails() {
    state.financeDetails.open = false;
    render();
  }

  function exportFinanceDetails() {
    const rows = getFilteredFinanceDetailRows();
    const fields = [
      ["date", "Дата"], ["category", "Категория"], ["uid", "UID"],
      ["subject", "Слушатель / контрагент"], ["context", "Программа / вид затрат"],
      ["description", "Описание"], ["amount", "Сумма"]
    ];
    const header = fields.map(([, label]) => csvCell(label)).join(";");
    const body = rows.map((row) => fields.map(([key]) => csvCell(row[key])).join(";")).join("\n");
    const date = new Date().toISOString().slice(0, 10);
    download(`finance-${state.financeDetails.metric}-${date}.csv`, `\ufeff${header}\n${body}`, "text/csv;charset=utf-8");
  }

  async function openFinanceDetailSource(rowId) {
    const row = getFilteredFinanceDetailRows().find((item) => String(item.id) === String(rowId));
    if (!row?.sourceConfig || !row.sourceId || !configs[row.sourceConfig]) return;
    await withCardLoadingIndicator(row.sourceConfig, row.sourceId, async () => {
      if (!await acquireRecordLock(recordLockEntityType(row.sourceConfig), row.sourceId)) return;
      const keepFinanceInBackground = row.sourceConfig === "students";
      if (!keepFinanceInBackground) state.financeDetails.open = false;
      state.lastEditedRow = { config: row.sourceConfig, id: row.sourceId };
      if (row.sourceConfig === "students") {
        state.studentCardTab = "income";
        state.openPaymentRows = [];
        state.openExpenseRows = [];
      }
      if (["students", "contracts"].includes(row.sourceConfig)) resetCardWindowState();
      state.modal = {
        config: row.sourceConfig,
        id: row.sourceId,
        ...(keepFinanceInBackground ? { studentNavigationIds: getFinanceDetailStudentNavigationIds() } : {})
      };
      render();
    });
  }

  function getFinanceDetailStudentNavigationIds() {
    return unique(getFilteredFinanceDetailRows()
      .filter((row) => row.sourceConfig === "students" && row.sourceId)
      .map((row) => String(row.sourceId)));
  }

  function bindFinanceDetailsEvents() {
    document.querySelectorAll("[data-action='open-finance-details']").forEach((button) => {
      button.addEventListener("click", () => openFinanceDetails(button.dataset.financeMetric));
    });
    if (!state.financeDetails.open) return;
    document.querySelectorAll("[data-action='close-finance-details']").forEach((element) => {
      element.addEventListener("click", (event) => {
        if (element.matches("button") || event.target === element) closeFinanceDetails();
      });
    });
    document.querySelectorAll("[data-action='select-finance-detail-metric']").forEach((button) => {
      button.addEventListener("click", () => {
        state.financeDetails.metric = button.dataset.financeMetric || "all";
        state.tablePages.financeDetails = 1;
        render();
      });
    });
    const queryInput = document.querySelector("[name='financeDetailsQuery']");
    queryInput?.addEventListener("input", (event) => {
      const cursor = event.currentTarget.selectionStart;
      state.financeDetails.query = event.currentTarget.value;
      state.tablePages.financeDetails = 1;
      render();
      const nextInput = document.querySelector("[name='financeDetailsQuery']");
      nextInput?.focus({ preventScroll: true });
      nextInput?.setSelectionRange(cursor, cursor);
    });
    ["financeDetailsDateFrom", "financeDetailsDateTo"].forEach((name) => {
      document.querySelector(`[name='${name}']`)?.addEventListener("change", (event) => {
        const key = name === "financeDetailsDateFrom" ? "dateFrom" : "dateTo";
        state.financeDetails[key] = event.currentTarget.value;
        state.tablePages.financeDetails = 1;
        render();
      });
    });
    document.querySelector("[data-action='reset-finance-detail-filters']")?.addEventListener("click", () => {
      state.financeDetails.query = "";
      state.financeDetails.dateFrom = "";
      state.financeDetails.dateTo = "";
      state.tablePages.financeDetails = 1;
      render();
    });
    document.querySelector("[data-action='export-finance-details']")?.addEventListener("click", exportFinanceDetails);
    document.querySelectorAll("[data-action='sort-finance-details']").forEach((button) => {
      button.addEventListener("click", () => {
        const key = button.dataset.key || "date";
        state.financeDetails.sort = {
          key,
          dir: state.financeDetails.sort.key === key && state.financeDetails.sort.dir === "asc" ? "desc" : "asc"
        };
        state.tablePages.financeDetails = 1;
        render();
      });
    });
    document.querySelectorAll("[data-action='open-finance-detail-source']").forEach((button) => {
      button.addEventListener("click", () => openFinanceDetailSource(button.dataset.rowId));
    });
  }

  function renderFinanceChart(series) {
    if (!series.length) return `<div class="empty-state compact"><span>Нет данных для графика</span></div>`;
    const activeMetrics = getActiveFinanceMetrics();
    const sortedSeries = sortFinanceSeries(series);
    const maxValue = Math.max(...sortedSeries.flatMap((item) => activeMetrics.map((metric) => item[metric.key])), 1);
    return `
      <div class="finance-chart">
        ${activeMetrics.length ? `
          <div class="finance-bars">
            ${sortedSeries.map((item) => `
            <div class="finance-month">
              <div class="finance-bars-group" style="grid-template-columns: repeat(${activeMetrics.length}, 1fr)">
                ${activeMetrics.map((metric) => financeBar(metric.tone, item[metric.key], maxValue, metric.label)).join("")}
              </div>
              <small>${escapeHtml(item.label)}</small>
            </div>
            `).join("")}
          </div>
        ` : `<div class="empty-state compact"><span>Выберите хотя бы один показатель</span></div>`}
        <div class="finance-chart-filters" aria-label="Фильтр показателей графика">
          ${financeMetrics.map((metric) => `
            <button class="chart-filter ${state.financeChart[metric.key] ? "active" : ""}" data-action="toggle-finance-metric" data-metric="${metric.key}" type="button" aria-pressed="${state.financeChart[metric.key] ? "true" : "false"}">
              <i class="${metric.tone}"></i>${escapeHtml(metric.label)}
            </button>
          `).join("")}
        </div>
      </div>
    `;
  }

  function getActiveFinanceMetrics() {
    return financeMetrics.filter((metric) => state.financeChart[metric.key]);
  }

  function sortFinanceSeries(series) {
    return series
      .slice()
      .sort((a, b) => b.key.localeCompare(a.key))
      .slice(0, 12);
  }

  function financeBar(kind, value, maxValue, label) {
    const amount = Number(value || 0);
    const height = amount > 0 ? Math.max(4, (amount / maxValue) * 100) : 0;
    const thousands = `${new Intl.NumberFormat("ru-RU", { maximumFractionDigits: 0 }).format(amount / 1000)} т.р.`;
    return `
      <span class="finance-bar-column" title="${escapeAttr(`${label}: ${money(amount)}`)}">
        <small class="finance-bar-value">${escapeHtml(thousands)}</small>
        <span class="finance-bar-area"><i class="finance-bar ${kind}" style="height:${height}%"></i></span>
      </span>
    `;
  }

  function getDirectExpenseNoteFilterOptions() {
    const valuesByNormalizedNote = new Map();
    getRowsForConfig(configs.directExpenses).forEach((expense) => {
      const note = String(expense?.note || "").replace(/\s+/g, " ").trim();
      if (!note) return;
      const normalized = note.toLocaleLowerCase("ru-RU");
      if (!valuesByNormalizedNote.has(normalized)) valuesByNormalizedNote.set(normalized, note);
    });
    return [...valuesByNormalizedNote.values()]
      .sort((left, right) => left.localeCompare(right, "ru", { sensitivity: "base" }));
  }

  function getStudentListDateFilterFields() {
    const excluded = /^(?:payment|expense)\d+Date$/u;
    const fields = studentAllFields
      .filter((item) => item.type === "date" && !excluded.test(item.key))
      .map((item) => ({ key: item.key, label: item.label }));
    const seen = new Set();
    return fields.filter((item) => {
      if (!item.key || seen.has(item.key)) return false;
      seen.add(item.key);
      return true;
    });
  }

  function getStudentListProgramFilterOptions() {
    return sortProgramNames([
      ...(state.data.collections.students || []).map((record) => String(record?.program || "").trim()),
      ...(state.data.collections.programs || []).map((record) => String(record?.name || "").trim())
    ]);
  }

  function getStudentListSelectedPrograms(filters = state.studentListFilters || {}) {
    const values = Array.isArray(filters.programs)
      ? filters.programs
      : [filters.program];
    return unique(values.map((value) => String(value || "").trim()).filter(Boolean));
  }

  function normalizeStudentListProgramQuery(value) {
    return String(value || "").trim().toLocaleLowerCase("ru-RU").replace(/ё/g, "е");
  }

  function applyStudentListProgramSearch(query, root = document) {
    const normalizedQuery = normalizeStudentListProgramQuery(query);
    let visibleCount = 0;
    root.querySelectorAll("[data-student-list-program-option-row]").forEach((row) => {
      const label = normalizeStudentListProgramQuery(row.textContent);
      const hidden = Boolean(normalizedQuery && !label.includes(normalizedQuery));
      row.hidden = hidden;
      if (!hidden) visibleCount += 1;
    });
    const empty = root.querySelector("[data-student-list-program-filter-empty]");
    if (empty) empty.hidden = visibleCount > 0;
  }

  function getStudentListDatePeriodDates(period, referenceDate = new Date()) {
    const value = String(period || "custom");
    if (["7", "30", "90"].includes(value)) {
      return getStudentApplicationsDefaultDates(Number(value), referenceDate);
    }
    const dateTo = getStudentApplicationsDefaultDates(0, referenceDate).dateTo;
    if (value === "month") return { dateFrom: `${dateTo.slice(0, 7)}-01`, dateTo };
    if (value === "year") return { dateFrom: `${dateTo.slice(0, 4)}-01-01`, dateTo };
    return null;
  }

  function renderStudentListAdvancedFilters() {
    const filters = state.studentListFilters || {};
    const dateFields = getStudentListDateFilterFields();
    const programs = getStudentListProgramFilterOptions();
    const selectedPrograms = getStudentListSelectedPrograms(filters);
    const selectionLabel = selectedPrograms.length === 1
      ? selectedPrograms[0]
      : (selectedPrograms.length ? `Выбрано: ${selectedPrograms.length}` : "Все программы");
    const programQuery = String(state.studentListProgramQuery || "");
    const normalizedProgramQuery = normalizeStudentListProgramQuery(programQuery);
    const visibleProgramCount = programs.filter((program) => (
      !normalizedProgramQuery
      || normalizeStudentListProgramQuery(program).includes(normalizedProgramQuery)
    )).length;
    const active = Boolean(selectedPrograms.length || filters.dateField || filters.dateFrom || filters.dateTo);
    return `
      <div class="student-list-advanced-filters ${active ? "is-active" : ""}" data-student-list-filters>
        <details class="student-program-type-filter student-list-program-filter ${selectedPrograms.length ? "is-active" : ""}" data-program-type-filter data-student-list-program-filter>
          <summary title="Выбрать одну или несколько программ">
            <span>Программа</span>
            <strong>${escapeHtml(selectionLabel)}</strong>
            <svg viewBox="0 0 12 8" aria-hidden="true"><path d="M1 1.5 6 6.5l5-5"></path></svg>
          </summary>
          <div class="student-program-type-filter-panel student-list-program-filter-panel">
            <label class="student-list-program-search">
              <span aria-hidden="true">⌕</span>
              <input type="search" value="${escapeAttr(programQuery)}" placeholder="Поиск программы" autocomplete="off" data-student-list-program-search>
            </label>
            <div class="student-list-program-filter-options" data-student-list-program-filter-options>
              ${programs.map((program) => {
                const normalizedProgram = normalizeStudentListProgramQuery(program);
                const hidden = normalizedProgramQuery && !normalizedProgram.includes(normalizedProgramQuery);
                return `
                  <label data-student-list-program-option-row ${hidden ? "hidden" : ""}>
                    <input type="checkbox" value="${escapeAttr(program)}" data-student-list-program-filter-option ${selectedPrograms.includes(program) ? "checked" : ""}>
                    <span>${escapeHtml(program)}</span>
                  </label>
                `;
              }).join("")}
              <div class="student-list-program-filter-empty" data-student-list-program-filter-empty ${visibleProgramCount ? "hidden" : ""}>Программы не найдены</div>
            </div>
            <button class="student-program-type-filter-clear" data-action="clear-student-list-program-filter" type="button" ${selectedPrograms.length ? "" : "disabled"}>Сбросить</button>
          </div>
        </details>
        <label class="student-list-date-field-filter">
          <span>Дата</span>
          <select class="select-control" data-student-list-filter="dateField">
            <option value="">Без фильтра по дате</option>
            ${dateFields.map((item) => `<option value="${escapeAttr(item.key)}" ${filters.dateField === item.key ? "selected" : ""}>${escapeHtml(item.label)}</option>`).join("")}
          </select>
        </label>
        <label class="student-list-date-period-filter">
          <span>Период</span>
          <select class="select-control" data-student-list-filter="datePeriod" ${filters.dateField ? "" : "disabled"}>
            <option value="7" ${filters.datePeriod === "7" ? "selected" : ""}>Последние 7 дней</option>
            <option value="30" ${filters.datePeriod === "30" ? "selected" : ""}>Последние 30 дней</option>
            <option value="90" ${filters.datePeriod === "90" ? "selected" : ""}>Последние 90 дней</option>
            <option value="month" ${filters.datePeriod === "month" ? "selected" : ""}>Текущий месяц</option>
            <option value="year" ${filters.datePeriod === "year" ? "selected" : ""}>Текущий год</option>
            <option value="custom" ${!filters.datePeriod || filters.datePeriod === "custom" ? "selected" : ""}>Произвольный период</option>
          </select>
        </label>
        <label>
          <span>С</span>
          <input type="date" data-student-list-filter="dateFrom" value="${escapeAttr(filters.dateFrom || "")}" ${filters.dateField ? "" : "disabled"}>
        </label>
        <label>
          <span>По</span>
          <input type="date" data-student-list-filter="dateTo" value="${escapeAttr(filters.dateTo || "")}" ${filters.dateField ? "" : "disabled"}>
        </label>
        <button class="ghost-button" data-action="clear-student-list-filters" type="button" ${active ? "" : "disabled"}>Сбросить</button>
      </div>
    `;
  }

  function normalizeIssuedDocumentFilterText(value) {
    return String(value || "")
      .trim()
      .toLocaleLowerCase("ru-RU")
      .replace(/ё/g, "е")
      .replace(/\s+/g, " ");
  }

  function getIssuedDocumentProgramType(student = {}, programs = []) {
    const directType = normalizeEducationProgramType(student.educationType || student.programType || "");
    if (directType) return directType;
    const program = findProgramInRows(programs, student.program);
    return normalizeEducationProgramType(program?.type || program?.educationType || "");
  }

  function isIssuedDocumentDateValue(value) {
    const text = String(value || "").trim();
    return /^\d{4}-\d{2}-\d{2}(?:[T\s].*)?$/u.test(text)
      || /^\d{1,2}\.\d{1,2}\.\d{4}(?:[T\s].*)?$/u.test(text);
  }

  function getIssuedDocumentFrdoDetails(student = {}, programType = "") {
    const sourceStatus = String(student.frdoStatus || "").trim();
    const statusDate = isIssuedDocumentDateValue(sourceStatus) ? sourceStatus : "";
    const date = String(student.frdoDate || statusDate || "").trim();
    const statusText = statusDate ? "" : sourceStatus;
    const normalizedStatus = normalizeIssuedDocumentFilterText(statusText);
    const explicitlyNotExported = normalizedStatus.includes("не выгруж")
      || normalizedStatus.includes("не загруж")
      || normalizedStatus.includes("не отправ")
      || ["нет", "-", "0"].includes(normalizedStatus);
    const explicitlyExported = Boolean(date)
      || (!explicitlyNotExported && (
        statusText === "+"
        || statusText === "1"
        || normalizedStatus === "да"
        || normalizedStatus.includes("выгруж")
        || normalizedStatus.includes("загруж")
        || normalizedStatus.includes("отправ")
      ));
    if (explicitlyExported) {
      return { key: "exported", label: statusText && statusText !== "+" ? statusText : "Выгружено", date };
    }
    if (normalizedStatus.includes("не треб") || !isFrdoProgramType(programType)) {
      return { key: "not-required", label: "Не требуется", date: "" };
    }
    return { key: "pending", label: statusText || "Не выгружено", date: "" };
  }

  function getIssuedDocumentElapsedDays(issueDate, currentDate = todayIso()) {
    const issueTimestamp = parseTableSortDate(issueDate);
    const currentTimestamp = parseTableSortDate(currentDate);
    if (issueTimestamp === null || currentTimestamp === null) return null;
    return Math.max(0, Math.floor((currentTimestamp - issueTimestamp) / 86400000));
  }

  function getIssuedDocumentPlannedFrdoDate(issueDate, deadlineDays = getIssuedDocumentDeadlineDays()) {
    const issueTimestamp = parseTableSortDate(issueDate);
    if (issueTimestamp === null) return "";
    const safeDeadlineDays = Math.max(0, Number(deadlineDays) - FRDO_UPLOAD_RESERVE_DAYS);
    return new Date(issueTimestamp + safeDeadlineDays * 86400000).toISOString().slice(0, 10);
  }

  function getIssuedDocumentDeadlineTone(frdoKey, elapsedDays, deadlineDays = getIssuedDocumentDeadlineDays()) {
    if (frdoKey !== "pending" || elapsedDays === null) return "";
    const remainingDays = deadlineDays - elapsedDays;
    if (remainingDays < 10) return "danger";
    if (remainingDays < 20) return "warning";
    return "";
  }

  function getIssuedDocumentRows() {
    const programs = getProgramRows();
    return (state.data.collections.students || []).flatMap((student) => {
      const documentNumber = String(student.diplomaBlankNo || "").trim();
      const registrationNumber = String(student.registrationNo || "").trim();
      const issueDate = String(student.diplomaIssueDate || "").trim();
      if (!documentNumber) return [];
      const program = String(student.program || "").trim();
      const programType = getIssuedDocumentProgramType(student, programs);
      const frdo = getIssuedDocumentFrdoDetails(student, programType);
      const elapsedDays = getIssuedDocumentElapsedDays(issueDate);
      const deadlineDays = getIssuedDocumentDeadlineDays();
      const hasFrdoValue = Boolean(String(student.frdoDate || student.frdoStatus || "").trim());
      const plannedFrdoDate = frdo.key === "pending" && !hasFrdoValue
        ? getIssuedDocumentPlannedFrdoDate(issueDate, deadlineDays)
        : "";
      return [{
        id: `issued-document-${String(student.id || student.uid || documentNumber || registrationNumber)}`,
        studentId: String(student.id || ""),
        documentNumber,
        registrationNumber,
        issueDate,
        elapsedDays,
        remainingDays: elapsedDays === null ? null : deadlineDays - elapsedDays,
        deadlineDays,
        deadlineTone: getIssuedDocumentDeadlineTone(frdo.key, elapsedDays, deadlineDays),
        frdoKey: frdo.key,
        frdoLabel: plannedFrdoDate ? `до ${dateRu(plannedFrdoDate)}` : frdo.label,
        frdoDate: frdo.date,
        plannedFrdoDate,
        studentName: String(student.name || "").trim(),
        studentUid: String(student.uid || "").trim(),
        program,
        programType
      }];
    });
  }

  function isIssuedDocumentFrdoExportEligible(row = {}) {
    return row.frdoKey === "pending"
      && isFrdoProgramType(row.programType)
      && Boolean(String(row.documentNumber || "").trim());
  }

  function getIssuedDocumentsOpeningView(rows = []) {
    const hasPendingDocuments = rows.some(isIssuedDocumentFrdoExportEligible);
    return {
      frdo: hasPendingDocuments ? "pending" : "exported",
      sort: { key: "issueDate", dir: hasPendingDocuments ? "asc" : "desc" },
      autoFallback: !hasPendingDocuments
    };
  }

  function prepareIssuedDocumentsRegistryOnOpen(rows = getIssuedDocumentRows()) {
    const openingView = getIssuedDocumentsOpeningView(rows);
    state.issuedDocumentFilters = {
      documentNumber: "",
      issueDateFrom: "",
      issueDateTo: "",
      frdo: openingView.frdo,
      student: "",
      program: "",
      programType: ""
    };
    state.issuedDocumentSort = { ...openingView.sort };
    state.issuedDocumentAutoFallback = openingView.autoFallback;
    state.issuedDocumentViewInitialized = true;
    state.tablePages.issuedDocuments = 1;
    return openingView;
  }

  function buildIssuedDocumentFrdoExportRecords() {
    const studentsById = new Map(
      (state.data.collections.students || []).map((student) => [String(student.id || ""), student])
    );
    return getIssuedDocumentRows()
      .filter(isIssuedDocumentFrdoExportEligible)
      .map((row) => {
        const student = studentsById.get(String(row.studentId || ""));
        if (!student) return null;
        const program = findProgramByName(row.program) || {};
        return {
          documentNumber: row.documentNumber,
          registrationNumber: row.registrationNumber,
          issueDate: row.issueDate,
          program: row.program,
          programType: row.programType,
          frdoProfessionalArea: program.frdoProfessionalArea || "",
          qualification: student.qualification || "",
          programQualification: program.qualification || "",
          startDate: student.startDate || "",
          endDate: student.endDate || "",
          hours: student.hours || program.hours || "",
          name: student.name || "",
          birthDate: student.birthDate || "",
          gender: student.gender || "",
          snils: student.snils || "",
          studyForm: student.studyForm || program.studyForm || "",
          fundingSource: student.fundingSource || "",
          citizenship: student.citizenship || "",
          educationLevel: student.educationLevel || "",
          educationDocument: student.educationDocument || "",
          educationDocumentSeries: student.educationDocumentSeries || "",
          educationDocumentNumber: student.educationDocumentNumber || "",
          educationDocumentSurname: student.educationDocumentSurname || "",
          frdoStatus: student.frdoStatus || "",
          frdoDate: student.frdoDate || ""
        };
      })
      .filter(Boolean);
  }

  async function exportIssuedDocumentsToFrdo(button) {
    if (state.issuedDocumentExportRunning) return;
    const records = buildIssuedDocumentFrdoExportRecords();
    if (!records.length) {
      alert("Нет невыгруженных удостоверений или дипломов с заполненным номером документа для экспорта в ФРДО.");
      return;
    }
    state.issuedDocumentExportRunning = true;
    const originalText = button?.textContent || "Экспорт в ФРДО";
    if (button) {
      button.disabled = true;
      button.classList.add("is-loading");
      button.setAttribute("aria-busy", "true");
      button.textContent = "Формирование…";
    }
    try {
      const response = await fetch(photoApiUrl("/api/issued-documents/frdo-export"), {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          records,
          frdoExportFolder: getFrdoExportFolder()
        })
      });
      if (!response.ok) {
        const payload = await response.json().catch(() => ({}));
        throw new Error(payload.error || "Не удалось сформировать выгрузку ФРДО.");
      }
      const blob = await response.blob();
      const fallback = `ВыгрузкаДПО_${todayIso().replace(/-/g, ".")}.xls`;
      const fileName = getDownloadFileNameFromResponse(response, fallback);
      const saved = response.headers.get("X-Frdo-Saved") === "true";
      if (!saved) {
        downloadBlob(fileName, blob);
        return;
      }
      const storage = response.headers.get("X-Frdo-Storage") || "";
      const warning = decodeURIComponent(response.headers.get("X-Frdo-Warning") || "");
      if (storage === "webdav") {
        const relativeFolder = decodeURIComponent(response.headers.get("X-Frdo-Relative-Folder") || "")
          || getFrdoExportFolder();
        await openStudentWebDavDocumentsManager(relativeFolder, "", {
          title: "Выгрузки ФРДО",
          rootLabel: "ФРДО",
          selectedFileName: fileName,
          notice: `Файл «${fileName}» сохранён в облачную папку ФРДО.`
        });
      } else if (warning) {
        alert(`Файл «${fileName}» сохранён. ${warning}`);
      }
    } catch (error) {
      alert(error.message || "Не удалось сформировать выгрузку ФРДО.");
    } finally {
      state.issuedDocumentExportRunning = false;
      if (button?.isConnected) {
        button.disabled = false;
        button.classList.remove("is-loading");
        button.removeAttribute("aria-busy");
        button.textContent = originalText;
      }
    }
  }

  function issuedDocumentFiltersAreActive(filters = state.issuedDocumentFilters || {}) {
    return Object.values(filters).some((value) => String(value || "").trim());
  }

  function issuedDocumentRowMatchesFilters(row, filters = state.issuedDocumentFilters || {}) {
    const contains = (value, query) => !query
      || normalizeIssuedDocumentFilterText(value).includes(normalizeIssuedDocumentFilterText(query));
    if (!contains(`${row.documentNumber} ${row.registrationNumber}`, filters.documentNumber)) return false;
    if (!contains(`${row.studentName} ${row.studentUid}`, filters.student)) return false;
    if (filters.program && row.program !== filters.program) return false;
    if (filters.programType && row.programType !== filters.programType) return false;
    if (filters.frdo && row.frdoKey !== filters.frdo) return false;
    const issueTimestamp = parseTableSortDate(row.issueDate);
    const fromTimestamp = parseTableSortDate(filters.issueDateFrom);
    const toTimestamp = parseTableSortDate(filters.issueDateTo);
    if (fromTimestamp !== null && (issueTimestamp === null || issueTimestamp < fromTimestamp)) return false;
    if (toTimestamp !== null && (issueTimestamp === null || issueTimestamp > toTimestamp)) return false;
    return true;
  }

  function getIssuedDocumentSortValue(row, key) {
    if (key === "frdo") return row.frdoLabel;
    if (key === "student") return row.studentName;
    if (key === "documentNumber") return row.documentNumber || row.registrationNumber;
    return row[key] ?? "";
  }

  function sortIssuedDocumentRows(rows) {
    const sort = state.issuedDocumentSort || { key: "issueDate", dir: "asc" };
    const direction = sort.dir === "desc" ? -1 : 1;
    const dateKeys = new Set(["issueDate", "frdoDate"]);
    return rows.map((row, index) => ({ row, index })).sort((leftEntry, rightEntry) => {
      const left = getIssuedDocumentSortValue(leftEntry.row, sort.key);
      const right = getIssuedDocumentSortValue(rightEntry.row, sort.key);
      const leftEmpty = String(left ?? "").trim() === "";
      const rightEmpty = String(right ?? "").trim() === "";
      if (leftEmpty !== rightEmpty) return leftEmpty ? 1 : -1;
      let comparison = 0;
      if (sort.key === "elapsedDays") {
        comparison = Number(left) - Number(right);
      } else if (dateKeys.has(sort.key)) {
        const leftDate = parseTableSortDate(left);
        const rightDate = parseTableSortDate(right);
        if (leftDate === null && rightDate !== null) return 1;
        if (leftDate !== null && rightDate === null) return -1;
        comparison = (leftDate || 0) - (rightDate || 0);
      } else {
        comparison = String(left).localeCompare(String(right), "ru", { numeric: true, sensitivity: "base" });
      }
      if (comparison) return comparison * direction;
      return leftEntry.index - rightEntry.index;
    }).map((entry) => entry.row);
  }

  function getVisibleIssuedDocumentRows(rows = getIssuedDocumentRows()) {
    return sortIssuedDocumentRows(rows.filter((row) => issuedDocumentRowMatchesFilters(row)));
  }

  function renderIssuedDocumentSortHeader(key, label) {
    const sort = state.issuedDocumentSort || {};
    const active = sort.key === key;
    const directionLabel = sort.dir === "desc" ? "по убыванию" : "по возрастанию";
    return `
      <button
        class="issued-document-sort-button ${active ? "is-active" : ""}"
        data-action="sort-issued-documents"
        data-sort-key="${escapeAttr(key)}"
        type="button"
        title="Сортировать ${active ? directionLabel : "по этому столбцу"}"
      >
        <span>${escapeHtml(label)}</span>
        <span class="issued-document-sort-indicator" aria-hidden="true">${active ? (sort.dir === "desc" ? "↓" : "↑") : "↕"}</span>
      </button>
    `;
  }

  function renderIssuedDocumentTableCell(row, column) {
    const attrs = columnDataAttrs(ISSUED_DOCUMENT_TABLE_CONFIG_ID, column.key);
    const style = issuedDocumentColumnStyleAttr(column);
    if (column.key === "student") {
      return `
        <td ${attrs} ${style}>
          <button class="table-edit-link issued-document-student-link" data-action="open-issued-document-student" data-student-id="${escapeAttr(row.studentId)}" type="button">
            ${escapeHtml(row.studentName || "Без ФИО")}
          </button>
          ${row.studentUid ? `<small>uid ${escapeHtml(row.studentUid)}</small>` : ""}
        </td>
      `;
    }
    if (column.key === "documentNumber") {
      return `
        <td ${attrs} ${style}>
          <strong>${escapeHtml(row.documentNumber || row.registrationNumber || "—")}</strong>
          ${row.documentNumber && row.registrationNumber ? `<small>Рег. № ${escapeHtml(row.registrationNumber)}</small>` : ""}
        </td>
      `;
    }
    if (column.key === "issueDate") {
      return `<td ${attrs} ${style}>${row.issueDate ? escapeHtml(dateRu(row.issueDate)) : "—"}</td>`;
    }
    if (column.key === "elapsedDays") {
      return `
        <td
          class="issued-document-days-cell"
          ${attrs}
          ${style}
          title="${row.elapsedDays === null ? "Дата выдачи не указана" : escapeAttr(`Норматив: ${row.deadlineDays} дней. Осталось: ${row.remainingDays} дней.`)}"
        >${row.elapsedDays === null ? "—" : escapeHtml(String(row.elapsedDays))}</td>
      `;
    }
    if (column.key === "frdo") {
      const deadlineTitle = row.plannedFrdoDate
        ? `Расчётный срок: норматив ${row.deadlineDays} дней минус резерв ${FRDO_UPLOAD_RESERVE_DAYS} дней.`
        : "";
      return `
        <td ${attrs} ${style}>
          <span class="issued-document-frdo-status is-${escapeAttr(row.frdoKey)}" ${deadlineTitle ? `title="${escapeAttr(deadlineTitle)}"` : ""}>${escapeHtml(row.frdoLabel)}</span>
          ${row.frdoDate ? `<small>${escapeHtml(dateRu(row.frdoDate))}</small>` : ""}
        </td>
      `;
    }
    if (column.key === "program") {
      return `<td ${attrs} ${style}>${escapeHtml(row.program || "—")}</td>`;
    }
    return `<td ${attrs} ${style}>${escapeHtml(row.programType || "—")}</td>`;
  }

  function renderIssuedDocumentsRegistry() {
    const allRows = getIssuedDocumentRows();
    if (!state.issuedDocumentViewInitialized) prepareIssuedDocumentsRegistryOnOpen(allRows);
    const rows = getVisibleIssuedDocumentRows(allRows);
    const filters = state.issuedDocumentFilters || {};
    const programs = unique(allRows.map((row) => row.program).filter(Boolean))
      .sort((left, right) => left.localeCompare(right, "ru", { numeric: true, sensitivity: "base" }));
    const programTypes = unique(allRows.map((row) => row.programType).filter(Boolean))
      .sort((left, right) => left.localeCompare(right, "ru", { numeric: true, sensitivity: "base" }));
    const pagination = getTablePagination("issuedDocuments", rows.length);
    const pageRows = rows.slice(pagination.start, pagination.end);
    const columns = getTableFields(issuedDocumentTableConfig, ISSUED_DOCUMENT_TABLE_CONFIG_ID);
    const exportedCount = allRows.filter((row) => row.frdoKey === "exported").length;
    const pendingCount = allRows.filter((row) => row.frdoKey === "pending").length;
    return `
      <section class="panel issued-documents-register" data-issued-documents-register data-main-registry>
        <div class="issued-documents-summary" aria-label="Сводка реестра">
          <span>Всего: <strong>${allRows.length}</strong></span>
          <span class="is-success">Выгружено в ФРДО: <strong>${exportedCount}</strong></span>
          <span class="${pendingCount ? "is-warning" : ""}">Ожидают ФРДО: <strong>${pendingCount}</strong></span>
          <div class="issued-documents-filter-actions">
            <button class="primary-button issued-documents-frdo-export-button" data-action="export-issued-documents-frdo" type="button" ${pendingCount && !state.issuedDocumentExportRunning ? "" : "disabled"}>Экспорт в ФРДО</button>
            <span>Показано <strong>${rows.length}</strong> из ${allRows.length}</span>
            <button class="ghost-button" data-action="reset-issued-document-filters" type="button" ${issuedDocumentFiltersAreActive(filters) ? "" : "disabled"}>Сбросить</button>
            <button class="ghost-button icon-only table-options-button" data-action="toggle-table-options" data-config="${ISSUED_DOCUMENT_TABLE_CONFIG_ID}" type="button" title="Опции таблицы" aria-label="Опции таблицы">⋯</button>
          </div>
        </div>
        ${renderTableOptions(ISSUED_DOCUMENT_TABLE_CONFIG_ID)}
        ${state.issuedDocumentAutoFallback ? `
          <div class="issued-documents-auto-fallback" role="status">
            Документов для выгрузки в ФРДО нет. Показаны ранее выгруженные документы, начиная с последних выданных.
          </div>
        ` : ""}
        <div class="issued-documents-filters" data-issued-document-filters>
          <label>
            <span>Номер документа</span>
            <input data-issued-document-filter="documentNumber" value="${escapeAttr(filters.documentNumber || "")}" placeholder="Номер бланка или рег. номер">
          </label>
          <label>
            <span>ФИО слушателя</span>
            <input data-issued-document-filter="student" value="${escapeAttr(filters.student || "")}" placeholder="ФИО или uid">
          </label>
          <label class="issued-documents-program-filter">
            <span>Образовательная программа</span>
            <select class="select-control" data-issued-document-filter="program">
              <option value="">Все программы</option>
              ${programs.map((program) => `<option value="${escapeAttr(program)}" ${filters.program === program ? "selected" : ""}>${escapeHtml(program)}</option>`).join("")}
            </select>
          </label>
          <label>
            <span>Вид программы</span>
            <select class="select-control" data-issued-document-filter="programType">
              <option value="">Все виды</option>
              ${programTypes.map((type) => `<option value="${escapeAttr(type)}" ${filters.programType === type ? "selected" : ""}>${escapeHtml(type)}</option>`).join("")}
            </select>
          </label>
          <label>
            <span>Выгрузка в ФРДО</span>
            <select class="select-control" data-issued-document-filter="frdo">
              <option value="">Все состояния</option>
              <option value="exported" ${filters.frdo === "exported" ? "selected" : ""}>Выгружено</option>
              <option value="pending" ${filters.frdo === "pending" ? "selected" : ""}>Не выгружено</option>
              <option value="not-required" ${filters.frdo === "not-required" ? "selected" : ""}>Не требуется</option>
            </select>
          </label>
          <label>
            <span>Дата выдачи с</span>
            <input type="date" data-issued-document-filter="issueDateFrom" value="${escapeAttr(filters.issueDateFrom || "")}">
          </label>
          <label>
            <span>Дата выдачи по</span>
            <input type="date" data-issued-document-filter="issueDateTo" value="${escapeAttr(filters.issueDateTo || "")}">
          </label>
        </div>
        ${rows.length ? `
          <div class="table-wrap issued-documents-table-wrap">
            <table class="data-table issued-documents-table">
              <thead>
                <tr>
                  ${columns.map((column) => `
                    <th
                      class="table-column-head"
                      ${columnDataAttrs(ISSUED_DOCUMENT_TABLE_CONFIG_ID, column.key)}
                      ${issuedDocumentColumnStyleAttr(column)}
                      draggable="true"
                      title="Перетащите заголовок для смены порядка"
                    >
                      <div class="table-head-cell">
                        ${renderIssuedDocumentSortHeader(column.key, column.label)}
                        <span class="column-resize-handle" data-action="resize-column" data-config="${ISSUED_DOCUMENT_TABLE_CONFIG_ID}" data-field="${escapeAttr(column.key)}" title="Изменить ширину"></span>
                      </div>
                    </th>
                  `).join("")}
                </tr>
              </thead>
              <tbody>
                ${pageRows.map((row) => `
                  <tr class="${row.deadlineTone ? `is-frdo-deadline-${escapeAttr(row.deadlineTone)}` : ""}">
                    ${columns.map((column) => renderIssuedDocumentTableCell(row, column)).join("")}
                  </tr>
                `).join("")}
              </tbody>
            </table>
          </div>
          ${renderTablePagination("issuedDocuments", rows.length, pagination)}
        ` : `<div class="empty-state"><strong>${allRows.length ? "По заданным фильтрам документов нет" : "Выданных документов пока нет"}</strong><span>${allRows.length ? "Измените или сбросьте фильтры." : "Записи появятся после заполнения номера документа или даты выдачи в карточке слушателя."}</span></div>`}
      </section>
    `;
  }

  function renderCollection(config) {
    const rows = getVisibleRows(config);
    const statuses = state.view === "generalExpenses" ? [] : getFilterOptions(config);
    const statusDictionary = config.fields.find((item) => item.key === "status")?.dict || "";
    const directExpenseNoteOptions = state.view === "directExpenses"
      ? getDirectExpenseNoteFilterOptions()
      : [];
    const importedViewIds = state.view === "students"
      ? (state.studentImportedViewIds || [])
      : [];
    const importedViewCount = state.view === "students"
      ? importedViewIds.filter((id) => (
        (state.data.collections.students || []).some((student) => String(student.id) === String(id))
      )).length
      : 0;
    return `
      <section class="panel collection-register" data-main-registry>
        <div class="section-head">
          <div class="collection-section-heading ${state.view === "directExpenses" ? "direct-expenses-section-heading" : ""}">
            <p class="eyebrow">${config.subtitle}</p>
            <h2>${config.title}</h2>
          </div>
          <div class="toolbar">
            <label class="search-box">
              <span>⌕</span>
              <input id="searchInput" value="${escapeAttr(state.search)}" placeholder="Поиск" autocomplete="off">
            </label>
            ${state.view === "directExpenses" ? `
              <div class="combo-field direct-expense-note-filter" data-direct-expense-note-filter>
                <div class="search-box combo-input-wrap">
                  <span>⌕</span>
                  <input
                    id="directExpenseNoteFilter"
                    value="${escapeAttr(state.directExpenseNoteFilter)}"
                    placeholder="Примечание"
                    autocomplete="off"
                    aria-label="Фильтр по примечанию"
                    aria-haspopup="listbox"
                    aria-expanded="false"
                    aria-controls="directExpenseNoteFilterOptions"
                  >
                  <button
                    class="direct-expense-note-filter-toggle"
                    data-action="toggle-direct-expense-note-filter"
                    type="button"
                    title="Показать список примечаний"
                    aria-label="Показать список примечаний"
                    tabindex="-1"
                  >
                    <svg viewBox="0 0 20 20" aria-hidden="true"><path d="m5 7 5 6 5-6"></path></svg>
                  </button>
                </div>
                <div class="combo-options direct-expense-note-filter-options" id="directExpenseNoteFilterOptions" data-direct-expense-note-filter-options role="listbox">
                  <button
                    class="${state.directExpenseNoteFilter ? "" : "is-selected"}"
                    data-action="select-direct-expense-note-filter"
                    data-value=""
                    type="button"
                    role="option"
                    aria-selected="${state.directExpenseNoteFilter ? "false" : "true"}"
                  >Все примечания</button>
                  ${directExpenseNoteOptions.map((value) => {
                    const selected = value === state.directExpenseNoteFilter;
                    return `
                      <button
                        class="${selected ? "is-selected" : ""}"
                        data-action="select-direct-expense-note-filter"
                        data-value="${escapeAttr(value)}"
                        type="button"
                        role="option"
                        aria-selected="${selected ? "true" : "false"}"
                      >${escapeHtml(value)}</button>
                    `;
                  }).join("")}
                  <div class="combo-empty" data-direct-expense-note-filter-empty hidden>Совпадений не найдено</div>
                </div>
              </div>
            ` : ""}
            ${statuses.length ? `
              <select
                id="statusFilter"
                class="select-control ${state.view === "students" ? "student-status-filter" : ""}"
                ${state.view === "students" ? 'aria-label="Фильтр слушателей по статусу" title="Фильтр слушателей по статусу"' : ""}
                ${statusDictionary ? `data-settings-dictionary="${escapeAttr(statusDictionary)}"` : ""}
              >
                ${["Все", ...statuses].map((item) => `<option ${state.statusFilter === item ? "selected" : ""}>${escapeHtml(item)}</option>`).join("")}
              </select>
            ` : ""}
            ${state.view === "generalExpenses" ? `
              ${renderGeneralExpenseSectionFilter()}
              ${renderGeneralExpenseWorkTypeFilter()}
            ` : ""}
            ${state.view === "students" ? renderStudentProgramTypeFilter() : ""}
            ${state.view === "programs" ? renderProgramRegistryTypeFilter() : ""}
            ${state.view === "contracts" ? renderContractSectionFilter() : ""}
            <div class="collection-toolbar-actions">
              ${state.view === "students" ? `<button class="ghost-button student-applications-import-button" data-action="open-student-applications-import" type="button">Импорт слушателей</button>` : ""}
              <button class="ghost-button" data-action="export-csv" data-config="${state.view}" type="button">CSV</button>
              <button class="primary-button" data-action="create" data-config="${state.view}" type="button">Добавить</button>
            </div>
          </div>
        </div>
        ${state.view === "students" ? renderStudentListAdvancedFilters() : ""}
        ${importedViewIds.length ? `
          <div class="student-imported-view-bar" role="status">
            <span>Показаны импортированные заявки: <strong>${importedViewCount}</strong></span>
            <button class="ghost-button" data-action="clear-student-imported-view" type="button">Показать всех</button>
          </div>
        ` : ""}
        ${renderBulkToolbar(config, rows, state.view)}
        ${renderTable(config, rows, state.view)}
      </section>
    `;
  }

  function getStudentApplicationsDefaultDates(days = 30, referenceDate = new Date()) {
    const dateTo = new Date(referenceDate);
    const dateFrom = new Date(dateTo);
    dateFrom.setDate(dateFrom.getDate() - days);
    const format = (date) => [
      date.getFullYear(),
      String(date.getMonth() + 1).padStart(2, "0"),
      String(date.getDate()).padStart(2, "0")
    ].join("-");
    return { dateFrom: format(dateFrom), dateTo: format(dateTo) };
  }

  function getStudentApplicationsAllTimeDates(referenceDate = new Date()) {
    return {
      dateFrom: "1970-01-01",
      dateTo: getStudentApplicationsDefaultDates(0, referenceDate).dateTo
    };
  }

  function openStudentApplicationsImport() {
    const dates = getStudentApplicationsDefaultDates(30);
    state.tableOptions = null;
    state.studentApplicationsImport = {
      open: true,
      loading: false,
      importing: false,
      rows: [],
      page: 1,
      pageSize: 100,
      selected: [],
      selectedPayment: 0,
      activeId: "",
      truncated: false,
      error: "",
      warnings: [],
      sort: { ...STUDENT_APPLICATIONS_IMPORT_DEFAULT_SORT },
      filters: {
        programId: "",
        programIds: [],
        programQuery: "",
        period: "30",
        ...dates,
        onlyPaid: false,
        search: "",
        status: "На зачисление"
      }
    };
    refreshStudentApplicationsImportDialog();
  }

  function closeStudentApplicationsImport() {
    if (state.studentApplicationsImport.importing) return;
    clearTimeout(studentApplicationsSearchTimer);
    state.studentApplicationsImport.open = false;
    state.studentApplicationsImport.loading = false;
    if (state.tableOptions === STUDENT_APPLICATIONS_IMPORT_TABLE_CONFIG_ID) state.tableOptions = null;
    document.querySelector("[data-student-applications-import-backdrop]")?.remove();
  }

  function getStudentApplicationsSelectedProgramIds(filters = state.studentApplicationsImport.filters || {}) {
    const values = Array.isArray(filters.programIds) && filters.programIds.length
      ? filters.programIds
      : [filters.programId];
    return unique(values.map((value) => String(value || "").trim()).filter(Boolean));
  }

  function getStudentApplicationsSingleProgramFilterId(filters = state.studentApplicationsImport.filters || {}) {
    const selectedIds = getStudentApplicationsSelectedProgramIds(filters);
    return selectedIds.length === 1 ? selectedIds[0] : "";
  }

  function getStudentApplicationsProgramFilterLabel(filters = state.studentApplicationsImport.filters || {}) {
    const selectedIds = getStudentApplicationsSelectedProgramIds(filters);
    if (!selectedIds.length) return "Все программы";
    if (selectedIds.length > 1) return `Выбрано: ${selectedIds.length}`;
    return getProgramRows().find((program) => String(program.id || "") === selectedIds[0])?.name
      || "Выбрана 1 программа";
  }

  function applyStudentApplicationsProgramSearch(query, root = document) {
    const normalizedQuery = normalizeStudentListProgramQuery(query);
    let visibleCount = 0;
    root.querySelectorAll("[data-student-applications-program-option-row]").forEach((row) => {
      const label = normalizeStudentListProgramQuery(row.textContent);
      const hidden = Boolean(normalizedQuery && !label.includes(normalizedQuery));
      row.hidden = hidden;
      if (!hidden) visibleCount += 1;
    });
    const empty = root.querySelector("[data-student-applications-program-filter-empty]");
    if (empty) empty.hidden = visibleCount > 0;
  }

  function refreshStudentApplicationsImportDialog(options = {}) {
    if (!state.studentApplicationsImport.open) return;
    const current = document.querySelector("[data-student-applications-import-backdrop]");
    const tableWrap = current?.querySelector(".student-applications-import-table-wrap");
    const scrollLeft = tableWrap?.scrollLeft || 0;
    const scrollTop = tableWrap?.scrollTop || 0;
    const html = renderStudentApplicationsImport();
    if (current) current.insertAdjacentHTML("beforebegin", html);
    else app.insertAdjacentHTML("beforeend", html);
    current?.remove();
    const next = document.querySelector("[data-student-applications-import-backdrop]");
    if (!next) return;
    bindStudentApplicationsImportEvents(next);
    const nextTableWrap = next.querySelector(".student-applications-import-table-wrap");
    if (nextTableWrap) {
      nextTableWrap.scrollLeft = scrollLeft;
      nextTableWrap.scrollTop = scrollTop;
    }
    if (options.focusSearch) {
      requestAnimationFrame(() => {
        const input = next.querySelector("[name='applicationSearch']");
        if (!input) return;
        const cursor = Math.min(Number(options.searchCursor) || input.value.length, input.value.length);
        input.focus({ preventScroll: true });
        input.setSelectionRange(cursor, cursor);
      });
    }
  }

  function getStudentApplicationSourceKey(row) {
    const orderId = String(row?.orderId || "").trim();
    const lineId = String(row?.id || "").trim();
    const sourceType = String(row?.sourceType || "mysql").trim().toLowerCase();
    return orderId && lineId ? `${sourceType}:${orderId}:${lineId}` : "";
  }

  function getStudentApplicationProgramTitle(row) {
    return String(row?.program || "")
      .replace(/\s*\[\s*\d+\s*\]\s*$/u, "")
      .trim();
  }

  function getStudentApplicationCanonicalProgramTitle(value) {
    return String(value || "")
      .replace(/\s*\[\s*\d+\s*\]\s*$/u, "")
      .replace(
        /^(?:(?:он[\s-]*лайн[- ]?)?курс|программа)\s+(?:(?:профессиональной\s+)?переподготовки|повышения\s+квалификации|дополнительного(?:\s+профессионального)?\s+образования)\s*[:\-–—]?\s*/iu,
        ""
      )
      .replace(/^(?:(?:онлайн[- ]?)?курс|программа)\s*[:\-–—]\s*/iu, "")
      .replace(/^[\s"'«»]+|[\s"'«»]+$/gu, "")
      .trim();
  }

  function normalizeStudentApplicationProgramName(value) {
    return normalizeProgramName(getStudentApplicationCanonicalProgramTitle(value))
      .replace(/\s*\(\s*\d+(?:[.,]\d+)?\s*(?:ч|час|часа|часов)(?:\s*\/[^)]*)?\)\s*$/iu, "")
      .trim();
  }

  function getStudentApplicationInferredProgramType(row) {
    const title = (getStudentApplicationProgramTitle(row) || [row?.order, row?.note].filter(Boolean).join(" "))
      .toLocaleLowerCase("ru-RU")
      .replace(/ё/g, "е");
    if (/переподготовк/iu.test(title)) return "ППП";
    if (/повышени\S*\s+квалификац/iu.test(title)) return "КПК";
    if (/курс\S*\s+дополнительн\S*\s+образован/iu.test(title)) return "ДОП";
    if (/он[\s-]*лайн|вебинар|семинар/iu.test(title)) return "ПРО";
    return "";
  }

  function studentApplicationProgramMatchesInferredType(program, inferredType) {
    const requiredType = normalizeEducationProgramType(inferredType);
    return !requiredType || normalizeEducationProgramType(program?.type) === requiredType;
  }

  function normalizeStudentApplicationProgramMappings(values) {
    return (Array.isArray(values) ? values : [])
      .map((item) => ({
        sourceProgram: String(item?.sourceProgram || "").trim(),
        sourceProgramNormalized: normalizeStudentApplicationProgramName(
          item?.sourceProgramNormalized || item?.sourceProgram
        ),
        sourceProductId: String(item?.sourceProductId || "").trim(),
        sourceType: String(item?.sourceType || "").trim().toLocaleLowerCase("ru-RU"),
        programId: String(item?.programId || "").trim(),
        programName: String(item?.programName || "").trim(),
        updatedAt: String(item?.updatedAt || "").trim(),
        updatedBy: String(item?.updatedBy || "").trim()
      }))
      .filter((item) => item.sourceProgramNormalized && (item.programId || item.programName));
  }

  function getStudentApplicationProgramMappingSource(row) {
    const sourceProgram = getStudentApplicationProgramTitle(row);
    return {
      sourceProgram,
      sourceProgramNormalized: normalizeStudentApplicationProgramName(sourceProgram),
      sourceProductId: String(row?.productId || "").trim(),
      sourceType: String(row?.sourceType || "").trim().toLocaleLowerCase("ru-RU")
    };
  }

  function getStoredStudentApplicationProgramMapping(row) {
    const source = getStudentApplicationProgramMappingSource(row);
    const mappings = normalizeStudentApplicationProgramMappings(
      state.data?.meta?.studentApplicationProgramMappings
    ).filter((item) => (
      item.sourceProgramNormalized === source.sourceProgramNormalized
      && (!item.sourceType || !source.sourceType || item.sourceType === source.sourceType)
    ));
    if (!mappings.length) return null;
    const exactProductMappings = source.sourceProductId
      ? mappings.filter((item) => item.sourceProductId === source.sourceProductId)
      : [];
    const candidates = exactProductMappings.length ? exactProductMappings : mappings;
    const programIds = unique(candidates.map((item) => item.programId || item.programName).filter(Boolean));
    return programIds.length === 1 ? candidates[0] : null;
  }

  function resolveStoredStudentApplicationProgram(row) {
    const mapping = getStoredStudentApplicationProgramMapping(row);
    if (!mapping) return null;
    const programs = state.data.collections.programs || [];
    const storedProgram = programs.find((program) => (
      String(program.id || "") === mapping.programId
    ));
    if (storedProgram) return storedProgram;
    const normalizedMappedName = normalizeProgramName(mapping.programName);
    return getProgramRows().find((program) => (
      [program.name, program.shortName].some((name) => normalizeProgramName(name) === normalizedMappedName)
    )) || null;
  }

  function getStudentApplicationProgramHours(value, fallback = "") {
    const match = String(value || "").match(
      /(?:^|[\s(])([0-9]+(?:[.,][0-9]+)?)\s*(?:ч|час|часа|часов)(?=$|[\s)/"'«»])/iu
    );
    const parsed = Number(String(match?.[1] || fallback || "").replace(",", "."));
    return Number.isFinite(parsed) && parsed > 0 ? String(parsed) : "";
  }

  function getStudentApplicationProgramIdentity(value, fallbackHours = "") {
    const name = normalizeStudentApplicationProgramName(value);
    if (!name) return "";
    const hours = getStudentApplicationProgramHours(value, fallbackHours);
    return hours ? `${name}\u0001hours:${hours}` : name;
  }

  function getStudentApplicationProgramMatchTokens(value) {
    const ignored = ["курс", "программа", "обучение", "образование"];
    return normalizeStudentApplicationProgramName(value)
      .replace(/[^a-zа-я0-9]+/giu, " ")
      .split(/\s+/u)
      .map((item) => item.trim())
      .filter((item) => item.length > 1 && !ignored.includes(item));
  }

  function getStudentApplicationProgramBigrams(value) {
    const text = normalizeStudentApplicationProgramName(value).replace(/[^a-zа-я0-9]+/giu, "");
    if (text.length < 2) return text ? [text] : [];
    const values = [];
    for (let index = 0; index < text.length - 1; index += 1) values.push(text.slice(index, index + 2));
    return values;
  }

  function buildStudentApplicationProgramMatchFeatures(value) {
    const normalized = normalizeStudentApplicationProgramName(value);
    const bigrams = getStudentApplicationProgramBigrams(normalized);
    const bigramCounts = new Map();
    bigrams.forEach((item) => bigramCounts.set(item, (bigramCounts.get(item) || 0) + 1));
    return {
      normalized,
      tokens: new Set(getStudentApplicationProgramMatchTokens(normalized)),
      bigrams,
      bigramCounts
    };
  }

  function getStudentApplicationProgramSimilarity(source, target) {
    const sourceName = source.normalized;
    const targetName = target.normalized;
    if (!sourceName || !targetName) return 0;
    if (sourceName === targetName) return 1;
    const sourceTokens = source.tokens;
    const targetTokens = target.tokens;
    const commonTokens = [...sourceTokens].filter((item) => targetTokens.has(item)).length;
    const sourceCoverage = sourceTokens.size ? commonTokens / sourceTokens.size : 0;
    const targetCoverage = targetTokens.size ? commonTokens / targetTokens.size : 0;
    const tokenScore = sourceCoverage * 0.65 + targetCoverage * 0.35;
    const sourceBigrams = source.bigrams;
    const targetBigrams = target.bigrams;
    let commonBigrams = 0;
    source.bigramCounts.forEach((count, item) => {
      commonBigrams += Math.min(count, target.bigramCounts.get(item) || 0);
    });
    const bigramScore = sourceBigrams.length + targetBigrams.length
      ? (2 * commonBigrams) / (sourceBigrams.length + targetBigrams.length)
      : 0;
    const shorterLength = Math.min(sourceName.length, targetName.length);
    const longerLength = Math.max(sourceName.length, targetName.length);
    const containmentScore = (sourceName.includes(targetName) || targetName.includes(sourceName)) && longerLength
      ? 0.72 + 0.24 * (shorterLength / longerLength)
      : 0;
    return Math.max(tokenScore, bigramScore, containmentScore);
  }

  function buildStudentApplicationProgramMatchContext() {
    const programs = getProgramRows();
    const entries = programs.map((program) => ({
      program,
      id: String(program.id || ""),
      productId: String(program.landingCode || "").trim(),
      hours: getStudentApplicationProgramHours(program.name, program.hours),
      names: unique([program.name, program.shortName].map((value) => String(value || "").trim()).filter(Boolean))
        .map((value) => ({ value, features: buildStudentApplicationProgramMatchFeatures(value) }))
    }));
    const byId = new Map(entries.map((entry) => [entry.id, entry.program]).filter(([id]) => id));
    const byRawName = new Map();
    const byComparableName = new Map();
    const byProductId = new Map();
    entries.forEach((entry) => entry.names.forEach((name) => {
      const key = normalizeProgramName(name.value);
      if (key) {
        const values = byRawName.get(key) || [];
        if (!values.includes(entry)) values.push(entry);
        byRawName.set(key, values);
      }
      if (name.features.normalized) {
        const values = byComparableName.get(name.features.normalized) || [];
        if (!values.includes(entry)) values.push(entry);
        byComparableName.set(name.features.normalized, values);
      }
    }));
    entries.forEach((entry) => {
      if (!entry.productId) return;
      const values = byProductId.get(entry.productId) || [];
      values.push(entry);
      byProductId.set(entry.productId, values);
    });
    const mappings = normalizeStudentApplicationProgramMappings(
      state.data?.meta?.studentApplicationProgramMappings
    );
    const mappingsBySourceName = new Map();
    mappings.forEach((mapping) => {
      const values = mappingsBySourceName.get(mapping.sourceProgramNormalized) || [];
      values.push(mapping);
      mappingsBySourceName.set(mapping.sourceProgramNormalized, values);
    });
    return {
      programs,
      entries,
      byId,
      byRawName,
      byComparableName,
      byProductId,
      mappingsBySourceName
    };
  }

  function resolveStudentApplicationProgramMatch(row, context = buildStudentApplicationProgramMatchContext()) {
    const source = getStudentApplicationProgramMappingSource(row);
    const inferredType = getStudentApplicationInferredProgramType(row);
    const matchesInferredType = (program) => (
      studentApplicationProgramMatchesInferredType(program, inferredType)
    );
    const filterEntriesByType = (entries) => (
      (entries || []).filter((entry) => matchesInferredType(entry.program))
    );
    const mapped = (context.mappingsBySourceName.get(source.sourceProgramNormalized) || [])
      .filter((item) => !item.sourceType || !source.sourceType || item.sourceType === source.sourceType);
    const exactProductMappings = source.sourceProductId
      ? mapped.filter((item) => item.sourceProductId === source.sourceProductId)
      : [];
    const mappedCandidates = exactProductMappings.length ? exactProductMappings : mapped;
    const mappedPrograms = unique(mappedCandidates.map((item) => item.programId || item.programName).filter(Boolean))
      .map((value) => context.byId.get(value)
        || (context.byRawName.get(normalizeProgramName(value)) || [])
          .find((entry) => matchesInferredType(entry.program))?.program)
      .filter((program) => program && matchesInferredType(program));
    if (mappedPrograms.length === 1) {
      return { programId: String(mappedPrograms[0].id || ""), kind: "stored", score: 1 };
    }

    if (source.sourceProductId) {
      const productMatches = filterEntriesByType(context.byProductId.get(source.sourceProductId));
      if (productMatches.length === 1) {
        return { programId: productMatches[0].id, kind: "product", score: 1 };
      }
    }

    const sourceTitle = getStudentApplicationProgramTitle(row);
    const rawMatches = filterEntriesByType(context.byRawName.get(normalizeProgramName(sourceTitle)));
    if (rawMatches.length === 1) return { programId: rawMatches[0].id, kind: "exact", score: 1 };

    const comparableTitle = normalizeStudentApplicationProgramName(sourceTitle);
    const sourceHours = getStudentApplicationProgramHours(sourceTitle);
    const comparableMatches = filterEntriesByType(context.byComparableName.get(comparableTitle));
    if (sourceHours) {
      const matchingHours = comparableMatches.filter((entry) => entry.hours === sourceHours);
      if (matchingHours.length === 1) {
        return { programId: matchingHours[0].id, kind: "exact", score: 1 };
      }
    }
    if (comparableMatches.length === 1) {
      return { programId: comparableMatches[0].id, kind: "exact", score: 0.99 };
    }

    const sourceFeatures = buildStudentApplicationProgramMatchFeatures(sourceTitle);
    const ranked = filterEntriesByType(context.entries).map((entry) => {
      let score = Math.max(...entry.names.map((name) => (
        getStudentApplicationProgramSimilarity(sourceFeatures, name.features)
      )), 0);
      if (sourceHours && entry.hours) score += sourceHours === entry.hours ? 0.08 : -0.16;
      return { entry, score: Math.max(0, Math.min(1, score)) };
    }).sort((left, right) => right.score - left.score || compareProgramNames(left.entry.program.name, right.entry.program.name));
    const best = ranked[0];
    if (!best || best.score < 0.5) return null;
    const margin = best.score - (ranked[1]?.score || 0);
    const confident = best.score >= 0.9 && margin >= 0.06;
    return {
      programId: best.entry.id,
      kind: confident ? "automatic" : "suggested",
      score: best.score
    };
  }

  async function prepareStudentApplicationRows(rows) {
    const context = buildStudentApplicationProgramMatchContext();
    const prepared = [];
    const matchCache = new Map();
    for (let index = 0; index < rows.length; index += 1) {
      const row = rows[index];
      const source = getStudentApplicationProgramMappingSource(row);
      const matchKey = [
        source.sourceProgramNormalized,
        source.sourceProductId,
        source.sourceType
      ].join("\u0000");
      if (!matchCache.has(matchKey)) {
        matchCache.set(matchKey, resolveStudentApplicationProgramMatch(row, context));
      }
      prepared.push({ ...row, _programMatch: matchCache.get(matchKey) });
      if (index > 0 && index % 250 === 0) {
        await new Promise((resolve) => requestAnimationFrame(resolve));
      }
    }
    return prepared;
  }

  function normalizeStudentApplicationPersonName(value) {
    return String(value || "")
      .replace(/\u00a0/g, " ")
      .replace(/[.,;:()[\]{}"'«»]/g, " ")
      .replace(/\s+/g, " ")
      .trim()
      .toLocaleLowerCase("ru-RU")
      .replace(/ё/g, "е");
  }

  function getStudentApplicationIdentityKeys(person, programName, programHours = "") {
    const program = getStudentApplicationProgramIdentity(programName, programHours);
    if (!program) return [];
    const name = normalizeStudentApplicationPersonName(person?.name);
    const email = String(person?.email || "").trim().toLocaleLowerCase("ru-RU");
    const phone = String(person?.phone || "").replace(/\D/g, "").slice(-10);
    return [
      name ? `name:${name}\u0000${program}` : "",
      email ? `email:${email}\u0000${program}` : "",
      phone.length === 10 ? `phone:${phone}\u0000${program}` : ""
    ].filter(Boolean);
  }

  function getStudentApplicationPersonIdentityKeys(person) {
    const name = normalizeStudentApplicationPersonName(person?.name);
    const email = String(person?.email || "").trim().toLocaleLowerCase("ru-RU");
    const phone = String(person?.phone || "").replace(/\D/g, "").slice(-10);
    return [
      name ? `name:${name}` : "",
      email ? `email:${email}` : "",
      phone.length === 10 ? `phone:${phone}` : ""
    ].filter(Boolean);
  }

  function getStudentApplicationProgram(row, selectedProgramId = "") {
    const inferredType = getStudentApplicationInferredProgramType(row);
    const matchesInferredType = (program) => (
      studentApplicationProgramMatchesInferredType(program, inferredType)
    );
    const selectedProgram = (state.data.collections.programs || [])
      .find((program) => String(program.id || "") === String(selectedProgramId || ""));
    if (selectedProgram) return selectedProgram;
    const preparedMatch = row?._programMatch;
    if (preparedMatch?.programId && preparedMatch.kind !== "suggested") {
      const preparedProgram = (state.data.collections.programs || [])
        .find((program) => String(program.id || "") === String(preparedMatch.programId || ""));
      if (preparedProgram && preparedMatch.kind === "stored") return preparedProgram;
      if (preparedProgram && matchesInferredType(preparedProgram)) return preparedProgram;
    }
    const storedProgram = resolveStoredStudentApplicationProgram(row);
    if (storedProgram) return storedProgram;
    const productId = String(row?.productId || "").trim();
    const byProductId = productId
      ? (state.data.collections.programs || []).find((program) => (
        String(program.landingCode || "").trim() === productId
        && matchesInferredType(program)
      ))
      : null;
    const title = getStudentApplicationProgramTitle(row);
    const normalizedTitle = normalizeProgramName(title);
    const byName = getProgramRows().find((program) => (
      matchesInferredType(program)
      && [program.name, program.shortName].some((name) => normalizeProgramName(name) === normalizedTitle)
    ));
    if (byProductId || byName) return byProductId || byName;
    const comparableTitle = normalizeStudentApplicationProgramName(title);
    const titleHours = getStudentApplicationProgramHours(title);
    const comparablePrograms = (state.data.collections.programs || []).filter((program) => (
      matchesInferredType(program) && [program.name, program.shortName].some((name) => (
        normalizeStudentApplicationProgramName(name) === comparableTitle
      ))
    ));
    if (!comparablePrograms.length) return null;
    if (titleHours) {
      const matchingHours = comparablePrograms.find((program) => (
        getStudentApplicationProgramHours(program.name, program.hours) === titleHours
      ));
      if (matchingHours) return matchingHours;
    }
    return comparablePrograms.length === 1 ? comparablePrograms[0] : null;
  }

  function getStudentApplicationProgramRecommendation(row) {
    const match = row?._programMatch;
    if (!match?.programId || match.kind !== "suggested") return null;
    const program = (state.data.collections.programs || [])
      .find((item) => String(item.id || "") === String(match.programId || ""));
    return program && studentApplicationProgramMatchesInferredType(
      program,
      getStudentApplicationInferredProgramType(row)
    ) ? { program, score: Number(match.score || 0) } : null;
  }

  function getStudentApplicationProgramRecommendations(row, limit = 6) {
    const sourceTitle = getStudentApplicationProgramTitle(row);
    const sourceFeatures = buildStudentApplicationProgramMatchFeatures(sourceTitle);
    if (!sourceFeatures.normalized) return [];
    const sourceHours = getStudentApplicationProgramHours(sourceTitle);
    const inferredType = getStudentApplicationInferredProgramType(row);
    const ranked = getProgramRows()
      .map((program) => {
        const names = unique([program.name, program.shortName]
          .map((value) => String(value || "").trim())
          .filter(Boolean));
        let score = Math.max(...names.map((name) => (
          getStudentApplicationProgramSimilarity(
            sourceFeatures,
            buildStudentApplicationProgramMatchFeatures(name)
          )
        )), 0);
        const programHours = getStudentApplicationProgramHours(program.name, program.hours);
        if (sourceHours && programHours) score += sourceHours === programHours ? 0.08 : -0.16;
        if (inferredType) {
          score += studentApplicationProgramMatchesInferredType(program, inferredType) ? 0.08 : -0.12;
        }
        return { program, score: Math.max(0, Math.min(1, score)) };
      })
      .sort((left, right) => (
        right.score - left.score || compareProgramNames(left.program.name, right.program.name)
      ));
    const minimumScore = Math.max(0.32, Number(ranked[0]?.score || 0) - 0.35);
    return ranked
      .filter((item, index) => item.score >= minimumScore || index === 0)
      .slice(0, Math.max(1, Number(limit) || 6));
  }

  function saveStudentApplicationProgramMapping(rowId, programId) {
    const row = (state.studentApplicationsImport.rows || [])
      .find((item) => String(item.id || "") === String(rowId || ""));
    if (!row) return;
    const program = (state.data.collections.programs || [])
      .find((item) => String(item.id || "") === String(programId || ""));
    const source = getStudentApplicationProgramMappingSource(row);
    const current = normalizeStudentApplicationProgramMappings(
      state.data.meta.studentApplicationProgramMappings
    ).filter((item) => !(
      item.sourceProgramNormalized === source.sourceProgramNormalized
      && item.sourceProductId === source.sourceProductId
      && item.sourceType === source.sourceType
    ));
    if (program) {
      current.push({
        ...source,
        programId: String(program.id || "").trim(),
        programName: String(program.name || "").trim(),
        updatedAt: new Date().toISOString(),
        updatedBy: getCurrentUserLogin()
      });
    }
    state.data.meta.studentApplicationProgramMappings = current;
    (state.studentApplicationsImport.rows || []).forEach((item) => {
      const itemSource = getStudentApplicationProgramMappingSource(item);
      if (
        itemSource.sourceProgramNormalized !== source.sourceProgramNormalized
        || (source.sourceType && itemSource.sourceType && itemSource.sourceType !== source.sourceType)
        || (source.sourceProductId && itemSource.sourceProductId !== source.sourceProductId)
      ) return;
      item._programMatch = program
        ? { programId: String(program.id || ""), kind: "stored", score: 1 }
        : null;
      delete item._previousMatches;
    });
    const importedLookup = state.studentApplicationsImport.importedLookup;
    if (importedLookup) {
      (state.studentApplicationsImport.rows || []).forEach((item) => {
        if (!Array.isArray(item._previousMatches)) {
          item._previousMatches = getStudentApplicationPreviousMatches(item, importedLookup, "");
        }
      });
    }
    state.studentApplicationsImport.error = "";
    addAudit(
      program ? "Сопоставлена программа заявки" : "Удалено сопоставление программы заявки",
      "Слушатели и заявки",
      program
        ? `${source.sourceProgram} → ${program.name}`
        : source.sourceProgram,
      { source: "applications-import" }
    );
    persist();
    refreshStudentApplicationsImportDialog();
  }

  function buildStudentApplicationsImportLookup() {
    const historyByIdentity = new Map();
    const historyByPersonIdentity = new Map();
    const historyBySourceKey = new Map();
    const programByName = new Map();
    getProgramRows().forEach((program) => {
      [program.name, program.shortName].forEach((name) => {
        const key = normalizeProgramName(name);
        if (key && !programByName.has(key)) programByName.set(key, program);
      });
    });
    (state.data.collections.students || []).forEach((student) => {
      const mappedProgram = programByName.get(normalizeProgramName(student.program)) || null;
      const entry = {
        id: String(student.id || ""),
        name: String(student.name || ""),
        program: String(student.program || ""),
        status: String(student.status || ""),
        applicationDate: String(student.applicationDate || ""),
        programIdentity: getStudentApplicationProgramIdentity(
          mappedProgram?.name || student.program,
          mappedProgram?.hours || student.hours
        )
      };
      const sourceKey = String(student.sourceApplicationKey || "").trim();
      if (sourceKey) historyBySourceKey.set(sourceKey, entry);
      getStudentApplicationIdentityKeys(
        student,
        mappedProgram?.name || student.program,
        mappedProgram?.hours || student.hours
      ).forEach((key) => {
        const history = historyByIdentity.get(key) || [];
        history.push(entry);
        historyByIdentity.set(key, history);
      });
      getStudentApplicationPersonIdentityKeys(student).forEach((key) => {
        const history = historyByPersonIdentity.get(key) || [];
        history.push(entry);
        historyByPersonIdentity.set(key, history);
      });
    });
    return { historyByIdentity, historyByPersonIdentity, historyBySourceKey };
  }

  function getStudentApplicationPreviousMatches(
    row,
    lookup = buildStudentApplicationsImportLookup(),
    selectedProgramId = getStudentApplicationsSingleProgramFilterId()
  ) {
    if (!row) return [];
    if (!selectedProgramId && Array.isArray(row._previousMatches)) return row._previousMatches;
    const mappedProgram = getStudentApplicationProgram(row, selectedProgramId);
    const programName = mappedProgram?.name || getStudentApplicationProgramTitle(row);
    const programIdentity = getStudentApplicationProgramIdentity(programName, mappedProgram?.hours);
    const matchesById = new Map();
    const rememberMatch = (entry, sameProgram = false) => {
      const key = entry.id || `${entry.name}\u0000${entry.applicationDate}`;
      const current = matchesById.get(key);
      matchesById.set(key, {
        ...entry,
        sameProgram: Boolean(sameProgram || current?.sameProgram)
      });
    };
    const sourceMatch = lookup.historyBySourceKey?.get(getStudentApplicationSourceKey(row));
    if (sourceMatch) {
      rememberMatch(sourceMatch, Boolean(programIdentity && sourceMatch.programIdentity === programIdentity));
    }
    getStudentApplicationIdentityKeys(row, programName, mappedProgram?.hours).forEach((key) => {
      (lookup.historyByIdentity.get(key) || []).forEach((entry) => {
        rememberMatch(entry, true);
      });
    });
    getStudentApplicationPersonIdentityKeys(row).forEach((key) => {
      (lookup.historyByPersonIdentity?.get(key) || []).forEach((entry) => {
        rememberMatch(entry, Boolean(programIdentity && entry.programIdentity === programIdentity));
      });
    });
    return [...matchesById.values()].sort((left, right) => {
      const leftDate = parseTableSortDate(left.applicationDate);
      const rightDate = parseTableSortDate(right.applicationDate);
      if (leftDate === null && rightDate !== null) return 1;
      if (leftDate !== null && rightDate === null) return -1;
      return (rightDate || 0) - (leftDate || 0);
    });
  }

  function hasReusableStudentPersonalValue(value) {
    if (value === null || value === undefined) return false;
    return typeof value !== "string" || Boolean(value.trim());
  }

  function getStudentApplicationExistingPersonalRecords(
    row,
    lookup = buildStudentApplicationsImportLookup(),
    selectedProgramId = ""
  ) {
    const studentsById = new Map((state.data.collections.students || []).map((student) => [
      String(student.id || ""),
      student
    ]));
    return getStudentApplicationPreviousMatches(row, lookup, selectedProgramId)
      .map((match) => studentsById.get(String(match.id || "")))
      .filter(Boolean);
  }

  function getMostCompleteExistingPersonName(records) {
    const scoreName = (value) => {
      const parts = String(value || "").trim().split(/\s+/u).filter(Boolean);
      const fullParts = parts.filter((part) => part.replace(/[^А-ЯЁA-Z]/giu, "").length > 1).length;
      return fullParts * 1000 + parts.length * 100 + String(value || "").replace(/\s+/gu, "").length;
    };
    return records.map((record) => String(record?.name || "").trim())
      .filter(Boolean)
      .sort((left, right) => scoreName(right) - scoreName(left))[0] || "";
  }

  function reuseExistingStudentPersonalData(record, row, lookup, selectedProgramId = "") {
    const sources = getStudentApplicationExistingPersonalRecords(row, lookup, selectedProgramId);
    if (!sources.length) return record;
    const nextRecord = { ...record };
    const sourceValue = (key) => sources
      .map((source) => source?.[key])
      .find(hasReusableStudentPersonalValue);
    [
      ...STUDENT_APPLICATION_REUSABLE_DOCUMENT_FIELDS,
      ...STUDENT_APPLICATION_REUSABLE_SDO_FIELDS,
      ...STUDENT_APPLICATION_REUSABLE_PERSONAL_FIELDS
    ].forEach((key) => {
      const value = sourceValue(key);
      if (hasReusableStudentPersonalValue(value)) nextRecord[key] = value;
    });
    ["phone", "email", "workPlace", "position", "employmentCategory"].forEach((key) => {
      if (hasReusableStudentPersonalValue(nextRecord[key])) return;
      const value = sourceValue(key);
      if (hasReusableStudentPersonalValue(value)) nextRecord[key] = value;
    });
    const existingName = getMostCompleteExistingPersonName(sources);
    const importedName = String(nextRecord.name || "").trim();
    if (existingName && getMostCompleteExistingPersonName([{ name: existingName }, { name: importedName }]) === existingName) {
      nextRecord.name = existingName;
    }
    return nextRecord;
  }

  function getStudentApplicationRepeatComment(row, lookup = buildStudentApplicationsImportLookup()) {
    const matches = getStudentApplicationPreviousMatches(row, lookup);
    const previous = matches.find((item) => item.sameProgram) || matches[0];
    if (!previous) return "";
    const applicationDate = dateRu(previous.applicationDate);
    if (previous.sameProgram) {
      return applicationDate
        ? `Слушатель уже подавал заявку на эту программу: ${applicationDate}. Повторный импорт разрешён.`
        : "Слушатель уже подавал заявку на эту программу. Дата предыдущей заявки не указана. Повторный импорт разрешён.";
    }
    const existingProgram = String(previous.program || "").trim();
    return `Слушатель уже есть в базе${existingProgram ? `: ${existingProgram}` : ""}${applicationDate ? `; заявка от ${applicationDate}` : ""}. После выбора программы совпадение проверено повторно.`;
  }

  function getStudentApplicationRepeatTooltip(row, lookup = buildStudentApplicationsImportLookup()) {
    const matches = getStudentApplicationPreviousMatches(row, lookup);
    if (!matches.length) return "";
    const lines = matches.map((item, index) => {
      const parts = [
        item.sameProgram ? "та же программа" : "другая программа",
        String(item.name || "").trim(),
        String(item.program || "Программа не указана").trim(),
        item.status ? `статус: ${item.status}` : "",
        dateRu(item.applicationDate) ? `заявка от ${dateRu(item.applicationDate)}` : "дата заявки не указана",
        item.id ? `uid ${item.id}` : ""
      ].filter(Boolean);
      return `${index + 1}. ${parts.join(" · ")}`;
    });
    return [
      "Повторная заявка. Слушатель уже найден в базе:",
      ...lines,
      "Повторный импорт разрешён."
    ].join("\n");
  }

  function isStudentApplicationImported(row, lookup = buildStudentApplicationsImportLookup()) {
    return getStudentApplicationPreviousMatches(row, lookup).length > 0;
  }

  function parseStudentApplicationSortDate(value) {
    const text = String(value || "").trim();
    if (!text) return null;
    const ru = /^(\d{1,2})\.(\d{1,2})\.(\d{4})(?:\s+(\d{1,2}):(\d{2})(?::(\d{2}))?)?/u.exec(text);
    if (ru) {
      return Date.UTC(
        Number(ru[3]),
        Number(ru[2]) - 1,
        Number(ru[1]),
        Number(ru[4] || 0),
        Number(ru[5] || 0),
        Number(ru[6] || 0)
      );
    }
    const timestamp = Date.parse(text);
    return Number.isNaN(timestamp) ? null : timestamp;
  }

  function getStudentApplicationSortValue(row, key) {
    if (key === "payment") return getStudentApplicationReceiptAmount(row);
    return row?.[key];
  }

  function sortStudentApplicationRows(rows, sort = STUDENT_APPLICATIONS_IMPORT_DEFAULT_SORT) {
    const key = String(sort?.key || "");
    if (!key) return rows;
    const column = STUDENT_APPLICATIONS_IMPORT_TABLE_COLUMNS.find((item) => item.key === key);
    if (!column) return rows;
    const direction = sort.dir === "desc" ? -1 : 1;
    return rows.slice().sort((leftRow, rightRow) => {
      const left = getStudentApplicationSortValue(leftRow, key);
      const right = getStudentApplicationSortValue(rightRow, key);
      if (column.type === "number") {
        const leftNumber = String(left ?? "").trim() === "" ? null : Number(left);
        const rightNumber = String(right ?? "").trim() === "" ? null : Number(right);
        const hasLeft = Number.isFinite(leftNumber);
        const hasRight = Number.isFinite(rightNumber);
        if (!hasLeft && hasRight) return 1;
        if (hasLeft && !hasRight) return -1;
        if (hasLeft && hasRight && leftNumber !== rightNumber) return (leftNumber - rightNumber) * direction;
      }
      if (column.type === "date") {
        const leftDate = parseStudentApplicationSortDate(left);
        const rightDate = parseStudentApplicationSortDate(right);
        if (leftDate === null && rightDate !== null) return 1;
        if (leftDate !== null && rightDate === null) return -1;
        if (leftDate !== null && rightDate !== null && leftDate !== rightDate) return (leftDate - rightDate) * direction;
      }
      return String(left || "").localeCompare(String(right || ""), "ru", {
        numeric: true,
        sensitivity: "base"
      }) * direction;
    });
  }

  function getVisibleStudentApplications() {
    const query = String(state.studentApplicationsImport.filters.search || "").trim().toLocaleLowerCase("ru-RU");
    const rows = state.studentApplicationsImport.rows || [];
    const filteredRows = query ? rows.filter((row) => (
      [
        row.date,
        row.name,
        row.order,
        row.paymentAmount,
        row.program,
        row.phone,
        row.email,
        row.city,
        row.organization,
        row.position,
        row.source,
        row.coupon,
        row.note
      ].some((value) => String(value || "").toLocaleLowerCase("ru-RU").includes(query))
    )) : rows;
    return sortStudentApplicationRows(filteredRows, state.studentApplicationsImport.sort);
  }

  function getStudentApplicationCouponTerms(row = {}) {
    const explicitCoupon = String(row.coupon || "").trim();
    const couponText = [explicitCoupon, row.order, row.note]
      .map((value) => String(value || "").trim())
      .filter(Boolean)
      .join(" ");
    const detectedCoupon = explicitCoupon || (
      /(?:^|[^a-z0-9])((?:RASS|SALE|NEXT)[a-z0-9_-]*)(?:$|[^a-z0-9_-])/i.exec(couponText)?.[1]
      || ""
    );
    const normalizedCoupon = String(detectedCoupon || "").trim();
    const installmentMatch = /^RASS(?:[-_]?([0-9]+(?:[.,][0-9]+)?))?/i.exec(normalizedCoupon);
    if (installmentMatch) {
      const installmentPercent = Number(String(installmentMatch[1] || "").replace(",", ".")) || 0;
      return {
        coupon: normalizedCoupon,
        percent: 0,
        installmentPercent,
        installment: true,
        description: installmentPercent
          ? `Рассрочка — платёж ${installmentPercent}% от суммы договора`
          : "Рассрочка"
      };
    }
    const periodicPromotion = /^(?:SALE|NEXT)/i.test(normalizedCoupon);
    return {
      coupon: normalizedCoupon,
      percent: 0,
      installmentPercent: 0,
      installment: false,
      periodicPromotion,
      description: normalizedCoupon
        ? (periodicPromotion
          ? "Периодическая акция"
          : "По решению директора учебного центра")
        : ""
    };
  }

  function getStudentApplicationCouponPercentHint(coupon) {
    const value = String(coupon || "").trim();
    if (!value) return 0;
    if (/free/iu.test(value)) return 100;
    const promotionMatch = /^(?:SALE|NEXT)[-_]?([0-9]+(?:[.,][0-9]+)?)/i.exec(value);
    const percent = Number(String(promotionMatch?.[1] || "").replace(",", "."));
    return Number.isFinite(percent) && percent >= 0 && percent <= 100 ? percent : 0;
  }

  function parseStudentApplicationMoney(value) {
    const normalized = String(value ?? "")
      .replace(/[\s\u00a0]+/g, "")
      .replace(",", ".");
    const amount = Number(normalized);
    return Number.isFinite(amount) ? amount : 0;
  }

  function getStudentApplicationReceiptAmount(row = {}) {
    const paymentAmount = parseStudentApplicationMoney(row.paymentAmount);
    if (paymentAmount > 0) return Math.round(paymentAmount * 100) / 100;
    const isInSales = String(row.sourceType || "").trim().toLowerCase() === "email"
      || /insales/iu.test(String(row.source || ""));
    const orderAmount = parseStudentApplicationMoney(row.orderAmount);
    return isInSales && orderAmount > 0 ? Math.round(orderAmount * 100) / 100 : 0;
  }

  function getStudentApplicationFinancialTerms(row = {}, programOverride = null) {
    const program = programOverride || getStudentApplicationProgram(row);
    const couponTerms = getStudentApplicationCouponTerms(row);
    const rawPaymentAmount = getStudentApplicationReceiptAmount(row);
    const paymentAmount = Number.isFinite(rawPaymentAmount) && rawPaymentAmount > 0
      ? Math.round(rawPaymentAmount * 100) / 100
      : 0;
    const rawRegistryPrice = parseStudentApplicationMoney(program?.price);
    const registryPrice = Number.isFinite(rawRegistryPrice) && rawRegistryPrice > 0
      ? Math.round(rawRegistryPrice * 100) / 100
      : 0;
    const installmentPercent = Number(couponTerms.installmentPercent || 0);
    let contractAmount = registryPrice || paymentAmount;
    let discountAmount = 0;
    let discountPercent = 0;
    if (couponTerms.installment) {
      if (!registryPrice && paymentAmount > 0 && installmentPercent > 0) {
        contractAmount = Math.round((paymentAmount * 100 / installmentPercent) * 100) / 100;
      }
    } else if (couponTerms.coupon && registryPrice > 0) {
      const percentHint = paymentAmount > 0
        ? 0
        : getStudentApplicationCouponPercentHint(couponTerms.coupon);
      const discountedAmount = paymentAmount > 0
        ? paymentAmount
        : (percentHint > 0 ? registryPrice * (1 - percentHint / 100) : registryPrice);
      contractAmount = Math.round(Math.max(0, Math.min(registryPrice, discountedAmount)) * 100) / 100;
      discountAmount = Math.round(Math.max(0, registryPrice - contractAmount) * 100) / 100;
      discountPercent = registryPrice > 0
        ? Math.round((discountAmount * 100 / registryPrice) * 100) / 100
        : 0;
    }
    return {
      ...couponTerms,
      percent: discountPercent,
      paymentAmount,
      registryPrice,
      discountAmount,
      contractAmount
    };
  }

  function renderStudentApplicationDetail(row, importedLookup = buildStudentApplicationsImportLookup()) {
    if (!row) return `<div class="student-applications-import-empty">Выберите заявку в таблице.</div>`;
    const mappedProgram = getStudentApplicationProgram(
      row,
      getStudentApplicationsSingleProgramFilterId()
    );
    const recommendation = mappedProgram ? null : getStudentApplicationProgramRecommendation(row);
    const financialTerms = getStudentApplicationFinancialTerms(row, mappedProgram);
    const inferredProgramType = getStudentApplicationInferredProgramType(row) || mappedProgram?.type;
    const programFilterOverridesMapping = Boolean(getStudentApplicationsSingleProgramFilterId());
    const programs = getProgramRows();
    const suitablePrograms = getStudentApplicationProgramRecommendations(row);
    const suitableProgramIds = new Set(suitablePrograms.map((item) => String(item.program.id || "")));
    const allOtherPrograms = programs.filter((program) => !suitableProgramIds.has(String(program.id || "")));
    const renderProgramOption = (program, options = {}) => `
      <option value="${escapeAttr(program.id)}" ${String(program.id || "") === String(mappedProgram?.id || "") ? "selected" : ""}>
        ${options.recommended ? "★ " : ""}${escapeHtml(program.name || "Без названия")}${program.type ? ` — ${escapeHtml(program.type)}` : ""}${program.hours ? `, ${escapeHtml(program.hours)} ч` : ""}${Number.isFinite(options.score) ? ` (${Math.round(options.score * 100)}%)` : ""}
      </option>
    `;
    const { paymentAmount, contractAmount } = financialTerms;
    const hasPayment = paymentAmount > 0 || Boolean(row.paid);
    const repeatComment = getStudentApplicationRepeatComment(row, importedLookup);
    const benefitDescription = financialTerms.description
      ? (financialTerms.percent
        ? `${financialTerms.percent}% — ${financialTerms.description}`
        : financialTerms.description)
      : "—";
    const topDetails = [
      ["Дата", row.date],
      ["ФИО", row.name],
      ["Телефон", row.phone],
      ["Email", row.email],
      ["Город", row.city]
    ];
    const orderLineDetails = [
      ["Заказ", row.order],
      ["Программа", row.program],
      ["Категория", inferredProgramType || "—"]
    ];
    const details = [
      ["Оплата", hasPayment ? money(paymentAmount) : "—"],
      ["Стоимость по реестру", financialTerms.registryPrice ? money(financialTerms.registryPrice) : "—"],
      ["Сумма договора", contractAmount || financialTerms.coupon ? money(contractAmount) : "—"],
      ["Купон", financialTerms.coupon || "—"],
      ["Скидка / рассрочка", benefitDescription],
      ["Организация", row.organization, true],
      ["Должность", row.position],
      ["Источник", row.source],
      ["Примечание", row.note, true]
    ];
    const renderDetailItems = (items) => items.map(([label, value, wide]) => `
      <div class="${wide ? "is-wide" : ""}">
        <dt>${escapeHtml(label)}</dt>
        <dd>${escapeHtml(value || "—")}</dd>
      </div>
    `).join("");
    return `
      <div class="student-application-detail-grid">
        ${renderDetailItems(topDetails)}
        <div class="student-application-detail-order-line">
          ${renderDetailItems(orderLineDetails)}
        </div>
        ${renderDetailItems(details)}
      </div>
      <div class="student-application-import-preview">
        <span>Будет добавлено</span>
        <strong>${escapeHtml(mappedProgram?.name || (recommendation
          ? `Рекомендуется: ${recommendation.program.name}`
          : getStudentApplicationProgramTitle(row) || "Программа не определена"))}</strong>
        <label class="student-application-program-mapping ${mappedProgram ? "is-matched" : (recommendation ? "is-suggested" : "is-unmatched")}">
          <span>Сопоставление с реестром программ</span>
          <select data-student-application-program-map="${escapeAttr(row.id)}" ${programFilterOverridesMapping ? "disabled" : ""}>
            <option value="">Выберите программу...</option>
            ${suitablePrograms.length ? `
              <optgroup label="Наиболее подходящие программы">
                ${suitablePrograms.map((item, index) => renderProgramOption(item.program, {
                  recommended: index === 0,
                  score: item.score
                })).join("")}
              </optgroup>
            ` : ""}
            <optgroup label="Все программы">
              ${allOtherPrograms.map((program) => renderProgramOption(program)).join("")}
            </optgroup>
          </select>
          <small>${programFilterOverridesMapping
            ? "Программа задана фильтром импорта."
            : (mappedProgram
              ? "Сопоставление найдено автоматически или сохранено ранее."
              : (recommendation
                ? `Найден похожий вариант (${Math.round(recommendation.score * 100)}%). Проверьте рекомендацию и подтвердите её выбором из списка.`
                : "Выберите программу: этот вариант будет сохранён для следующих заявок с таким названием."))}</small>
        </label>
        <small>${hasPayment
          ? (financialTerms.installmentPercent
            ? `Платёж ${financialTerms.installmentPercent}%: ${escapeHtml(money(paymentAmount))}; сумма договора: ${escapeHtml(money(contractAmount))}`
            : `Оплата: ${escapeHtml(money(paymentAmount))}; сумма договора: ${escapeHtml(money(contractAmount))}`)
          : `Без оплаты; сумма договора: ${escapeHtml(money(contractAmount))}`}</small>
      </div>
      ${repeatComment ? `
        <div class="student-application-listener-comment">
          <strong>Комментарий по слушателю</strong>
          <span>${escapeHtml(repeatComment)}</span>
        </div>
      ` : ""}
    `;
  }

  function getStudentApplicationsImportPagination(totalRows) {
    const allowedPageSizes = [50, 100, 200];
    const requestedPageSize = Number(state.studentApplicationsImport.pageSize || 100);
    const pageSize = allowedPageSizes.includes(requestedPageSize) ? requestedPageSize : 100;
    const totalPages = Math.max(1, Math.ceil(totalRows / pageSize));
    const requestedPage = Number(state.studentApplicationsImport.page || 1);
    const page = Math.max(1, Math.min(totalPages, Number.isFinite(requestedPage) ? requestedPage : 1));
    state.studentApplicationsImport.page = page;
    state.studentApplicationsImport.pageSize = pageSize;
    const start = (page - 1) * pageSize;
    const end = Math.min(totalRows, start + pageSize);
    return { page, pageSize, totalPages, start, end };
  }

  function renderStudentApplicationsImportPagination(totalRows, pagination) {
    if (totalRows <= 50) return "";
    const { page, pageSize, totalPages, start, end } = pagination;
    return `
      <div class="table-pagination student-applications-import-pagination">
        <span class="table-pagination-summary">Показано ${start + 1}–${end} из ${totalRows}</span>
        <div class="table-pagination-navigation" aria-label="Навигация по страницам заявок">
          <button class="icon-button" data-action="student-applications-page" data-page="1" type="button" title="Первая страница" aria-label="Первая страница" ${page <= 1 ? "disabled" : ""}>«</button>
          <button class="icon-button" data-action="student-applications-page" data-page="${page - 1}" type="button" title="Предыдущая страница" aria-label="Предыдущая страница" ${page <= 1 ? "disabled" : ""}>‹</button>
          <label class="table-pagination-current">
            <span>Страница</span>
            <input data-action="student-applications-page-input" type="number" min="1" max="${totalPages}" value="${page}" aria-label="Номер страницы заявок">
            <span>из ${totalPages}</span>
          </label>
          <button class="icon-button" data-action="student-applications-page" data-page="${page + 1}" type="button" title="Следующая страница" aria-label="Следующая страница" ${page >= totalPages ? "disabled" : ""}>›</button>
          <button class="icon-button" data-action="student-applications-page" data-page="${totalPages}" type="button" title="Последняя страница" aria-label="Последняя страница" ${page >= totalPages ? "disabled" : ""}>»</button>
        </div>
        <label class="table-page-size">
          <span>Строк на странице</span>
          <select data-action="student-applications-page-size">
            ${[50, 100, 200].map((size) => `<option value="${size}" ${size === pageSize ? "selected" : ""}>${size}</option>`).join("")}
          </select>
        </label>
      </div>
    `;
  }

  function renderStudentApplicationImportTableCell(row, column, context = {}) {
    const attrs = columnDataAttrs(STUDENT_APPLICATIONS_IMPORT_TABLE_CONFIG_ID, column.key);
    const style = columnStyleAttr(STUDENT_APPLICATIONS_IMPORT_TABLE_CONFIG_ID, column.key);
    const paymentAmount = Number(context.paymentAmount) || 0;
    const plainCell = (value, className = "") => {
      const text = String(value || "");
      return `
        <td ${className ? `class="${className}"` : ""} title="${escapeAttr(text)}" ${attrs} ${style}>
          <div class="student-application-cell-content">${escapeHtml(text)}</div>
        </td>
      `;
    };
    if (column.key === "name") {
      return `
        <td title="${escapeAttr(row.name || "")}" ${attrs} ${style}>
          <div class="student-application-name-cell">
            <span>${escapeHtml(row.name || "")}</span>
            ${context.imported ? `<span class="student-application-repeat-badge" title="${escapeMultilineAttr(context.repeatTooltip)}">Повтор</span>` : ""}
          </div>
        </td>
      `;
    }
    if (column.key === "payment") {
      const value = paymentAmount > 0 || row.paid ? money(paymentAmount) : "—";
      return `<td class="student-applications-payment-cell" title="${escapeAttr(value)}" ${attrs} ${style}>${escapeHtml(value)}</td>`;
    }
    if (column.key === "program") {
      const recommendation = context.recommendation;
      const recommendationText = recommendation
        ? `Рекомендуется: ${recommendation.program.name} (${Math.round(recommendation.score * 100)}%)`
        : "";
      const title = [row.program, recommendationText].filter(Boolean).join(" · ");
      return `
        <td title="${escapeAttr(title)}" ${attrs} ${style}>
          <div class="student-application-cell-content">${escapeHtml(row.program || "")}${recommendation ? ` · ${escapeHtml(recommendationText)}` : ""}</div>
        </td>
      `;
    }
    return plainCell(row[column.key] || "");
  }

  function renderStudentApplicationsImport() {
    const importState = state.studentApplicationsImport;
    const filters = importState.filters;
    const visibleRows = getVisibleStudentApplications();
    const pagination = getStudentApplicationsImportPagination(visibleRows.length);
    const pageRows = visibleRows.slice(pagination.start, pagination.end);
    const importedLookup = importState.importedLookup || {
      historyByIdentity: new Map(),
      historyByPersonIdentity: new Map(),
      historyBySourceKey: new Map()
    };
    const selectedIds = new Set(importState.selected || []);
    const selectedRows = (importState.rows || []).filter((row) => selectedIds.has(String(row.id)));
    const selectedPayment = Math.max(0, Number(importState.selectedPayment) || 0);
    const importedCount = visibleRows.filter((row) => isStudentApplicationImported(row, importedLookup)).length;
    const activeRow = pageRows.find((row) => String(row.id) === String(importState.activeId))
      || pageRows[0]
      || null;
    const programs = getProgramRows();
    const selectedProgramIds = getStudentApplicationsSelectedProgramIds(filters);
    const selectedProgramIdSet = new Set(selectedProgramIds);
    const programSelectionLabel = getStudentApplicationsProgramFilterLabel(filters);
    const programQuery = String(filters.programQuery || "");
    const normalizedProgramQuery = normalizeStudentListProgramQuery(programQuery);
    const visibleProgramOptionCount = programs.filter((program) => (
      !normalizedProgramQuery
      || normalizeStudentListProgramQuery(`${program.name || ""} ${program.landingCode || ""}`)
        .includes(normalizedProgramQuery)
    )).length;
    const statuses = unique([
      ...(state.data.dictionaries.statuses || []),
      filters.status || "На зачисление"
    ].filter(Boolean));
    const tableColumns = getTableFields(
      studentApplicationsImportTableConfig,
      STUDENT_APPLICATIONS_IMPORT_TABLE_CONFIG_ID
    );
    const tableSort = importState.sort || STUDENT_APPLICATIONS_IMPORT_DEFAULT_SORT;
    return `
      <div class="modal-backdrop student-applications-import-backdrop" data-student-applications-import-backdrop data-action="close-student-applications-import">
        <section class="modal student-applications-import-modal" role="dialog" aria-modal="true" aria-label="Импорт слушателей">
          <form data-student-applications-import-form>
            <header class="modal-head student-applications-import-head">
              <div>
                <p class="eyebrow">Слушатели и заявки</p>
                <h2>Импорт слушателей</h2>
              </div>
              <button class="icon-button" data-action="close-student-applications-import" type="button" title="Закрыть" aria-label="Закрыть">×</button>
            </header>

            <div class="student-applications-import-body">
            <div class="student-applications-import-filters">
              <div class="student-applications-program-filter">
                <span>Программа обучения</span>
                <details class="student-program-type-filter student-list-program-filter student-applications-program-multiselect ${selectedProgramIds.length ? "is-active" : ""}" data-student-applications-program-filter>
                  <summary title="Выбрать одну или несколько программ">
                    <strong data-student-applications-program-filter-label>${escapeHtml(programSelectionLabel)}</strong>
                    <svg viewBox="0 0 12 8" aria-hidden="true"><path d="M1 1.5 6 6.5l5-5"></path></svg>
                  </summary>
                  <div class="student-program-type-filter-panel student-list-program-filter-panel student-applications-program-filter-panel">
                    <label class="student-list-program-search">
                      <span aria-hidden="true">⌕</span>
                      <input type="search" value="${escapeAttr(programQuery)}" placeholder="Поиск программы" autocomplete="off" data-student-applications-program-search>
                    </label>
                    <div class="student-list-program-filter-options" data-student-applications-program-filter-options>
                      ${programs.map((program) => {
                        const programId = String(program.id || "");
                        const searchValue = normalizeStudentListProgramQuery(`${program.name || ""} ${program.landingCode || ""}`);
                        const hidden = normalizedProgramQuery && !searchValue.includes(normalizedProgramQuery);
                        return `
                          <label data-student-applications-program-option-row ${hidden ? "hidden" : ""}>
                            <input type="checkbox" value="${escapeAttr(programId)}" data-student-applications-program-filter-option ${selectedProgramIdSet.has(programId) ? "checked" : ""}>
                            <span>${escapeHtml(program.name || "Без названия")}${program.landingCode ? ` [${escapeHtml(program.landingCode)}]` : ""}</span>
                          </label>
                        `;
                      }).join("")}
                      <div class="student-list-program-filter-empty" data-student-applications-program-filter-empty ${visibleProgramOptionCount ? "hidden" : ""}>Программы не найдены</div>
                    </div>
                    <button class="student-program-type-filter-clear" data-action="clear-student-applications-program-filter" type="button" ${selectedProgramIds.length ? "" : "disabled"}>Сбросить</button>
                  </div>
                </details>
              </div>
              <label>
                <span>Период импорта</span>
                <select name="period">
                  <option value="all" ${filters.period === "all" ? "selected" : ""}>За всё время</option>
                  <option value="7" ${filters.period === "7" ? "selected" : ""}>За последние 7 дней</option>
                  <option value="30" ${filters.period === "30" ? "selected" : ""}>За последние 30 дней</option>
                  <option value="90" ${filters.period === "90" ? "selected" : ""}>За последние 90 дней</option>
                  <option value="custom" ${filters.period === "custom" ? "selected" : ""}>Произвольный период</option>
                </select>
              </label>
              <label>
                <span>Дата с</span>
                <input name="dateFrom" type="date" value="${escapeAttr(filters.dateFrom)}" ${filters.period === "all" ? "disabled" : ""} required>
              </label>
              <label>
                <span>Дата по</span>
                <input name="dateTo" type="date" value="${escapeAttr(filters.dateTo)}" ${filters.period === "all" ? "disabled" : ""} required>
              </label>
              <label class="student-applications-paid-filter">
                <input name="onlyPaid" type="checkbox" ${filters.onlyPaid ? "checked" : ""}>
                <span>Только с оплатой</span>
              </label>
              <button class="primary-button student-applications-fetch-button ${importState.loading ? "is-loading" : ""}" type="submit" ${importState.loading ? "disabled" : ""}>
                ${importState.loading ? "Получение..." : "Получить список заявок"}
              </button>
            </div>

            <div class="student-applications-import-tools">
              <label class="search-box">
                <span>⌕</span>
                <input name="applicationSearch" value="${escapeAttr(filters.search)}" placeholder="Поиск в заявках" autocomplete="off">
              </label>
              <button class="ghost-button" data-action="select-all-student-applications" type="button" ${visibleRows.length ? "" : "disabled"}>Выделить все</button>
              <button class="ghost-button" data-action="clear-student-applications-filters" type="button">Очистить фильтры</button>
              <button class="ghost-button icon-only table-options-button" data-action="toggle-student-applications-table-options" type="button" title="Опции таблицы" aria-label="Опции таблицы">⋯</button>
              <label class="student-applications-status-filter">
                <span>Установить статус</span>
                <select name="importStatus" data-settings-dictionary="statuses">
                  ${renderStudentStatusOptions(statuses, filters.status)}
                </select>
              </label>
              <div class="student-applications-import-summary">
                Всего: <strong>${visibleRows.length}</strong>
                <span>Выбрано: <strong data-student-applications-selected-count>${selectedRows.length}</strong></span>
                <span>Оплаты: <strong data-student-applications-selected-payment>${escapeHtml(money(selectedPayment))}</strong></span>
                ${importedCount ? `<span>Повторные заявки: <strong>${importedCount}</strong></span>` : ""}
              </div>
            </div>
            ${renderTableOptions(STUDENT_APPLICATIONS_IMPORT_TABLE_CONFIG_ID)}

            <div class="student-applications-import-messages">
              ${importState.error ? `<div class="student-applications-import-error">${escapeHtml(importState.error)}</div>` : ""}
              ${(importState.warnings || []).map((warning) => `<div class="student-applications-import-warning">${escapeHtml(warning)}</div>`).join("")}
              ${importState.truncated ? `<div class="student-applications-import-warning">Показаны первые 5000 заявок. Уточните условия отбора.</div>` : ""}
            </div>

            <div class="student-applications-import-table-wrap">
              <table class="student-applications-import-table">
                <thead>
                  <tr>
                    <th aria-label="Выбор"></th>
                    ${tableColumns.map((column) => {
                      const sorted = tableSort.key === column.key;
                      const directionLabel = sorted
                        ? (tableSort.dir === "asc" ? "по возрастанию" : "по убыванию")
                        : "без сортировки";
                      return `
                        <th
                          class="table-column-head"
                          ${columnDataAttrs(STUDENT_APPLICATIONS_IMPORT_TABLE_CONFIG_ID, column.key)}
                          ${columnStyleAttr(STUDENT_APPLICATIONS_IMPORT_TABLE_CONFIG_ID, column.key)}
                          draggable="true"
                          aria-sort="${sorted ? (tableSort.dir === "asc" ? "ascending" : "descending") : "none"}"
                          title="Перетащите заголовок для смены порядка"
                        >
                          <div class="table-head-cell">
                            <button
                              data-action="sort-student-applications"
                              data-key="${escapeAttr(column.key)}"
                              type="button"
                              aria-label="${escapeAttr(`${column.label}: ${directionLabel}`)}"
                            >
                              ${escapeHtml(column.label)}${sorted ? (tableSort.dir === "asc" ? " ↑" : " ↓") : ""}
                            </button>
                            <span
                              class="column-resize-handle"
                              data-action="resize-column"
                              data-config="${STUDENT_APPLICATIONS_IMPORT_TABLE_CONFIG_ID}"
                              data-field="${escapeAttr(column.key)}"
                              title="Изменить ширину"
                            ></span>
                          </div>
                        </th>
                      `;
                    }).join("")}
                  </tr>
                </thead>
                <tbody>
                  ${pageRows.length ? pageRows.map((row) => {
                    const imported = isStudentApplicationImported(row, importedLookup);
                    const repeatTooltip = imported ? getStudentApplicationRepeatTooltip(row, importedLookup) : "";
                    const recommendation = getStudentApplicationProgramRecommendation(row);
                    const selected = selectedIds.has(String(row.id));
                    const active = String(activeRow?.id || "") === String(row.id);
                    const paymentAmount = getStudentApplicationReceiptAmount(row);
                    return `
                      <tr class="${active ? "is-active" : ""} ${imported ? "is-repeat" : ""}" data-student-application-row="${escapeAttr(row.id)}">
                        <td>
                          <input data-student-application-select="${escapeAttr(row.id)}" data-payment-amount="${escapeAttr(paymentAmount)}" type="checkbox" ${selected ? "checked" : ""} aria-label="Выбрать заявку">
                        </td>
                        ${tableColumns.map((column) => renderStudentApplicationImportTableCell(row, column, {
                          imported,
                          repeatTooltip,
                          recommendation,
                          paymentAmount
                        })).join("")}
                      </tr>
                    `;
                  }).join("") : `
                    <tr>
                      <td colspan="${tableColumns.length + 1}">
                        <div class="student-applications-import-empty">
                          ${importState.loading ? "Получение заявок из базы и электронной почты..." : "Задайте условия и получите список заявок."}
                        </div>
                      </td>
                    </tr>
                  `}
                </tbody>
              </table>
            </div>
            ${renderStudentApplicationsImportPagination(visibleRows.length, pagination)}

            <div class="student-applications-import-detail" data-student-applications-detail role="region" tabindex="0" aria-labelledby="student-applications-detail-title">
              <h3 id="student-applications-detail-title">Информация о выбранной заявке</h3>
              ${renderStudentApplicationDetail(activeRow, importedLookup)}
            </div>
            </div>

            <div class="modal-actions student-applications-import-actions">
              <button class="ghost-button" data-action="close-student-applications-import" type="button">Закрыть</button>
              <button class="primary-button" data-action="add-selected-student-applications" type="button" ${selectedRows.length && !importState.importing ? "" : "disabled"}>
                ${importState.importing ? "Создание папок..." : "Добавить в базу"}
              </button>
            </div>
          </form>
        </section>
      </div>
    `;
  }

  function syncStudentApplicationsImportFilters(form) {
    if (!form) return;
    const filters = state.studentApplicationsImport.filters;
    const programIds = Array.from(
      form.querySelectorAll("[data-student-applications-program-filter-option]:checked")
    ).map((input) => String(input.value || "")).filter(Boolean);
    filters.programIds = unique(programIds);
    filters.programId = filters.programIds.length === 1 ? filters.programIds[0] : "";
    filters.period = String(form.elements.period?.value || "custom");
    filters.dateFrom = String(form.elements.dateFrom?.value || "");
    filters.dateTo = String(form.elements.dateTo?.value || "");
    filters.onlyPaid = Boolean(form.elements.onlyPaid?.checked);
    filters.search = String(form.elements.applicationSearch?.value || "");
    filters.status = String(form.elements.importStatus?.value || "На зачисление");
  }

  async function fetchStudentApplications(event) {
    event?.preventDefault();
    const form = event?.currentTarget || document.querySelector("[data-student-applications-import-form]");
    syncStudentApplicationsImportFilters(form);
    const filters = state.studentApplicationsImport.filters;
    if (!filters.dateFrom || !filters.dateTo) {
      state.studentApplicationsImport.error = "Укажите период импорта.";
      refreshStudentApplicationsImportDialog();
      return;
    }
    if (filters.dateFrom > filters.dateTo) {
      state.studentApplicationsImport.error = "Дата начала периода не может быть позже даты окончания.";
      refreshStudentApplicationsImportDialog();
      return;
    }
    const selectedProgramIds = getStudentApplicationsSelectedProgramIds(filters);
    const selectedProgramIdSet = new Set(selectedProgramIds);
    const programs = getProgramRows()
      .filter((item) => selectedProgramIdSet.has(String(item.id || "")));
    state.studentApplicationsImport.loading = true;
    state.studentApplicationsImport.error = "";
    state.studentApplicationsImport.warnings = [];
    refreshStudentApplicationsImportDialog();
    try {
      const response = await fetch(photoApiUrl("/api/students/import-applications/query"), {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          dateFrom: filters.dateFrom,
          dateTo: filters.dateTo,
          programName: programs.length === 1 ? String(programs[0]?.name || "") : "",
          productId: programs.length === 1 ? String(programs[0]?.landingCode || "") : "",
          programs: programs.map((program) => ({
            programName: String(program?.name || ""),
            productId: String(program?.landingCode || "")
          })),
          onlyPaid: filters.onlyPaid
        })
      });
      const payload = await response.json().catch(() => ({}));
      if (!response.ok) throw new Error(payload.error || "Не удалось получить заявки.");
      const rawRows = (Array.isArray(payload.rows) ? payload.rows : []).map((row, index) => ({
        ...row,
        id: String(row.id || `${row.orderId || "order"}-${index}`)
      }));
      const rows = await prepareStudentApplicationRows(rawRows);
      const importedLookup = buildStudentApplicationsImportLookup();
      for (let index = 0; index < rows.length; index += 1) {
        rows[index]._previousMatches = getStudentApplicationPreviousMatches(rows[index], importedLookup, "");
        if (index > 0 && index % 500 === 0) {
          await new Promise((resolve) => requestAnimationFrame(resolve));
        }
      }
      state.studentApplicationsImport.rows = rows;
      state.studentApplicationsImport.importedLookup = importedLookup;
      state.studentApplicationsImport.page = 1;
      state.studentApplicationsImport.selected = [];
      state.studentApplicationsImport.selectedPayment = 0;
      state.studentApplicationsImport.activeId = String(
        sortStudentApplicationRows(rows, state.studentApplicationsImport.sort)[0]?.id || ""
      );
      state.studentApplicationsImport.truncated = Boolean(payload.truncated);
      state.studentApplicationsImport.warnings = Array.isArray(payload.warnings)
        ? payload.warnings.map(String).filter(Boolean)
        : [];
    } catch (error) {
      state.studentApplicationsImport.rows = [];
      state.studentApplicationsImport.importedLookup = null;
      state.studentApplicationsImport.page = 1;
      state.studentApplicationsImport.selected = [];
      state.studentApplicationsImport.selectedPayment = 0;
      state.studentApplicationsImport.activeId = "";
      state.studentApplicationsImport.error = error.message;
      state.studentApplicationsImport.warnings = [];
    } finally {
      state.studentApplicationsImport.loading = false;
      refreshStudentApplicationsImportDialog();
    }
  }

  function updateStudentApplicationsPeriod(period) {
    const value = String(period || "custom");
    state.studentApplicationsImport.filters.period = value;
    if (value === "all") {
      Object.assign(
        state.studentApplicationsImport.filters,
        getStudentApplicationsAllTimeDates()
      );
    } else if (value !== "custom") {
      Object.assign(
        state.studentApplicationsImport.filters,
        getStudentApplicationsDefaultDates(Number(value) || 30)
      );
    }
    refreshStudentApplicationsImportDialog();
  }

  function clearStudentApplicationsFilters() {
    const dates = getStudentApplicationsDefaultDates(30);
    state.studentApplicationsImport.filters = {
      programId: "",
      programIds: [],
      programQuery: "",
      period: "30",
      ...dates,
      onlyPaid: false,
      search: "",
      status: "На зачисление"
    };
    state.studentApplicationsImport.rows = [];
    state.studentApplicationsImport.importedLookup = null;
    state.studentApplicationsImport.page = 1;
    state.studentApplicationsImport.selected = [];
    state.studentApplicationsImport.selectedPayment = 0;
    state.studentApplicationsImport.activeId = "";
    state.studentApplicationsImport.truncated = false;
    state.studentApplicationsImport.error = "";
    state.studentApplicationsImport.warnings = [];
    refreshStudentApplicationsImportDialog();
  }

  function toggleAllStudentApplications() {
    const selectableIds = getVisibleStudentApplications()
      .map((row) => String(row.id));
    const selected = new Set(state.studentApplicationsImport.selected || []);
    const allSelected = selectableIds.length && selectableIds.every((id) => selected.has(id));
    selectableIds.forEach((id) => {
      if (allSelected) selected.delete(id);
      else selected.add(id);
    });
    state.studentApplicationsImport.selected = [...selected];
    state.studentApplicationsImport.selectedPayment = (state.studentApplicationsImport.rows || [])
      .reduce((sum, row) => selected.has(String(row.id))
        ? sum + getStudentApplicationReceiptAmount(row)
        : sum, 0);
    updateStudentApplicationsSelectionUi({ refreshAll: true });
  }

  function bindStudentApplicationProgramMappingControl(root = document) {
    root.querySelector("[data-student-application-program-map]")
      ?.addEventListener("change", (event) => {
        saveStudentApplicationProgramMapping(
          event.currentTarget.dataset.studentApplicationProgramMap,
          event.currentTarget.value
        );
      });
  }

  function updateStudentApplicationsSelectionUi(options = {}) {
    const selectedIds = options.selectedIds instanceof Set
      ? options.selectedIds
      : new Set((state.studentApplicationsImport.selected || []).map(String));
    const activeId = String(state.studentApplicationsImport.activeId || "");
    if (options.refreshAll) {
      document.querySelectorAll("[data-student-application-select]").forEach((input) => {
        input.checked = selectedIds.has(String(input.dataset.studentApplicationSelect || ""));
      });
    } else if (options.input) {
      options.input.checked = selectedIds.has(String(options.input.dataset.studentApplicationSelect || ""));
    }
    if (options.updateDetail) {
      document.querySelector("[data-student-application-row].is-active")?.classList.remove("is-active");
      options.row?.classList.add("is-active");
    }
    const selectedCount = document.querySelector("[data-student-applications-selected-count]");
    if (selectedCount) selectedCount.textContent = String(selectedIds.size);
    const paymentTotal = document.querySelector("[data-student-applications-selected-payment]");
    if (paymentTotal) paymentTotal.textContent = money(state.studentApplicationsImport.selectedPayment || 0);
    const addButton = document.querySelector("[data-action='add-selected-student-applications']");
    if (addButton) addButton.disabled = !selectedIds.size || state.studentApplicationsImport.importing;
    if (options.updateDetail) {
      const activeRow = (state.studentApplicationsImport.rows || [])
        .find((row) => String(row.id || "") === activeId) || null;
      const detail = document.querySelector("[data-student-applications-detail]");
      if (detail) {
        detail.innerHTML = `
          <h3 id="student-applications-detail-title">Информация о выбранной заявке</h3>
          ${renderStudentApplicationDetail(
            activeRow,
            state.studentApplicationsImport.importedLookup || buildStudentApplicationsImportLookup()
          )}
        `;
        detail.scrollTop = 0;
        bindStudentApplicationProgramMappingControl(detail);
      }
    }
  }

  function toggleStudentApplicationSelection(id, selected, options = {}) {
    const values = new Set(state.studentApplicationsImport.selected || []);
    const wasSelected = values.has(String(id));
    if (selected) values.add(String(id));
    else values.delete(String(id));
    state.studentApplicationsImport.selected = [...values];
    if (wasSelected !== Boolean(selected)) {
      const inputAmount = Number(options.input?.dataset.paymentAmount);
      const row = Number.isFinite(inputAmount)
        ? null
        : (state.studentApplicationsImport.rows || [])
          .find((item) => String(item.id || "") === String(id));
      const delta = Number.isFinite(inputAmount)
        ? Math.max(0, inputAmount)
        : getStudentApplicationReceiptAmount(row);
      state.studentApplicationsImport.selectedPayment = Math.max(
        0,
        (Number(state.studentApplicationsImport.selectedPayment) || 0) + (selected ? delta : -delta)
      );
    }
    if (options.activate) state.studentApplicationsImport.activeId = String(id);
    updateStudentApplicationsSelectionUi({ ...options, selectedIds: values });
  }

  function parseSourceAgentAssignments(value) {
    return String(value || "").split(/\r?\n/u)
      .map((line) => line.trim())
      .filter(Boolean)
      .map((line) => {
        const separatorIndex = line.indexOf("=");
        if (separatorIndex < 0) return null;
        return {
          source: line.slice(0, separatorIndex).trim(),
          agent: line.slice(separatorIndex + 1).trim()
        };
      })
      .filter((item) => item?.source && item.agent);
  }

  function getApplicationSourceAgent(source) {
    const normalizedSource = normalizeProgramName(source);
    if (!normalizedSource) return "";
    const assignments = parseSourceAgentAssignments(getPaymentSettingValue("sourceAgentAssignments"));
    const exact = assignments.find((item) => normalizeProgramName(item.source) === normalizedSource);
    if (exact) return exact.agent;
    return assignments
      .filter((item) => normalizedSource.includes(normalizeProgramName(item.source)))
      .sort((left, right) => normalizeProgramName(right.source).length - normalizeProgramName(left.source).length)[0]
      ?.agent || "";
  }

  function applyMappedAgentToStudentRecord(record, options = {}) {
    if (!record || typeof record !== "object") return record;
    const mappedAgent = getApplicationSourceAgent(record.source);
    if (!mappedAgent || (options.onlyWhenEmpty && String(record.agent || "").trim())) return record;
    return { ...record, agent: mappedAgent };
  }

  function syncStudentAgentFromSource(source) {
    const mappedAgent = getApplicationSourceAgent(source);
    if (!mappedAgent) return;
    const form = document.getElementById("recordForm");
    if (!form || form.dataset.config !== "students") return;
    const agentInput = form.elements.agent;
    if (!(agentInput instanceof HTMLInputElement) || agentInput.value === mappedAgent) return;
    agentInput.value = mappedAgent;
    agentInput.dispatchEvent(new Event("input", { bubbles: true }));
    agentInput.dispatchEvent(new Event("change", { bubbles: true }));
  }

  function parseAutomaticExpenseRules(value) {
    return String(value || "").split(/\r?\n/u)
      .map((line, index) => {
        const parts = line.split(",");
        const type = String(parts.shift() || "").trim();
        const amountFormula = String(parts.shift() || "").trim();
        const noteValues = parts.join(",").split(";")
          .map((item) => item.trim())
          .filter(Boolean);
        return {
          id: `automatic-expense-${index + 1}`,
          type,
          amountFormula,
          notes: noteValues.filter((item) => !item.startsWith("-")),
          exclusions: noteValues
            .filter((item) => item.startsWith("-"))
            .map((item) => item.slice(1).trim())
            .filter(Boolean)
        };
      })
      .filter((item) => item.type && item.amountFormula);
  }

  function getPaymentRateMarkerValues() {
    const settings = normalizePaymentSettings(state.data.dictionaries.paymentSettings);
    return Object.fromEntries(settings
      .filter((setting) => setting.type === "number" && setting.marker)
      .map((setting) => [setting.marker, Number(setting.value || 0)]));
  }

  function evaluatePaymentArithmeticExpression(value) {
    const source = String(value || "").replace(/\s+/g, "").replace(/,/g, ".");
    if (!source) return 0;
    const tokens = source.match(/\d+(?:\.\d+)?|[()+\-*/]/g) || [];
    if (tokens.join("") !== source) return 0;
    let index = 0;
    const parsePrimary = () => {
      const token = tokens[index];
      if (token === "(") {
        index += 1;
        const result = parseAddition();
        if (tokens[index] !== ")") throw new Error("missing parenthesis");
        index += 1;
        return result;
      }
      if (token === "+" || token === "-") {
        index += 1;
        const result = parsePrimary();
        return token === "-" ? -result : result;
      }
      const number = Number(token);
      if (!Number.isFinite(number)) throw new Error("invalid number");
      index += 1;
      return number;
    };
    const parseMultiplication = () => {
      let result = parsePrimary();
      while (tokens[index] === "*" || tokens[index] === "/") {
        const operator = tokens[index];
        index += 1;
        const operand = parsePrimary();
        result = operator === "*" ? result * operand : result / operand;
      }
      return result;
    };
    const parseAddition = () => {
      let result = parseMultiplication();
      while (tokens[index] === "+" || tokens[index] === "-") {
        const operator = tokens[index];
        index += 1;
        const operand = parseMultiplication();
        result = operator === "+" ? result + operand : result - operand;
      }
      return result;
    };
    try {
      const result = parseAddition();
      return index === tokens.length && Number.isFinite(result) ? result : 0;
    } catch {
      return 0;
    }
  }

  function evaluatePaymentAmountFormula(formula) {
    let expression = String(formula || "").trim().replace(/[\[\]]/g, "");
    const markerValues = new Map(Object.entries(getPaymentRateMarkerValues()).map(([marker, value]) => [
      normalizePaymentConstantMarker(marker).toLocaleLowerCase("ru-RU"),
      value
    ]));
    expression = expression
      .split(/([A-Za-zА-Яа-яЁё_][A-Za-zА-Яа-яЁё0-9_]*)/gu)
      .map((part) => (
        markerValues.has(part.toLocaleLowerCase("ru-RU"))
          ? String(markerValues.get(part.toLocaleLowerCase("ru-RU")))
          : part
      ))
      .join("");
    const amount = evaluatePaymentArithmeticExpression(expression);
    return Math.round(Math.max(0, amount) * 100) / 100;
  }

  function getProgramAuthorPaymentPercent(formula) {
    const source = String(formula || "").trim();
    const normalizedAuthorRateFormula = source
      .replace(/^\[+|\]+$/g, "")
      .trim()
      .toLocaleLowerCase("ru-RU");
    if (normalizedAuthorRateFormula === "АвторскаяСтавка".toLocaleLowerCase("ru-RU")) {
      return evaluatePaymentAmountFormula("[АвторскаяСтавка]");
    }
    if (!source.endsWith("%")) return "";
    return evaluatePaymentAmountFormula(source.slice(0, -1));
  }

  function evaluateProgramAuthorPaymentFormula(formula, paymentTotal) {
    const percent = getProgramAuthorPaymentPercent(formula);
    if (percent !== "") {
      return Math.round(Math.max(0, Number(paymentTotal || 0)) * Number(percent || 0)) / 100;
    }
    return evaluatePaymentAmountFormula(formula);
  }

  function extractPaymentRecipientName(value) {
    return String(value || "").split(",")[0].trim();
  }

  function automaticExpenseFingerprint(expense) {
    return [
      normalizeProgramName(expense?.type),
      Math.round(Number(expense?.amount || 0) * 100) / 100,
      normalizeProgramName(expense?.note)
    ].join("|");
  }

  function getProgramAuthorExpenseRule(rules = null) {
    const sourceRules = Array.isArray(rules)
      ? rules
      : parseAutomaticExpenseRules(getPaymentSettingValue("automaticExpenseRules"));
    return sourceRules.find((rule) => (
      normalizeProgramName(rule.type) === normalizeProgramName("Оплата преподавателю")
    )) || null;
  }

  function buildProgramAuthorExpenseSpecifications(record, program, rule) {
    if (!program || !rule) return [];
    const paymentTotal = Math.round(sumStudentPayments(record) * 100) / 100;
    const authors = normalizeProgramAuthorPayments(
      program.authorPayments,
      program.authorSource,
      program.defaultAuthorPaymentPercent || state.data.meta.defaultAuthorPaymentPercent || 50
    );
    return authors.map((author, index) => {
      const recipient = String(author.recipient || "").trim();
      const normalizedRecipient = normalizeProgramName(recipient);
      if (!recipient || rule.exclusions.some((item) => normalizeProgramName(item) === normalizedRecipient)) {
        return null;
      }
      const amountFormula = String(rule.amountFormula || "").trim();
      const paymentPercent = getProgramAuthorPaymentPercent(amountFormula);
      const amount = evaluateProgramAuthorPaymentFormula(amountFormula, paymentTotal);
      return {
        recipient,
        amount: Math.round(Math.max(0, Number(amount || 0)) * 100) / 100,
        suffix: `author-${index + 1}-${normalizedRecipient}`,
        automaticPaymentKind: "program-author",
        automaticPaymentProgramId: String(program.id || "").trim(),
        automaticPaymentProgramName: String(program.name || "").trim(),
        automaticPaymentAuthorId: String(author.id || `program-author-${index + 1}`),
        automaticPaymentPercent: paymentPercent === "" ? "" : Number(paymentPercent || 0),
        automaticPaymentFormula: amountFormula
      };
    }).filter(Boolean);
  }

  function isAutomaticProgramAuthorExpense(expense) {
    const key = String(expense?.automaticPaymentKey || "");
    return expense?.automaticPaymentKind === "program-author"
      || (/^automatic-expense-\d+:author-/u.test(key));
  }

  function recalculateAutomaticProgramAuthorExpenses(record, programOverride = null) {
    const directExpenses = Array.isArray(record?.directExpenses)
      ? record.directExpenses
      : [];
    if (!directExpenses.some(isAutomaticProgramAuthorExpense)) return record;
    const program = programOverride || findProgramByName(record?.program);
    const rule = getProgramAuthorExpenseRule();
    if (!program || !rule) return record;
    const specifications = buildProgramAuthorExpenseSpecifications(record, program, rule)
      .map((item) => ({
        ...item,
        automaticPaymentKey: `${rule.id}:${item.suffix}`
      }));
    const unusedSpecifications = new Set(specifications);
    let changed = false;
    const nextExpenses = directExpenses.map((expense) => {
      if (!isAutomaticProgramAuthorExpense(expense)) return expense;
      const expenseKey = String(expense.automaticPaymentKey || "");
      let specification = specifications.find((item) => (
        unusedSpecifications.has(item) && item.automaticPaymentKey === expenseKey
      ));
      if (!specification) {
        const recipient = normalizeProgramName(expense.note);
        specification = specifications.find((item) => (
          unusedSpecifications.has(item) && normalizeProgramName(item.recipient) === recipient
        ));
      }
      if (!specification) return expense;
      unusedSpecifications.delete(specification);
      const nextExpense = {
        ...expense,
        type: rule.type,
        amount: specification.amount,
        note: specification.recipient,
        automaticPaymentKey: specification.automaticPaymentKey,
        automaticPaymentKind: specification.automaticPaymentKind,
        automaticPaymentProgramId: specification.automaticPaymentProgramId,
        automaticPaymentProgramName: specification.automaticPaymentProgramName,
        automaticPaymentAuthorId: specification.automaticPaymentAuthorId,
        automaticPaymentPercent: specification.automaticPaymentPercent,
        automaticPaymentFormula: specification.automaticPaymentFormula
      };
      if (
        Number(expense.amount || 0) !== nextExpense.amount
        || expense.note !== nextExpense.note
        || expense.automaticPaymentKey !== nextExpense.automaticPaymentKey
        || expense.automaticPaymentPercent !== nextExpense.automaticPaymentPercent
        || expense.automaticPaymentFormula !== nextExpense.automaticPaymentFormula
      ) changed = true;
      return nextExpense;
    });
    return changed ? { ...record, directExpenses: nextExpenses } : record;
  }

  function buildAutomaticStudentExpenses(record, program = null) {
    const rules = parseAutomaticExpenseRules(getPaymentSettingValue("automaticExpenseRules"));
    const commonRulesAllowed = isFrdoProgramType(program?.type || record.educationType);
    const existingExpenses = Array.isArray(record.directExpenses) ? record.directExpenses : [];
    const existingKeys = new Set(existingExpenses.map((expense) => String(expense?.automaticPaymentKey || "")).filter(Boolean));
    const existingFingerprints = new Set(existingExpenses.map(automaticExpenseFingerprint));
    const additions = [];
    const addExpense = (rule, recipient, amount, suffix = "", options = {}) => {
      const note = String(recipient || "").trim();
      const normalizedRecipient = normalizeProgramName(note);
      if (rule.exclusions.some((item) => normalizeProgramName(item) === normalizedRecipient)) return;
      const roundedAmount = Math.round(Number(amount || 0) * 100) / 100;
      if (!Number.isFinite(roundedAmount) || roundedAmount < 0 || (!options.allowZero && roundedAmount === 0)) return;
      const automaticPaymentKey = `${rule.id}:${suffix || normalizedRecipient || "default"}`;
      const expense = {
        id: makeId("direct-expense"),
        uid: String(record.uid || "").trim(),
        date: todayIso(),
        type: rule.type,
        amount: roundedAmount,
        isPaid: "",
        note,
        inventoryId: "",
        inventoryLink: "",
        automaticPaymentKey,
        ...(options.metadata || {})
      };
      const fingerprint = automaticExpenseFingerprint(expense);
      if (
        existingKeys.has(automaticPaymentKey)
        || (!options.allowDuplicateFingerprint && existingFingerprints.has(fingerprint))
      ) return;
      existingKeys.add(automaticPaymentKey);
      existingFingerprints.add(fingerprint);
      additions.push(expense);
    };

    rules.forEach((rule) => {
      const normalizedType = normalizeProgramName(rule.type);
      if (normalizedType === normalizeProgramName("Оплата преподавателю")) {
        buildProgramAuthorExpenseSpecifications(record, program, rule).forEach((item) => {
          addExpense(rule, item.recipient, item.amount, item.suffix, {
            allowZero: true,
            allowDuplicateFingerprint: true,
            metadata: {
              automaticPaymentKind: item.automaticPaymentKind,
              automaticPaymentProgramId: item.automaticPaymentProgramId,
              automaticPaymentProgramName: item.automaticPaymentProgramName,
              automaticPaymentAuthorId: item.automaticPaymentAuthorId,
              automaticPaymentPercent: item.automaticPaymentPercent,
              automaticPaymentFormula: item.automaticPaymentFormula
            }
          });
        });
        return;
      }
      if (normalizedType === normalizeProgramName("Оплата председателю ИАК")) {
        const recipient = extractPaymentRecipientName(program?.commissionChair);
        if (recipient) addExpense(rule, recipient, evaluatePaymentAmountFormula(rule.amountFormula), "commission-chair");
        return;
      }
      if (!commonRulesAllowed) return;
      addExpense(
        rule,
        rule.notes.join("; "),
        evaluatePaymentAmountFormula(rule.amountFormula),
        `rule-${rule.id}`
      );
    });
    return additions;
  }

  function addAutomaticStudentExpenses(record, program = null) {
    const reconciledRecord = recalculateAutomaticProgramAuthorExpenses(record, program);
    const additions = buildAutomaticStudentExpenses(reconciledRecord, program);
    const nextRecord = {
      ...reconciledRecord,
      directExpenses: [
        ...(Array.isArray(reconciledRecord.directExpenses) ? reconciledRecord.directExpenses : []),
        ...additions
      ]
    };
    nextRecord.expenseTotal = Math.round(sumStudentExpenses(nextRecord) * 100) / 100;
    return { record: nextRecord, additions };
  }

  function createStudentFromApplication(row, uid, status, selectedProgramId, existingStudentsLookup) {
    const program = getStudentApplicationProgram(row, selectedProgramId);
    const financialTerms = getStudentApplicationFinancialTerms(row, program);
    const { paymentAmount, contractAmount } = financialTerms;
    const applicationDate = String(row.dateCreated || "").slice(0, 10);
    const paymentDate = paymentAmount ? (applicationDate || todayIso()) : "";
    const city = String(row.city || "").trim();
    const noteParts = [
      String(row.note || "").trim(),
      city ? `Город: ${city}` : ""
    ].filter(Boolean);
    let record = {
      id: makeId("students"),
      uid: String(uid),
      name: String(row.name || "").trim(),
      status: status || "На зачисление",
      program: String(program?.name || getStudentApplicationProgramTitle(row)).trim(),
      studyForm: String(program?.studyForm || ""),
      educationType: String(program?.type || getStudentApplicationInferredProgramType(row) || ""),
      hours: program?.hours || "",
      phone: String(row.phone || "").trim(),
      email: String(row.email || "").trim(),
      registrationAddress: city,
      workPlace: String(row.organization || "").trim(),
      position: String(row.position || "").trim(),
      source: String(row.source || "Сайт").trim(),
      agent: getApplicationSourceAgent(row.source || "Сайт"),
      manager: getCurrentUserLogin() || String(program?.manager || ""),
      fundingSource: "Собственные средства",
      discount: financialTerms.percent,
      discountUnit: "percent",
      discountDescription: financialTerms.description,
      coupon: financialTerms.coupon,
      note: noteParts.join("\n"),
      applicationDate,
      orderNo: String(row.orderId || "").trim(),
      sourceApplicationKey: getStudentApplicationSourceKey(row),
      sourceOrderId: String(row.orderId || "").trim(),
      sourceProductId: String(row.productId || "").trim(),
      photoPath: "",
      contractAmount,
      payment1Date: paymentDate,
      payment1Amount: paymentAmount,
      payment1Note: paymentAmount ? [
        `Заказ №${String(row.orderId || "").trim()}`,
        financialTerms.installmentPercent
          ? `рассрочка ${financialTerms.installmentPercent}% по купону ${financialTerms.coupon}`
          : ""
      ].filter(Boolean).join("; ") : "",
      directExpenses: []
    };
    record = reuseExistingStudentPersonalData(record, row, existingStudentsLookup, selectedProgramId);
    record.additionalStatus = resolveProStudentAdditionalStatus(
      record,
      program?.type || record.educationType,
      { imported: true }
    );
    return calculateStudentFinance(addAutomaticStudentExpenses(
      applyStudentEventTemplateDefaults(record),
      program
    ).record);
  }

  async function ensureStudentDocumentFolders(records) {
    const recordsWithoutFolder = records.filter((record) => !String(record.photoPath || "").trim());
    if (!recordsWithoutFolder.length) return;
    const response = await fetch(photoApiUrl("/api/students/ensure-document-folders"), {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        students: recordsWithoutFolder.map((record) => ({
          id: record.id,
          name: record.name
        }))
      })
    });
    const payload = await response.json().catch(() => ({}));
    if (!response.ok) {
      throw new Error(payload.error || "Не удалось создать папки слушателей на Яндекс-Диске.");
    }
    const folderById = new Map((payload.folders || []).map((item) => [
      String(item.id),
      String(item.relativePath || "")
    ]));
    recordsWithoutFolder.forEach((record) => {
      const relativePath = folderById.get(String(record.id));
      if (!relativePath) {
        throw new Error(`Сервер не вернул путь папки для ${record.name}.`);
      }
      record.photoPath = relativePath;
    });
  }

  async function addSelectedStudentApplications() {
    const selectedIds = new Set(state.studentApplicationsImport.selected || []);
    const selectedRows = (state.studentApplicationsImport.rows || [])
      .filter((row) => selectedIds.has(String(row.id)));
    if (!selectedRows.length) {
      alert("Выберите заявки, которые нужно добавить.");
      return;
    }
    const selectedProgramId = getStudentApplicationsSingleProgramFilterId();
    const unresolvedRow = selectedRows.find((row) => !getStudentApplicationProgram(row, selectedProgramId));
    if (unresolvedRow) {
      state.studentApplicationsImport.activeId = String(unresolvedRow.id || "");
      const visibleRows = getVisibleStudentApplications();
      const rowIndex = visibleRows.findIndex((row) => String(row.id || "") === String(unresolvedRow.id || ""));
      if (rowIndex >= 0) {
        state.studentApplicationsImport.page = Math.floor(
          rowIndex / Number(state.studentApplicationsImport.pageSize || 100)
        ) + 1;
      }
      state.studentApplicationsImport.error = `Сопоставьте программу заявки «${getStudentApplicationProgramTitle(unresolvedRow) || "Без названия"}» с программой из реестра.`;
      refreshStudentApplicationsImportDialog();
      requestAnimationFrame(() => {
        document.querySelector(`[data-student-application-program-map="${CSS.escape(String(unresolvedRow.id || ""))}"]`)?.focus();
      });
      return;
    }
    if (!confirm(`Добавить выбранных слушателей: ${selectedRows.length}?`)) return;
    const status = state.studentApplicationsImport.filters.status || "На зачисление";
    const existingStudentsLookup = state.studentApplicationsImport.importedLookup
      || buildStudentApplicationsImportLookup();
    let nextUid = Number(getNextUid()) || 1;
    const imported = [];
    let skipped = 0;
    selectedRows.forEach((row) => {
      if (!String(row.name || "").trim()) {
        skipped += 1;
        return;
      }
      imported.push(createStudentFromApplication(
        row,
        nextUid,
        status,
        selectedProgramId,
        existingStudentsLookup
      ));
      nextUid += 1;
    });
    if (!imported.length) {
      alert("В выбранных заявках не заполнено ФИО.");
      return;
    }
    state.studentApplicationsImport.importing = true;
    refreshStudentApplicationsImportDialog();
    try {
      await ensureStudentDocumentFolders(imported);
    } catch (error) {
      state.studentApplicationsImport.importing = false;
      refreshStudentApplicationsImportDialog();
      alert(`Слушатели не импортированы: ${error.message}`);
      return;
    }
    state.data.collections.students = [
      ...imported,
      ...(state.data.collections.students || [])
    ];
    state.data.dictionaries.agents = unique([
      ...(state.data.dictionaries.agents || []),
      ...imported.map((record) => String(record.agent || "").trim()).filter(Boolean)
    ]);
    state.data.dictionaries.managers = unique([
      ...(state.data.dictionaries.managers || []),
      getCurrentUserLogin()
    ].filter(Boolean));
    addAudit(
      "Импортированы слушатели",
      "Слушатели и заявки",
      `Добавлено: ${imported.length}${skipped ? `, пропущено без ФИО: ${skipped}` : ""}`,
      {
        entityType: "students",
        entityId: imported.map((record) => record.id).join(", "),
        entityLabel: imported.map((record) => record.name).filter(Boolean).join(", "),
        source: "applications-import"
      }
    );
    state.lastEditedRow = { config: "students", id: imported[0].id };
    state.view = "students";
    state.search = "";
    state.statusFilter = "Все";
    state.studentProgramTypeFilter = [];
    state.studentImportedViewIds = imported.map((record) => record.id);
    state.selected.students = [];
    state.sort = getStudentStatusTableSort(state.statusFilter);
    state.tablePages.students = 1;
    state.tableOptions = null;
    state.studentApplicationsImport.open = false;
    state.studentApplicationsImport.importing = false;
    persist();
    render();
  }

  function bindStudentApplicationsImportEvents(root = document) {
    if (root === document) {
      document.querySelector("[data-action='open-student-applications-import']")
        ?.addEventListener("click", openStudentApplicationsImport);
    }
    if (!state.studentApplicationsImport.open) return;
    const scope = root.matches?.("[data-student-applications-import-backdrop]")
      ? root
      : root.querySelector?.("[data-student-applications-import-backdrop]");
    if (!scope) return;
    const closeElements = [
      ...(scope.matches("[data-action='close-student-applications-import']") ? [scope] : []),
      ...scope.querySelectorAll("[data-action='close-student-applications-import']")
    ];
    closeElements.forEach((element) => {
      element.addEventListener("click", (event) => {
        if (element === event.currentTarget && (
          element.matches("button")
          || event.target === element
        )) {
          event.preventDefault();
          closeStudentApplicationsImport();
        }
      });
    });
    const form = scope.querySelector("[data-student-applications-import-form]");
    form?.addEventListener("submit", fetchStudentApplications);
    form?.elements.period?.addEventListener("change", (event) => {
      syncStudentApplicationsImportFilters(form);
      updateStudentApplicationsPeriod(event.currentTarget.value);
    });
    ["dateFrom", "dateTo", "onlyPaid", "importStatus"].forEach((name) => {
      form?.elements[name]?.addEventListener("change", () => {
        if (name === "dateFrom" || name === "dateTo") {
          form.elements.period.value = "custom";
        }
        syncStudentApplicationsImportFilters(form);
      });
    });
    form?.elements.applicationSearch?.addEventListener("input", (event) => {
      const cursor = event.currentTarget.selectionStart;
      state.studentApplicationsImport.filters.search = event.currentTarget.value;
      state.studentApplicationsImport.page = 1;
      clearTimeout(studentApplicationsSearchTimer);
      studentApplicationsSearchTimer = window.setTimeout(() => {
        refreshStudentApplicationsImportDialog({ focusSearch: true, searchCursor: cursor });
      }, 120);
    });
    scope.querySelector("[data-student-applications-program-search]")?.addEventListener("input", (event) => {
      state.studentApplicationsImport.filters.programQuery = event.currentTarget.value;
      applyStudentApplicationsProgramSearch(
        event.currentTarget.value,
        event.currentTarget.closest("[data-student-applications-program-filter]")
      );
    });
    scope.querySelectorAll("[data-student-applications-program-filter-option]").forEach((input) => {
      input.addEventListener("change", () => {
        const filter = input.closest("[data-student-applications-program-filter]");
        const selectedIds = Array.from(
          filter?.querySelectorAll("[data-student-applications-program-filter-option]:checked") || []
        ).map((item) => String(item.value || "")).filter(Boolean);
        state.studentApplicationsImport.filters.programIds = unique(selectedIds);
        state.studentApplicationsImport.filters.programId = selectedIds.length === 1 ? selectedIds[0] : "";
        filter?.classList.toggle("is-active", selectedIds.length > 0);
        const label = filter?.querySelector("[data-student-applications-program-filter-label]");
        if (label) label.textContent = getStudentApplicationsProgramFilterLabel();
        const clearButton = filter?.querySelector("[data-action='clear-student-applications-program-filter']");
        if (clearButton) clearButton.disabled = selectedIds.length === 0;
      });
    });
    scope.querySelector("[data-action='clear-student-applications-program-filter']")?.addEventListener("click", (event) => {
      const filter = event.currentTarget.closest("[data-student-applications-program-filter]");
      filter?.querySelectorAll("[data-student-applications-program-filter-option]")
        .forEach((input) => { input.checked = false; });
      state.studentApplicationsImport.filters.programIds = [];
      state.studentApplicationsImport.filters.programId = "";
      state.studentApplicationsImport.filters.programQuery = "";
      filter?.classList.remove("is-active");
      const search = filter?.querySelector("[data-student-applications-program-search]");
      if (search) search.value = "";
      applyStudentApplicationsProgramSearch("", filter || scope);
      const label = filter?.querySelector("[data-student-applications-program-filter-label]");
      if (label) label.textContent = "Все программы";
      event.currentTarget.disabled = true;
    });
    scope.querySelector("[data-action='clear-student-applications-filters']")
      ?.addEventListener("click", clearStudentApplicationsFilters);
    scope.querySelector("[data-action='select-all-student-applications']")
      ?.addEventListener("click", toggleAllStudentApplications);
    scope.querySelector("[data-action='add-selected-student-applications']")
      ?.addEventListener("click", addSelectedStudentApplications);
    scope.querySelectorAll("[data-action='student-applications-page']").forEach((button) => {
      button.addEventListener("click", () => {
        state.studentApplicationsImport.page = Number(button.dataset.page || 1);
        const visibleRows = getVisibleStudentApplications();
        const pagination = getStudentApplicationsImportPagination(visibleRows.length);
        state.studentApplicationsImport.activeId = String(visibleRows[pagination.start]?.id || "");
        refreshStudentApplicationsImportDialog();
      });
    });
    const pageInput = scope.querySelector("[data-action='student-applications-page-input']");
    const applyPageInput = () => {
      if (!pageInput) return;
      state.studentApplicationsImport.page = Number(pageInput.value || 1);
      const visibleRows = getVisibleStudentApplications();
      const pagination = getStudentApplicationsImportPagination(visibleRows.length);
      state.studentApplicationsImport.activeId = String(visibleRows[pagination.start]?.id || "");
      refreshStudentApplicationsImportDialog();
    };
    pageInput?.addEventListener("change", applyPageInput);
    pageInput?.addEventListener("keydown", (event) => {
      if (event.key !== "Enter") return;
      event.preventDefault();
      applyPageInput();
    });
    scope.querySelector("[data-action='student-applications-page-size']")?.addEventListener("change", (event) => {
      state.studentApplicationsImport.pageSize = Number(event.currentTarget.value || 100);
      state.studentApplicationsImport.page = 1;
      state.studentApplicationsImport.activeId = String(getVisibleStudentApplications()[0]?.id || "");
      refreshStudentApplicationsImportDialog();
    });
    scope.querySelectorAll("[data-action='sort-student-applications']").forEach((button) => {
      button.addEventListener("click", () => {
        const key = String(button.dataset.key || "");
        if (!STUDENT_APPLICATIONS_IMPORT_TABLE_COLUMNS.some((column) => column.key === key)) return;
        const currentSort = state.studentApplicationsImport.sort || STUDENT_APPLICATIONS_IMPORT_DEFAULT_SORT;
        state.studentApplicationsImport.sort = {
          key,
          dir: currentSort.key === key && currentSort.dir === "asc" ? "desc" : "asc"
        };
        state.studentApplicationsImport.page = 1;
        refreshStudentApplicationsImportDialog();
      });
    });
    scope.querySelector("[data-action='toggle-student-applications-table-options']")?.addEventListener("click", () => {
      state.tableOptions = state.tableOptions === STUDENT_APPLICATIONS_IMPORT_TABLE_CONFIG_ID
        ? null
        : STUDENT_APPLICATIONS_IMPORT_TABLE_CONFIG_ID;
      refreshStudentApplicationsImportDialog();
    });
    scope.querySelector("[data-action='reset-table-options']")?.addEventListener("click", (event) => {
      if (event.currentTarget.dataset.config !== STUDENT_APPLICATIONS_IMPORT_TABLE_CONFIG_ID) return;
      resetTableOptions(STUDENT_APPLICATIONS_IMPORT_TABLE_CONFIG_ID);
    });
    scope.querySelectorAll("[data-action='close-table-options']").forEach((element) => {
      element.addEventListener("click", () => {
        state.tableOptions = null;
        refreshStudentApplicationsImportDialog();
      });
    });
    bindTableColumnEvents(scope);
    annotateShiftRequiredDraggableElements(scope);
    bindStudentApplicationProgramMappingControl(scope);
    scope.querySelectorAll("[data-student-application-select]").forEach((input) => {
      input.addEventListener("click", (event) => event.stopPropagation());
      input.addEventListener("change", () => {
        toggleStudentApplicationSelection(
          input.dataset.studentApplicationSelect,
          input.checked,
          { input, updateDetail: false }
        );
      });
    });
    scope.querySelectorAll("[data-student-application-row]").forEach((row) => {
      row.addEventListener("click", () => {
        const id = String(row.dataset.studentApplicationRow || "");
        const checkbox = row.querySelector("[data-student-application-select]");
        if (checkbox && !checkbox.disabled) {
          toggleStudentApplicationSelection(
            id,
            !checkbox.checked,
            { input: checkbox, row, activate: true, updateDetail: true }
          );
          return;
        }
        state.studentApplicationsImport.activeId = id;
        refreshStudentApplicationsImportDialog();
      });
    });
  }

  function renderBulkToolbar(config, rows, configId) {
    const selected = getSelected(configId);
    const selectedRows = getRowsByIds(config.collection, selected);
    const statusField = config.fields.find((item) => item.key === "status");
    const statusOptions = statusField ? (statusField.options || state.data.dictionaries[statusField.dict] || getFilterOptions(config)) : [];
    return `
      <div class="bulk-toolbar ${selected.length ? "active" : ""}">
        <span>Выбрано: <strong>${selected.length}</strong></span>
        ${statusOptions.length ? `
          <select id="bulkStatusSelect" class="select-control" ${statusField?.dict ? `data-settings-dictionary="${escapeAttr(statusField.dict)}"` : ""} ${selected.length ? "" : "disabled"}>
            ${configId === "students"
              ? renderStudentStatusOptions(statusOptions)
              : statusOptions.map((item) => `<option>${escapeHtml(item)}</option>`).join("")}
          </select>
          <button class="ghost-button" data-action="bulk-status" data-config="${configId}" type="button" ${selected.length ? "" : "disabled"}>Сменить статус</button>
        ` : ""}
        ${configId === "students" ? "" : `<button class="ghost-button" data-action="bulk-clear" data-config="${configId}" type="button" ${selected.length ? "" : "disabled"}>Снять выбор</button>`}
        ${configId === "students" ? `
          <button class="primary-button" data-action="open-student-bulk-operations" type="button" ${selected.length ? "" : "disabled"}>Групповые операции</button>
        ` : ""}
        ${configId === "generalExpenses" ? `
          <button class="ghost-button" data-action="bulk-copy-general-expenses" data-config="${configId}" type="button" title="Копировать выбранные общие расходы с текущей датой" ${selectedRows.length ? "" : "disabled"}>
            Копировать
          </button>
        ` : ""}
        <button class="ghost-button icon-only csv-button" data-action="bulk-export" data-config="${configId}" type="button" title="Экспорт выбранных в CSV" aria-label="Экспорт выбранных в CSV" ${selectedRows.length ? "" : "disabled"}>
          <svg class="csv-icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false">
            <rect x="3" y="4" width="13" height="16" rx="2"></rect>
            <path d="M3 9h13"></path>
            <path d="M3 14h9"></path>
            <path d="M8 4v16"></path>
            <path d="M19 10v9"></path>
            <path d="m16 16 3 3 3-3"></path>
          </svg>
        </button>
        <button class="danger-button icon-only trash-button" data-action="bulk-delete" data-config="${configId}" type="button" title="Удалить выбранные" aria-label="Удалить выбранные" ${selected.length ? "" : "disabled"}>
          <svg class="trash-icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false">
            <path d="M3 6h18"></path>
            <path d="M8 6V4h8v2"></path>
            <path d="M6 6l1 15h10l1-15"></path>
            <path d="M10 11v6"></path>
            <path d="M14 11v6"></path>
          </svg>
        </button>
        <button class="ghost-button icon-only table-options-button" data-action="toggle-table-options" data-config="${configId}" type="button" title="Опции таблицы" aria-label="Опции таблицы">⋯</button>
      </div>
      ${renderTableOptions(configId)}
    `;
  }

  function getRowsForConfig(config, rowsOverride = null) {
    if (Array.isArray(rowsOverride)) return rowsOverride;
    if (config?.collection === "documentTemplates") return getDocumentTemplateRows();
    return state.data.collections[config.collection] || [];
  }

  function renderDatabaseImportIndicator() {
    const progress = Math.max(0, Math.min(100, Number(state.databaseImport.progress || 0)));
    const tone = ["active", "success", "error"].includes(state.databaseImport.tone)
      ? state.databaseImport.tone
      : "active";
    return `
      <div class="database-import-indicator tone-${tone} ${state.databaseImport.indeterminate ? "is-indeterminate" : ""}" data-database-import-indicator role="status" aria-live="polite" ${state.databaseImport.visible ? "" : "hidden"}>
        <div class="database-import-indicator-head">
          <span class="database-import-indicator-icon" aria-hidden="true"></span>
          <div>
            <strong>Импорт из АИС Допобразование</strong>
            <span data-database-import-status>${escapeHtml(state.databaseImport.status || "Подготовка...")}</span>
          </div>
          <span class="database-import-indicator-percent" data-database-import-percent ${state.databaseImport.indeterminate || tone === "error" ? "hidden" : ""}>${progress}%</span>
        </div>
        <div class="database-import-progress-track" data-database-import-progress>
          <span style="width: ${progress}%"></span>
        </div>
      </div>
    `;
  }

  function renderDatabaseExportIndicator() {
    const progress = Math.max(0, Math.min(100, Number(state.databaseExport.progress || 0)));
    const tone = ["active", "success", "error"].includes(state.databaseExport.tone)
      ? state.databaseExport.tone
      : "active";
    return `
      <div class="database-import-indicator tone-${tone} ${state.databaseExport.indeterminate ? "is-indeterminate" : ""}" data-database-export-indicator role="status" aria-live="polite" ${state.databaseExport.visible ? "" : "hidden"}>
        <div class="database-import-indicator-head">
          <span class="database-import-indicator-icon" aria-hidden="true"></span>
          <div>
            <strong>Синхронизация с АИС Допобразование</strong>
            <span data-database-export-status>${escapeHtml(state.databaseExport.status || "Подготовка...")}</span>
          </div>
          <span class="database-import-indicator-percent" data-database-export-percent ${state.databaseExport.indeterminate || tone === "error" ? "hidden" : ""}>${progress}%</span>
        </div>
        <div class="database-import-progress-track" data-database-export-progress>
          <span style="width: ${progress}%"></span>
        </div>
      </div>
    `;
  }

  function renderStudentProgramTypeFilter() {
    const selected = STUDENT_PROGRAM_TYPE_FILTER_OPTIONS
      .filter((item) => state.studentProgramTypeFilter.includes(item));
    const selectionLabel = selected.length ? selected.join(", ") : "Все виды";
    return `
      <details class="student-program-type-filter ${selected.length ? "is-active" : ""}" data-program-type-filter data-student-program-type-filter>
        <summary title="Фильтр по виду программы">
          <span>Вид программы</span>
          <strong>${escapeHtml(selectionLabel)}</strong>
          <svg viewBox="0 0 12 8" aria-hidden="true"><path d="M1 1.5 6 6.5l5-5"></path></svg>
        </summary>
        <div class="student-program-type-filter-panel">
          ${STUDENT_PROGRAM_TYPE_FILTER_OPTIONS.map((item) => `
            <label>
              <input type="checkbox" value="${escapeAttr(item)}" data-student-program-type-filter-option ${selected.includes(item) ? "checked" : ""}>
              <span>${escapeHtml(item)}</span>
            </label>
          `).join("")}
          <button class="student-program-type-filter-clear" data-action="clear-student-program-type-filter" type="button" ${selected.length ? "" : "disabled"}>Сбросить</button>
        </div>
      </details>
    `;
  }

  function getProgramRegistryTypeFilterOptions() {
    const values = unique(
      getProgramRows()
        .map((program) => String(program.type || "").trim())
        .filter(Boolean)
    );
    const ordered = [
      ...STUDENT_PROGRAM_TYPE_FILTER_OPTIONS.filter((item) => values.includes(item)),
      ...values
        .filter((item) => !STUDENT_PROGRAM_TYPE_FILTER_OPTIONS.includes(item))
        .sort((left, right) => left.localeCompare(right, "ru"))
    ];
    if (getProgramRows().some((program) => !String(program.type || "").trim())) {
      ordered.push("Не задано");
    }
    return ordered;
  }

  function renderProgramRegistryTypeFilter() {
    const options = getProgramRegistryTypeFilterOptions();
    const selected = options.filter((item) => state.programRegistryTypeFilter.includes(item));
    const selectionLabel = selected.length ? selected.join(", ") : "Все типы";
    return `
      <details class="student-program-type-filter ${selected.length ? "is-active" : ""}" data-program-type-filter data-program-registry-type-filter>
        <summary title="Фильтр по типу программы">
          <span>Тип программы</span>
          <strong>${escapeHtml(selectionLabel)}</strong>
          <svg viewBox="0 0 12 8" aria-hidden="true"><path d="M1 1.5 6 6.5l5-5"></path></svg>
        </summary>
        <div class="student-program-type-filter-panel">
          ${options.map((item) => `
            <label>
              <input type="checkbox" value="${escapeAttr(item)}" data-program-registry-type-filter-option ${selected.includes(item) ? "checked" : ""}>
              <span>${escapeHtml(item)}</span>
            </label>
          `).join("")}
          <button class="student-program-type-filter-clear" data-action="clear-program-registry-type-filter" type="button" ${selected.length ? "" : "disabled"}>Сбросить</button>
        </div>
      </details>
    `;
  }

  function renderContractSectionFilter() {
    const selected = CONTRACT_SECTIONS.filter((item) => state.contractSectionFilter.includes(item));
    const selectionLabel = selected.length ? selected.join(", ") : `Все разделы (${getRowsForConfig(configs.contracts).length})`;
    return `
      <details class="student-program-type-filter ${selected.length ? "is-active" : ""}" data-program-type-filter data-contract-section-filter>
        <summary title="Фильтр по разделу реестра договоров">
          <span>Раздел</span>
          <strong>${escapeHtml(selectionLabel)}</strong>
          <svg viewBox="0 0 12 8" aria-hidden="true"><path d="M1 1.5 6 6.5l5-5"></path></svg>
        </summary>
        <div class="student-program-type-filter-panel">
          ${CONTRACT_SECTIONS.map((item) => {
            const count = getRowsForConfig(configs.contracts)
              .filter((contract) => normalizeContractSection(contract.section, contract.status) === item).length;
            return `
              <label>
                <input type="checkbox" value="${escapeAttr(item)}" data-contract-section-filter-option ${selected.includes(item) ? "checked" : ""}>
                <span>${escapeHtml(item)} (${count})</span>
              </label>
            `;
          }).join("")}
          <button class="student-program-type-filter-clear" data-action="clear-contract-section-filter" type="button" ${selected.length ? "" : "disabled"}>Сбросить</button>
        </div>
      </details>
    `;
  }

  function getGeneralExpenseRowsForSectionFilter() {
    const selectedSections = GENERAL_EXPENSE_SECTIONS
      .filter((item) => state.generalExpenseSectionFilter.includes(item));
    const rows = getRowsForConfig(configs.generalExpenses);
    if (!selectedSections.length) return rows;
    return rows.filter((expense) => selectedSections.includes(
      normalizeGeneralExpenseSection(expense.section, expense.counterparty)
    ));
  }

  function getGeneralExpenseWorkTypeFilterOptions() {
    const rows = getGeneralExpenseRowsForSectionFilter();
    const values = unique(rows
      .map((expense) => String(expense.workType || "").trim())
      .filter(Boolean))
      .sort((left, right) => left.localeCompare(right, "ru", { sensitivity: "base" }));
    if (rows.some((expense) => !String(expense.workType || "").trim())) values.push("Не задано");
    return values;
  }

  function formatGeneralExpenseMultiFilterLabel(selected, emptyLabel) {
    if (!selected.length) return emptyLabel;
    if (selected.length === 1) return selected[0];
    return `Выбрано: ${selected.length}`;
  }

  function renderGeneralExpenseSectionFilter() {
    const selected = GENERAL_EXPENSE_SECTIONS
      .filter((item) => state.generalExpenseSectionFilter.includes(item));
    const selectionLabel = formatGeneralExpenseMultiFilterLabel(selected, "Все разделы");
    const rows = getRowsForConfig(configs.generalExpenses);
    return `
      <details class="student-program-type-filter general-expense-filter ${selected.length ? "is-active" : ""}" data-program-type-filter data-general-expense-section-filter>
        <summary title="Фильтр общих затрат по разделу">
          <span>Раздел</span>
          <strong>${escapeHtml(selectionLabel)}</strong>
          <svg viewBox="0 0 12 8" aria-hidden="true"><path d="M1 1.5 6 6.5l5-5"></path></svg>
        </summary>
        <div class="student-program-type-filter-panel general-expense-filter-panel">
          ${GENERAL_EXPENSE_SECTIONS.map((item) => {
            const count = rows.filter((expense) => (
              normalizeGeneralExpenseSection(expense.section, expense.counterparty) === item
            )).length;
            return `
              <label>
                <input type="checkbox" value="${escapeAttr(item)}" data-general-expense-section-filter-option ${selected.includes(item) ? "checked" : ""}>
                <span>${escapeHtml(item)} (${count})</span>
              </label>
            `;
          }).join("")}
          <button class="student-program-type-filter-clear" data-action="clear-general-expense-section-filter" type="button" ${selected.length ? "" : "disabled"}>Все разделы</button>
        </div>
      </details>
    `;
  }

  function renderGeneralExpenseWorkTypeFilter() {
    const options = getGeneralExpenseWorkTypeFilterOptions();
    const selected = state.generalExpenseWorkTypeFilter.filter((item) => options.includes(item));
    const selectionLabel = formatGeneralExpenseMultiFilterLabel(selected, "Все виды");
    return `
      <details class="student-program-type-filter general-expense-filter general-expense-work-type-filter ${selected.length ? "is-active" : ""}" data-program-type-filter data-general-expense-work-type-filter>
        <summary title="Фильтр общих затрат по виду работ; можно выбрать несколько значений">
          <span>Вид работ</span>
          <strong>${escapeHtml(selectionLabel)}</strong>
          <svg viewBox="0 0 12 8" aria-hidden="true"><path d="M1 1.5 6 6.5l5-5"></path></svg>
        </summary>
        <div class="student-program-type-filter-panel general-expense-filter-panel general-expense-work-type-filter-panel">
          ${options.length ? options.map((item) => `
            <label>
              <input type="checkbox" value="${escapeAttr(item)}" data-general-expense-work-type-filter-option ${selected.includes(item) ? "checked" : ""}>
              <span>${escapeHtml(item)}</span>
            </label>
          `).join("") : '<span class="general-expense-filter-empty">Нет доступных видов работ</span>'}
          <button class="student-program-type-filter-clear" data-action="clear-general-expense-work-type-filter" type="button" ${selected.length ? "" : "disabled"}>Сбросить</button>
        </div>
      </details>
    `;
  }

  function updateDatabaseImportIndicator(patch) {
    window.clearTimeout(databaseImportHideTimer);
    state.databaseImport = { ...state.databaseImport, ...patch };
    const indicator = document.querySelector("[data-database-import-indicator]");
    if (indicator) {
      const tone = ["active", "success", "error"].includes(state.databaseImport.tone)
        ? state.databaseImport.tone
        : "active";
      indicator.hidden = !state.databaseImport.visible;
      indicator.className = `database-import-indicator tone-${tone}${state.databaseImport.indeterminate ? " is-indeterminate" : ""}`;
      const status = indicator.querySelector("[data-database-import-status]");
      if (status) status.textContent = state.databaseImport.status || "Подготовка...";
      const progress = Math.max(0, Math.min(100, Number(state.databaseImport.progress || 0)));
      const progressBar = indicator.querySelector("[data-database-import-progress] > span");
      if (progressBar) progressBar.style.width = `${progress}%`;
      const percent = indicator.querySelector("[data-database-import-percent]");
      if (percent) {
        percent.hidden = Boolean(state.databaseImport.indeterminate || tone === "error");
        percent.textContent = `${progress}%`;
      }
    }
    document.querySelectorAll("[data-action='import-students-database']").forEach((button) => {
      button.disabled = Boolean(state.databaseImport.running);
      button.classList.toggle("is-loading", Boolean(state.databaseImport.running));
      const label = button.querySelector("[data-import-button-label]");
      if (label) label.textContent = state.databaseImport.running ? "Импорт..." : "Загрузить из базы";
    });
  }

  function finishDatabaseImportIndicator(tone, status, hideAfter = 3500) {
    updateDatabaseImportIndicator({
      running: false,
      visible: true,
      status,
      progress: 100,
      tone,
      indeterminate: false
    });
    databaseImportHideTimer = window.setTimeout(() => {
      updateDatabaseImportIndicator({ visible: false });
    }, hideAfter);
  }

  function updateDatabaseExportIndicator(patch) {
    window.clearTimeout(databaseExportHideTimer);
    state.databaseExport = { ...state.databaseExport, ...patch };
    const indicator = document.querySelector("[data-database-export-indicator]");
    if (indicator) {
      const tone = ["active", "success", "error"].includes(state.databaseExport.tone)
        ? state.databaseExport.tone
        : "active";
      indicator.hidden = !state.databaseExport.visible;
      indicator.className = `database-import-indicator tone-${tone}${state.databaseExport.indeterminate ? " is-indeterminate" : ""}`;
      const status = indicator.querySelector("[data-database-export-status]");
      if (status) status.textContent = state.databaseExport.status || "Подготовка...";
      const progress = Math.max(0, Math.min(100, Number(state.databaseExport.progress || 0)));
      const progressBar = indicator.querySelector("[data-database-export-progress] > span");
      if (progressBar) progressBar.style.width = `${progress}%`;
      const percent = indicator.querySelector("[data-database-export-percent]");
      if (percent) {
        percent.hidden = Boolean(state.databaseExport.indeterminate || tone === "error");
        percent.textContent = `${progress}%`;
      }
    }
    const syncButton = document.querySelector("[data-action='sync-students-database']");
    if (syncButton) {
      syncButton.disabled = Boolean(state.databaseExport.running);
      syncButton.classList.toggle(
        "is-loading",
        Boolean(state.databaseExport.running && state.databaseExport.operation !== "download")
      );
      const label = syncButton.querySelector("[data-database-export-button-label]");
      if (label) {
        label.textContent = state.databaseExport.running && state.databaseExport.operation !== "download"
          ? "Синхронизация..."
          : "Синхронизировать с базой";
      }
    }
    const downloadButton = document.querySelector("[data-action='download-students-database']");
    if (downloadButton) {
      downloadButton.disabled = Boolean(state.databaseExport.running);
      downloadButton.classList.toggle(
        "is-loading",
        Boolean(state.databaseExport.running && state.databaseExport.operation === "download")
      );
      const label = downloadButton.querySelector("[data-database-download-button-label]");
      if (label) {
        label.textContent = state.databaseExport.running && state.databaseExport.operation === "download"
          ? "Формирование..."
          : "Экспорт в базу";
      }
    }
  }

  function finishDatabaseExportIndicator(tone, status, hideAfter = 4500) {
    updateDatabaseExportIndicator({
      running: false,
      visible: true,
      status,
      progress: tone === "success" ? 100 : state.databaseExport.progress,
      tone,
      indeterminate: false
    });
    databaseExportHideTimer = window.setTimeout(() => {
      updateDatabaseExportIndicator({ visible: false });
    }, hideAfter);
  }

  function getDefaultTableSort(configId) {
    const tableConfigId = configId === "documentConstructor" ? "documentTemplates" : configId;
    const defaultSort = configs[tableConfigId]?.defaultSort || {};
    return {
      key: String(defaultSort.key || ""),
      dir: defaultSort.dir === "desc" ? "desc" : "asc"
    };
  }

  function getStudentStatusTableSort(status) {
    const normalizedStatus = String(status || "").trim().toLocaleLowerCase("ru-RU");
    if (normalizedStatus === "учится") return { key: "daysUntilEnd", dir: "asc" };
    if (normalizedStatus === "все") return { key: "applicationDate", dir: "desc" };
    if (normalizedStatus === "отчислен") return { key: "endDate", dir: "desc" };
    return getDefaultTableSort("students");
  }

  function parseTableSortDate(value) {
    const text = String(value || "").trim();
    if (!text) return null;
    const iso = /^(\d{4})-(\d{2})-(\d{2})/.exec(text);
    if (iso) return Date.UTC(Number(iso[1]), Number(iso[2]) - 1, Number(iso[3]));
    const ru = /^(\d{1,2})\.(\d{1,2})\.(\d{4})/.exec(text);
    if (ru) return Date.UTC(Number(ru[3]), Number(ru[2]) - 1, Number(ru[1]));
    const timestamp = Date.parse(text);
    return Number.isNaN(timestamp) ? null : timestamp;
  }

  function getVisibleRows(config, rowsOverride = null) {
    const isDocumentTemplateTable = config.collection === "documentTemplates";
    const isGeneralExpenseTable = config.collection === "generalExpenses";
    const query = (isDocumentTemplateTable ? state.documentTemplateSearch : state.search).trim().toLowerCase();
    const rows = getRowsForConfig(config, rowsOverride);
    const selectedProgramTypes = state.view === "students"
      ? state.studentProgramTypeFilter
      : [];
    const studentListFilters = state.view === "students"
      ? (state.studentListFilters || {})
      : {};
    const selectedStudentPrograms = getStudentListSelectedPrograms(studentListFilters);
    const selectedRegistryProgramTypes = state.view === "programs"
      ? getProgramRegistryTypeFilterOptions()
        .filter((item) => state.programRegistryTypeFilter.includes(item))
      : [];
    const selectedContractSections = state.view === "contracts"
      ? CONTRACT_SECTIONS.filter((item) => state.contractSectionFilter.includes(item))
      : [];
    const importedViewIds = state.view === "students"
      ? new Set((state.studentImportedViewIds || []).map(String))
      : new Set();
    const directExpenseNoteQuery = state.view === "directExpenses"
      ? String(state.directExpenseNoteFilter || "").trim().toLocaleLowerCase("ru-RU")
      : "";
    const selectedGeneralExpenseSections = isGeneralExpenseTable
      ? GENERAL_EXPENSE_SECTIONS.filter((item) => state.generalExpenseSectionFilter.includes(item))
      : [];
    const selectedGeneralExpenseWorkTypes = isGeneralExpenseTable
      ? state.generalExpenseWorkTypeFilter.map((item) => String(item || "").trim()).filter(Boolean)
      : [];
    let filtered = rows.filter((row) => {
      const matchQuery = !query || Object.values(row).some((value) => String(value || "").toLowerCase().includes(query));
      const hasUnassignedStatus = state.statusFilter === "Не задано"
        && ![row.status, row.type, row.workType, row.itemType].some((value) => String(value || "").trim());
      const matchStatus = isDocumentTemplateTable
        || state.statusFilter === "Все"
        || hasUnassignedStatus
        || row.status === state.statusFilter
        || row.type === state.statusFilter
        || row.workType === state.statusFilter
        || row.itemType === state.statusFilter;
      const programType = normalizeEducationProgramType(
        row.educationType || findProgramByName(row.program)?.type
      );
      const matchProgramType = !selectedProgramTypes.length || selectedProgramTypes.includes(programType);
      const matchStudentProgram = !selectedStudentPrograms.length
        || selectedStudentPrograms.includes(String(row.program || "").trim());
      const studentDateValue = studentListFilters.dateField
        ? parseTableSortDate(row[studentListFilters.dateField])
        : null;
      const studentDateFrom = parseTableSortDate(studentListFilters.dateFrom);
      const studentDateTo = parseTableSortDate(studentListFilters.dateTo);
      const matchStudentDate = !studentListFilters.dateField
        || (studentDateValue !== null
          && (studentDateFrom === null || studentDateValue >= studentDateFrom)
          && (studentDateTo === null || studentDateValue <= studentDateTo));
      const registryProgramType = String(row.type || "").trim() || "Не задано";
      const matchRegistryProgramType = !selectedRegistryProgramTypes.length
        || selectedRegistryProgramTypes.includes(registryProgramType);
      const contractSection = normalizeContractSection(row.section, row.status);
      const matchContractSection = !selectedContractSections.length
        || selectedContractSections.includes(contractSection);
      const matchImportedView = !importedViewIds.size || importedViewIds.has(String(row.id));
      const matchDirectExpenseNote = !directExpenseNoteQuery
        || String(row.note || "").toLocaleLowerCase("ru-RU").includes(directExpenseNoteQuery);
      const generalExpenseSection = isGeneralExpenseTable
        ? normalizeGeneralExpenseSection(row.section, row.counterparty)
        : "";
      const matchGeneralExpenseSection = !selectedGeneralExpenseSections.length
        || selectedGeneralExpenseSections.includes(generalExpenseSection);
      const generalExpenseWorkType = String(row.workType || "").trim();
      const matchGeneralExpenseWorkType = !selectedGeneralExpenseWorkTypes.length
        || selectedGeneralExpenseWorkTypes.includes(generalExpenseWorkType || "Не задано");
      return matchQuery
        && matchStatus
        && matchProgramType
        && matchStudentProgram
        && matchStudentDate
        && matchRegistryProgramType
        && matchContractSection
        && matchImportedView
        && matchDirectExpenseNote
        && matchGeneralExpenseSection
        && matchGeneralExpenseWorkType;
    });
    if (state.sort.key) {
      const dir = state.sort.dir === "asc" ? 1 : -1;
      const sortField = config.fields?.find((fieldDefinition) => fieldDefinition.key === state.sort.key);
      filtered = filtered.slice().sort((a, b) => {
        const left = getTableCellValue(config, a, state.sort.key);
        const right = getTableCellValue(config, b, state.sort.key);
        if (sortField?.type === "number") {
          const leftNumber = String(left ?? "").trim() === "" ? null : Number(left);
          const rightNumber = String(right ?? "").trim() === "" ? null : Number(right);
          const hasLeftNumber = Number.isFinite(leftNumber);
          const hasRightNumber = Number.isFinite(rightNumber);
          if (!hasLeftNumber && hasRightNumber) return 1;
          if (hasLeftNumber && !hasRightNumber) return -1;
          if (hasLeftNumber && hasRightNumber && leftNumber !== rightNumber) {
            return (leftNumber - rightNumber) * dir;
          }
        }
        if (sortField?.type === "date") {
          const leftDate = parseTableSortDate(left);
          const rightDate = parseTableSortDate(right);
          if (leftDate === null && rightDate !== null) return 1;
          if (leftDate !== null && rightDate === null) return -1;
          if (leftDate !== null && rightDate !== null && leftDate !== rightDate) {
            return (leftDate - rightDate) * dir;
          }
        }
        const textComparison = config.collection === "programs" && state.sort.key === "name"
          ? compareProgramNames(left, right)
          : String(left || "").localeCompare(String(right || ""), "ru");
        return textComparison * dir;
      });
    }
    return filtered;
  }

  function getFilterOptions(config) {
    if (config.collection === "contracts") return [];
    const rows = getRowsForConfig(config);
    const keys = ["status", "type", "workType", "itemType"];
    const key = keys.find((item) => rows.some((row) => Object.prototype.hasOwnProperty.call(row, item)));
    if (!key) return [];
    const values = unique(rows.map((row) => row[key]).filter(Boolean));
    if (rows.some((row) => !String(row[key] || "").trim())) values.push("Не задано");
    return values;
  }

  function getTablePageSize(configId) {
    const saved = Number(state.tableSettings[configId]?.pageSize);
    return TABLE_PAGE_SIZE_OPTIONS.includes(saved) ? saved : DEFAULT_TABLE_PAGE_SIZE;
  }

  function getTablePagination(configId, totalRows) {
    const pageSize = getTablePageSize(configId);
    const totalPages = Math.max(1, Math.ceil(totalRows / pageSize));
    const requestedPage = Number(state.tablePages[configId] || 1);
    const page = Math.max(1, Math.min(totalPages, Number.isFinite(requestedPage) ? requestedPage : 1));
    state.tablePages[configId] = page;
    const start = (page - 1) * pageSize;
    const end = Math.min(totalRows, start + pageSize);
    return { page, pageSize, totalPages, start, end };
  }

  function getCurrentTablePageRows(configId, rows) {
    const pagination = getTablePagination(configId, rows.length);
    return rows.slice(pagination.start, pagination.end);
  }

  function setTablePageForRow(configId, id) {
    const config = configs[configId];
    if (!config || !id) return;
    const rows = getVisibleRows(config);
    const rowIndex = rows.findIndex((row) => String(row.id || "") === String(id));
    if (rowIndex < 0) return;
    state.tablePages[configId] = Math.floor(rowIndex / getTablePageSize(configId)) + 1;
  }

  function renderTablePagination(configId, totalRows, pagination) {
    if (totalRows <= TABLE_PAGE_SIZE_OPTIONS[0]) return "";
    const { page, pageSize, totalPages, start, end } = pagination;
    return `
      <div class="table-pagination" data-table-pagination="${escapeAttr(configId)}">
        <span class="table-pagination-summary">Показано ${start + 1}–${end} из ${totalRows}</span>
        <div class="table-pagination-navigation" aria-label="Навигация по страницам">
          <button class="icon-button" data-action="table-page" data-config="${escapeAttr(configId)}" data-page="1" type="button" title="Первая страница" aria-label="Первая страница" ${page <= 1 ? "disabled" : ""}>«</button>
          <button class="icon-button" data-action="table-page" data-config="${escapeAttr(configId)}" data-page="${page - 1}" type="button" title="Предыдущая страница" aria-label="Предыдущая страница" ${page <= 1 ? "disabled" : ""}>‹</button>
          <label class="table-pagination-current">
            <span>Страница</span>
            <input data-action="table-page-input" data-config="${escapeAttr(configId)}" type="number" min="1" max="${totalPages}" value="${page}" aria-label="Номер страницы">
            <span>из ${totalPages}</span>
          </label>
          <button class="icon-button" data-action="table-page" data-config="${escapeAttr(configId)}" data-page="${page + 1}" type="button" title="Следующая страница" aria-label="Следующая страница" ${page >= totalPages ? "disabled" : ""}>›</button>
          <button class="icon-button" data-action="table-page" data-config="${escapeAttr(configId)}" data-page="${totalPages}" type="button" title="Последняя страница" aria-label="Последняя страница" ${page >= totalPages ? "disabled" : ""}>»</button>
        </div>
        <label class="table-page-size">
          <span>Строк на странице</span>
          <select data-action="table-page-size" data-config="${escapeAttr(configId)}">
            ${TABLE_PAGE_SIZE_OPTIONS.map((size) => `<option value="${size}" ${size === pageSize ? "selected" : ""}>${size}</option>`).join("")}
          </select>
        </label>
      </div>
    `;
  }

  function renderTable(config, rows, configId = state.view) {
    const fields = getTableFields(config, configId);
    const selected = getSelected(configId);
    const lastEdited = state.lastEditedRow || {};
    if (!rows.length) {
      return `
        <div class="empty-state"><strong>Записей нет</strong><span>Измените фильтр или добавьте новую запись.</span></div>
      `;
    }
    const pagination = getTablePagination(configId, rows.length);
    const pageRows = rows.slice(pagination.start, pagination.end);
    const selectableRows = configId === "students" ? rows : pageRows;
    const allVisibleSelected = selectableRows.length > 0
      && selectableRows.every((row) => selected.includes(String(row?.id || "").trim()));
    const selectAllLabel = configId === "students"
      ? "Выбрать все отфильтрованные строки"
      : "Выбрать строки текущей страницы";
    return `
      <div class="table-wrap">
        <table class="data-table">
          <thead>
            <tr>
              <th class="select-col">
                <input type="checkbox" data-action="toggle-all-selection" data-config="${configId}" ${allVisibleSelected ? "checked" : ""} aria-label="${selectAllLabel}">
              </th>
              ${fields.map((fieldItem) => `
                <th class="table-column-head" ${columnDataAttrs(configId, fieldItem.key)} ${columnStyleAttr(configId, fieldItem.key)} draggable="true" title="Перетащите заголовок для смены порядка">
                  <div class="table-head-cell">
                    <button data-action="sort" data-config="${escapeAttr(configId)}" data-key="${fieldItem.key}" type="button">
                      ${escapeHtml(fieldItem.label)}
                      ${state.sort.key === fieldItem.key ? (state.sort.dir === "asc" ? "↑" : "↓") : ""}
                    </button>
                    <span class="column-resize-handle" data-action="resize-column" data-config="${configId}" data-field="${escapeAttr(fieldItem.key)}" title="Изменить ширину"></span>
                  </div>
                </th>
              `).join("")}
            </tr>
          </thead>
          <tbody>
            ${pageRows.map((row) => {
              const recordLock = getRecordLock(recordLockEntityType(configId), row.id);
              const programHoursSummary = configId === "programs"
                ? getProgramTrainingPlanHoursSummary(row)
                : null;
              const lockedByOther = Boolean(recordLock && !recordLock.ownedByClient);
              const lockedByCurrentSession = Boolean(recordLock?.ownedByClient);
              const accountingPending = configId === "contracts" && !isChecked(row.accountingRecorded);
              const trainingDeadlinePassed = configId === "students" && isStudentTrainingDeadlinePassed(row);
              const rowClasses = [
                lastEdited.config === configId && String(lastEdited.id || "") === String(row.id || "") ? "is-last-edited" : "",
                lockedByOther ? "is-record-locked" : "",
                lockedByCurrentSession ? "is-record-locked-by-current" : "",
                accountingPending ? "contract-accounting-pending" : "",
                trainingDeadlinePassed ? "student-training-expired" : ""
              ].filter(Boolean).join(" ");
              const lockTitle = lockedByOther
                ? formatRecordLockMessage(recordLock)
                : lockedByCurrentSession
                  ? "Запись заблокирована текущей сессией"
                  : "";
              const rowTitle = [
                lockTitle,
                accountingPending ? "Договор не передан в бухгалтерию" : "",
                trainingDeadlinePassed ? "Срок окончания обучения истёк" : ""
              ].filter(Boolean).join("\n");
              return `
              <tr class="${rowClasses}" ${lockedByOther ? "data-record-locked" : ""} ${rowTitle ? `title="${escapeAttr(rowTitle)}"` : ""}>
                <td class="select-col">
                  <input type="checkbox" data-action="toggle-row-selection" data-config="${configId}" data-id="${row.id}" ${selected.includes(String(row?.id || "").trim()) ? "checked" : ""} aria-label="Выбрать строку">
                </td>
                ${fields.map((fieldItem, index) => {
                  const rawValue = getTableCellValue(config, row, fieldItem.key);
                  const displayValue = valueForDisplay(fieldItem.key, rawValue, configId) || "Открыть";
                  const externalUrl = configId === "programs" && fieldItem.key === "promoSite"
                    ? normalizeExternalUrl(rawValue)
                    : "";
                  const value = externalUrl
                    ? `<a class="table-edit-link" href="${escapeAttr(externalUrl)}" target="_blank" rel="noopener noreferrer" title="Открыть страницу промосайта">${escapeHtml(displayValue)}</a>`
                    : escapeHtml(displayValue);
                  const style = columnStyleAttr(configId, fieldItem.key);
                  const attrs = columnDataAttrs(configId, fieldItem.key);
                  const hoursMismatch = configId === "programs"
                    && fieldItem.key === "hours"
                    && programHoursSummary?.mismatch;
                  const mismatchAttrs = hoursMismatch
                    ? `class="program-hours-mismatch-cell" title="${escapeAttr(getProgramTrainingPlanHoursMismatchTitle(programHoursSummary))}"`
                    : "";
                  if (index === 0) {
                    return `
                      <td class="table-primary-col" ${attrs} ${style}>
                        <button class="table-edit-link" data-action="edit" data-config="${configId}" data-id="${row.id}" type="button" ${lockedByOther ? `aria-label="${escapeAttr(lockTitle)}"` : ""}>
                          ${value}
                          ${recordLock ? '<span class="record-lock-indicator" aria-hidden="true">🔒</span>' : ""}
                        </button>
                      </td>
                    `;
                  }
                  return `<td ${mismatchAttrs} ${attrs} ${style}>${value}</td>`;
                }).join("")}
              </tr>
            `;
            }).join("")}
          </tbody>
        </table>
      </div>
      ${renderTablePagination(configId, rows.length, pagination)}
    `;
  }

  function renderTableOptions(configId) {
    const isOpen = state.tableOptions === configId;
    const isStudentApplicationsImport = configId === STUDENT_APPLICATIONS_IMPORT_TABLE_CONFIG_ID;
    return `
      ${isOpen ? `
        <div class="table-options-backdrop ${isStudentApplicationsImport ? "student-applications-table-options-backdrop" : ""}" data-action="close-table-options"></div>
        <div class="table-options-panel ${isStudentApplicationsImport ? "student-applications-table-options-panel" : ""}" role="dialog" aria-label="Опции таблицы">
          <div class="table-options-head">
            <strong>Опции таблицы</strong>
            <button class="icon-button" data-action="close-table-options" type="button" title="Закрыть">×</button>
          </div>
          ${isStudentApplicationsImport ? "" : `<button class="ghost-button table-option-command" data-action="refresh-table-data" data-config="${configId}" type="button">Обновить данные</button>`}
          <button class="ghost-button table-option-command" data-action="reset-table-options" data-config="${configId}" type="button">Восстановить исходный вид</button>
        </div>
      ` : ""}
    `;
  }

  function getTableLayoutConfig(configId) {
    if (configId === STUDENT_APPLICATIONS_IMPORT_TABLE_CONFIG_ID) return studentApplicationsImportTableConfig;
    if (configId === ISSUED_DOCUMENT_TABLE_CONFIG_ID) return issuedDocumentTableConfig;
    return configs[configId];
  }

  function getTableFields(config, configId) {
    return getTableKeys(config, configId).map((key) => {
      const item = config.fields.find((fieldItem) => fieldItem.key === key);
      if (!item) return { key, label: key };
      return {
        ...item,
        label: String(item.options?.tableLabel || item.label || key)
      };
    });
  }

  function getTableKeys(config, configId) {
    const baseKeys = config.table || [];
    const settings = state.tableSettings[configId] || {};
    const savedOrder = Array.isArray(settings.order) ? settings.order : [];
    return [
      ...savedOrder.filter((key) => baseKeys.includes(key)),
      ...baseKeys.filter((key) => !savedOrder.includes(key))
    ];
  }

  function getColumnWidth(configId, key) {
    return state.tableSettings[configId]?.widths?.[key] || "";
  }

  function getColumnWidthBounds(configId, key) {
    if (configId === EMPLOYEE_PAYMENT_TABLE_CONFIG_ID) {
      const column = EMPLOYEE_PAYMENT_TABLE_COLUMNS.find((item) => item.key === key);
      if (column) return { min: column.defaultWidth, max: 640 };
    }
    if (configId === ISSUED_DOCUMENT_TABLE_CONFIG_ID) {
      const column = issuedDocumentTableConfig.fields.find((item) => item.key === key);
      if (column) return { min: 80, max: 640 };
    }
    if (configId === STUDENT_APPLICATIONS_IMPORT_TABLE_CONFIG_ID) {
      return { min: key === "payment" ? 70 : 80, max: 640 };
    }
    return { min: 80, max: 640 };
  }

  function getRegistryColumnPercentages(configId, columns, overrideKey = "", overrideWidth = 0, totalPercent = 100) {
    const weights = columns.map((column, index) => {
      const savedWidth = Number(getColumnWidth(configId, column.key));
      const configuredWidth = Number(REGISTRY_COLUMN_WEIGHT_OVERRIDES[configId]?.[column.key]);
      const isLongText = ["textarea", "email"].includes(String(column.type || ""))
        || /(?:name|program|title|description|comment|note|sourceValue|fileName|discipline|counterparty|teacher)/i.test(column.key);
      const isCompact = ["number", "date", "checkbox"].includes(String(column.type || ""))
        || /(?:date|amount|balance|count|hours|status|uid|code|index|paid)$/i.test(column.key);
      const defaultWidth = configuredWidth
        || Number(column.defaultWidth)
        || (isLongText ? 210 : (isCompact ? 90 : (index === 0 ? 190 : 125)));
      const width = column.key === overrideKey ? Number(overrideWidth) : savedWidth;
      return {
        key: column.key,
        weight: clamp(width || defaultWidth, 40, 640)
      };
    });
    const totalWeight = weights.reduce((total, item) => total + item.weight, 0) || 1;
    return new Map(weights.map((item) => [
      item.key,
      item.weight / totalWeight * totalPercent
    ]));
  }

  function issuedDocumentColumnStyleAttr(column) {
    const columns = getTableFields(issuedDocumentTableConfig, ISSUED_DOCUMENT_TABLE_CONFIG_ID);
    const percentage = getRegistryColumnPercentages(
      ISSUED_DOCUMENT_TABLE_CONFIG_ID,
      columns
    ).get(column.key) || 0;
    return `style="width:${percentage.toFixed(4)}%;min-width:0"`;
  }

  function getEmployeePaymentColumnWidth(column, overrideKey = "", overrideWidth = 0) {
    const width = column.key === overrideKey
      ? Number(overrideWidth)
      : Number(getColumnWidth(EMPLOYEE_PAYMENT_TABLE_CONFIG_ID, column.key));
    return clamp(width || column.defaultWidth, column.defaultWidth, 640);
  }

  function employeePaymentColumnStyleAttr(column) {
    const width = getEmployeePaymentColumnWidth(column);
    return `style="width:${width}px;min-width:${width}px"`;
  }

  function getEmployeePaymentTableMinWidth(overrideKey = "", overrideWidth = 0) {
    const columnsWidth = EMPLOYEE_PAYMENT_TABLE_COLUMNS.reduce((total, column) => (
      total + getEmployeePaymentColumnWidth(column, overrideKey, overrideWidth)
    ), 0);
    return Math.max(820, Math.round(columnsWidth));
  }

  function columnStyleAttr(configId, key) {
    const config = getTableLayoutConfig(configId);
    if (!config) return "";
    const columns = getTableFields(config, configId);
    const totalPercent = configId === STUDENT_APPLICATIONS_IMPORT_TABLE_CONFIG_ID ? 96.8 : 96.5;
    const percentage = getRegistryColumnPercentages(configId, columns, "", 0, totalPercent).get(key) || 0;
    return `style="width:${percentage.toFixed(4)}%;min-width:0"`;
  }

  function columnDataAttrs(configId, key) {
    return `data-table-config="${escapeAttr(configId)}" data-column-key="${escapeAttr(key)}"`;
  }

  function updateTableSettings(configId, updater) {
    const current = state.tableSettings[configId] || {};
    state.tableSettings[configId] = updater({
      order: Array.isArray(current.order) ? [...current.order] : [],
      widths: { ...(current.widths || {}) },
      pageSize: getTablePageSize(configId)
    });
    persistTableSettings();
  }

  function moveTableColumn(configId, fieldKey, dir) {
    const config = getTableLayoutConfig(configId);
    if (!config) return;
    const order = getTableKeys(config, configId);
    const from = order.indexOf(fieldKey);
    const to = from + Number(dir);
    if (from < 0 || to < 0 || to >= order.length) return;
    [order[from], order[to]] = [order[to], order[from]];
    updateTableSettings(configId, (settings) => ({ ...settings, order }));
    if (configId === STUDENT_APPLICATIONS_IMPORT_TABLE_CONFIG_ID) refreshStudentApplicationsImportDialog();
    else render();
  }

  function setTableColumnWidth(configId, fieldKey, value) {
    updateTableSettings(configId, (settings) => {
      const raw = String(value || "").trim();
      if (!raw) {
        delete settings.widths[fieldKey];
      } else {
        const bounds = getColumnWidthBounds(configId, fieldKey);
        settings.widths[fieldKey] = clamp(Number(raw) || 0, bounds.min, bounds.max);
      }
      return settings;
    });
  }

  function reorderTableColumn(configId, fromKey, toKey) {
    const config = getTableLayoutConfig(configId);
    if (!config || !fromKey || !toKey || fromKey === toKey) return;
    const order = getTableKeys(config, configId);
    const from = order.indexOf(fromKey);
    const to = order.indexOf(toKey);
    if (from < 0 || to < 0) return;
    [order[from], order[to]] = [order[to], order[from]];
    updateTableSettings(configId, (settings) => ({ ...settings, order }));
    if (configId === STUDENT_APPLICATIONS_IMPORT_TABLE_CONFIG_ID) refreshStudentApplicationsImportDialog();
    else render();
  }

  function resetTableOptions(configId) {
    delete state.tableSettings[configId];
    delete state.tablePages[configId];
    const activeTableConfigId = state.view === "documentConstructor" ? "documentTemplates" : state.view;
    if (configId === STUDENT_APPLICATIONS_IMPORT_TABLE_CONFIG_ID) {
      state.studentApplicationsImport.sort = { ...STUDENT_APPLICATIONS_IMPORT_DEFAULT_SORT };
      state.studentApplicationsImport.page = 1;
    } else if (configId === ISSUED_DOCUMENT_TABLE_CONFIG_ID) {
      state.issuedDocumentSort = { key: "issueDate", dir: "asc" };
    } else if (activeTableConfigId === configId) {
      state.sort = getDefaultTableSort(configId);
    }
    state.tableOptions = null;
    persistTableSettings();
    if (configId === STUDENT_APPLICATIONS_IMPORT_TABLE_CONFIG_ID) refreshStudentApplicationsImportDialog();
    else render();
  }

  async function refreshTableData(configId) {
    try {
      if (sharedStateDirty || sharedStateConflict) {
        const confirmed = confirm(
          "Загрузить последнюю общую базу? Несохранённый вариант этого браузера останется в локальной резервной копии."
        );
        if (!confirmed) return;
      }
      if (sharedStateReady || sharedStateConflict) {
        await reloadSharedApplicationState({ renderAfter: false });
      } else {
        state.data = loadState();
      }
      state.selected[configId] = [];
      state.tablePages[configId] = 1;
      state.tableOptions = null;
      render();
    } catch (error) {
      alert(`Не удалось обновить общую базу: ${error.message}`);
    }
  }

  function bindTableColumnEvents(root = document) {
    root.querySelectorAll(".table-column-head").forEach((header) => {
      header.addEventListener("dragstart", (event) => {
        if (event.target.closest(".column-resize-handle")) {
          event.preventDefault();
          return;
        }
        event.dataTransfer.effectAllowed = "move";
        event.dataTransfer.setData("text/plain", JSON.stringify({
          configId: header.dataset.tableConfig,
          fieldKey: header.dataset.columnKey
        }));
        header.classList.add("is-dragging");
      });
      header.addEventListener("dragend", () => {
        document.querySelectorAll(".table-column-head").forEach((item) => item.classList.remove("is-dragging", "is-drop-target"));
      });
      header.addEventListener("dragover", (event) => {
        event.preventDefault();
        header.classList.add("is-drop-target");
      });
      header.addEventListener("dragleave", () => {
        header.classList.remove("is-drop-target");
      });
      header.addEventListener("drop", (event) => {
        event.preventDefault();
        header.classList.remove("is-drop-target");
        const source = parseDragPayload(event.dataTransfer.getData("text/plain"));
        if (!source || source.configId !== header.dataset.tableConfig) return;
        reorderTableColumn(source.configId, source.fieldKey, header.dataset.columnKey);
      });
    });

    root.querySelectorAll("[data-action='resize-column']").forEach((handle) => {
      if (handle.dataset.config === EMPLOYEE_PAYMENT_TABLE_CONFIG_ID) {
        handle.addEventListener("pointerdown", startEmployeePaymentColumnResize);
        handle.addEventListener("dblclick", resetEmployeePaymentColumnWidth);
        handle.addEventListener("keydown", resizeEmployeePaymentColumnWithKeyboard);
      } else {
        handle.addEventListener("mousedown", startColumnResize);
      }
      handle.addEventListener("dragstart", (event) => event.preventDefault());
      handle.addEventListener("click", (event) => event.stopPropagation());
    });
  }

  function parseDragPayload(value) {
    try {
      const parsed = JSON.parse(value);
      return parsed && parsed.configId && parsed.fieldKey ? parsed : null;
    } catch (error) {
      return null;
    }
  }

  function startColumnResize(event) {
    event.preventDefault();
    event.stopPropagation();
    const handle = event.currentTarget;
    const header = handle.closest("th");
    const configId = handle.dataset.config;
    const fieldKey = handle.dataset.field;
    if (!header || !configId || !fieldKey) return;
    const bounds = getColumnWidthBounds(configId, fieldKey);
    const minWidth = clamp(Number(handle.dataset.minWidth) || bounds.min, 32, bounds.max);
    const startWidth = header.getBoundingClientRect().width || Number(getColumnWidth(configId, fieldKey)) || 160;
    const resizeState = {
      configId,
      fieldKey,
      startX: event.clientX,
      startWidth,
      currentWidth: startWidth,
      minWidth,
      maxWidth: bounds.max
    };
    document.body.classList.add("is-resizing-column");
    const onMove = (moveEvent) => {
      resizeState.currentWidth = clamp(
        Math.round(resizeState.startWidth + moveEvent.clientX - resizeState.startX),
        resizeState.minWidth,
        resizeState.maxWidth
      );
      applyColumnWidthToDom(resizeState.configId, resizeState.fieldKey, resizeState.currentWidth);
    };
    const onUp = () => {
      document.removeEventListener("mousemove", onMove);
      document.body.classList.remove("is-resizing-column");
      setTableColumnWidth(resizeState.configId, resizeState.fieldKey, resizeState.currentWidth);
    };
    document.addEventListener("mousemove", onMove);
    document.addEventListener("mouseup", onUp, { once: true });
  }

  function startEmployeePaymentColumnResize(event) {
    if (event.button !== undefined && event.button !== 0) return;
    if (Number(event.detail) > 1) return;
    event.preventDefault();
    event.stopPropagation();
    const handle = event.currentTarget;
    const header = handle.closest("th");
    const configId = handle.dataset.config;
    const fieldKey = handle.dataset.field;
    if (!header || configId !== EMPLOYEE_PAYMENT_TABLE_CONFIG_ID || !fieldKey) return;
    const bounds = getColumnWidthBounds(configId, fieldKey);
    const minWidth = clamp(Number(handle.dataset.minWidth) || bounds.min, 32, bounds.max);
    const startWidth = header.getBoundingClientRect().width
      || Number(getColumnWidth(configId, fieldKey))
      || minWidth;
    const startX = event.clientX;
    const pointerId = event.pointerId;
    const tableWrap = header.closest(".employee-payment-table-wrap");
    const headerBox = header.getBoundingClientRect();
    const wrapBox = tableWrap?.getBoundingClientRect() || headerBox;
    const guide = document.createElement("span");
    guide.className = "employee-payment-column-resize-guide";
    guide.style.left = `${Math.round(headerBox.right)}px`;
    guide.style.top = `${Math.max(0, Math.round(wrapBox.top))}px`;
    guide.style.height = `${Math.max(24, Math.round(Math.min(window.innerHeight, wrapBox.bottom) - Math.max(0, wrapBox.top)))}px`;
    document.body.appendChild(guide);
    document.body.classList.add("is-resizing-column");
    handle.setPointerCapture?.(pointerId);
    let currentWidth = startWidth;
    let pendingX = startX;
    let resizeFrame = 0;
    let finished = false;

    const updateGuide = () => {
      resizeFrame = 0;
      currentWidth = clamp(Math.round(startWidth + pendingX - startX), minWidth, bounds.max);
      guide.style.transform = `translate3d(${Math.round(currentWidth - startWidth)}px, 0, 0)`;
      handle.setAttribute("aria-valuenow", String(currentWidth));
    };
    const scheduleGuideUpdate = () => {
      if (!resizeFrame) resizeFrame = window.requestAnimationFrame(updateGuide);
    };
    const cleanup = () => {
      if (resizeFrame) window.cancelAnimationFrame(resizeFrame);
      resizeFrame = 0;
      document.removeEventListener("pointermove", onMove);
      document.removeEventListener("pointerup", onUp);
      document.removeEventListener("pointercancel", onCancel);
      document.removeEventListener("keydown", onKeyDown, true);
      document.body.classList.remove("is-resizing-column");
      guide.remove();
      try {
        if (handle.hasPointerCapture?.(pointerId)) handle.releasePointerCapture(pointerId);
      } catch (error) {
        // Pointer capture may already be released after pointerup.
      }
    };
    const finish = (apply) => {
      if (finished) return;
      finished = true;
      if (resizeFrame) window.cancelAnimationFrame(resizeFrame);
      resizeFrame = 0;
      updateGuide();
      cleanup();
      if (!apply) {
        handle.setAttribute("aria-valuenow", String(Math.round(startWidth)));
        return;
      }
      applyColumnWidthToDom(configId, fieldKey, currentWidth);
      setTableColumnWidth(configId, fieldKey, currentWidth);
      handle.focus({ preventScroll: true });
    };
    const onMove = (moveEvent) => {
      if (moveEvent.pointerId !== pointerId) return;
      pendingX = moveEvent.clientX;
      scheduleGuideUpdate();
    };
    const onUp = (upEvent) => {
      if (upEvent.pointerId !== pointerId) return;
      pendingX = upEvent.clientX;
      finish(true);
    };
    const onCancel = (cancelEvent) => {
      if (cancelEvent.pointerId !== pointerId) return;
      finish(false);
    };
    const onKeyDown = (keyEvent) => {
      if (keyEvent.key !== "Escape") return;
      keyEvent.preventDefault();
      finish(false);
    };
    document.addEventListener("pointermove", onMove);
    document.addEventListener("pointerup", onUp);
    document.addEventListener("pointercancel", onCancel);
    document.addEventListener("keydown", onKeyDown, true);
  }

  function resetEmployeePaymentColumnWidth(event) {
    event.preventDefault();
    event.stopPropagation();
    const handle = event.currentTarget;
    const fieldKey = String(handle.dataset.field || "");
    const column = EMPLOYEE_PAYMENT_TABLE_COLUMNS.find((item) => item.key === fieldKey);
    if (!column) return;
    setTableColumnWidth(EMPLOYEE_PAYMENT_TABLE_CONFIG_ID, fieldKey, "");
    applyColumnWidthToDom(EMPLOYEE_PAYMENT_TABLE_CONFIG_ID, fieldKey, column.defaultWidth);
    handle.setAttribute("aria-valuenow", String(column.defaultWidth));
  }

  function resizeEmployeePaymentColumnWithKeyboard(event) {
    if (event.key !== "ArrowLeft" && event.key !== "ArrowRight") return;
    event.preventDefault();
    event.stopPropagation();
    const handle = event.currentTarget;
    const fieldKey = String(handle.dataset.field || "");
    const column = EMPLOYEE_PAYMENT_TABLE_COLUMNS.find((item) => item.key === fieldKey);
    if (!column) return;
    const header = handle.closest("th");
    const currentWidth = header?.getBoundingClientRect().width
      || getEmployeePaymentColumnWidth(column);
    const step = event.shiftKey ? 24 : 8;
    const direction = event.key === "ArrowRight" ? 1 : -1;
    const nextWidth = clamp(Math.round(currentWidth + step * direction), column.defaultWidth, 640);
    applyColumnWidthToDom(EMPLOYEE_PAYMENT_TABLE_CONFIG_ID, fieldKey, nextWidth);
    setTableColumnWidth(EMPLOYEE_PAYMENT_TABLE_CONFIG_ID, fieldKey, nextWidth);
    handle.setAttribute("aria-valuenow", String(nextWidth));
  }

  function applyColumnWidthToDom(configId, fieldKey, width) {
    const scope = configId === EMPLOYEE_PAYMENT_TABLE_CONFIG_ID
      ? ".employee-payment-table [data-table-config][data-column-key]"
      : "[data-table-config][data-column-key]";
    if (configId === EMPLOYEE_PAYMENT_TABLE_CONFIG_ID) {
      document.querySelectorAll(scope).forEach((cell) => {
        if (cell.dataset.tableConfig !== configId || cell.dataset.columnKey !== fieldKey) return;
        cell.style.width = `${width}px`;
        cell.style.minWidth = `${width}px`;
      });
      document.querySelectorAll(".employee-payment-table").forEach((table) => {
        table.style.minWidth = `${getEmployeePaymentTableMinWidth(fieldKey, width)}px`;
      });
      return;
    }
    const config = getTableLayoutConfig(configId);
    if (!config) return;
    const columns = getTableFields(config, configId);
    const percentages = getRegistryColumnPercentages(
      configId,
      columns,
      fieldKey,
      width,
      configId === ISSUED_DOCUMENT_TABLE_CONFIG_ID
        ? 100
        : (configId === STUDENT_APPLICATIONS_IMPORT_TABLE_CONFIG_ID ? 96.8 : 96.5)
    );
    document.querySelectorAll(scope).forEach((cell) => {
      if (cell.dataset.tableConfig !== configId) return;
      const percentage = percentages.get(cell.dataset.columnKey);
      if (!percentage) return;
      cell.style.width = `${percentage.toFixed(4)}%`;
      cell.style.minWidth = "0";
    });
  }

  function getSelected(configId) {
    return (state.selected[configId] || []).map((id) => String(id || "").trim()).filter(Boolean);
  }

  function setSelected(configId, ids) {
    state.selected[configId] = unique(
      ids.map((id) => String(id || "").trim()).filter(Boolean)
    );
  }

  function getRowsByIds(collection, ids) {
    const set = new Set(ids.map((id) => String(id || "").trim()).filter(Boolean));
    const rows = collection === "documentTemplates"
      ? getDocumentTemplateRows()
      : (state.data.collections[collection] || []);
    return rows.filter((row) => set.has(String(row?.id || "").trim()));
  }

  function toggleRowSelection(configId, id, checked) {
    const selected = new Set(getSelected(configId));
    const normalizedId = String(id || "").trim();
    if (checked) selected.add(normalizedId);
    else selected.delete(normalizedId);
    setSelected(configId, Array.from(selected));
    render();
  }

  function toggleAllSelection(configId, checked) {
    const config = configs[configId];
    const visibleRows = getVisibleRows(config);
    const visibleIds = (configId === "students"
      ? visibleRows
      : getCurrentTablePageRows(configId, visibleRows)
    ).map((row) => row.id);
    const selected = new Set(getSelected(configId));
    visibleIds.forEach((id) => {
      const normalizedId = String(id || "").trim();
      if (checked) selected.add(normalizedId);
      else selected.delete(normalizedId);
    });
    setSelected(configId, Array.from(selected));
    render();
  }

  function renderDocumentConstructor() {
    const documents = getDocumentTemplates();
    const activeDocument = getActiveDocumentTemplate(documents);
    const fields = activeDocument.fields;
    const customCount = fields.filter((field) => field.custom).length;
    return `
      <section class="panel document-constructor-panel" data-main-registry>
        <div class="section-head">
          <div>
            <p class="eyebrow">Шаблоны и формулы</p>
            <h2 class="document-constructor-title">
              <span>Конструктор документов</span>
              <span class="document-constructor-active-title" title="${escapeAttr(activeDocument.title)}">- ${escapeHtml(activeDocument.title)}</span>
            </h2>
          </div>
          <div class="contract-template-summary">
            <span>${documents.length} документов</span>
            <span>${fields.length} полей</span>
            <span>${customCount} пользовательских</span>
          </div>
        </div>
        ${renderDocumentTemplatesTable(documents, activeDocument.id)}
      </section>
    `;
  }

  function renderSimpleDictionaryEditor(dictionary, values) {
    const dict = String(dictionary || "").trim();
    const items = (Array.isArray(values) ? values : [])
      .filter((value) => typeof value !== "object")
      .map((value) => String(value || ""));
    return `
      <form class="inline-form dictionary-add-form" data-action="dict-add" data-dict="${escapeAttr(dict)}">
        <input name="value" placeholder="Новое значение или список из буфера обмена" autocomplete="off" data-dictionary-add-input>
        <button class="ghost-button" type="submit">Добавить</button>
      </form>
      ${dict === "discountRules" ? `
        <p class="dictionary-format-hint">Формат скидок: <code># Название группы</code>, <code>25,50; Описание скидки</code>, <code>или</code>.</p>
      ` : ""}
      <div class="chips dictionary-detail-values" data-dictionary-values data-dict="${escapeAttr(dict)}">
        ${items.length ? items.map((value) => `
          <span class="chip dictionary-value-chip" draggable="true" data-dict="${escapeAttr(dict)}" data-value="${escapeAttr(value)}" title="Перетащите, чтобы изменить порядок">
            ${escapeHtml(value)}
            <button data-action="dict-remove" data-dict="${escapeAttr(dict)}" data-value="${escapeAttr(value)}" type="button">×</button>
          </span>
        `).join("") : `<span class="lookup-empty">Значений пока нет</span>`}
      </div>
    `;
  }

  function renderSettings() {
    const dictionaries = state.data.dictionaries;
    const dictionaryItems = Object.keys(dictionaries)
      .filter((key) => ![
        "communicationTemplateDescriptions",
        "employeeCommunicationTemplates",
        "employeeCommunicationTemplateDescriptions",
        "communicationTemplateFieldOverrides",
        "communicationTemplateCustomFields",
        "contractTemplateFields",
        "contractTemplateSettings",
        "documentTemplates"
      ].includes(key))
      .map((key) => ({ key, title: dictionaryTitle(key), values: dictionaries[key] || [] }))
      .sort((a, b) => a.title.localeCompare(b.title, "ru"));
    const query = state.dictionarySearch.trim().toLowerCase();
    const visibleItems = dictionaryItems.filter((item) => (
      !query ||
      item.title.toLowerCase().includes(query) ||
      item.values.some((value) => (
        typeof value === "object"
          ? `${value?.label || ""} ${value?.name || ""} ${value?.formula || ""} ${value?.template || ""} ${value?.value || ""} ${value?.programType || ""} ${value?.grade || ""} ${value?.code || ""}`.toLowerCase().includes(query)
          : String(value || "").toLowerCase().includes(query)
      ))
    ));
    const selectedKey = visibleItems.some((item) => item.key === state.selectedDictionary)
      ? state.selectedDictionary
      : visibleItems[0]?.key || dictionaryItems[0]?.key || "";
    if (state.selectedDictionary !== selectedKey) state.selectedDictionary = selectedKey;
    const selectedItem = dictionaryItems.find((item) => item.key === selectedKey);
    const selectedValues = selectedItem?.values || [];
    const isCommunicationTemplates = selectedKey === "communicationTemplates";
    const isDataFormulas = selectedKey === "dataFormulas";
    const isSdoSettings = selectedKey === "sdoSettings";
    const isPaymentSettings = selectedKey === "paymentSettings";
    const isDocumentPathSettings = selectedKey === "documentPathSettings";
    const isEducationRegistrationTypeCodes = selectedKey === "educationRegistrationTypeCodes";
    const isFinalAttestationSettings = selectedKey === "finalAttestationSettings";
    const isIssuedDocumentSettings = selectedKey === "issuedDocumentSettings";
    const isSpecialDictionary = isCommunicationTemplates || isDataFormulas || isSdoSettings || isPaymentSettings || isDocumentPathSettings || isEducationRegistrationTypeCodes || isFinalAttestationSettings || isIssuedDocumentSettings;
    const communicationTemplateFieldSortOrder = state.communicationTemplateFieldSort === "desc" ? "desc" : "asc";
    return `
      <section class="panel settings-page-panel">
        <div class="section-head">
          <div>
            <p class="eyebrow">Настройки</p>
            <h2>Настройки системы</h2>
          </div>
        </div>
        <div class="dictionary-browser">
          <aside class="dictionary-list-panel">
            <div class="search-box dictionary-search" role="search">
              <span aria-hidden="true">⌕</span>
              <input id="dictionarySearch" type="search" value="${escapeAttr(state.dictionarySearch)}" placeholder="Поиск справочника" autocomplete="off" aria-label="Поиск справочника">
              <button
                class="dictionary-search-clear"
                data-action="clear-dictionary-search"
                type="button"
                title="Сбросить поиск"
                aria-label="Сбросить поиск справочника"
                ${state.dictionarySearch ? "" : "hidden"}
              >
                <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M6 6l12 12M18 6 6 18"></path></svg>
              </button>
            </div>
            <div class="dictionary-list" role="listbox" aria-label="Справочники">
              ${visibleItems.length ? visibleItems.map((item) => `
                <button class="dictionary-list-item ${item.key === selectedKey ? "active" : ""}" data-action="select-dictionary" data-dict="${item.key}" type="button" role="option" aria-selected="${item.key === selectedKey ? "true" : "false"}" tabindex="${item.key === selectedKey ? "0" : "-1"}">
                  <span>${escapeHtml(item.title)}</span>
                  <small>${item.key === "communicationTemplates" ? item.values.length + employeeCommunicationMessages.length : item.values.length}</small>
                </button>
              `).join("") : `<div class="empty-state compact"><span>Справочники не найдены</span></div>`}
            </div>
          </aside>
          <section class="dictionary-detail ${isSpecialDictionary ? "is-communication-templates" : ""} ${selectedKey === "discountRules" ? "has-format-hint" : ""}">
            ${selectedItem ? `
              <div class="dictionary-detail-head">
                <div>
                  <p class="eyebrow">Содержание справочника</p>
                  <h3>${escapeHtml(selectedItem.title)}</h3>
                </div>
                <div class="dictionary-detail-actions">
                  ${isCommunicationTemplates ? `
                    <button class="icon-button communication-template-field-sort-button ${communicationTemplateFieldSortOrder === "asc" ? "active" : ""}" data-action="sort-communication-template-fields" data-order="asc" type="button" title="Сортировать поля по алфавиту" aria-label="Сортировать поля по алфавиту" aria-pressed="${communicationTemplateFieldSortOrder === "asc" ? "true" : "false"}">А→Я</button>
                    <button class="icon-button communication-template-field-sort-button ${communicationTemplateFieldSortOrder === "desc" ? "active" : ""}" data-action="sort-communication-template-fields" data-order="desc" type="button" title="Сортировать поля против алфавита" aria-label="Сортировать поля против алфавита" aria-pressed="${communicationTemplateFieldSortOrder === "desc" ? "true" : "false"}">Я→А</button>
                  ` : isDataFormulas || isSdoSettings || isPaymentSettings || isDocumentPathSettings || isEducationRegistrationTypeCodes || isFinalAttestationSettings || isIssuedDocumentSettings ? "" : `
                    <button class="icon-button dictionary-sort-button" data-action="dict-sort" data-dict="${selectedKey}" data-order="asc" type="button" title="Сортировать по алфавиту" aria-label="Сортировать по алфавиту">А→Я</button>
                    <button class="icon-button dictionary-sort-button" data-action="dict-sort" data-dict="${selectedKey}" data-order="desc" type="button" title="Сортировать против алфавита" aria-label="Сортировать против алфавита">Я→А</button>
                  `}
                  ${isSpecialDictionary ? "" : `
                    <button class="icon-button dictionary-copy-button" data-action="dict-copy-all" data-dict="${selectedKey}" type="button" title="Скопировать все значения" aria-label="Скопировать все значения">
                      <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><rect x="8" y="8" width="11" height="11" rx="2"></rect><path d="M5 15V5h10"></path></svg>
                    </button>
                    <button class="icon-button dictionary-clear-button" data-action="dict-clear" data-dict="${selectedKey}" type="button" title="Очистить справочник" aria-label="Очистить справочник">
                      <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M3 6h18"></path><path d="M8 6V4h8v2"></path><path d="M6 6l1 15h10l1-15"></path><path d="M10 11v6"></path><path d="M14 11v6"></path></svg>
                    </button>
                  `}
                  ${selectedKey === "discountRules" ? `
                    <button class="icon-button dictionary-restore-button" data-action="restore-default-discount-rules" type="button" title="Восстановить исходный перечень скидок" aria-label="Восстановить исходный перечень скидок">
                      <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M3 12a9 9 0 1 0 3-6.7"></path><path d="M3 4v6h6"></path><path d="M12 8v5l3 2"></path></svg>
                    </button>
                  ` : ""}
                  <span>${isCommunicationTemplates ? selectedValues.length + employeeCommunicationMessages.length : selectedValues.length}</span>
                </div>
              </div>
              ${isCommunicationTemplates
                ? renderCommunicationTemplateDictionary(selectedValues)
                : isDataFormulas
                  ? renderDataFormulaDictionary(selectedValues)
                : isSdoSettings
                    ? renderSdoSettingsDictionary(selectedValues)
                    : isPaymentSettings
                      ? renderPaymentSettingsDictionary(selectedValues)
                    : isDocumentPathSettings
                      ? renderDocumentPathSettingsDictionary(selectedValues)
                      : isEducationRegistrationTypeCodes
                        ? renderEducationRegistrationTypeCodesDictionary(selectedValues)
                        : isFinalAttestationSettings
                        ? renderFinalAttestationSettingsDictionary(selectedValues)
                        : isIssuedDocumentSettings
                          ? renderIssuedDocumentSettingsDictionary(selectedValues)
                        : renderSimpleDictionaryEditor(selectedKey, selectedValues)}
            ` : `<div class="empty-state"><span>Выберите справочник</span></div>`}
          </section>
        </div>
      </section>
    `;
  }

  function keepDictionaryListItemVisible(list, item) {
    if (!list || !item) return;
    const listRect = list.getBoundingClientRect();
    const itemRect = item.getBoundingClientRect();
    if (itemRect.top < listRect.top) {
      list.scrollTop -= listRect.top - itemRect.top + 4;
    } else if (itemRect.bottom > listRect.bottom) {
      list.scrollTop += itemRect.bottom - listRect.bottom + 4;
    }
  }

  function selectDictionary(dict, { focus = true, reveal = false } = {}) {
    if (!dict) return;
    const currentList = document.querySelector(".dictionary-list");
    const listScrollTop = currentList?.scrollTop || 0;
    const scrollingElement = document.scrollingElement;
    const pageScrollTop = scrollingElement?.scrollTop || window.scrollY || 0;
    const pageScrollLeft = scrollingElement?.scrollLeft || window.scrollX || 0;

    state.selectedDictionary = dict;
    render();

    const nextScrollingElement = document.scrollingElement;
    if (nextScrollingElement) {
      nextScrollingElement.scrollTop = pageScrollTop;
      nextScrollingElement.scrollLeft = pageScrollLeft;
    }
    const nextList = document.querySelector(".dictionary-list");
    if (!nextList) return;
    nextList.scrollTop = listScrollTop;
    const selectedButton = Array.from(nextList.querySelectorAll("[data-action='select-dictionary']"))
      .find((button) => button.dataset.dict === dict);
    if (!selectedButton) return;
    if (reveal) keepDictionaryListItemVisible(nextList, selectedButton);
    if (focus) selectedButton.focus({ preventScroll: true });
  }

  function handleDictionaryListKeydown(event) {
    if (event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) return;
    const currentButton = event.target.closest("[data-action='select-dictionary']");
    const list = currentButton?.closest(".dictionary-list");
    if (!currentButton || !list) return;
    const buttons = Array.from(list.querySelectorAll("[data-action='select-dictionary']"));
    const currentIndex = buttons.indexOf(currentButton);
    if (currentIndex < 0) return;

    let targetIndex = currentIndex;
    if (event.key === "ArrowDown" || event.key === "ArrowRight") targetIndex += 1;
    else if (event.key === "ArrowUp" || event.key === "ArrowLeft") targetIndex -= 1;
    else if (event.key === "Home") targetIndex = 0;
    else if (event.key === "End") targetIndex = buttons.length - 1;
    else return;

    event.preventDefault();
    const target = buttons[Math.max(0, Math.min(buttons.length - 1, targetIndex))];
    if (target === currentButton) return;
    selectDictionary(target.dataset.dict, { focus: true, reveal: true });
  }

  function focusDictionaryListFromSearch(event) {
    if (!["ArrowDown", "ArrowUp"].includes(event.key)) return;
    const list = document.querySelector(".dictionary-list");
    if (!list) return;
    const buttons = Array.from(list.querySelectorAll("[data-action='select-dictionary']"));
    if (!buttons.length) return;
    event.preventDefault();
    const target = list.querySelector(".dictionary-list-item.active")
      || (event.key === "ArrowUp" ? buttons.at(-1) : buttons[0]);
    keepDictionaryListItemVisible(list, target);
    target.focus({ preventScroll: true });
  }

  function renderSdoSettingsDictionary(values) {
    const settings = normalizeSdoSettings(values);
    return `
      <form class="sdo-settings-form" data-action="save-sdo-settings">
        <div class="sdo-settings-fields">
          ${settings.map((setting) => `
            <label>
              <span>${escapeHtml(setting.label)}</span>
              <input
                name="${escapeAttr(setting.key)}"
                type="${setting.type === "text" ? "text" : "url"}"
                value="${escapeAttr(setting.value)}"
                placeholder="${setting.type === "text" ? "" : "https://"}"
                autocomplete="off"
                required
              >
            </label>
          `).join("")}
        </div>
        <p class="sdo-settings-hint">Здесь настраиваются адреса СДО и тема письма с данными доступа.</p>
        <div class="sdo-settings-actions">
          <button class="ghost-button" data-action="reset-sdo-settings" type="button">Восстановить исходные</button>
          <button class="primary-button" type="submit">Сохранить настройки</button>
        </div>
      </form>
    `;
  }

  function renderPaymentSettingsDictionary(values) {
    const settings = normalizePaymentSettings(values);
    const rateSettings = settings.filter((setting) => setting.type === "number");
    const automaticExpenseRules = settings.find((setting) => setting.key === "automaticExpenseRules");
    const sourceAgentAssignments = settings.find((setting) => setting.key === "sourceAgentAssignments");
    const agentRateWithoutAuthor = settings.find((setting) => setting.key === "agentRateWithoutAuthor");
    const agentRateWithAuthor = settings.find((setting) => setting.key === "agentRateWithAuthor");
    const tabs = getOrderedTabs("payment-settings", [
      { id: "rates", label: "Ставки" },
      { id: "assignment", label: "Назначение" },
      { id: "agents", label: "Агенты" }
    ]);
    const activeTab = tabs.some((tab) => tab.id === state.paymentSettingsTab)
      ? state.paymentSettingsTab
      : tabs[0].id;
    state.paymentSettingsTab = activeTab;
    const tabAttributes = (tabId) => (
      tabId === activeTab
        ? 'class="active" aria-selected="true" tabindex="0"'
        : 'aria-selected="false" tabindex="-1"'
    );
    return `
      <form class="payment-settings-form" data-action="save-payment-settings">
        <div class="payment-settings-tabs" data-orderable-tabs="payment-settings" role="tablist" aria-label="Разделы настроек оплаты">
          ${tabs.map((tab) => `
            <button
              ${tabAttributes(tab.id)}
              data-payment-settings-tab="${escapeAttr(tab.id)}"
              data-orderable-tab="${escapeAttr(tab.id)}"
              data-orderable-tab-default-index="${tab.defaultTabIndex}"
              draggable="true"
              type="button"
              role="tab"
              aria-controls="payment-settings-panel-${escapeAttr(tab.id)}"
            >${escapeHtml(tab.label)}</button>
          `).join("")}
        </div>
        <section
          id="payment-settings-panel-rates"
          class="payment-settings-card payment-settings-panel ${activeTab === "rates" ? "is-active" : ""}"
          data-payment-settings-panel="rates"
          role="tabpanel"
          ${activeTab === "rates" ? "" : "hidden"}
        >
          <div class="payment-settings-card-head">
            <div>
              <h4>Константы оплаты</h4>
              <p>Встроенные значения загружаются с листа «Настройки». Пользовательские константы можно применять в формулах по имени в квадратных скобках.</p>
            </div>
            <button class="ghost-button payment-add-button" data-action="add-payment-constant" type="button">Добавить константу</button>
          </div>
          <div class="payment-constant-table" data-payment-constant-list>
            <div class="payment-constant-head payment-constant-order-cell">№</div>
            <div class="payment-constant-head">Константа</div>
            <div class="payment-constant-head">Значение</div>
            <div class="payment-constant-head"></div>
            ${rateSettings.map((setting, index) => renderPaymentConstantRow(setting, index)).join("")}
          </div>
        </section>
        <section
          id="payment-settings-panel-assignment"
          class="payment-settings-card payment-settings-panel ${activeTab === "assignment" ? "is-active" : ""}"
          data-payment-settings-panel="assignment"
          role="tabpanel"
          ${activeTab === "assignment" ? "" : "hidden"}
        >
          ${renderAutomaticExpenseRulesEditor(automaticExpenseRules)}
          <p class="payment-settings-hint">
            Этот список является источником правил автоматического назначения оплат: вида выплаты, формулы, ставки, примечания и исключений.
            При работе с XLSB он синхронизируется с ключом <code>АвтоНазнОплат</code> диапазона <code>НастройкиМакросов</code>.
            Формат строки: <code>Вид затрат, Сумма или формула, Примечание</code>.
            Значения примечания со знаком «-» не добавляются. Несколько исключений разделяются точкой с запятой.
            Для «Оплаты преподавателю» и «Оплаты председателю ИАК» получатель определяется из настроек программы,
            и эти две выплаты применяются ко всем видам программ. Остальные строки применяются только для ППП и КПК.
          </p>
        </section>
        <section
          id="payment-settings-panel-agents"
          class="payment-settings-card payment-settings-panel ${activeTab === "agents" ? "is-active" : ""}"
          data-payment-settings-panel="agents"
          role="tabpanel"
          ${activeTab === "agents" ? "" : "hidden"}
        >
          <div class="payment-agent-rate-card">
            <div>
              <h4>Расчёт агентского вознаграждения</h4>
              <p>Сумма считается от всех поступлений слушателя и округляется вверх до 50 ₽, как на листе «База».</p>
            </div>
            <div class="payment-agent-rate-grid">
              ${[agentRateWithoutAuthor, agentRateWithAuthor].filter(Boolean).map((setting) => `
                <label>
                  <span>${escapeHtml(setting.label)}</span>
                  <span class="payment-agent-rate-input">
                    <input name="${escapeAttr(setting.key)}" type="number" min="0" max="100" step="0.01" value="${escapeAttr(setting.value)}" required>
                    <span aria-hidden="true">%</span>
                  </span>
                </label>
              `).join("")}
            </div>
          </div>
          <label class="payment-settings-textarea">
            <span>${escapeHtml(sourceAgentAssignments.label)}</span>
            <textarea name="${escapeAttr(sourceAgentAssignments.key)}" rows="6" spellcheck="false">${escapeHtml(sourceAgentAssignments.value)}</textarea>
          </label>
          <p class="payment-settings-hint">Каждое соответствие указывается с новой строки в формате <code>Источник=ФИО агента</code>. Если в «Реестре программ» заполнен автор, применяется ставка авторского курса; иначе — ставка курса без автора.</p>
        </section>
        <div class="sdo-settings-actions">
          <button class="ghost-button" data-action="reset-payment-settings" type="button">Восстановить исходные</button>
          <button class="primary-button" type="submit">Сохранить настройки</button>
        </div>
      </form>
    `;
  }

  function renderAutomaticExpenseRulesEditor(setting = {}) {
    const value = String(setting.value || "");
    return `
      <section class="payment-assignment-editor-shell" data-automatic-expense-rules-shell>
        <div class="payment-assignment-editor-head">
          <div>
            <h4>${escapeHtml(setting.label || "Автоматическое назначение оплат")}</h4>
            <p>Установите курсор в нужной строке, затем перетащите или щёлкните константу — она будет вставлена в формулу.</p>
          </div>
          <div class="payment-assignment-syntax-legend" aria-label="Обозначения подсветки">
            <span class="is-type">Вид выплаты</span>
            <span class="is-formula">Формула</span>
            <span class="is-note">Примечание</span>
            <span class="is-exclusion">Исключение</span>
          </div>
        </div>
        <textarea
          name="${escapeAttr(setting.key || "automaticExpenseRules")}"
          data-automatic-expense-rules-value
          hidden
          aria-hidden="true"
        >${escapeHtml(value)}</textarea>
        <div class="payment-assignment-editor-columns">
          <div class="payment-assignment-constant-palette">
            ${renderProgramPaymentConstantPalette({ assignment: true })}
          </div>
          <div
            class="payment-assignment-rules-editor"
            contenteditable="true"
            data-automatic-expense-rules-editor
            data-placeholder="Вид затрат, Сумма или формула, Примечание"
            role="textbox"
            aria-label="Правила автоматического назначения оплат"
            aria-multiline="true"
            spellcheck="false"
          >${renderAutomaticExpenseRulesEditorContent(value)}</div>
        </div>
      </section>
    `;
  }

  function renderAutomaticExpenseRulesEditorContent(value) {
    const lines = String(value || "").replace(/\r\n?/gu, "\n").split("\n");
    if (lines.length === 1 && !lines[0]) return "";
    return lines.map((line) => {
      const firstComma = line.indexOf(",");
      if (firstComma < 0) {
        const invalid = line ? " is-invalid" : "";
        return `<span class="payment-assignment-rule-line${invalid}">${renderAutomaticExpenseRuleFormula(line)}</span>`;
      }
      const secondComma = line.indexOf(",", firstComma + 1);
      const type = line.slice(0, firstComma);
      const formula = secondComma < 0
        ? line.slice(firstComma + 1)
        : line.slice(firstComma + 1, secondComma);
      const note = secondComma < 0 ? "" : line.slice(secondComma + 1);
      const invalid = !type.trim() || !formula.trim() ? " is-invalid" : "";
      return `<span class="payment-assignment-rule-line${invalid}"><span class="payment-assignment-rule-type">${escapeHtml(type)}</span><span class="payment-assignment-rule-separator">,</span><span class="payment-assignment-rule-formula">${renderAutomaticExpenseRuleFormula(formula)}</span>${secondComma < 0 ? "" : `<span class="payment-assignment-rule-separator">,</span>${renderAutomaticExpenseRuleNote(note)}`}</span>`;
    }).join("<br>");
  }

  function renderAutomaticExpenseRuleFormula(formula) {
    const constants = new Map(getPaymentConstantSettings().map((setting) => [
      normalizePaymentConstantMarker(setting.marker).toLocaleLowerCase("ru-RU"),
      setting
    ]));
    return String(formula || "")
      .split(/(\[[^\[\]\r\n]+\])/gu)
      .map((part) => {
        const match = part.match(/^\[([^\[\]\r\n]+)\]$/u);
        if (!match) return escapeHtml(part);
        const marker = normalizePaymentConstantMarker(match[1]);
        const setting = constants.get(marker.toLocaleLowerCase("ru-RU"));
        const title = setting
          ? `Константа: ${setting.label}. Значение: ${formatPaymentConstantValue(setting)}. Перетащите или нажмите правой кнопкой мыши.`
          : "Неизвестная константа. Нажмите правой кнопкой мыши, чтобы создать или удалить её.";
        return `<span class="communication-template-block payment-formula-constant payment-assignment-rule-token ${setting ? "is-known" : "is-unresolved"}" contenteditable="false" draggable="true" data-template-token="${escapeAttr(part)}" data-payment-constant-marker="${escapeAttr(marker)}" data-automatic-expense-rule-token title="${escapeAttr(title)}">${escapeHtml(part)}</span>`;
      })
      .join("");
  }

  function renderAutomaticExpenseRuleNote(note) {
    return String(note || "")
      .split(/(;)/gu)
      .map((part) => {
        if (part === ";") return `<span class="payment-assignment-rule-separator">;</span>`;
        const className = part.trim().startsWith("-")
          ? "payment-assignment-rule-exclusion"
          : "payment-assignment-rule-note";
        return `<span class="${className}">${escapeHtml(part)}</span>`;
      })
      .join("");
  }

  function renderPaymentConstantRow(setting = {}, index = 0) {
    const custom = Boolean(setting.custom);
    const pinned = setting.key === "authorRate";
    const removable = custom && !pinned;
    const unit = getPaymentConstantUnit(setting);
    return `
      <div
        class="payment-constant-row ${pinned ? "is-pinned" : ""}"
        data-payment-constant-row
        data-payment-constant-custom="${custom ? "true" : "false"}"
        ${pinned ? "data-payment-constant-pinned" : ""}
      >
        <input type="hidden" data-payment-constant-field="key" value="${escapeAttr(setting.key || makeId("payment-constant"))}">
        <input type="hidden" data-payment-constant-field="label" value="${escapeAttr(setting.label || setting.marker || "")}">
        <div class="payment-constant-order-cell">
          ${renderFinanceRowDragHandle(
            pinned ? "Глобальная авторская ставка закреплена первой" : `Перетащить константу ${index + 1}`,
            { disabled: pinned }
          )}
          <strong data-payment-constant-row-number>${index + 1}</strong>
        </div>
        <label class="payment-constant-marker-cell">
          <span class="sr-only">Константа</span>
          <span class="payment-constant-bracket">[</span>
          <input
            data-payment-constant-field="marker"
            value="${escapeAttr(setting.marker || "")}"
            placeholder="НоваяКонстанта"
            autocomplete="off"
            ${custom ? "" : "readonly"}
            required
          >
          <span class="payment-constant-bracket">]</span>
        </label>
        <label class="payment-constant-value-cell">
          <span class="sr-only">Значение</span>
          <input data-payment-constant-field="value" type="number" ${getPaymentConstantInputAttributes(setting)} value="${escapeAttr(setting.value ?? "")}" required>
          ${unit ? `<span class="payment-constant-unit" aria-hidden="true">${escapeHtml(unit)}</span>` : ""}
        </label>
        <button
          class="payment-row-delete"
          data-action="delete-payment-constant"
          type="button"
          title="${removable ? "Удалить константу" : "Глобальную или встроенную константу удалить нельзя"}"
          aria-label="${removable ? "Удалить константу" : "Глобальную или встроенную константу удалить нельзя"}"
          ${removable ? "" : "disabled"}
        >
          <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M4 7h16"></path><path d="M10 11v6"></path><path d="M14 11v6"></path><path d="M6 7l1 14h10l1-14"></path><path d="M9 7V4h6v3"></path></svg>
        </button>
      </div>
    `;
  }

  function switchPaymentSettingsTab(tabId, options = {}) {
    const target = ["rates", "assignment", "agents"].includes(String(tabId || ""))
      ? String(tabId)
      : "rates";
    state.paymentSettingsTab = target;
    const form = document.querySelector("form[data-action='save-payment-settings']");
    if (!form) return;
    form.querySelectorAll("[data-payment-settings-tab]").forEach((button) => {
      const isActive = button.dataset.paymentSettingsTab === target;
      button.classList.toggle("active", isActive);
      button.setAttribute("aria-selected", isActive ? "true" : "false");
      button.tabIndex = isActive ? 0 : -1;
      if (isActive && options.focus) button.focus({ preventScroll: true });
    });
    form.querySelectorAll("[data-payment-settings-panel]").forEach((panel) => {
      const isActive = panel.dataset.paymentSettingsPanel === target;
      panel.classList.toggle("is-active", isActive);
      panel.hidden = !isActive;
    });
  }

  function bindPaymentSettingsTabs() {
    document.querySelectorAll("[data-payment-settings-tab]").forEach((button) => {
      button.addEventListener("click", () => switchPaymentSettingsTab(button.dataset.paymentSettingsTab));
    });
  }

  function addPaymentConstantRow() {
    const list = document.querySelector("[data-payment-constant-list]");
    if (!list) return;
    const index = list.querySelectorAll("[data-payment-constant-row]").length;
    list.insertAdjacentHTML("beforeend", renderPaymentConstantRow({
      key: makeId("payment-constant"),
      marker: "",
      label: "",
      value: "0",
      type: "number",
      custom: true
    }, index));
    const row = list.lastElementChild;
    bindMoneyInputStepControls(row);
    updatePaymentConstantRowNumbers(list);
    row?.querySelector('[data-payment-constant-field="marker"]')?.focus({ preventScroll: true });
  }

  function bindPaymentConstantListActions(list) {
    if (!list || list.dataset.paymentConstantActionsBound === "true") return;
    list.dataset.paymentConstantActionsBound = "true";
    list.addEventListener("click", (event) => {
      const button = event.target.closest("[data-action='delete-payment-constant']");
      if (!button || !list.contains(button)) return;
      deletePaymentConstantRow(button);
    });
  }

  function deletePaymentConstantRow(button) {
    const row = button?.closest("[data-payment-constant-row]");
    const key = String(
      row?.querySelector('[data-payment-constant-field="key"]')?.value || ""
    ).trim();
    if (!row || key === "authorRate" || row.dataset.paymentConstantCustom !== "true") return;
    const marker = normalizePaymentConstantMarker(
      row.querySelector('[data-payment-constant-field="marker"]')?.value
    );
    if (marker && !confirm(`Удалить константу [${marker}]? Формулы с ней перестанут вычисляться.`)) return;
    row.remove();
    updatePaymentConstantRowNumbers(document.querySelector("[data-payment-constant-list]"));
  }

  function updatePaymentConstantRowNumbers(list) {
    const pinnedRow = list?.querySelector("[data-payment-constant-pinned]");
    const firstRow = list?.querySelector("[data-payment-constant-row]");
    if (pinnedRow && firstRow && pinnedRow !== firstRow) {
      list.insertBefore(pinnedRow, firstRow);
    }
    list?.querySelectorAll("[data-payment-constant-row]").forEach((row, index) => {
      const number = row.querySelector("[data-payment-constant-row-number]");
      if (number) number.textContent = String(index + 1);
      const handle = row.querySelector("[data-finance-row-drag]");
      if (handle && !row.hasAttribute("data-payment-constant-pinned")) {
        handle.setAttribute("aria-label", `Перетащить константу ${index + 1}`);
      }
    });
  }

  function getPaymentConstantDragAfterRow(list, y) {
    return [...list.querySelectorAll("[data-payment-constant-row]:not(.is-dragging)")].reduce((closest, row) => {
      const cell = row.querySelector(".payment-constant-order-cell");
      if (!cell) return closest;
      const box = cell.getBoundingClientRect();
      const offset = y - box.top - box.height / 2;
      return offset < 0 && offset > closest.offset ? { offset, row } : closest;
    }, { offset: Number.NEGATIVE_INFINITY, row: null }).row;
  }

  function bindPaymentConstantRowDrag(list) {
    if (!list || list.dataset.paymentConstantDragBound === "true") return;
    list.dataset.paymentConstantDragBound = "true";
    list.addEventListener("dragstart", (event) => {
      const handle = event.target.closest("[data-finance-row-drag]");
      const row = handle?.closest("[data-payment-constant-row]");
      if (!row) {
        event.preventDefault();
        return;
      }
      row.classList.add("is-dragging");
      if (event.dataTransfer) {
        event.dataTransfer.effectAllowed = "move";
        event.dataTransfer.setData("text/plain", "");
      }
    });
    list.addEventListener("dragover", (event) => {
      const dragging = list.querySelector("[data-payment-constant-row].is-dragging");
      if (!dragging) return;
      event.preventDefault();
      const afterRow = getPaymentConstantDragAfterRow(list, event.clientY);
      if (afterRow) list.insertBefore(dragging, afterRow);
      else list.appendChild(dragging);
      updatePaymentConstantRowNumbers(list);
    });
    list.addEventListener("drop", (event) => event.preventDefault());
    list.addEventListener("dragend", () => {
      list.querySelectorAll("[data-payment-constant-row]").forEach((row) => row.classList.remove("is-dragging"));
      updatePaymentConstantRowNumbers(list);
    });
  }

  function collectPaymentConstantSettings(form) {
    const rows = [...(form?.querySelectorAll("[data-payment-constant-row]") || [])];
    const markers = new Set();
    const settings = [];
    for (const row of rows) {
      const field = (name) => row.querySelector(`[data-payment-constant-field="${name}"]`);
      const marker = normalizePaymentConstantMarker(field("marker")?.value);
      const normalizedMarker = marker.toLocaleLowerCase("ru-RU");
      const label = String(field("label")?.value || "").trim() || marker;
      const rawValue = String(field("value")?.value || "").trim().replace(",", ".");
      const value = Number(rawValue);
      if (!isValidPaymentConstantMarker(marker)) {
        return { error: `Некорректное имя константы «${marker || "(пусто)"}». Используйте буквы, цифры и знак подчеркивания.`, input: field("marker") };
      }
      if (markers.has(normalizedMarker)) {
        return { error: `Константа [${marker}] указана несколько раз.`, input: field("marker") };
      }
      if (!isPaymentRateValueValid(value)) {
        return { error: `Значение константы [${marker}] должно быть неотрицательным и кратным 10.`, input: field("value") };
      }
      markers.add(normalizedMarker);
      const custom = row.dataset.paymentConstantCustom === "true";
      settings.push({
        key: String(field("key")?.value || makeId("payment-constant")).trim(),
        marker,
        label,
        type: "number",
        value: String(normalizePaymentRateValue(value)),
        ...(custom ? { custom: true } : {})
      });
    }
    return { settings };
  }

