  function renderOrdersSdoControl(key, label, record, type = "text", options = {}) {
    const tools = options.tools || [];
    const value = record[key] ?? "";
    const control = `<input name="${key}" type="${type}" value="${escapeAttr(value)}" ${options.attrs || ""}>`;
    return `
      <label class="orders-sdo-field ${options.compact ? "is-compact" : ""} ${options.className || ""}">
        <span>${escapeHtml(label)}</span>
        <div class="orders-sdo-control">
          ${control}
          ${tools.map((tool) => renderOrdersSdoToolButton(tool, key)).join("")}
          ${options.after || ""}
        </div>
      </label>
    `;
  }

  function renderOrdersSdoToolButton(tool, fieldName) {
    if (["generateContractNo", "generateEnrollmentOrderNo", "generateExpulsionOrderNo", "generateGroupNo", "generateEndDate"].includes(tool)) {
      const actionMap = {
        generateContractNo: ["generate-contract-number", "Сформировать номер договора"],
        generateEnrollmentOrderNo: ["generate-enrollment-order-number", "Сформировать номер приказа о зачислении"],
        generateExpulsionOrderNo: ["generate-expulsion-order-number", "Сформировать номер приказа об отчислении"],
        generateGroupNo: ["generate-group-number", "Сформировать номер группы"],
        generateEndDate: ["generate-training-end-date", "Рассчитать по сроку программы; если срок не указан — по 40 часам в неделю"]
      };
      const [action, title] = actionMap[tool];
      return `
        <button
          class="orders-sdo-icon-button is-magic"
          data-action="${action}"
          type="button"
          title="${escapeAttr(title)}"
          aria-label="${escapeAttr(title)}"
        >
          ${renderOrdersSdoIcon("wand")}
        </button>
      `;
    }
    if (tool === "document") {
      const title = fieldName === "enrollmentOrderNo"
        ? buildStudentDocumentGenerationTooltip(
          "Приказ на зачисление",
          "Сформировать общий приказ для слушателей с одинаковым номером приказа."
        )
        : fieldName === "expulsionOrderNo"
          ? buildStudentDocumentGenerationTooltip(
            "Приказ об отчислении",
            "Сформировать общий приказ для слушателей с одинаковым номером приказа."
          )
          : "Документ";
      const action = fieldName === "enrollmentOrderNo"
        ? "open-student-enrollment-order-document"
        : fieldName === "expulsionOrderNo"
          ? "open-student-expulsion-order-document"
          : "";
      const contextKind = fieldName === "enrollmentOrderNo"
        ? "enrollmentOrder"
        : fieldName === "expulsionOrderNo"
          ? "expulsionOrder"
          : "";
      return `
        <button
          class="orders-sdo-icon-button student-document-generate-button"
          ${action ? `data-action="${escapeAttr(action)}"` : ""}
          ${contextKind ? `data-document-context-kind="${escapeAttr(contextKind)}"` : ""}
          type="button"
          title="${escapeMultilineAttr(title)}"
          aria-label="${fieldName === "enrollmentOrderNo" ? "Приказ на зачисление" : "Приказ об отчислении"}"
        >
          ${renderOrdersSdoIcon("document")}
        </button>
      `;
    }
    if (tool === "educationCertificate") {
      const title = buildStudentDocumentGenerationTooltip(
        "Справка об обучении",
        "Сформировать справку по данным карточки слушателя."
      );
      return `
        <button
          class="orders-sdo-icon-button student-document-generate-button"
          data-action="open-student-study-certificate-document"
          data-document-context-kind="studyCertificate"
          type="button"
          title="${escapeMultilineAttr(title)}"
          aria-label="Справка об обучении"
        >
          ${renderOrdersSdoIcon("documentText")}
        </button>
      `;
    }
    if (tool === "dateStep") {
      return `
        <span class="orders-sdo-date-step">
          <button
            class="orders-sdo-icon-button"
            data-action="shift-orders-sdo-date"
            data-field="${escapeAttr(fieldName)}"
            data-direction="-1"
            type="button"
            title="На один день назад; с Alt — на один месяц назад"
            aria-label="Изменить дату назад"
          >${renderOrdersSdoIcon("chevronLeft")}</button>
          <button
            class="orders-sdo-icon-button"
            data-action="shift-orders-sdo-date"
            data-field="${escapeAttr(fieldName)}"
            data-direction="1"
            type="button"
            title="На один день вперед; с Alt — на один месяц вперед"
            aria-label="Изменить дату вперед"
          >${renderOrdersSdoIcon("chevronRight")}</button>
        </span>
      `;
    }
    if (tool === "copyExtendedEndUp") {
      return `
        <button
          class="orders-sdo-icon-button"
          data-action="copy-extended-end-date-up"
          type="button"
          title="Скопировать измененную дату окончания обучения в дату окончания обучения"
          aria-label="Скопировать измененную дату окончания обучения в дату окончания обучения"
        >${renderOrdersSdoIcon("arrowUp")}</button>
      `;
    }
    const map = {
      copy: [renderOrdersSdoIcon("copy"), "Копировать"],
      file: [renderOrdersSdoIcon("document"), "Документ"],
      up: [renderOrdersSdoIcon("arrowUp"), "Перенести вверх"],
      dropdown: [renderOrdersSdoIcon("chevronDown"), "Выбрать"]
    };
    const [icon, title] = map[tool] || [tool, ""];
    const tone = tool === "clear" ? " is-danger" : "";
    return `<button class="orders-sdo-icon-button${tone}" type="button" title="${escapeAttr(title)}" aria-label="${escapeAttr(title)}">${icon}</button>`;
  }

  function shiftOrdersSdoDate(fieldName, direction, byMonth = false) {
    const formElement = document.getElementById("recordForm");
    const input = formElement?.elements[fieldName];
    if (!(input instanceof HTMLInputElement) || input.type !== "date") return;
    const current = parseOrdersSdoDate(input.value) || new Date();
    const step = Number(direction) < 0 ? -1 : 1;
    const shifted = byMonth
      ? shiftDateByClampedMonth(current, step)
      : new Date(current.getFullYear(), current.getMonth(), current.getDate() + step);
    input.value = formatOrdersSdoDate(shifted);
    input.dispatchEvent(new Event("input", { bubbles: true }));
    input.dispatchEvent(new Event("change", { bubbles: true }));
    input.focus({ preventScroll: true });
  }

  function copyExtendedEndDateToEndDate() {
    const formElement = document.getElementById("recordForm");
    const source = formElement?.elements.extendedEndDate;
    const target = formElement?.elements.endDate;
    if (!(source instanceof HTMLInputElement) || !(target instanceof HTMLInputElement)) return;
    if (!source.value) {
      alert("Укажите измененную дату окончания обучения.");
      source.focus({ preventScroll: true });
      return;
    }
    if (!confirm("Скопировать измененную дату окончания обучения в дату окончания обучения?")) return;
    target.value = source.value;
    target.dispatchEvent(new Event("input", { bubbles: true }));
    target.dispatchEvent(new Event("change", { bubbles: true }));
    target.focus({ preventScroll: true });
  }

  function generateContractNumber() {
    generateNumberFromDataFormula("contractNumber");
  }

  function ensureFormDateForGeneration(fieldName, message) {
    const formElement = document.getElementById("recordForm");
    const input = formElement?.elements[fieldName];
    const value = String(input?.value || "").trim();
    if (parseOrdersSdoDate(value)) return true;
    alert(message);
    input?.focus({ preventScroll: true });
    return false;
  }

  function generateEnrollmentOrderNumber() {
    if (!ensureFormDateForGeneration("enrollmentDate", "Заполните дату зачисления перед формированием номера приказа о зачислении.")) return;
    generateNumberFromDataFormula("enrollmentOrderNumber");
  }

  function generateExpulsionOrderNumber() {
    if (!ensureFormDateForGeneration("expulsionDate", "Заполните дату отчисления перед формированием номера приказа об отчислении.")) return;
    generateNumberFromDataFormula("expulsionOrderNumber");
  }

  function getGeneratedNumberFromDataFormula(formulaKey, date, currentId = "", contextOverride = null) {
    const formula = normalizeDataFormulaTemplates(state.data.dictionaries.dataFormulas)
      .find((item) => item.key === formulaKey);
    if (!formula) return { formula: null, value: "" };
    const context = contextOverride && typeof contextOverride === "object"
      ? contextOverride
      : getDataFormulaContext(formulaKey);
    const sequence = formula.template.includes("{ПорядковыйНомерЗаГод}")
      ? getNextDataFormulaYearSequence(formula, date, currentId, context)
      : formula.template.includes("{ПорядковыйНомерЗаДату}")
        ? getNextDataFormulaSequence(formula, date, currentId, context)
        : 1;
    return {
      formula,
      value: evaluateDataFormula(formula.template, date, sequence, context)
    };
  }

  function getDataFormulaContext(formulaKey) {
    if (formulaKey !== "educationRegistrationNumber") return {};
    const form = document.getElementById("recordForm");
    if (!form || form.dataset.config !== "students") return {};
    const record = collectStudentFormDraft();
    const program = findProgramByName(record.program);
    const programType = normalizeEducationProgramType(program?.type || record.educationType);
    return {
      programType,
      programTypeCode: getEducationRegistrationTypeCode(programType)
    };
  }

  function generateNumberFromDataFormula(formulaKey) {
    const formElement = document.getElementById("recordForm");
    const formula = normalizeDataFormulaTemplates(state.data.dictionaries.dataFormulas)
      .find((item) => item.key === formulaKey);
    const input = formElement?.elements[formula?.targetField];
    if (!formula || !(input instanceof HTMLInputElement)) return;
    const dateInput = formElement.elements[formula.dateField];
    const date = parseOrdersSdoDate(dateInput?.value) || new Date();
    input.value = getGeneratedNumberFromDataFormula(formulaKey, date, formElement.dataset.id).value;
    input.dispatchEvent(new Event("input", { bubbles: true }));
    input.dispatchEvent(new Event("change", { bubbles: true }));
    input.focus({ preventScroll: true });
  }

  function parseTrainingProgramDuration(value) {
    const text = String(value || "").trim().toLocaleLowerCase("ru-RU").replace(/\s+/g, " ");
    if (!text) return null;
    const match = /^(\d+(?:[.,]\d+)?)\s*([а-яё]+)\.?$/iu.exec(text);
    if (!match) return null;
    const amount = Number(match[1].replace(",", "."));
    if (!Number.isFinite(amount) || amount <= 0) return null;
    const unit = match[2];
    if (/^д(?:н|ень)/u.test(unit)) return { amount, unit: "days" };
    if (/^нед/u.test(unit)) return { amount, unit: "weeks" };
    if (/^(?:мес|месяц)/u.test(unit)) return { amount, unit: "months" };
    return null;
  }

  function addTrainingProgramDuration(date, duration) {
    if (!duration) return null;
    if (duration.unit === "days") {
      return new Date(date.getFullYear(), date.getMonth(), date.getDate() + Math.ceil(duration.amount));
    }
    if (duration.unit === "weeks") {
      return new Date(date.getFullYear(), date.getMonth(), date.getDate() + Math.ceil(duration.amount * 7));
    }
    if (duration.unit !== "months") return null;
    const wholeMonths = Math.floor(duration.amount);
    const fractionalDays = Math.round((duration.amount - wholeMonths) * 30);
    const targetMonth = new Date(date.getFullYear(), date.getMonth() + wholeMonths, 1);
    const lastDay = new Date(targetMonth.getFullYear(), targetMonth.getMonth() + 1, 0).getDate();
    targetMonth.setDate(Math.min(date.getDate(), lastDay));
    if (fractionalDays) targetMonth.setDate(targetMonth.getDate() + fractionalDays);
    return targetMonth;
  }

  function getTrainingEndDate(startDate, options = {}) {
    const date = parseOrdersSdoDate(startDate);
    if (!date) return null;
    if (options.sameDayForPro && normalizeEducationProgramType(options.programType) === "ПРО") {
      return new Date(date.getFullYear(), date.getMonth(), date.getDate());
    }
    const durationText = String(options.duration || "").trim();
    let result = null;
    if (durationText) {
      result = addTrainingProgramDuration(date, parseTrainingProgramDuration(durationText));
    } else {
      const numericHours = Number(String(options.hours ?? "").replace(",", "."));
      const weeklyLimit = Number(options.hoursPerWeek ?? 40);
      if (!Number.isFinite(numericHours) || numericHours <= 0
        || !Number.isFinite(weeklyLimit) || weeklyLimit <= 0) return null;
      const fullWeeks = Math.ceil(numericHours / weeklyLimit);
      result = new Date(date.getFullYear(), date.getMonth(), date.getDate() + fullWeeks * 7);
    }
    if (!result) return null;
    if (result.getDay() === 0) result.setDate(result.getDate() + 1);
    return result;
  }

  function setOrdersSdoFieldValue(form, fieldName, value) {
    const input = form?.elements[fieldName];
    if (!(input instanceof HTMLInputElement) && !(input instanceof HTMLTextAreaElement) && !(input instanceof HTMLSelectElement)) return false;
    input.value = value;
    input.dispatchEvent(new Event("input", { bubbles: true }));
    input.dispatchEvent(new Event("change", { bubbles: true }));
    return true;
  }

  function normalizeEducationProgramType(value) {
    const text = String(value || "").trim().toUpperCase();
    if (!text) return "";
    if (text.includes("КПК") || text.includes("ПОВЫШ")) return "КПК";
    if (text.includes("ППП") || text.includes("ПЕРЕПОД")) return "ППП";
    if (text.includes("ДОП")) return "ДОП";
    if (text.includes("ПРО")) return "ПРО";
    return text.replace(/[^А-ЯA-Z0-9]/g, "").slice(0, 8);
  }

  function resolveProStudentAdditionalStatus(record = {}, programType = "", options = {}) {
    const current = String(record.additionalStatus || "").trim();
    const normalizedProgramType = normalizeEducationProgramType(programType || record.educationType);
    if (normalizedProgramType !== "ПРО") return current;
    if (String(record.status || "").trim().toLocaleLowerCase("ru-RU") === "отчислен") {
      return PRO_STUDENT_ARCHIVE_ADDITIONAL_STATUS;
    }
    return options.imported === true ? PRO_STUDENT_ADDITIONAL_STATUS : current;
  }

  function resolveStudentAdditionalStatusAfterMainStatusChange(record = {}, programType = "") {
    if (String(record.status || "").trim().toLocaleLowerCase("ru-RU") === "учится") {
      return STUDENT_LEARNING_ADDITIONAL_STATUS;
    }
    return resolveProStudentAdditionalStatus(record, programType);
  }

  function isFrdoProgramType(programType) {
    return ["КПК", "ППП"].includes(normalizeEducationProgramType(programType));
  }

  function getEducationRegistrationTypeCode(programType) {
    const typeCode = normalizeEducationProgramType(programType);
    const settings = normalizeEducationRegistrationTypeCodes(state.data.dictionaries.educationRegistrationTypeCodes);
    return settings.find((item) => normalizeEducationProgramType(item.programType) === typeCode)?.code || typeCode;
  }

  function getEducationDocumentAutofillContext() {
    const form = document.getElementById("recordForm");
    if (!form || form.dataset.config !== "students") return null;
    const record = collectStudentFormDraft();
    const programName = String(record.program || "").trim();
    const program = findProgramByName(programName);
    if (!programName || !program) {
      alert("Выберите программу обучения из реестра программ.");
      form.querySelector("[name='program']")?.focus({ preventScroll: true });
      return null;
    }
    const programType = normalizeEducationProgramType(program.type || record.educationType);
    if (!programType) {
      alert("Для выбранной программы в реестре не указан тип образовательной программы.");
      return null;
    }
    const issueDate = String(record.expulsionDate || record.expulsionOrderDate || "").trim();
    if (!parseOrdersSdoDate(issueDate)) {
      alert("Заполните дату отчисления. Дата выдачи документа берется из даты отчисления.");
      form.querySelector("[name='expulsionDate'], [name='expulsionOrderDate']")?.focus({ preventScroll: true });
      return null;
    }
    return { form, record, program, programType, issueDate };
  }

  function getStudentProgramTypeCode(record) {
    const program = findProgramByName(record?.program);
    return normalizeEducationProgramType(program?.type || record?.educationType);
  }

  function getNextEducationBlankNumber(programType, currentId = "") {
    const typeCode = normalizeEducationProgramType(programType);
    const numbers = (state.data.collections.students || [])
      .filter((record) => !currentId || String(record.id || "") !== String(currentId))
      .filter((record) => getStudentProgramTypeCode(record) === typeCode)
      .map((record) => String(record.diplomaBlankNo || "").trim())
      .filter((value) => /^\d{1,10}$/.test(value))
      .map((value) => Number(value))
      .filter((value) => Number.isFinite(value));
    return String((numbers.length ? Math.max(...numbers) : 0) + 1).padStart(10, "0");
  }

  function getNextEducationProtocolNo(issueDate, currentId = "") {
    const numbers = (state.data.collections.students || [])
      .filter((record) => !currentId || String(record.id || "") !== String(currentId))
      .filter((record) => getStudentProgramTypeCode(record) === "ППП")
      .filter((record) => String(record.diplomaIssueDate || record.protocolDate || "").trim() === issueDate)
      .map((record) => String(record.protocolNo || "").trim())
      .filter((value) => /^\d+$/.test(value))
      .map((value) => Number(value))
      .filter((value) => Number.isFinite(value) && value > 0);
    return String((numbers.length ? Math.max(...numbers) : 0) + 1);
  }

  function getEducationDocumentAutofillValues(record, options = {}) {
    const source = record && typeof record === "object" ? record : {};
    const program = options.program || findProgramByName(source.program);
    const programType = normalizeEducationProgramType(
      options.programType || program?.type || source.educationType
    );
    const issueDate = String(
      options.issueDate || source.expulsionDate || source.expulsionOrderDate || ""
    ).trim();
    if (!program || !programType || !parseOrdersSdoDate(issueDate)) return null;
    const currentId = String(options.currentId || source.id || "").trim();
    return {
      diplomaBlankNo: getNextEducationBlankNumber(programType, currentId),
      registrationNo: getGeneratedNumberFromDataFormula(
        "educationRegistrationNumber",
        parseOrdersSdoDate(issueDate),
        currentId,
        {
          programType,
          programTypeCode: getEducationRegistrationTypeCode(programType)
        }
      ).value,
      diplomaIssueDate: issueDate,
      frdoDate: isFrdoProgramType(programType) ? source.frdoDate || "" : "",
      protocolNo: programType === "ППП"
        ? getNextEducationProtocolNo(issueDate, currentId)
        : "",
      qualification: programType === "ППП"
        ? String(program.qualification || "").trim()
        : ""
    };
  }

  function autoFillEducationDocument() {
    const context = getEducationDocumentAutofillContext();
    if (!context) return;
    const values = getEducationDocumentAutofillValues(context.record, {
      program: context.program,
      programType: context.programType,
      issueDate: context.issueDate,
      currentId: context.form.dataset.id
    });
    if (!values) return;
    Object.entries(values).forEach(([fieldName, value]) => {
      setOrdersSdoFieldValue(context.form, fieldName, value);
    });
    state.modal.draft = {
      ...(state.modal.draft || {}),
      ...collectStudentFormDraft(),
      ...values
    };
    state.modal.hasDraftChanges = true;
    context.form.elements.diplomaBlankNo?.focus({ preventScroll: true });
  }

  function getOrdersSdoAutofillContext() {
    const form = document.getElementById("recordForm");
    if (!form || form.dataset.config !== "students") return null;
    const record = collectStudentFormDraft();
    const programName = String(record.program || "").trim();
    const program = findProgramByName(programName);
    if (!programName || !program) {
      alert("Выберите программу обучения из реестра программ.");
      form.querySelector("[name='program']")?.focus();
      return null;
    }
    const duration = String(program.duration || "").trim();
    const hours = Number(String(getStudentProgramHours(record)).replace(",", "."));
    if (duration && !parseTrainingProgramDuration(duration)) {
      alert(`Не удалось распознать срок программы «${duration}». Укажите его в днях, неделях или месяцах.`);
      return null;
    }
    if (!duration && (!Number.isFinite(hours) || hours <= 0)) {
      alert("Укажите поле «Срок» или количество часов для выбранной программы.");
      form.querySelector("[name='hours']")?.focus();
      return null;
    }
    return { form, record, program, programName, duration, hours };
  }

  function generateTrainingEndDate() {
    const context = getOrdersSdoAutofillContext();
    if (!context) return;
    const startDateInput = context.form.elements.startDate;
    const startDate = String(startDateInput?.value || context.record.startDate || "").trim();
    if (!parseOrdersSdoDate(startDate)) {
      alert("Заполните дату начала обучения.");
      startDateInput?.focus({ preventScroll: true });
      return;
    }
    const endDate = getTrainingEndDate(startDate, {
      duration: context.duration,
      hours: context.hours
    });
    if (!endDate) return;
    setOrdersSdoFieldValue(context.form, "endDate", formatOrdersSdoDate(endDate));
    state.modal.draft = collectStudentFormDraft();
    state.modal.hasDraftChanges = true;
    context.form.elements.endDate?.focus({ preventScroll: true });
  }

  function autoFillOrdersSdo() {
    const context = getOrdersSdoAutofillContext();
    if (!context) return;
    if (!String(context.program.groupIndex || "").trim()) {
      alert("Для выбранной программы в реестре не указан индекс группы.");
      return;
    }
    const enteredContractDate = String(
      context.form.elements.contractDate?.value || context.record.contractDate || ""
    ).trim();
    const parsedContractDate = parseOrdersSdoDate(enteredContractDate);
    const baseDate = parsedContractDate || new Date();
    const baseDateValue = formatOrdersSdoDate(baseDate);
    const baseDateLabel = baseDate.toLocaleDateString("ru-RU");
    const confirmed = confirm(
      `Использовать ${parsedContractDate ? "дату договора" : "текущую дату"} ${baseDateLabel} `
      + "для даты договора, начала обучения и зачисления, "
      + "автоматически сформировать дату окончания, номер договора, номер приказа, номер группы, "
      + "а также данные СДО: логин, пароль и сообщение о доступе?"
    );
    if (!confirmed) return;

    const endDate = getTrainingEndDate(baseDateValue, {
      duration: context.duration,
      hours: context.hours
    });
    const contract = getGeneratedNumberFromDataFormula("contractNumber", baseDate, context.form.dataset.id);
    const enrollmentOrder = getGeneratedNumberFromDataFormula("enrollmentOrderNumber", baseDate, context.form.dataset.id);
    const group = getStudentGroupNumber(context.programName, baseDateValue);
    const portalCredentials = getPortalCredentialsForAutofill(context.form);
    if (!portalCredentials) return;

    setOrdersSdoFieldValue(context.form, "contractDate", baseDateValue);
    setOrdersSdoFieldValue(context.form, "startDate", baseDateValue);
    setOrdersSdoFieldValue(context.form, "enrollmentDate", baseDateValue);
    setOrdersSdoFieldValue(context.form, "endDate", formatOrdersSdoDate(endDate));
    setOrdersSdoFieldValue(context.form, "contractNo", contract.value);
    setOrdersSdoFieldValue(context.form, "enrollmentOrderNo", enrollmentOrder.value);
    setOrdersSdoFieldValue(context.form, "group", group);
    setOrdersSdoFieldValue(context.form, "login", portalCredentials.login);
    setOrdersSdoFieldValue(context.form, "password", portalCredentials.password);
    setOrdersSdoFieldValue(context.form, "portalAccessMessage", getGeneratedPortalAccessMessage(context.form));

    state.modal.draft = collectStudentFormDraft();
    state.modal.hasDraftChanges = true;
    context.form.elements.contractDate?.focus({ preventScroll: true });
  }

  function evaluateDataFormula(template, date, sequence = 1, context = {}) {
    const safeDate = date instanceof Date && !Number.isNaN(date.getTime()) ? date : new Date();
    const programTypeCode = String(
      context.programTypeCode
      || (context.programType ? getEducationRegistrationTypeCode(context.programType) : "")
      || educationRegistrationTypeCodeDefaults[0].code
    ).trim();
    const values = {
      Год1: String(safeDate.getFullYear()).slice(-1),
      Год2: String(safeDate.getFullYear()).slice(-2),
      Месяц2: String(safeDate.getMonth() + 1).padStart(2, "0"),
      День2: String(safeDate.getDate()).padStart(2, "0"),
      ПорядковыйНомерЗаДату: String(sequence),
      ПорядковыйНомерЗаГод: String(sequence),
      СокращениеТипаПрограммы: programTypeCode
    };
    return String(template || "").replace(/\{([^{}]+)\}/g, (match, name) => (
      Object.prototype.hasOwnProperty.call(values, name) ? values[name] : match
    ));
  }

  function getDataFormulaTargetRecords(formula, currentId = "") {
    return ["students", "contracts"]
      .flatMap((collection) => state.data.collections[collection] || [])
      .filter((record) => !currentId || String(record.id || "") !== String(currentId))
      .filter((record) => Object.prototype.hasOwnProperty.call(record, formula.targetField));
  }

  function getNextDataFormulaSequence(formula, date, currentId = "", context = {}) {
    const pattern = buildDataFormulaSequencePattern(formula.template, date, "ПорядковыйНомерЗаДату", context);
    if (!pattern) return 1;
    const sequences = getDataFormulaTargetRecords(formula, currentId)
      .map((record) => pattern.exec(String(record[formula.targetField] || "").trim()))
      .filter(Boolean)
      .map((match) => Number(match[1]))
      .filter((number) => Number.isFinite(number) && number > 0);
    return (sequences.length ? Math.max(...sequences) : 0) + 1;
  }

  function getNextDataFormulaYearSequence(formula, date, currentId = "", context = {}) {
    const pattern = buildDataFormulaSequencePattern(
      formula.template,
      date,
      "ПорядковыйНомерЗаГод",
      context,
      new Set(["СокращениеТипаПрограммы"])
    );
    if (!pattern) return 1;
    const sequences = getDataFormulaTargetRecords(formula, currentId)
      .map((record) => pattern.exec(String(record[formula.targetField] || "").trim()))
      .filter(Boolean)
      .map((match) => Number(match[1]))
      .filter((number) => Number.isFinite(number) && number > 0);
    return (sequences.length ? Math.max(...sequences) : 0) + 1;
  }

  function buildDataFormulaSequencePattern(template, date, sequenceTokenName, context = {}, wildcardTokenNames = new Set()) {
    let hasSequence = false;
    const source = String(template || "")
      .split(/(\{[^{}]+\})/g)
      .map((part) => {
        const tokenMatch = /^\{([^{}]+)\}$/.exec(part);
        if (!tokenMatch) return escapeRegExp(part);
        const tokenName = tokenMatch[1];
        if (tokenName === sequenceTokenName) {
          hasSequence = true;
          return "(\\d+)";
        }
        if (wildcardTokenNames.has(tokenName)) return "[^\\s/\\\\-]+";
        return escapeRegExp(evaluateDataFormula(part, date, 1, context));
      })
      .join("");
    return hasSequence ? new RegExp(`^${source}$`, "i") : null;
  }

  function escapeRegExp(value) {
    return String(value || "").replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  }

  function parseOrdersSdoDate(value) {
    const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(value || ""));
    if (!match) return null;
    const date = new Date(Number(match[1]), Number(match[2]) - 1, Number(match[3]));
    return Number.isNaN(date.getTime()) ? null : date;
  }

  function shiftDateByClampedMonth(date, direction) {
    const target = new Date(date.getFullYear(), date.getMonth() + direction, 1);
    const lastDay = new Date(target.getFullYear(), target.getMonth() + 1, 0).getDate();
    target.setDate(Math.min(date.getDate(), lastDay));
    return target;
  }

  function formatOrdersSdoDate(date) {
    return [
      date.getFullYear(),
      String(date.getMonth() + 1).padStart(2, "0"),
      String(date.getDate()).padStart(2, "0")
    ].join("-");
  }

  function renderStudentCommunicationMessages(section, record) {
    const generatedMessages = generateStudentCommunicationMessages(record);
    const descriptions = normalizeCommunicationTemplateDescriptions(
      state.data.dictionaries.communicationTemplateDescriptions
    );
    return `
      <div class="communication-message-grid">
        ${section.fields.map((item, index) => {
          const message = studentCommunicationMessages.find((entry) => entry.key === item.key);
          const source = message?.source || `Примечание${index + 1}`;
          const label = descriptions[index] || message?.label || item.label;
          const generatedValue = generatedMessages[item.key] || "";
          const value = record[item.key] || generatedValue;
          const isCustomized = String(record[item.key] || "") !== "" && String(record[item.key]) !== String(generatedValue);
          return `
            <article class="communication-message-card ${isCustomized ? "is-customized" : ""}">
              <div class="communication-message-head">
                <strong>Сообщение ${index + 1}</strong>
                <span title="${escapeAttr(label)}">${escapeHtml(label)}</span>
              </div>
              <textarea
                name="${item.key}"
                data-communication-message="${item.key}"
                data-generated-message="${escapeAttr(encodeURIComponent(generatedValue))}"
                placeholder="${escapeAttr(`Значение из столбца ${source}`)}"
                readonly
              >${escapeHtml(value)}</textarea>
              <div class="communication-message-menu" role="menu" aria-label="${escapeAttr(`Действия для сообщения ${index + 1}`)}">
                <button data-action="copy-communication-message" data-message-key="${item.key}" type="button">
                  ${renderCommunicationActionIcon("copy")}
                  <span>Копировать</span>
                </button>
                <button data-action="edit-communication-message" data-message-key="${item.key}" type="button">
                  ${renderCommunicationActionIcon("edit")}
                  <span>Редактировать</span>
                </button>
                <button data-action="restore-communication-message" data-message-key="${item.key}" type="button">
                  ${renderCommunicationActionIcon("restore")}
                  <span>Восстановить</span>
                </button>
                <button data-action="email-communication-message" data-message-key="${item.key}" data-email-recipient-mode="student" type="button" aria-haspopup="menu" aria-expanded="false" title="Отправить слушателю&#10;Правый щелчок: выбрать получателя&#10;Shift + щелчок: отправить на системный ящик">
                  ${renderCommunicationActionIcon("mail")}
                  <span>Отправить по почте</span>
                </button>
              </div>
            </article>
          `;
        }).join("")}
      </div>
    `;
  }

  function renderCommunicationActionIcon(action) {
    if (action === "edit") {
      return `<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="m14 5 5 5"></path><path d="M4 20h5L19 10a3.5 3.5 0 0 0-5-5L4 15z"></path></svg>`;
    }
    if (action === "mail") {
      return `<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><rect x="3" y="5" width="18" height="14" rx="2"></rect><path d="m4 7 8 6 8-6"></path></svg>`;
    }
    if (action === "restore") {
      return `<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M3 12a9 9 0 1 0 3-6.7"></path><path d="M3 4v6h6"></path></svg>`;
    }
    return `<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><rect x="9" y="9" width="10" height="10" rx="2"></rect><path d="M5 15V7a2 2 0 0 1 2-2h8"></path></svg>`;
  }

  function renderStudentMainIdentity(section, record) {
    const hiddenKeys = new Set(["name", "nameEnglish", "gender", "noDeclension", "addressByFirstName", "uid", "photoPath", "status", "additionalStatus", "program", "studyForm", "educationType", "hours", "registrationAddress", "mailingAddress", "workPlace", "position", "employmentCategory", "ovzStatus", "internship", "group", "source", "tags"]);
    const nameField = section.fields.find((item) => item.key === "name");
    const nameEnglishField = section.fields.find((item) => item.key === "nameEnglish");
    const uidField = section.fields.find((item) => item.key === "uid");
    const photoPathField = section.fields.find((item) => item.key === "photoPath");
    const statusField = section.fields.find((item) => item.key === "status");
    const additionalStatusField = section.fields.find((item) => item.key === "additionalStatus");
    const programField = section.fields.find((item) => item.key === "program");
    const studyFormField = section.fields.find((item) => item.key === "studyForm");
    const educationTypeField = section.fields.find((item) => item.key === "educationType");
    const hoursField = section.fields.find((item) => item.key === "hours");
    const registrationAddressField = section.fields.find((item) => item.key === "registrationAddress");
    const mailingAddressField = section.fields.find((item) => item.key === "mailingAddress");
    const employmentFields = ["workPlace", "position"]
      .map((key) => section.fields.find((item) => item.key === key))
      .filter(Boolean);
    const employmentDetailsFields = ["employmentCategory", "ovzStatus"]
      .map((key) => section.fields.find((item) => item.key === key))
      .filter(Boolean);
    const internshipField = section.fields.find((item) => item.key === "internship");
    const sourceField = section.fields.find((item) => item.key === "source");
    return `
      <div class="student-main-identity">
        <div class="student-main-photo">
          ${renderStudentPhotoEditor(record)}
        </div>
        <div class="student-main-fields">
          <div class="student-name-status-grid">
            <div class="student-name-stack">
              ${renderStudentField(nameField, record)}
              ${renderStudentNameOptions(record)}
              ${renderStudentEnglishNameField(nameEnglishField, record)}
            </div>
            <div class="student-status-stack">
              ${renderStudentField(sourceField, record)}
              ${renderStudentGenderField(record)}
            </div>
            ${renderStudentContactLine(record)}
          </div>
          ${renderStudentPhotoPathField(photoPathField, record)}
        </div>
        <div class="student-main-uid">
          ${renderStudentField(uidField, record)}
        </div>
        <div class="student-form-grid student-additional-status-grid">
          ${renderStudentField(additionalStatusField, record)}
        </div>
        <div class="student-form-grid student-agent-manager-grid">
          ${section.fields.filter((item) => !hiddenKeys.has(item.key)).sort(orderStudentMainField).map((item) => renderStudentField(item, record)).join("")}
        </div>
        <div class="student-main-program-row student-main-subsection student-program-section">
          ${renderStudentProgramLine(programField, internshipField, record)}
          <div class="student-program-details-row">
            ${[studyFormField, educationTypeField, hoursField].filter(Boolean).map((item) => renderStudentField(item, record)).join("")}
          </div>
          <div class="student-main-subsection student-address-section">
            <div class="student-address-pair">
              ${renderStudentAddressField(registrationAddressField, record, "mailingAddress")}
              ${renderStudentAddressField(mailingAddressField, record, "registrationAddress")}
            </div>
          </div>
          <div class="student-main-subsection student-employment-section">
            <div class="student-employment-row">
              ${employmentFields.map((item) => renderStudentField(item, record)).join("")}
            </div>
            <div class="student-employment-details-row">
              ${employmentDetailsFields.map((item) => renderStudentField(item, record)).join("")}
            </div>
          </div>
        </div>
      </div>
    `;
  }

  function renderStudentAddressField(item, record, copyTargetKey) {
    if (!item) return "";
    const value = record[item.key] || "";
    return `
      <label class="student-address-field">
        <span>${escapeHtml(item.label)}</span>
        <div class="student-address-control">
          <textarea name="${item.key}" data-address-field="${item.key}">${escapeHtml(value)}</textarea>
          <div class="student-address-actions">
            <button class="icon-button student-address-action" data-action="copy-address-to" data-source="${item.key}" data-target="${copyTargetKey}" type="button" title="Скопировать в другое адресное поле" aria-label="Скопировать в другое адресное поле">
              ${renderAddressCopyIcon(item.key === "registrationAddress" ? "down" : "up")}
            </button>
            <button class="icon-button student-address-action student-address-check-action" data-action="check-post-index" data-source="${item.key}" type="button" title="Проверить почтовый индекс через Почту России" aria-label="Проверить почтовый индекс через Почту России">
              ${renderGlobeGridIcon()}
            </button>
          </div>
        </div>
      </label>
    `;
  }

  function renderStudentProgramLine(item, internshipField, record) {
    if (!item) return "";
    const promoTitle = getProgramPromoButtonTitle(getProgramPromoUrl(findProgramByName(record.program)));
    return `
      <div class="student-program-link-row">
        ${renderStudentField(item, record)}
        <button class="icon-button student-program-promo-button" data-action="open-student-program-promo" type="button" title="${escapeAttr(promoTitle)}" aria-label="${escapeAttr(promoTitle)}">
          ${renderExternalLinkIcon()}
        </button>
        ${renderStudentInternshipField(internshipField, record)}
      </div>
    `;
  }

  function renderStudentInternshipField(item, record) {
    if (!item) return "";
    return `
      <label class="student-internship-field">
        <span class="student-internship-control">
          <input name="${item.key}" type="checkbox" value="Да" ${isChecked(record[item.key]) ? "checked" : ""}>
          <span>${escapeHtml(item.label)}</span>
        </span>
      </label>
    `;
  }

  function renderStudentNameOptions(record) {
    return `
      <div class="student-name-options" aria-label="Настройки ФИО">
        <label>
          <input name="noDeclension" type="checkbox" value="Да" ${isChecked(record.noDeclension) ? "checked" : ""}>
          <span>Не склоняется фамилия</span>
        </label>
        <label>
          <input name="addressByFirstName" type="checkbox" value="Да" ${isChecked(record.addressByFirstName) ? "checked" : ""}>
          <span>Обращаться по имени</span>
        </label>
      </div>
    `;
  }

  function orderStudentMainField(a, b) {
    const order = {
      agent: 1,
      manager: 2,
      workPlace: 3,
      position: 4,
      employmentCategory: 5,
      ovzStatus: 6
    };
    return (order[a.key] || 10) - (order[b.key] || 10);
  }

  function renderStudentGenderField(record) {
    const value = record.gender || "";
    const options = ["", "Женский", "Мужской"];
    return `
      <label class="student-gender-field">
        <span>Пол</span>
        <select name="gender">
          ${options.map((option) => `<option value="${escapeAttr(option)}" ${option === value ? "selected" : ""}>${escapeHtml(option)}</option>`).join("")}
        </select>
      </label>
    `;
  }

  function renderStudentContactLine(record) {
    return `
      <div class="student-contact-line">
        <label class="student-contact-field">
          <span>Email</span>
          <input name="email" type="email" value="${escapeAttr(record.email || "")}">
        </label>
        <div class="student-contact-field student-phone-field">
          <span>Телефон</span>
          <div class="student-phone-messenger-row">
            <input name="phone" type="tel" value="${escapeAttr(record.phone || "")}" aria-label="Телефон">
            <div class="student-messenger-actions">
              ${renderMessengerButton("max", "Открыть Max", renderMaxIcon())}
              ${renderMessengerButton("telegram", "Открыть Telegram", renderTelegramIcon())}
              ${renderMessengerButton("whatsapp", "Открыть WhatsApp", renderWhatsAppIcon())}
            </div>
          </div>
        </div>
        <label class="student-contact-field student-messenger-url-field">
          <span>Адрес мессенджера</span>
          <div class="student-messenger-url-row">
            <input name="messengerUrl" type="text" value="${escapeAttr(record.messengerUrl || "")}" placeholder="https://max.ru/u/...">
            <button class="icon-button student-messenger-url-button" data-action="open-student-messenger-url" type="button" title="Перейти по адресу мессенджера" aria-label="Перейти по адресу мессенджера">
              ${renderExternalLinkIcon()}
            </button>
          </div>
        </label>
      </div>
    `;
  }

  function renderCardContextActions(record, entityType = "student") {
    const isContract = entityType === "contract";
    const personLabel = isContract ? "сотрудника" : "слушателя";
    const copyTooltip = `Скопировать данные ${personLabel}: ФИО, телефон, email, организация, должность`;
    return `
      <div class="student-card-quick-actions" aria-label="Контекстные действия ${personLabel}">
        ${renderStudentDocumentsFolderLink(record, "student-card-header-action", entityType)}
        <button class="icon-button student-copy-details-button student-card-header-action" data-action="copy-student-details" type="button" title="${escapeAttr(copyTooltip)}" aria-label="${escapeAttr(copyTooltip)}">
          ${renderOrdersSdoIcon("copy")}
        </button>
        ${renderMessengerButton("max", "Открыть Max", renderMaxIcon(), "student-card-header-action")}
        ${renderMessengerButton("telegram", "Открыть Telegram", renderTelegramIcon(), "student-card-header-action")}
        ${renderMessengerButton("whatsapp", "Открыть WhatsApp", renderWhatsAppIcon(), "student-card-header-action")}
      </div>
    `;
  }

  function renderContractCommunicationMessages(record) {
    const generatedMessages = generateEmployeeCommunicationMessages(record);
    const descriptions = normalizeEmployeeCommunicationTemplateDescriptions(
      state.data.dictionaries.employeeCommunicationTemplateDescriptions
    );
    return `
      <section class="form-section contract-card-section contract-messages-section">
        <div class="form-section-head"><h3>Сообщения</h3></div>
        <div class="communication-message-grid">
          ${employeeCommunicationMessages.map((message, index) => {
            const label = descriptions[index] || message.label;
            const generatedValue = generatedMessages[message.key] || "";
            const savedValue = String(record[message.key] || "");
            const value = savedValue || generatedValue;
            const isCustomized = savedValue !== "" && savedValue !== String(generatedValue);
            return `
              <article class="communication-message-card ${isCustomized ? "is-customized" : ""}">
                <div class="communication-message-head">
                  <strong>Сообщение ${index + 1}</strong>
                  <span title="${escapeAttr(label)}">${escapeHtml(label)}</span>
                </div>
                <textarea
                  name="${message.key}"
                  data-communication-message="${message.key}"
                  data-communication-entity="contract"
                  data-generated-message="${escapeAttr(encodeURIComponent(generatedValue))}"
                  placeholder="${escapeAttr(`Значение из столбца ${message.source}`)}"
                  readonly
                >${escapeHtml(value)}</textarea>
                <div class="communication-message-menu" role="menu" aria-label="${escapeAttr(`Действия для сообщения ${index + 1}`)}">
                  <button data-action="copy-communication-message" data-message-key="${message.key}" type="button">
                    ${renderCommunicationActionIcon("copy")}
                    <span>Копировать</span>
                  </button>
                  <button data-action="edit-communication-message" data-message-key="${message.key}" type="button">
                    ${renderCommunicationActionIcon("edit")}
                    <span>Редактировать</span>
                  </button>
                  <button data-action="restore-communication-message" data-message-key="${message.key}" type="button">
                    ${renderCommunicationActionIcon("restore")}
                    <span>Восстановить</span>
                  </button>
                  <button data-action="email-communication-message" data-message-key="${message.key}" data-email-recipient-mode="employee" type="button" aria-haspopup="menu" aria-expanded="false" title="Отправить сотруднику&#10;Правый щелчок: выбрать получателя&#10;Shift + щелчок: отправить на системный ящик">
                    ${renderCommunicationActionIcon("mail")}
                    <span>Отправить по почте</span>
                  </button>
                </div>
              </article>
            `;
          }).join("")}
        </div>
      </section>
    `;
  }

