  function renderStudentMailboxDocumentsButton(record, extraClass = "", showLabel = false, entityType = "student") {
    const isContract = entityType === "contract";
    const documentsFolder = isContract
      ? getContractDocumentsFolder(record)
      : getStudentYandexDocumentsFolder(record);
    const title = "Загрузить документы из писем электронной почты";
    return `
      <button
        class="ghost-button student-mailbox-documents-button ${escapeAttr(extraClass)}"
        data-action="open-student-mailbox-documents"
        data-mailbox-entity-type="${escapeAttr(isContract ? "contract" : "student")}"
        data-student-id="${escapeAttr(record?.id || "")}"
        data-student-name="${escapeAttr(record?.name || "")}"
        data-student-email="${escapeAttr(record?.email || "")}"
        data-student-documents-folder="${escapeAttr(documentsFolder)}"
        type="button"
        title="${escapeAttr(title)}"
        aria-label="${escapeAttr(title)}"
      >
        ${renderOrdersSdoIcon("mailDownload")}
        ${showLabel ? "<span>Загрузить из почты</span>" : ""}
      </button>
    `;
  }

  function isCardSidePanelCollapsed(entityType) {
    const key = entityType === "contract" ? "contract" : "student";
    return Boolean(state.cardSidePanelCollapsed?.[key]);
  }

  function toggleCardSidePanel(button) {
    const entityType = button?.dataset.cardPanelEntity === "contract" ? "contract" : "student";
    const collapsed = !isCardSidePanelCollapsed(entityType);
    state.cardSidePanelCollapsed = {
      ...(state.cardSidePanelCollapsed || {}),
      [entityType]: collapsed
    };
    const panel = button?.closest("[data-card-side-panel]");
    const layout = panel?.closest(".student-card-layout, .contract-card-layout");
    const content = panel?.querySelector("[data-card-side-panel-content]");
    const label = collapsed
      ? "Развернуть область примечаний и перечня событий"
      : "Свернуть область примечаний и перечня событий";
    layout?.classList.toggle("is-side-panel-collapsed", collapsed);
    panel?.classList.toggle("is-collapsed", collapsed);
    if (content) {
      content.hidden = collapsed;
      if (collapsed) content.setAttribute("inert", "");
      else content.removeAttribute("inert");
    }
    button.setAttribute("aria-expanded", collapsed ? "false" : "true");
    button.setAttribute("aria-label", label);
    button.title = label;
  }

  function renderStudentSidePanel(record, options = {}) {
    const entityType = options.entityType === "contract" ? "contract" : "student";
    const collapsed = isCardSidePanelCollapsed(entityType);
    const contentId = `${entityType}-card-side-panel-content`;
    const toggleLabel = collapsed
      ? "Развернуть область примечаний и перечня событий"
      : "Свернуть область примечаний и перечня событий";
    const eventTemplates = Array.isArray(options.eventTemplates) && options.eventTemplates.length
      ? options.eventTemplates
      : getStudentEventTemplatesForRecord(record);
    const notePlaceholder = String(options.notePlaceholder || "Общее примечание по слушателю");
    const orderedEvents = getOrderedStudentEvents(record, eventTemplates);
    return `
      <div class="student-side-head card-side-panel-head">
        <h3>Примечание</h3>
        <button
          class="icon-button card-side-panel-toggle"
          data-action="toggle-card-side-panel"
          data-card-panel-entity="${entityType}"
          type="button"
          title="${toggleLabel}"
          aria-label="${toggleLabel}"
          aria-controls="${contentId}"
          aria-expanded="${collapsed ? "false" : "true"}"
        >
          <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">
            <path d="M9 6l6 6-6 6"></path>
          </svg>
        </button>
      </div>
      <div
        id="${contentId}"
        class="student-side-panel-content card-side-panel-content"
        data-card-side-panel-content
        ${collapsed ? "hidden inert" : ""}
      >
      <section class="student-note-block">
        <textarea name="note" placeholder="${escapeAttr(notePlaceholder)}">${escapeHtml(record.note || "")}</textarea>
      </section>
      <section class="student-events-block">
        <div class="student-side-head">
          <h3>Перечень событий</h3>
          <button class="icon-button event-add-button" data-action="add-student-event" type="button" title="Добавить событие" aria-label="Добавить событие">
            <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">
              <path d="M12 5v14"></path>
              <path d="M5 12h14"></path>
            </svg>
          </button>
        </div>
        <div class="student-events-head" aria-hidden="true">
          <span></span>
          <span>Дата</span>
          <span>Событие</span>
        </div>
        <input type="hidden" name="eventOrder" data-event-order value="${escapeAttr(orderedEvents.map((event) => event.key).join(","))}">
        <input type="hidden" name="eventDeleted" data-event-deleted value="${escapeAttr(csvList(record.eventDeleted).join(","))}">
        <input type="hidden" name="eventCustomKeys" data-event-custom-keys value="${escapeAttr(csvList(record.eventCustomKeys).join(","))}">
        <div class="student-events-list" data-student-events-list>
          ${orderedEvents.map((event) => renderStudentEventRow(event, record)).join("")}
        </div>
        <div class="student-event-editor" data-event-editor hidden>
          <label>
            <span>Дата</span>
            <input type="date" data-event-editor-date>
          </label>
          <label>
            <span>Событие</span>
            <input type="text" data-event-editor-label>
          </label>
          <div class="student-event-editor-actions">
            <button class="event-editor-delete" data-action="delete-student-event" type="button" title="Удалить событие" aria-label="Удалить событие">
              <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">
                <path d="M3 6h18"></path>
                <path d="M8 6V4c0-1.1.9-2 2-2h4c1.1 0 2 .9 2 2v2"></path>
                <path d="M19 6l-1 14c-.1 1.1-1 2-2.1 2H8.1c-1.1 0-2-.9-2.1-2L5 6"></path>
                <path d="M10 11v6"></path>
                <path d="M14 11v6"></path>
              </svg>
            </button>
            <button class="ghost-button" data-action="close-event-editor" type="button">Отмена</button>
            <button class="primary-button" data-action="apply-event-editor" type="button">Применить</button>
          </div>
        </div>
      </section>
      </div>
    `;
  }

  function renderStudentEventRow(event, record) {
    const stateKey = `event_${event.key}_state`;
    const dateKey = `event_${event.key}_date`;
    const labelKey = `event_${event.key}_label`;
    const stateValue = normalizeEventState(record[stateKey], record[dateKey]);
    const storedStateValue = isExplicitUncheckedEventState(record[stateKey]) ? "unchecked" : stateValue;
    const dateValue = record[dateKey] || "";
    const labelValue = record[labelKey] || event.label;
    return `
      <div class="student-event-row ${stateValue ? "is-selected" : ""} ${stateValue === "dated" ? "has-date" : ""}" data-action="toggle-student-event" data-event-key="${escapeAttr(event.key)}" data-event-custom="${event.custom ? "true" : ""}" role="button" tabindex="0" draggable="false">
        <input
          type="checkbox"
          tabindex="-1"
          aria-hidden="true"
          ${stateValue ? "checked" : ""}
        >
        <input type="hidden" name="${stateKey}" data-event-state="${escapeAttr(event.key)}" value="${escapeAttr(storedStateValue)}">
        <input type="hidden" name="${dateKey}" data-event-date="${escapeAttr(event.key)}" value="${escapeAttr(dateValue)}">
        <input type="hidden" name="${labelKey}" data-event-label-value="${escapeAttr(event.key)}" value="${escapeAttr(labelValue)}">
        <span class="event-date" data-event-date-label="${escapeAttr(event.key)}">${stateValue === "dated" ? escapeHtml(dateRu(dateValue)) : ""}</span>
        <span class="event-label" data-event-label-text="${escapeAttr(event.key)}" title="${escapeAttr(labelValue)}">${escapeHtml(labelValue)}</span>
      </div>
    `;
  }

  function getOrderedStudentEvents(record, eventTemplates = getStudentEventTemplatesForRecord(record)) {
    const catalog = getStudentEventCatalog(record, eventTemplates);
    const keys = String(record.eventOrder || "")
      .split(",")
      .map((key) => key.trim())
      .filter(Boolean);
    const eventByKey = new Map(catalog.map((event) => [event.key, event]));
    const ordered = keys.map((key) => eventByKey.get(key)).filter(Boolean);
    const usedKeys = new Set(ordered.map((event) => event.key));
    return [
      ...ordered,
      ...catalog.filter((event) => !usedKeys.has(event.key))
    ];
  }

  function getStudentEventCatalog(record, eventTemplates = getStudentEventTemplatesForRecord(record)) {
    const deleted = new Set(csvList(record.eventDeleted));
    const configuredEvents = [
      ...getStudentEventTemplates(),
      ...eventTemplates
    ];
    const configuredByKey = new Map(configuredEvents.map((event) => [event.key, event]));
    const preservedKeys = new Set([
      ...csvList(record.eventOrder),
      ...configuredEvents
        .filter((event) => (
          normalizeEventState(record[`event_${event.key}_state`], record[`event_${event.key}_date`])
          || String(record[`event_${event.key}_date`] || "").trim()
        ))
        .map((event) => event.key)
    ]);
    const baseEvents = unique([
      ...eventTemplates.map((event) => event.key),
      ...preservedKeys
    ]).map((key) => configuredByKey.get(key)).filter((event) => event && !deleted.has(event.key));
    const customEvents = csvList(record.eventCustomKeys).map((key) => ({
      key,
      label: record[`event_${key}_label`] || "Новое событие",
      custom: true
    }));
    return [...baseEvents, ...customEvents];
  }

  function csvList(value) {
    return String(value || "")
      .split(",")
      .map((item) => item.trim())
      .filter(Boolean);
  }

  function syncStudentEventOrder() {
    const input = document.querySelector("[data-event-order]");
    const list = document.querySelector("[data-student-events-list]");
    if (!input || !list) return;
    input.value = Array.from(list.querySelectorAll(".student-event-row"))
      .map((row) => row.dataset.eventKey)
      .filter(Boolean)
      .join(",");
  }

  function setCsvHidden(selector, values) {
    const input = document.querySelector(selector);
    if (input) input.value = unique(values.filter(Boolean)).join(",");
  }

  function syncCardEventDraftFromDom() {
    if (!state.modal || !["students", "contracts"].includes(state.modal.config)) return;
    const form = document.getElementById("recordForm");
    if (!form) return;
    const eventValues = {};
    form.querySelectorAll("[name^='event_'], [name='eventOrder'], [name='eventDeleted'], [name='eventCustomKeys']")
      .forEach((control) => {
        if (control.name) eventValues[control.name] = String(control.value || "");
      });
    state.modal.draft = { ...(state.modal.draft || {}), ...eventValues };
    state.modal.hasDraftChanges = true;
  }

  function getEventDragAfterElement(list, y) {
    const rows = Array.from(list.querySelectorAll(".student-event-row:not(.is-dragging)"));
    return rows.reduce((closest, row) => {
      const box = row.getBoundingClientRect();
      const offset = y - box.top - box.height / 2;
      if (offset < 0 && offset > closest.offset) return { offset, row };
      return closest;
    }, { offset: Number.NEGATIVE_INFINITY, row: null }).row;
  }

  function bindStudentEventRow(row) {
    row.draggable = false;
    row.addEventListener("pointerdown", (event) => {
      const canReorder = event.button === 0 && (event.shiftKey || document.body.classList.contains("event-reorder-mode"));
      row.draggable = canReorder;
      row.dataset.reorderDragReady = canReorder ? "true" : "";
    });
    row.addEventListener("pointerup", () => {
      if (row.classList.contains("is-dragging")) return;
      row.draggable = false;
      row.dataset.reorderDragReady = "";
    });
    row.addEventListener("click", (event) => {
      event.preventDefault();
      if (row.dataset.wasDragged === "true") {
        row.dataset.wasDragged = "";
        return;
      }
      updateStudentEventRow(row);
    });
    row.addEventListener("dragstart", (event) => {
      const canReorder = row.dataset.reorderDragReady === "true" || event.shiftKey || document.body.classList.contains("event-reorder-mode");
      if (!canReorder) {
        event.preventDefault();
        row.draggable = false;
        return;
      }
      closeStudentEventEditor();
      row.classList.add("is-dragging");
      document.body.classList.add("event-reorder-dragging");
      event.dataTransfer.effectAllowed = "move";
      event.dataTransfer.setData("text/plain", row.dataset.eventKey || "");
    });
    row.addEventListener("dragend", () => {
      row.classList.remove("is-dragging");
      document.body.classList.remove("event-reorder-dragging");
      row.draggable = false;
      row.dataset.reorderDragReady = "";
      row.dataset.wasDragged = "true";
      window.setTimeout(() => {
        row.dataset.wasDragged = "";
      }, 150);
      syncStudentEventOrder();
      syncCardEventDraftFromDom();
    });
    row.addEventListener("contextmenu", (event) => {
      event.preventDefault();
      openStudentEventEditor(row, event.clientX, event.clientY);
    });
    row.addEventListener("keydown", (event) => {
      if (event.key !== "Enter" && event.key !== " ") return;
      event.preventDefault();
      updateStudentEventRow(row);
    });
  }

  function setEventReorderMode(active) {
    document.body.classList.toggle("event-reorder-mode", active);
    if (!active) {
      document.querySelectorAll(".student-event-row:not(.is-dragging)").forEach((row) => {
        row.draggable = false;
        row.dataset.reorderDragReady = "";
      });
    }
  }

  function bindStudentEventReorderKeys() {
    if (window.studentEventReorderKeysBound) return;
    window.studentEventReorderKeysBound = true;
    document.addEventListener("keydown", (event) => {
      if (event.key === "Shift") setEventReorderMode(true);
    });
    document.addEventListener("keyup", (event) => {
      if (event.key === "Shift") setEventReorderMode(false);
    });
    window.addEventListener("blur", () => {
      setEventReorderMode(false);
      document.body.classList.remove("event-reorder-dragging");
    });
  }

  function addStudentEvent() {
    const name = window.prompt("Название события");
    const label = String(name || "").trim();
    if (!label) return;
    const list = document.querySelector("[data-student-events-list]");
    if (!list) return;
    const key = `customEvent_${Date.now().toString(36)}`;
    const customKeys = csvList(document.querySelector("[data-event-custom-keys]")?.value);
    setCsvHidden("[data-event-custom-keys]", [...customKeys, key]);
    list.insertAdjacentHTML("beforeend", renderStudentEventRow({ key, label, custom: true }, { [`event_${key}_label`]: label }));
    const row = list.querySelector(`.student-event-row[data-event-key="${CSS.escape(key)}"]`);
    if (row) bindStudentEventRow(row);
    syncStudentEventOrder();
    syncCardEventDraftFromDom();
  }

  function deleteStudentEvent(event) {
    event.preventDefault();
    event.stopPropagation();
    const editor = document.querySelector("[data-event-editor]");
    const key = editor?.dataset.eventKey;
    const row = key ? document.querySelector(`.student-event-row[data-event-key="${CSS.escape(key)}"]`) : null;
    if (!row || !key) return;
    closeStudentEventEditor();
    if (row.dataset.eventCustom === "true") {
      setCsvHidden("[data-event-custom-keys]", csvList(document.querySelector("[data-event-custom-keys]")?.value).filter((item) => item !== key));
    } else {
      setCsvHidden("[data-event-deleted]", [...csvList(document.querySelector("[data-event-deleted]")?.value), key]);
    }
    row.remove();
    syncStudentEventOrder();
    syncCardEventDraftFromDom();
  }

  function renderStudentField(item, record) {
    const value = item.key === "manager"
      ? (getCurrentUserLogin() || record[item.key] || "")
      : (record[item.key] ?? "");
    const required = item.required ? "required" : "";
    const isCalculatedFinanceField = ["paidAmount", "balance"].includes(item.key);
    const isIssuerField = ["passportIssuer", "customerPassportIssuer", "educationDocumentIssuer"]
      .includes(item.key);
    const isWide = item.type === "textarea" || item.key === "program" || isIssuerField;
    const classes = [
      isWide ? "wide-field" : "",
      item.key === "manager" ? "manager-field" : "",
      item.key === "agent" ? "agent-field" : "",
      item.key === "finalGrade" ? "student-final-grade-field" : "",
      ["finalWorkTopic", "finalWorkNotes"].includes(item.key) ? "student-final-work-field" : "",
      item.key === "discountDescription" ? "discount-description-label" : "",
      item.key === "orderNo" ? "student-order-number-field" : "",
      item.key === "educationDocumentSurname" ? "student-document-surname-field" : "",
      isIssuerField ? "student-issuer-field" : "",
      ["workPlace", "employmentCategory"].includes(item.key) ? "long-label-field" : ""
    ].filter(Boolean).join(" ");
    const tooltip = item.key === "finalGrade"
      ? ` data-tooltip="${escapeAttr(getFinalAttestationGradeTooltip())}"`
      : "";
    const label = `<label class="${classes}"${tooltip}><span>${escapeHtml(item.label)}${item.required ? " *" : ""}</span>`;
    if (item.key === "name") {
      return `${label}${renderComboField({
        name: item.key,
        type: "search",
        value,
        required,
        options: getSavedPersonNameOptions("students", value),
        attrs: 'aria-label="ФИО слушателя"'
      })}</label>`;
    }
    if (item.key === "program") {
      return renderStudentProgramField(label, value, required);
    }
    if (item.key === "hours") {
      return renderProgramHoursField(label, value, required);
    }
    if (searchableStudentFields[item.key]) {
      return renderSearchableStudentField(label, item, value, required);
    }
    if (isIssuerField) {
      return renderIssuerLookupField(label, item, value, required);
    }
    if (item.key === "educationType") {
      const programType = getProgramType(record.program, record);
      return `
        ${label}
          ${renderComboField({
            name: item.key,
            type: "search",
            value: programType,
            options: getProgramTypeOptions(programType),
            attrs: 'data-program-autofill="educationType"'
          })}
        </label>
      `;
    }
    if (item.key === "discountDescription") {
      return renderDiscountDescriptionField(label, value);
    }
    if (item.key === "orderNo") {
      return renderStudentOrderNumberField(label, value, required);
    }
    if (item.key === "manager") {
      return `${label}<input name="${item.key}" type="text" value="${escapeAttr(value)}" readonly title="Ответственный определяется по текущей учётной записи"></label>`;
    }
    if (item.key === "discount") {
      return `${label}<input name="${item.key}" type="number" value="${escapeAttr(normalizeDiscountPercent(value, record.discountUnit))}" min="0" max="100" step="0.01" inputmode="decimal"></label>`;
    }
    if (item.key === "finalGrade") {
      const options = ["", ...getFinalAttestationGradeOptions(value)];
      return `${label}<select name="${item.key}" data-settings-dictionary="finalAttestationSettings">${options.map((option) => `<option value="${escapeAttr(option)}" ${String(option) === String(value) ? "selected" : ""}>${escapeHtml(option)}</option>`).join("")}</select></label>`;
    }
    if (item.key === "documentsStatus") {
      const checked = isChecked(value);
      return `
        <label class="student-personal-case-toggle">
          <input
            class="student-personal-case-toggle-input"
            name="documentsStatus"
            type="checkbox"
            value="+"
            ${checked ? "checked" : ""}
          >
          <span class="student-personal-case-toggle-card">
            <span class="student-personal-case-toggle-track" aria-hidden="true"><span></span></span>
            <span class="student-personal-case-toggle-copy">
              <strong>Личное дело сформировано</strong>
              <small class="student-personal-case-state is-pending">Не сформировано</small>
              <small class="student-personal-case-state is-complete">Сформировано</small>
            </span>
          </span>
        </label>
      `;
    }
    if (item.key === "educationDocumentSurname") {
      const copyTitle = "Скопировать фамилию слушателя";
      return `
        ${label}
          <div class="student-document-surname-control">
            <input name="${item.key}" type="text" value="${escapeAttr(value)}" ${required}>
            <button class="icon-button student-document-surname-copy" data-action="copy-student-surname-to-document" type="button" title="${copyTitle}" aria-label="${copyTitle}">
              ${renderOrdersSdoIcon("copy")}
            </button>
          </div>
        </label>
      `;
    }
    if (item.key === "frdoDate") {
      const enabled = isFrdoProgramType(getProgramType(record.program, record));
      const title = enabled ? "" : "Дата выгрузки в ФРДО доступна только для КПК и ППП";
      return `${label}<input name="${item.key}" type="date" value="${escapeAttr(value)}" ${enabled ? "" : "disabled"} title="${escapeAttr(title)}"></label>`;
    }
    if (["inn", "customerInn"].includes(item.key)) {
      return renderStudentIdentityInput(label, item.key, value, {
        maxLength: 12,
        pattern: "\\d{10}|\\d{12}"
      });
    }
    if (["snils", "customerSnils"].includes(item.key)) {
      return renderStudentIdentityInput(label, item.key, value, { maxLength: 14 });
    }
    if (item.type === "checkbox") {
      return `${label}<input name="${item.key}" type="checkbox" value="Да" ${isChecked(value) ? "checked" : ""}></label>`;
    }
    if (item.type === "textarea") {
      return `${label}<textarea name="${item.key}" ${required}>${escapeHtml(value)}</textarea></label>`;
    }
    if (item.type === "select") {
      const dictionaryOptions = item.options || state.data.dictionaries[item.dict] || [];
      const options = item.required ? dictionaryOptions : ["", ...dictionaryOptions];
      return `${label}<select name="${item.key}" ${item.dict ? `data-settings-dictionary="${escapeAttr(item.dict)}"` : ""} ${required}>${options.map((option) => `<option ${String(option) === String(value) ? "selected" : ""}>${escapeHtml(option)}</option>`).join("")}</select></label>`;
    }
    const moneyStepAttribute = item.type === "number"
      ? getMoneyInputStepAttribute("students", item.key)
      : "";
    return `${label}<input name="${item.key}" type="${item.type}" value="${escapeAttr(value)}" ${required} ${moneyStepAttribute} ${isCalculatedFinanceField ? 'readonly class="calculated-finance-field"' : ""}></label>`;
  }

  function getStudentOrderAdminUrlTemplate() {
    return String(
      state.data.meta.applicationsOrderAdminUrlTemplate
        || DEFAULT_STUDENT_ORDER_ADMIN_URL_TEMPLATE
    ).trim();
  }

  function getStudentOrderAdminUrl(orderNumber) {
    const value = String(orderNumber || "").trim();
    if (!value) return "";
    const encodedValue = encodeURIComponent(value);
    const template = getStudentOrderAdminUrlTemplate();
    const url = template
      .replaceAll("{НомерЗаказа}", encodedValue)
      .replaceAll("НомерЗаказа", encodedValue)
      .replaceAll("{orderNo}", encodedValue)
      .replaceAll("%ORDER_ID%", encodedValue);
    return normalizeExternalUrl(url);
  }

  function getStudentOrderAdminButtonTitle(orderNumber) {
    const value = String(orderNumber || "").trim();
    const url = getStudentOrderAdminUrl(value);
    return url
      ? `Открыть заказ № ${value} в интернет-магазине\n${url}`
      : "Укажите номер заказа";
  }

  function renderStudentOrderNumberField(label, value, required) {
    const title = getStudentOrderAdminButtonTitle(value);
    return `
      ${label}
        <div class="student-order-number-control">
          <input name="orderNo" type="text" value="${escapeAttr(value)}" ${required} autocomplete="off">
          <button class="icon-button student-order-admin-button" data-action="open-student-order-admin" type="button" title="${escapeAttr(title)}" aria-label="${escapeAttr(title)}" ${getStudentOrderAdminUrl(value) ? "" : "disabled"}>
            ${renderOrdersSdoIcon("externalLink")}
          </button>
        </div>
      </label>
    `;
  }

  function refreshStudentOrderAdminButton(input) {
    const button = input?.closest("label")?.querySelector("[data-action='open-student-order-admin']");
    if (!button) return;
    const title = getStudentOrderAdminButtonTitle(input.value);
    button.disabled = !getStudentOrderAdminUrl(input.value);
    button.title = title;
    button.setAttribute("aria-label", title);
  }

  function openStudentOrderAdmin(event) {
    event?.preventDefault();
    const form = event?.currentTarget?.closest("form")
      || document.querySelector("#recordForm[data-config='students']");
    const input = form?.elements?.orderNo;
    const url = getStudentOrderAdminUrl(input?.value || "");
    if (!url) {
      alert("Укажите номер заказа.");
      input?.focus({ preventScroll: true });
      return;
    }
    openExternalUrl(url);
  }

  function renderStudentIdentityInput(label, field, value, { maxLength, pattern = "" }) {
    const statusId = `student-${field}-validation`;
    return `
      ${label}
        <div class="student-identity-control" data-student-identity-control>
          <input
            name="${escapeAttr(field)}"
            type="text"
            value="${escapeAttr(value)}"
            inputmode="numeric"
            maxlength="${maxLength}"
            ${pattern ? `pattern="${escapeAttr(pattern)}"` : ""}
            autocomplete="off"
            aria-describedby="${escapeAttr(statusId)}"
          >
          <span
            class="student-identity-status"
            id="${escapeAttr(statusId)}"
            data-student-identity-status
            aria-live="polite"
          ></span>
        </div>
      </label>
    `;
  }

  function renderDiscountDescriptionField(label, value) {
    return `
      ${label}
        <div class="discount-description-field">
          <input name="discountDescription" type="text" value="${escapeAttr(value)}" autocomplete="off">
          <button class="icon-button discount-picker-trigger" data-action="open-discount-picker" type="button" title="Выбрать скидку" aria-label="Выбрать скидку">
            <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">
              <path d="M20 10.6V5.8A1.8 1.8 0 0 0 18.2 4h-4.8a2 2 0 0 0-1.4.6l-7.4 7.4a2 2 0 0 0 0 2.8l4.6 4.6a2 2 0 0 0 2.8 0l7.4-7.4a2 2 0 0 0 .6-1.4z"></path>
              <circle cx="16.2" cy="7.8" r="1"></circle>
              <path d="M8.6 15.4l6.8-6.8"></path>
              <circle cx="9.2" cy="9.2" r="1"></circle>
              <circle cx="14.8" cy="14.8" r="1"></circle>
            </svg>
          </button>
        </div>
      </label>
    `;
  }

  function getDiscountOptionKey(groupIndex, itemIndex) {
    return `${groupIndex}:${itemIndex}`;
  }

  function getDefaultDiscountRuleValues() {
    return discountGroups.flatMap((group) => [
      `# ${group.title}`,
      ...group.items.map((item) => item.separator
        ? item.separator
        : `${item.rates.join(",")}; ${item.title}`)
    ]);
  }

  function parseDiscountRuleValues(values = []) {
    const groups = [];
    let currentGroup = null;
    const ensureGroup = () => {
      if (!currentGroup) {
        currentGroup = { title: "СКИДКИ", items: [] };
        groups.push(currentGroup);
      }
      return currentGroup;
    };
    (values || []).forEach((raw) => {
      const line = String(raw || "").trim();
      if (!line) return;
      if (line.startsWith("#")) {
        currentGroup = { title: line.replace(/^#+\s*/, "").trim() || "СКИДКИ", items: [] };
        groups.push(currentGroup);
        return;
      }
      if (/^или$/i.test(line)) {
        ensureGroup().items.push({ separator: "или" });
        return;
      }
      const match = line.match(/^([\d\s,.;]+)\s*;\s*(.+)$/);
      if (!match) return;
      const rates = match[1]
        .split(/[,\s]+/)
        .map((value) => Number(String(value).replace(",", ".")))
        .filter((value) => Number.isFinite(value) && value > 0 && value <= 100);
      const title = match[2].trim();
      if (!rates.length || !title) return;
      ensureGroup().items.push({ rates: unique(rates), title });
    });
    return groups.filter((group) => group.items.length);
  }

  function getDiscountGroups() {
    return parseDiscountRuleValues(state.data.dictionaries.discountRules || []);
  }

  function getFlatDiscountOptions() {
    return getDiscountGroups().flatMap((group, groupIndex) => (
      group.items
        .map((item, itemIndex) => ({ ...item, groupTitle: group.title, key: getDiscountOptionKey(groupIndex, itemIndex) }))
        .filter((item) => !item.separator)
    ));
  }

  function getDiscountPickerState(record = {}) {
    const picker = state.discountPicker || {};
    const description = String(picker.description ?? record.discountDescription ?? "").trim();
    const option = findDiscountOptionByKey(picker.key)
      || getFlatDiscountOptions().find((item) => item.title === description)
      || getFlatDiscountOptions().find((item) => item.rates.includes(Number(picker.percent ?? record.discount ?? 0)))
      || getFlatDiscountOptions()[0];
    const percent = Number(picker.percent ?? record.discount ?? 0) || option?.rates?.[0] || 0;
    return {
      key: picker.key || option?.key || "",
      description: description || option?.title || "",
      percent
    };
  }

  function renderDiscountPicker(record) {
    const picker = getDiscountPickerState(record);
    const groups = getDiscountGroups();
    const flatOptions = getFlatDiscountOptions();
    const selectedOption = flatOptions.find((item) => item.key === picker.key)
      || flatOptions.find((item) => item.title === picker.description);
    const selectedRates = selectedOption?.rates || (picker.percent ? [picker.percent] : []);
    const selectedPercent = picker.percent || selectedRates[0] || 0;
    return `
      <div class="discount-picker-backdrop" role="presentation">
        <section class="discount-picker" role="dialog" aria-modal="true" aria-label="Скидки">
          <header class="discount-picker-head">
            <h3>Скидки</h3>
            <button class="icon-button" data-action="close-discount-picker" type="button" title="Закрыть" aria-label="Закрыть">
              <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M7 7l10 10"></path><path d="M17 7L7 17"></path></svg>
            </button>
          </header>
          <div class="discount-picker-body">
            <div class="discount-picker-list-wrap">
              <div class="discount-picker-hint">
                <span>Перечень доступных скидок</span>
                <button class="ghost-button discount-picker-tool-button discount-refresh-button" data-action="refresh-discount-picker" type="button" title="Обновить список из справочника">
                  <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M4 12a8 8 0 0 1 13.7-5.7"></path><path d="M18 4v5h-5"></path><path d="M20 12a8 8 0 0 1-13.7 5.7"></path><path d="M6 20v-5h5"></path></svg>
                  <span>Обновить</span>
                </button>
                <button class="ghost-button discount-picker-tool-button discount-restore-button" data-action="restore-default-discount-rules" type="button" title="Восстановить исходный перечень">
                  <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M3 12a9 9 0 1 0 3-6.7"></path><path d="M3 4v6h6"></path><path d="M12 8v5l3 2"></path></svg>
                  <span>Восстановить</span>
                </button>
              </div>
              <div class="discount-picker-list">
                ${groups.length ? groups.map((group, groupIndex) => `
                  <div class="discount-group-title">${escapeHtml(group.title)}</div>
                  ${group.items.map((item, itemIndex) => item.separator
                    ? `<div class="discount-separator">${escapeHtml(item.separator)}</div>`
                    : `<button class="discount-option ${picker.key === getDiscountOptionKey(groupIndex, itemIndex) ? "active" : ""}" data-action="select-discount-option" data-key="${getDiscountOptionKey(groupIndex, itemIndex)}" type="button">
                        <strong>${escapeHtml(item.rates.join(","))};</strong>
                        <span>${escapeHtml(item.title)}</span>
                      </button>`
                  ).join("")}
                `).join("") : `<div class="discount-empty discount-list-empty">Справочник скидок пуст. Восстановите исходный перечень или добавьте значения в справочнике.</div>`}
              </div>
            </div>
            <aside class="discount-picker-side">
              <label class="discount-rate-box">
                <span>Величина скидки</span>
                <div class="discount-rate-list">
                  ${selectedRates.length ? selectedRates.map((rate) => `
                    <button class="${Number(rate) === Number(selectedPercent) ? "active" : ""}" data-action="select-discount-rate" data-rate="${rate}" type="button" aria-pressed="${Number(rate) === Number(selectedPercent) ? "true" : "false"}">${rate}</button>
                  `).join("") : `<span class="discount-empty">Нет</span>`}
                </div>
              </label>
              <label class="discount-total-box">
                <span>Суммарная скидка, %</span>
                <output>${escapeHtml(selectedPercent)}</output>
              </label>
              <label class="discount-note-box">
                <span>Примечание</span>
                <textarea data-discount-note>${escapeHtml(picker.description)}</textarea>
              </label>
            </aside>
          </div>
          <footer class="discount-picker-actions">
            <button class="primary-button discount-apply-button" data-action="apply-discount-picker" type="button">
              <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M5 13l4 4L19 7"></path></svg>
              <span>Применить</span>
            </button>
            <button class="ghost-button discount-cancel-button" data-action="close-discount-picker" type="button">
              <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M7 7l10 10"></path><path d="M17 7L7 17"></path></svg>
              <span>Отмена</span>
            </button>
          </footer>
        </section>
      </div>
    `;
  }

  function renderStudentProgramField(label, value, required) {
    const programNames = sortProgramNames([
      ...getProgramRows().map((program) => program.name).filter(Boolean),
      value
    ]);
    return `
      ${label}
        ${renderComboField({
          name: "program",
          type: "search",
          value,
          required,
          options: programNames,
          action: "set-student-program"
        })}
      </label>
    `;
  }

  function renderSearchableStudentField(label, item, value, required) {
    const config = searchableStudentFields[item.key];
    const options = getLookupOptions(config);
    return `
      ${label}
        ${renderComboField({
          name: item.key,
          type: "search",
          value,
          required,
          options,
          dictionary: config.dict
        })}
      </label>
    `;
  }

  function renderComboField({ name, type = "text", value = "", required = "", options = [], action = "", attrs = "", dictionary = "" }) {
    const normalizedOptions = unique(options.map((option) => String(option)).filter(Boolean));
    return `
      <div class="combo-field" data-combo-field>
        <div class="combo-input-wrap">
          <input
            name="${escapeAttr(name)}"
            type="${escapeAttr(type)}"
            value="${escapeAttr(value)}"
            autocomplete="off"
            data-combo-input
            ${dictionary ? `data-settings-dictionary="${escapeAttr(dictionary)}"` : ""}
            ${action ? `data-action="${escapeAttr(action)}"` : ""}
            ${attrs}
            ${required}
          >
          <button class="combo-clear" data-action="clear-combo-value" type="button" title="Очистить" aria-label="Очистить значение">
            <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M7 7l10 10"></path><path d="M17 7L7 17"></path></svg>
          </button>
        </div>
        <div class="combo-options" data-combo-options>
          ${normalizedOptions.map((option) => {
            const selected = option === String(value);
            return `
              <button class="${selected ? "is-selected" : ""}" data-action="select-combo-value" data-value="${escapeAttr(option)}" type="button" aria-selected="${selected ? "true" : "false"}">
                ${escapeHtml(option)}
              </button>
            `;
          }).join("") || `<span class="combo-empty">Нет значений</span>`}
        </div>
      </div>
    `;
  }

  function renderIssuerLookupField(label, item, value, required) {
    const options = item.key === "educationDocumentIssuer"
      ? getEducationDocumentIssuerOptions(value)
      : getPassportIssuerOptions(value);
    return `
      ${label}
        <div class="lookup-field">
          <input name="${item.key}" type="text" value="${escapeAttr(value)}" data-settings-dictionary="${item.key === "educationDocumentIssuer" ? "educationDocumentIssuers" : "passportIssuers"}" ${required} autocomplete="off">
          <button class="icon-button lookup-trigger" data-action="open-field-lookup" data-field="${item.key}" type="button" title="Найти в базе" aria-label="Найти в базе">
            <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><circle cx="11" cy="11" r="6"></circle><path d="M16 16l4 4"></path></svg>
          </button>
          <button class="icon-button lookup-clear" data-action="clear-lookup-value" data-field="${item.key}" type="button" title="Очистить" aria-label="Очистить значение">
            <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M7 7l10 10"></path><path d="M17 7L7 17"></path></svg>
          </button>
          <div class="lookup-panel" data-lookup-panel="${item.key}">
            <input class="lookup-search" data-action="filter-lookup-values" data-field="${item.key}" type="search" placeholder="Поиск по базе" autocomplete="off">
            <div class="lookup-list">
              ${options.map((option) => `
                <button data-action="select-lookup-value" data-field="${item.key}" data-value="${escapeAttr(option)}" type="button">
                  ${escapeHtml(option)}
                </button>
              `).join("") || `<span class="lookup-empty">Значений пока нет</span>`}
            </div>
          </div>
        </div>
      </label>
    `;
  }

  function getSavedPersonNameOptions(collection, currentValue = "") {
    return unique([
      ...(state.data.collections[collection] || []).map((record) => String(record?.name || "").trim()),
      String(currentValue || "").trim()
    ].filter(Boolean)).sort((left, right) => left.localeCompare(right, "ru", {
      numeric: true,
      sensitivity: "base"
    }));
  }

  function positionFieldLookupPanel(panel) {
    const field = panel?.closest(".lookup-field");
    if (!field) return;

    const fieldRect = field.getBoundingClientRect();
    const viewportWidth = document.documentElement.clientWidth || window.innerWidth;
    const viewportHeight = document.documentElement.clientHeight || window.innerHeight;
    const margin = 8;
    const gap = 5;
    const availableWidth = Math.max(0, viewportWidth - margin * 2);
    const panelWidth = Math.min(Math.max(fieldRect.width, 640), availableWidth);
    const panelLeft = Math.min(
      Math.max(fieldRect.left, margin),
      Math.max(margin, viewportWidth - panelWidth - margin)
    );
    const spaceBelow = Math.max(0, viewportHeight - fieldRect.bottom - gap - margin);
    const spaceAbove = Math.max(0, fieldRect.top - gap - margin);
    const openAbove = spaceBelow < 220 && spaceAbove > spaceBelow;
    const preferredSpace = openAbove ? spaceAbove : spaceBelow;
    const fullViewportHeight = Math.max(80, viewportHeight - margin * 2);
    const panelMaxHeight = preferredSpace >= 120
      ? Math.min(360, preferredSpace)
      : fullViewportHeight;

    panel.style.left = `${panelLeft}px`;
    panel.style.width = `${panelWidth}px`;
    panel.style.setProperty("--lookup-panel-max-height", `${panelMaxHeight}px`);
    panel.style.setProperty("--lookup-list-max-height", `${Math.max(48, panelMaxHeight - 64)}px`);

    if (preferredSpace < 120) {
      panel.style.top = `${margin}px`;
      panel.style.bottom = "auto";
    } else if (openAbove) {
      panel.style.top = "auto";
      panel.style.bottom = `${viewportHeight - fieldRect.top + gap}px`;
    } else {
      panel.style.top = `${fieldRect.bottom + gap}px`;
      panel.style.bottom = "auto";
    }
  }

  function repositionOpenFieldLookupPanels() {
    document.querySelectorAll(".lookup-panel.is-open").forEach(positionFieldLookupPanel);
  }

  function getProgramRows() {
    return sortProgramRows(state.data.collections.programs || []);
  }

  function findProgramByName(name) {
    return findProgramInRows(getProgramRows(), name);
  }

  function getProgramTrainingPlanNameKeys(programRecord = {}, fallbackName = "") {
    const names = [fallbackName, programRecord.name, programRecord.shortName]
      .map((value) => String(value || "").trim())
      .filter(Boolean);
    return {
      exact: new Set(names.map(normalizeProgramName).filter(Boolean)),
      comparable: new Set(names.map(normalizeTrainingPlanProgramName).filter(Boolean))
    };
  }

  function isTrainingPlanRowLinkedToProgram(item, programRecord = {}, fallbackName = "") {
    const programId = String(programRecord.id || "").trim();
    const rowProgramId = String(item?.programId || "").trim();
    if (programId && rowProgramId) return rowProgramId === programId;
    if (rowProgramId) return false;
    const rowProgramName = String(item?.programName || "").trim();
    if (!rowProgramName) return false;
    const keys = getProgramTrainingPlanNameKeys(programRecord, fallbackName);
    return keys.exact.has(normalizeProgramName(rowProgramName))
      || keys.comparable.has(normalizeTrainingPlanProgramName(rowProgramName));
  }

  function getProgramTrainingPlanRows(programRecord = {}, fallbackName = "") {
    return (state.data.collections.trainingPlans || [])
      .filter((item) => isTrainingPlanRowLinkedToProgram(item, programRecord, fallbackName));
  }

  function parseTrainingPlanHoursValue(value) {
    const text = String(value ?? "").replace(/\s+/gu, "").replace(",", ".").trim();
    if (!text) return null;
    const number = Number(text);
    return Number.isFinite(number) ? number : null;
  }

  function roundTrainingPlanHours(value) {
    return Math.round(Number(value || 0) * 1000000) / 1000000;
  }

  function calculateProgramTrainingPlanHoursSummary(programHoursValue, rows = []) {
    const planRows = Array.isArray(rows) ? rows : [];
    const programHours = parseTrainingPlanHoursValue(programHoursValue);
    const distributedHours = roundTrainingPlanHours(planRows.reduce((sum, row) => {
      const rowHours = parseTrainingPlanHoursValue(row?.totalHours);
      return sum + (rowHours === null ? 0 : rowHours);
    }, 0));
    const remainingHours = programHours === null
      ? null
      : roundTrainingPlanHours(programHours - distributedHours);
    const hasPlan = planRows.length > 0;
    return {
      hasPlan,
      programHours,
      distributedHours,
      remainingHours,
      mismatch: hasPlan && (programHours === null || Math.abs(remainingHours) > 0.000001)
    };
  }

  function getProgramTrainingPlanHoursSummary(programRecord = {}, rows = null, fallbackName = "") {
    const planRows = Array.isArray(rows)
      ? rows
      : getProgramTrainingPlanRows(programRecord, fallbackName);
    return calculateProgramTrainingPlanHoursSummary(programRecord?.hours, planRows);
  }

  function formatTrainingPlanHours(value) {
    if (value === null || !Number.isFinite(Number(value))) return "—";
    return `${Number(value).toLocaleString("ru-RU", { maximumFractionDigits: 6 })} ч`;
  }

  function getProgramTrainingPlanHoursStatus(summary = {}) {
    if (!summary.hasPlan) return "Учебный план пока не заполнен.";
    if (summary.programHours === null) return "Укажите объём часов программы для сверки с учебным планом.";
    if (!summary.mismatch) return "Все часы программы распределены по учебному плану.";
    if (summary.remainingHours > 0) {
      return `По учебному плану не распределено ${formatTrainingPlanHours(summary.remainingHours)}.`;
    }
    return `Учебный план превышает объём программы на ${formatTrainingPlanHours(Math.abs(summary.remainingHours))}.`;
  }

  function getProgramTrainingPlanHoursMismatchTitle(summary = {}) {
    if (!summary.mismatch) return "";
    return [
      "Сумма часов учебного плана не совпадает с объёмом образовательной программы.",
      `Объём программы: ${formatTrainingPlanHours(summary.programHours)}.`,
      `Распределено: ${formatTrainingPlanHours(summary.distributedHours)}.`,
      `Нераспределено: ${formatTrainingPlanHours(summary.remainingHours)}.`
    ].join(" ");
  }

  function getStudentGroupNumber(programName, startDate) {
    return buildStudentGroupNumber(programName, startDate, getProgramRows());
  }

  function generateStudentGroupNumber() {
    const form = document.getElementById("recordForm");
    if (!form || form.dataset.config !== "students") return;
    const programName = String(form.querySelector("[name='program']")?.value || state.modal?.draft?.program || "").trim();
    const startDate = String(form.querySelector("[name='startDate']")?.value || state.modal?.draft?.startDate || "").trim();
    const program = findProgramByName(programName);
    if (!programName || !program) {
      alert("Выберите программу обучения из реестра программ.");
      form.querySelector("[name='program']")?.focus();
      return;
    }
    if (!String(program.groupIndex || "").trim()) {
      alert("Для выбранной программы в реестре не указан индекс группы.");
      return;
    }
    if (!startDate) {
      alert("Заполните дату начала обучения.");
      form.querySelector("[name='startDate']")?.focus();
      return;
    }
    const group = getStudentGroupNumber(programName, startDate);
    if (!group) {
      alert("Не удалось сформировать номер группы. Проверьте программу и дату начала обучения.");
      return;
    }
    const groupInput = form.querySelector("[name='group']");
    if (!groupInput) return;
    groupInput.value = group;
    groupInput.dispatchEvent(new Event("input", { bubbles: true }));
    groupInput.dispatchEvent(new Event("change", { bubbles: true }));
    state.modal.draft = {
      ...(state.modal.draft || {}),
      program: programName,
      startDate,
      group
    };
    state.modal.hasDraftChanges = true;
    groupInput.focus({ preventScroll: true });
  }

  function getPortalLoginFromForm(form) {
    const isEmployee = form?.dataset.config === "contracts";
    const collection = isEmployee
      ? state.data.collections.contracts || []
      : state.data.collections.students || [];
    const currentRecord = collection.find((item) => item.id === state.modal?.id) || {};
    const email = String(
      form?.querySelector("[name='email']")?.value
      || state.modal?.draft?.email
      || currentRecord.email
      || ""
    ).trim();
    const emailParts = email.split("@");
    return emailParts.length > 1 ? emailParts[0].trim().toLowerCase() : "";
  }

  function createPortalPassword() {
    const random = new Uint32Array(1);
    crypto.getRandomValues(random);
    return String(random[0] % 1000000).padStart(6, "0");
  }

  function getPortalCredentialsForAutofill(form) {
    const login = getPortalLoginFromForm(form);
    if (!login) {
      alert("Заполните корректный адрес электронной почты слушателя. Логин СДО формируется из части адреса до символа @.");
      form?.querySelector("[name='email']")?.focus({ preventScroll: true });
      return null;
    }
    return { login, password: createPortalPassword() };
  }

  function getGeneratedPortalAccessMessage(form) {
    const currentStudent = (state.data.collections.students || [])
      .find((student) => student.id === state.modal?.id) || {};
    const values = {
      ...currentStudent,
      ...(state.modal?.draft || {}),
      ...collectStudentFormDraft(),
      login: String(form?.querySelector("[name='login']")?.value || ""),
      password: String(form?.querySelector("[name='password']")?.value || ""),
      portalAccessMessage: ""
    };
    return generateStudentCommunicationMessages(values).portalAccessMessage || "";
  }

  function generatePortalPassword() {
    const form = document.getElementById("recordForm");
    const loginInput = form?.querySelector("[name='login']");
    const passwordInput = form?.querySelector("[name='password']");
    if (!loginInput || !passwordInput) return;
    const generatedLogin = getPortalLoginFromForm(form);
    if (!generatedLogin) {
      const recipient = form?.dataset.config === "contracts" ? "сотрудника" : "слушателя";
      alert(`Заполните корректный адрес электронной почты ${recipient}. Логин формируется из части адреса до символа @.`);
      form?.querySelector("[name='email']")?.focus({ preventScroll: true });
      return;
    }
    if (passwordInput.value && !confirm("Пароль уже заполнен. Заменить его новым шестизначным паролем?")) return;
    loginInput.value = generatedLogin;
    passwordInput.value = createPortalPassword();
    loginInput.dispatchEvent(new Event("input", { bubbles: true }));
    loginInput.dispatchEvent(new Event("change", { bubbles: true }));
    passwordInput.dispatchEvent(new Event("input", { bubbles: true }));
    passwordInput.dispatchEvent(new Event("change", { bubbles: true }));
    state.modal.draft = {
      ...(state.modal.draft || {}),
      login: loginInput.value,
      password: passwordInput.value
    };
    state.modal.hasDraftChanges = true;
    passwordInput.focus({ preventScroll: true });
    passwordInput.select();
  }

  function updatePortalAccessMessage() {
    const form = document.getElementById("recordForm");
    const messageInput = form?.querySelector("[name='portalAccessMessage']");
    if (!form || !messageInput || form.dataset.config !== "students") return;
    const generated = getGeneratedPortalAccessMessage(form);
    const values = {
      login: String(form.querySelector("[name='login']")?.value || ""),
      password: String(form.querySelector("[name='password']")?.value || "")
    };
    messageInput.value = generated;
    state.modal.draft = {
      ...(state.modal.draft || {}),
      login: values.login,
      password: values.password,
      portalAccessMessage: ""
    };
    state.modal.hasDraftChanges = true;
  }

  function updatePortalAccessEndDate() {
    const form = document.getElementById("recordForm");
    const messageInput = form?.querySelector("[name='portalAccessMessage']");
    if (!form || !messageInput || form.dataset.config !== "students") return;
    const currentStudent = (state.data.collections.students || [])
      .find((student) => student.id === state.modal?.id) || {};
    const values = {
      ...currentStudent,
      ...(state.modal?.draft || {}),
      ...collectStudentFormDraft(),
      endDate: String(form.querySelector("[name='endDate']")?.value || ""),
      extendedEndDate: String(form.querySelector("[name='extendedEndDate']")?.value || "")
    };
    const syncedMessage = syncStudentPortalEndDateLine(messageInput.value, values);
    messageInput.value = syncedMessage;
    const generatedMessage = getGeneratedPortalAccessMessage(form);
    state.modal.draft = {
      ...(state.modal.draft || {}),
      endDate: values.endDate,
      extendedEndDate: values.extendedEndDate,
      portalAccessMessage: syncedMessage === generatedMessage ? "" : syncedMessage
    };
    state.modal.hasDraftChanges = true;
  }

  function openSdoCourses() {
    const coursesUrl = normalizeExternalUrl(getSdoSettingValue("coursesUrl"));
    if (!coursesUrl) {
      alert("Укажите корректный адрес страницы курсов в справочнике «Настройки СДО».");
      return;
    }
    openExternalUrl(coursesUrl);
  }

  function exportStudentToSdo() {
    const record = collectStudentFormDraft();
    const uploadUsersUrl = normalizeExternalUrl(getSdoSettingValue("uploadUsersUrl"));
    if (!uploadUsersUrl) {
      alert("Укажите корректный адрес страницы загрузки пользователей в справочнике «Настройки СДО».");
      return;
    }
    const login = String(record.login || "").trim();
    const password = String(record.password || "");
    const email = String(record.email || "").trim();
    const nameParts = splitStudentNameForSdo(record.name);
    const program = findProgramByName(record.program);
    const cohort = String(program?.groupIndex || "").trim();
    const required = [
      [login, "Заполните логин для портала.", "login"],
      [password, "Заполните пароль для портала.", "password"],
      [nameParts.lastname, "Заполните ФИО слушателя.", ""],
      [email, "Заполните Email слушателя.", ""],
      [String(record.program || "").trim(), "Выберите программу обучения.", ""],
      [cohort, "Для выбранной программы в реестре не указан индекс группы.", ""]
    ];
    const missing = required.find(([value]) => !value);
    if (missing) {
      alert(missing[1]);
      if (missing[2]) document.querySelector(`[name="${missing[2]}"]`)?.focus({ preventScroll: true });
      return;
    }
    const columns = ["username", "password", "firstname", "lastname", "email", "cohort1"];
    const values = [login, password, nameParts.firstname, nameParts.lastname, email, cohort];
    const content = [
      columns.map(sdoCsvCell).join(";"),
      values.map(sdoCsvCell).join(";")
    ].join("\r\n");
    download(`ЭкспортПользователей_${formatSdoExportDate(new Date())}.csv`, `\ufeff${content}`, "text/csv;charset=utf-8");
    openExternalUrl(uploadUsersUrl);
  }

  function exportEmployeeToSdo() {
    const record = collectContractFormDraft();
    const uploadUsersUrl = normalizeExternalUrl(getSdoSettingValue("uploadUsersUrl"));
    if (!uploadUsersUrl) {
      alert("Укажите корректный адрес страницы загрузки пользователей в справочнике «Настройки СДО».");
      return;
    }
    const login = String(record.login || "").trim();
    const password = String(record.password || "");
    const email = String(record.email || "").trim();
    const nameParts = splitStudentNameForSdo(record.name);
    const required = [
      [login, "Заполните логин для портала.", "login"],
      [password, "Заполните пароль для портала.", "password"],
      [nameParts.lastname, "Заполните ФИО сотрудника.", "name"],
      [email, "Заполните Email сотрудника.", "email"]
    ];
    const missing = required.find(([value]) => !value);
    if (missing) {
      alert(missing[1]);
      if (missing[2]) document.querySelector(`[name="${missing[2]}"]`)?.focus({ preventScroll: true });
      return;
    }
    const columns = ["username", "password", "firstname", "lastname", "email"];
    const values = [login, password, nameParts.firstname, nameParts.lastname, email];
    const content = [
      columns.map(sdoCsvCell).join(";"),
      values.map(sdoCsvCell).join(";")
    ].join("\r\n");
    download(`ЭкспортСотрудникаСДО_${formatSdoExportDate(new Date())}.csv`, `\ufeff${content}`, "text/csv;charset=utf-8");
    openExternalUrl(uploadUsersUrl);
  }

  function splitStudentNameForSdo(value) {
    const parts = String(value || "").trim().replace(/\s+/g, " ").split(" ").filter(Boolean);
    const lastname = parts.shift() || "";
    return {
      firstname: parts.join(" ") || lastname,
      lastname
    };
  }

  function sdoCsvCell(value) {
    const text = String(value ?? "").trim().replace(/\s{2,}/g, " ");
    return /[;"\r\n]/.test(text) ? `"${text.replaceAll('"', '""')}"` : text;
  }

  function formatSdoExportDate(date) {
    return [
      date.getFullYear(),
      String(date.getMonth() + 1).padStart(2, "0"),
      String(date.getDate()).padStart(2, "0")
    ].join(".");
  }

  function getProgramPromoUrl(program) {
    if (!program) return "";
    const rawValue = [
      program.promoSite,
      program.promoUrl,
      program.promoWebsite,
      program.landingUrl,
      program.siteUrl,
      program.website,
      program.url,
      program["На промо сайте"],
      program["Промосайт"],
      program["Промо сайт"]
    ].find((value) => String(value || "").trim());
    return normalizeExternalUrl(rawValue);
  }

  function getProgramGradeReportUrl(program) {
    if (!program) return "";
    const rawValue = [
      program.gradeReportUrl,
      program.reportUrl,
      program.gradeUrl,
      program["Ссылка на отчет по оценкам"]
    ].find((value) => String(value || "").trim());
    return normalizeExternalUrl(rawValue);
  }

  function getProgramActivityLogUrl(program) {
    const gradeReportUrl = getProgramGradeReportUrl(program);
    if (!gradeReportUrl) return "";
    try {
      const url = new URL(gradeReportUrl);
      const courseId = String(url.searchParams.get("id") || "").trim();
      if (!courseId) return "";
      url.pathname = "/report/log/index.php";
      url.search = "";
      url.searchParams.set("id", courseId);
      url.hash = "";
      return url.href;
    } catch (error) {
      return "";
    }
  }

  function getProgramPromoButtonTitle(url) {
    return url ? `Перейти на промосайт программы\n${url}` : "Перейти на промосайт программы";
  }

  function updateStudentProgramPromoTitle(programName) {
    const button = document.querySelector("[data-action='open-student-program-promo']");
    if (!button) return;
    const url = getProgramPromoUrl(findProgramByName(programName));
    const title = getProgramPromoButtonTitle(url);
    button.title = title;
    button.setAttribute("aria-label", title);
  }

  function getProgramType(programName, record = {}) {
    const program = findProgramByName(programName);
    return program?.type || record.educationType || "";
  }

  function getProgramTypeOptions(value = "") {
    return unique([
      ...getProgramRows().map((program) => program.type).filter(Boolean),
      value
    ].map((item) => String(item).trim()).filter(Boolean)).sort((a, b) => a.localeCompare(b, "ru"));
  }

  function getLookupOptions(config, extraValues = []) {
    const dictionaryValues = state.data.dictionaries[config.dict] || [];
    const rowValues = (config.fields || []).flatMap(([collection, key]) => (
      state.data.collections[collection] || []
    ).map((row) => row[key]).filter(Boolean));
    return unique([...dictionaryValues, ...rowValues, ...extraValues].map((value) => String(value).trim()).filter(Boolean)).sort((a, b) => a.localeCompare(b, "ru"));
  }

  function getPassportIssuerOptions(currentValue = "") {
    return getLookupOptions({
      dict: "passportIssuers",
      fields: [["students", "passportIssuer"], ["students", "customerPassportIssuer"]]
    }, [currentValue]);
  }

  function getEducationDocumentIssuerOptions(currentValue = "") {
    return getLookupOptions({
      dict: "educationDocumentIssuers",
      fields: [["students", "educationDocumentIssuer"]]
    }, [currentValue]);
  }

  function todayIso() {
    const date = new Date();
    return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`;
  }

  function isExplicitUncheckedEventState(stateValue) {
    return ["unchecked", "none", "false", "0"].includes(String(stateValue || "").trim().toLowerCase());
  }

  function normalizeEventState(stateValue, dateValue = "") {
    if (isExplicitUncheckedEventState(stateValue)) return "";
    if (stateValue === "dated" || stateValue === "checked") return stateValue;
    if (dateValue) return "dated";
    return "";
  }

  function nextEventState(stateValue) {
    if (!stateValue) return "dated";
    if (stateValue === "dated") return "checked";
    return "";
  }

  function updateStudentEventRow(row) {
    const key = row.dataset.eventKey;
    const checkbox = row.querySelector("input[type='checkbox']");
    const stateInput = row?.querySelector(`[data-event-state="${key}"]`);
    const dateInput = row?.querySelector(`[data-event-date="${key}"]`);
    const dateLabel = row?.querySelector(`[data-event-date-label="${key}"]`);
    if (!row || !stateInput || !dateInput || !dateLabel) return;
    const nextState = nextEventState(normalizeEventState(stateInput.value, dateInput.value));
    stateInput.value = nextState;
    dateInput.value = nextState === "dated" ? todayIso() : "";
    checkbox.checked = Boolean(nextState);
    row.classList.toggle("is-selected", Boolean(nextState));
    row.classList.toggle("has-date", nextState === "dated");
    dateLabel.textContent = nextState === "dated" ? dateRu(dateInput.value) : "";
    syncCardEventDraftFromDom();
  }

  function openStudentEventEditor(row, clientX = 0, clientY = 0) {
    const key = row.dataset.eventKey;
    const editor = document.querySelector("[data-event-editor]");
    const dateInput = editor?.querySelector("[data-event-editor-date]");
    const labelInput = editor?.querySelector("[data-event-editor-label]");
    const dateValue = row.querySelector(`[data-event-date="${key}"]`)?.value || "";
    const labelValue = row.querySelector(`[data-event-label-value="${key}"]`)?.value || row.querySelector("[data-event-label-text]")?.textContent || "";
    if (!editor || !dateInput || !labelInput) return;
    document.querySelectorAll(".student-event-row.is-editing").forEach((item) => item.classList.remove("is-editing"));
    row.classList.add("is-editing");
    editor.dataset.eventKey = key;
    dateInput.value = dateValue;
    labelInput.value = labelValue;
    editor.hidden = false;
    const rect = editor.parentElement.getBoundingClientRect();
    editor.style.left = `${clamp(clientX - rect.left, 8, Math.max(8, rect.width - 320))}px`;
    editor.style.top = `${clamp(clientY - rect.top, 8, Math.max(8, rect.height - 132))}px`;
    labelInput.focus({ preventScroll: true });
    labelInput.select();
  }

  function closeStudentEventEditor() {
    const editor = document.querySelector("[data-event-editor]");
    if (!editor) return;
    editor.hidden = true;
    editor.dataset.eventKey = "";
    document.querySelectorAll(".student-event-row.is-editing").forEach((item) => item.classList.remove("is-editing"));
  }

  function applyStudentEventEditor() {
    const editor = document.querySelector("[data-event-editor]");
    const key = editor?.dataset.eventKey;
    const row = key ? document.querySelector(`.student-event-row[data-event-key="${CSS.escape(key)}"]`) : null;
    const dateInput = editor?.querySelector("[data-event-editor-date]");
    const labelInput = editor?.querySelector("[data-event-editor-label]");
    if (!editor || !key || !row || !dateInput || !labelInput) return;
    const stateInput = row.querySelector(`[data-event-state="${key}"]`);
    const dateHidden = row.querySelector(`[data-event-date="${key}"]`);
    const labelHidden = row.querySelector(`[data-event-label-value="${key}"]`);
    const dateLabel = row.querySelector(`[data-event-date-label="${key}"]`);
    const labelText = row.querySelector(`[data-event-label-text="${key}"]`);
    const newDate = dateInput.value || "";
    const newLabel = labelInput.value.trim();
    if (dateHidden) dateHidden.value = newDate;
    if (labelHidden && newLabel) labelHidden.value = newLabel;
    if (labelText && newLabel) {
      labelText.textContent = newLabel;
      labelText.title = newLabel;
    }
    if (dateLabel) dateLabel.textContent = newDate ? dateRu(newDate) : "";
    if (stateInput) stateInput.value = newDate ? "dated" : (stateInput.value ? "checked" : "");
    const checkbox = row.querySelector("input[type='checkbox']");
    const isSelected = Boolean(stateInput?.value);
    if (checkbox) checkbox.checked = isSelected;
    row.classList.toggle("is-selected", isSelected);
    row.classList.toggle("has-date", stateInput?.value === "dated");
    syncCardEventDraftFromDom();
    closeStudentEventEditor();
  }

  function getComboVisibleVerticalBounds(field) {
    const margin = 8;
    let top = margin;
    let bottom = (document.documentElement.clientHeight || window.innerHeight) - margin;
    let ancestor = field?.parentElement;
    while (ancestor && ancestor !== document.body && ancestor !== document.documentElement) {
      const style = window.getComputedStyle(ancestor);
      if (/(?:auto|scroll|hidden|clip)/u.test(`${style.overflowY} ${style.overflow}`)) {
        const rect = ancestor.getBoundingClientRect();
        if (rect.height > 0) {
          top = Math.max(top, rect.top + 4);
          bottom = Math.min(bottom, rect.bottom - 4);
        }
      }
      ancestor = ancestor.parentElement;
    }
    return { top, bottom: Math.max(top, bottom) };
  }

  function positionComboOptions(field) {
    const panel = field?.querySelector(":scope > [data-combo-options], :scope > .combo-options");
    const anchor = field?.querySelector(":scope > .combo-input-wrap") || field;
    if (!panel || !anchor || !field.classList.contains("is-open")) return;
    const rect = anchor.getBoundingClientRect();
    const bounds = getComboVisibleVerticalBounds(field);
    const gap = field.closest(".modal") ? 3 : 6;
    const baseMaxHeight = field.closest(".modal") ? 210 : 260;
    const spaceAbove = Math.max(0, rect.top - bounds.top - gap);
    const spaceBelow = Math.max(0, bounds.bottom - rect.bottom - gap);
    const desiredHeight = Math.min(baseMaxHeight, Math.max(48, panel.scrollHeight || baseMaxHeight));
    const lowerHalf = rect.top + rect.height / 2 > bounds.top + (bounds.bottom - bounds.top) / 2;
    const openAbove = spaceAbove > spaceBelow
      && (spaceBelow < desiredHeight || lowerHalf)
      && spaceAbove >= 48;
    const availableHeight = openAbove ? spaceAbove : spaceBelow;
    field.classList.toggle("is-open-above", openAbove);
    panel.style.setProperty(
      "--combo-options-max-height",
      `${Math.max(48, Math.min(baseMaxHeight, availableHeight || baseMaxHeight))}px`
    );
  }

  function repositionOpenComboPanels() {
    document.querySelectorAll(".combo-field.is-open").forEach(positionComboOptions);
  }

  function openComboPanel(field) {
    if (!field) return;
    field.classList.add("is-open");
    positionComboOptions(field);
    window.requestAnimationFrame(() => positionComboOptions(field));
  }

  function closeComboPanels(except = null) {
    document.querySelectorAll(".combo-field.is-open").forEach((field) => {
      if (field !== except) {
        field.classList.remove("is-open", "is-open-above");
      }
    });
  }

  function bindComboFieldEvents(root = document) {
    root.querySelectorAll("[data-combo-field]").forEach((field) => {
      if (field.dataset.comboBound === "true") return;
      const input = field.querySelector("[data-combo-input]");
      if (!input) return;
      field.dataset.comboBound = "true";
      const open = (event) => {
        closeComboPanels(field);
        const showAll = event?.type !== "input";
        filterComboOptions(input, { showAll });
        openComboPanel(field);
        if (showAll) focusComboSelectedOption(input);
        if (event?.type === "input" && document.activeElement !== input) {
          input.focus({ preventScroll: true });
        }
      };
      input.addEventListener("focus", open);
      input.addEventListener("click", open);
      input.addEventListener("input", open);
      input.addEventListener("keydown", (event) => {
        if (event.key === "Escape") field.classList.remove("is-open", "is-open-above");
      });
      field.addEventListener("pointerdown", (event) => {
        if (event.target.closest("[data-action='select-combo-value'], [data-action='clear-combo-value']")) {
          event.preventDefault();
        }
      });
      field.addEventListener("focusout", (event) => {
        if (event.relatedTarget && field.contains(event.relatedTarget)) return;
        setTimeout(() => {
          if (!field.contains(document.activeElement)) field.classList.remove("is-open", "is-open-above");
        }, 0);
      });
    });

    root.querySelectorAll("[data-action='select-combo-value']").forEach((button) => {
      if (button.dataset.comboSelectBound === "true") return;
      button.dataset.comboSelectBound = "true";
      button.addEventListener("click", () => {
        const field = button.closest("[data-combo-field]");
        const input = field?.querySelector("[data-combo-input]");
        if (!input) return;
        input.value = button.dataset.value || "";
        input.dispatchEvent(new Event("input", { bubbles: true }));
        input.dispatchEvent(new Event("change", { bubbles: true }));
        field.classList.remove("is-open", "is-open-above");
        input.focus();
      });
    });

    root.querySelectorAll("[data-action='clear-combo-value']").forEach((button) => {
      if (button.dataset.comboClearBound === "true") return;
      button.dataset.comboClearBound = "true";
      button.addEventListener("click", () => {
        const field = button.closest("[data-combo-field]");
        const input = field?.querySelector("[data-combo-input]");
        if (!input) return;
        input.value = "";
        input.dispatchEvent(new Event("input", { bubbles: true }));
        input.dispatchEvent(new Event("change", { bubbles: true }));
        filterComboOptions(input);
        openComboPanel(field);
        input.focus();
      });
    });
  }

  function filterComboOptions(input, { showAll = false } = {}) {
    const field = input.closest("[data-combo-field]");
    const query = showAll ? "" : input.value.trim().toLowerCase();
    field?.querySelectorAll("[data-action='select-combo-value']").forEach((button) => {
      button.hidden = query && !button.textContent.toLowerCase().includes(query);
    });
    if (field?.classList.contains("is-open")) positionComboOptions(field);
  }

  function closeDirectExpenseNoteFilter() {
    const field = document.querySelector("[data-direct-expense-note-filter]");
    if (!field) return;
    field.classList.remove("is-open", "is-open-above");
    field.querySelector("#directExpenseNoteFilter")?.setAttribute("aria-expanded", "false");
  }

  function filterDirectExpenseNoteOptions(input, { showAll = false } = {}) {
    const field = input?.closest("[data-direct-expense-note-filter]");
    if (!field) return;
    const query = showAll ? "" : input.value.trim().toLocaleLowerCase("ru-RU");
    let visibleCount = 0;
    field.querySelectorAll("[data-action='select-direct-expense-note-filter']").forEach((button) => {
      const value = String(button.dataset.value || "").toLocaleLowerCase("ru-RU");
      const visible = !query || (value && value.includes(query));
      button.hidden = !visible;
      if (visible) visibleCount += 1;
    });
    const empty = field.querySelector("[data-direct-expense-note-filter-empty]");
    if (empty) empty.hidden = visibleCount > 0;
  }

  function openDirectExpenseNoteFilter(input, { showAll = false } = {}) {
    const field = input?.closest("[data-direct-expense-note-filter]");
    if (!field) return;
    closeComboPanels();
    filterDirectExpenseNoteOptions(input, { showAll });
    openComboPanel(field);
    input.setAttribute("aria-expanded", "true");
  }

  function focusComboSelectedOption(input) {
    const field = input.closest("[data-combo-field]");
    const optionsPanel = field?.querySelector("[data-combo-options]");
    const value = input.value.trim();
    let selectedOption = null;
    field?.querySelectorAll("[data-action='select-combo-value']").forEach((button) => {
      const selected = Boolean(value) && String(button.dataset.value || "").trim() === value;
      button.classList.toggle("is-selected", selected);
      button.setAttribute("aria-selected", selected ? "true" : "false");
      if (selected) selectedOption = button;
    });
    if (!selectedOption || !optionsPanel) return;
    requestAnimationFrame(() => {
      const centeredTop = selectedOption.offsetTop
        - Math.max(0, (optionsPanel.clientHeight - selectedOption.offsetHeight) / 2);
      optionsPanel.scrollTop = Math.max(0, centeredTop);
    });
  }

  function isChecked(value) {
    if (value === true || value === 1) return true;
    const normalized = String(value || "").trim().toLowerCase();
    if (!normalized || ["нет", "не", "false", "0", "off"].includes(normalized)) return false;
    return true;
  }

  function getStoredCheckboxValue(configId, fieldKey, checked) {
    if (!checked) return "";
    if (
      (configId === "students" && fieldKey === "documentsStatus")
      || (configId === "generalExpenses" && fieldKey === "accountingClosed")
    ) return "+";
    return "Да";
  }

  function paymentRowHasData(record, index) {
    return Boolean(record[`payment${index}Date`] || record[`payment${index}Amount`] || record[`payment${index}Note`]);
  }

  function getOpenPaymentRowIndexes() {
    return (state.openPaymentRows || [])
      .map((value) => Number(value))
      .filter((value) => Number.isInteger(value) && value >= 1 && value <= 8);
  }

  function getVisiblePaymentRowIndexes(record) {
    const openRows = new Set(getOpenPaymentRowIndexes());
    return Array.from({ length: 8 }, (_, index) => index + 1)
      .filter((index) => paymentRowHasData(record, index) || openRows.has(index));
  }

  function getNextAvailablePaymentRowIndex(record) {
    const openRows = new Set(getOpenPaymentRowIndexes());
    const hasOpenEmptyRow = [...openRows].some((index) => !paymentRowHasData(record, index));
    if (hasOpenEmptyRow) return "";
    return Array.from({ length: 8 }, (_, index) => index + 1)
      .find((index) => !paymentRowHasData(record, index) && !openRows.has(index)) || "";
  }

  function renderFinanceRowDragHandle(label, options = {}) {
    const disabled = Boolean(options.disabled);
    return `
      <button
        class="finance-row-drag-handle"
        data-finance-row-drag
        draggable="${disabled ? "false" : "true"}"
        type="button"
        title="${escapeAttr(disabled ? label : "Перетащите строку")}"
        aria-label="${escapeAttr(label)}"
        ${disabled ? "disabled" : ""}
      >
        <span></span><span></span><span></span><span></span><span></span><span></span>
      </button>
    `;
  }

  function renderPaymentRows(record) {
    const rowIndexes = getVisiblePaymentRowIndexes(record);
    const nextPaymentRow = getNextAvailablePaymentRowIndex(record);
    return `
      <section class="form-section">
        <div class="payment-section-head">
          <h3>Оплаты слушателя</h3>
          <button class="ghost-button payment-add-button" data-action="add-payment-row" type="button" ${nextPaymentRow ? "" : "disabled"}>Добавить</button>
        </div>
        ${rowIndexes.length ? `<div class="editable-grid payment-grid" data-student-finance-grid="payments">
          <div class="editable-grid-head">№</div>
          <div class="editable-grid-head">Дата</div>
          <div class="editable-grid-head">Сумма</div>
          <div class="editable-grid-head">Примечание</div>
          <div class="editable-grid-head"></div>
          ${rowIndexes.map((n) => {
            const hasPayment = paymentRowHasData(record, n);
            return `
              <div class="editable-grid-row payment-grid-row" data-student-finance-row data-finance-row-key="${n}">
                <div class="editable-grid-cell row-number-cell finance-row-number-cell" data-label="№">
                  ${renderFinanceRowDragHandle(`Перетащить оплату ${n}`)}
                  <strong class="editable-grid-row-number" data-finance-row-number>${n}</strong>
                </div>
                <label class="editable-grid-cell" data-label="Дата">
                  <input name="payment${n}Date" data-payment-index="${n}" type="date" value="${escapeAttr(record[`payment${n}Date`] || "")}">
                </label>
                <label class="editable-grid-cell" data-label="Сумма">
                  <input name="payment${n}Amount" data-payment-index="${n}" data-money-input type="number" step="${MONEY_INPUT_STEP}" value="${escapeAttr(record[`payment${n}Amount`] || "")}">
                </label>
                <label class="editable-grid-cell" data-label="Примечание">
                  <input name="payment${n}Note" data-payment-index="${n}" value="${escapeAttr(record[`payment${n}Note`] || "")}">
                </label>
                <div class="editable-grid-cell row-action-cell" data-label="Удалить">
                  <button
                    class="payment-row-delete"
                    data-action="delete-payment-row"
                    data-payment-index="${n}"
                    type="button"
                    title="Удалить оплату"
                    aria-label="Удалить оплату ${n}"
                    ${hasPayment ? "" : "disabled"}
                  >
                    <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">
                      <path d="M3 6h18"></path>
                      <path d="M8 6V4h8v2"></path>
                      <path d="M6 6l1 15h10l1-15"></path>
                      <path d="M10 11v6"></path>
                      <path d="M14 11v6"></path>
                    </svg>
                  </button>
                </div>
              </div>
            `;
          }).join("")}
        </div>` : `<p class="payment-empty">Оплаты пока не добавлены.</p>`}
      </section>
    `;
  }

  function getPaymentRowInputs(index) {
    return ["Date", "Amount", "Note"]
      .map((suffix) => document.querySelector(`[name="payment${index}${suffix}"]`))
      .filter(Boolean);
  }

  function syncPaymentRowDeleteButton(index) {
    const button = document.querySelector(`[data-action='delete-payment-row'][data-payment-index="${index}"]`);
    if (!button) return;
    button.disabled = !getPaymentRowInputs(index).some((input) => String(input.value || "").trim());
  }

  function syncPaymentAddButton() {
    const button = document.querySelector("[data-action='add-payment-row']");
    if (!button) return;
    const draft = collectStudentFormDraft();
    button.disabled = !getNextAvailablePaymentRowIndex(draft);
  }

  function syncStudentFinanceFields() {
    const form = document.getElementById("recordForm");
    if (!form || form.dataset.config !== "students") return;
    const values = calculateStudentFinance(collectStudentFormDraft());
    (values.directExpenses || []).forEach((expense, index) => {
      if (!isAutomaticProgramAuthorExpense(expense)) return;
      const amountInput = form.elements[`directExpense${index}Amount`];
      if (amountInput instanceof HTMLInputElement) amountInput.value = String(expense.amount ?? 0);
    });
    const expenses = Math.round(sumStudentExpenses(values) * 100) / 100;
    const financialResult = Math.round((values.paidAmount - expenses) * 100) / 100;
    ["paidAmount", "balance"].forEach((fieldName) => {
      const input = form.elements[fieldName];
      if (input instanceof HTMLInputElement) input.value = String(values[fieldName] ?? 0);
    });
    const paymentsOutput = document.querySelector("[data-student-finance-payments]");
    const expensesOutput = document.querySelector("[data-student-finance-expenses]");
    const resultOutput = document.querySelector("[data-student-finance-result]");
    const resultCard = document.querySelector("[data-student-finance-result-card]");
    if (paymentsOutput) paymentsOutput.textContent = money(values.paidAmount);
    if (expensesOutput) expensesOutput.textContent = money(expenses);
    if (resultOutput) resultOutput.textContent = money(financialResult);
    resultCard?.classList.toggle("is-positive", financialResult > 0);
    resultCard?.classList.toggle("is-negative", financialResult < 0);
    resultCard?.classList.toggle("is-neutral", financialResult === 0);
    if (state.modal) {
      state.modal.draft = { ...(state.modal.draft || {}), ...values, expenseTotal: expenses };
      state.modal.hasDraftChanges = true;
    }
  }

  function compactStudentPayments(record, deletedIndex) {
    const payments = Array.from({ length: 8 }, (_, index) => index + 1)
      .filter((index) => index !== Number(deletedIndex))
      .map((index) => ({
        date: record[`payment${index}Date`] || "",
        amount: record[`payment${index}Amount`] || "",
        note: record[`payment${index}Note`] || ""
      }))
      .filter((payment) => payment.date || payment.amount || payment.note);
    Array.from({ length: 8 }, (_, index) => index + 1).forEach((index) => {
      const payment = payments[index - 1] || {};
      record[`payment${index}Date`] = payment.date || "";
      record[`payment${index}Amount`] = payment.amount || "";
      record[`payment${index}Note`] = payment.note || "";
    });
    return record;
  }

  function clearStudentPaymentRow(index) {
    const inputs = getPaymentRowInputs(index);
    if (!inputs.length || !inputs.some((input) => String(input.value || "").trim())) return;
    if (!confirm("Удалить запись оплаты?")) return;
    if (state.modal) {
      state.modal.draft = calculateStudentFinance(compactStudentPayments(collectStudentFormDraft(), index));
      state.modal.hasDraftChanges = true;
    }
    state.openPaymentRows = [];
    render();
  }

  function addStudentPaymentRow() {
    if (!state.modal) return;
    const draft = collectStudentFormDraft();
    const nextIndex = getNextAvailablePaymentRowIndex(draft);
    if (!nextIndex) return;
    state.modal.draft = {
      ...draft,
      [`payment${nextIndex}Date`]: formatOrdersSdoDate(new Date())
    };
    state.modal.hasDraftChanges = true;
    state.openPaymentRows = unique([...getOpenPaymentRowIndexes(), nextIndex]);
    render();
    requestAnimationFrame(() => {
      document.querySelector(`[name="payment${nextIndex}Amount"]`)?.focus({ preventScroll: true });
    });
  }

  function getStudentExpenseTypeOptions(record = {}) {
    const inventoryRows = state.data.collections.inventory || [];
    const studentTypes = (state.data.collections.students || []).flatMap((student) => (
      Array.from({ length: 6 }, (_, index) => student[`expense${index + 1}Type`])
    ));
    const currentTypes = Array.from({ length: 6 }, (_, index) => record[`expense${index + 1}Type`]);
    return unique([
      ...(state.data.dictionaries.expenseTypes || []),
      ...(state.data.dictionaries.inventoryTypes || []),
      ...studentTypes,
      ...currentTypes,
      ...(state.data.collections.students || []).flatMap((student) => (
        Array.isArray(student.directExpenses) ? student.directExpenses.map((expense) => expense.type) : []
      )),
      ...(state.data.collections.directExpenses || []).map((expense) => expense.type),
      ...(state.data.collections.generalExpenses || []).map((expense) => expense.workType),
      ...inventoryRows.flatMap((item) => [item.itemType, item.note])
    ].map((value) => String(value || "").trim()).filter(Boolean));
  }

  function getInventoryBalance(item) {
    const balance = Number(item?.balance || 0);
    return Number.isFinite(balance) ? Math.max(0, balance) : 0;
  }

  function findInventoryItemById(id) {
    const inventoryId = String(id || "").trim();
    if (!inventoryId) return null;
    return (state.data.collections.inventory || []).find((item) => String(item.id || "") === inventoryId) || null;
  }

  function getStudentExpenseInventoryOptions(selectedId = "") {
    const currentId = String(selectedId || "").trim();
    return (state.data.collections.inventory || [])
      .filter((item) => (
        String(item.id || "").trim()
        && String(item.itemType || "").trim()
        && (getInventoryBalance(item) > 0 || String(item.id || "") === currentId)
      ))
      .slice()
      .sort((left, right) => (
        String(left.itemType || "").localeCompare(String(right.itemType || ""), "ru", {
          numeric: true,
          sensitivity: "base"
        })
        || String(left.date || "").localeCompare(String(right.date || ""))
        || String(left.id || "").localeCompare(String(right.id || ""))
      ));
  }

  function formatStudentExpenseInventoryOption(item) {
    const details = [
      Number(item?.amount || 0) ? money(Number(item.amount)) : "",
      `остаток: ${pieces(getInventoryBalance(item))}`,
      String(item?.note || "").trim()
    ].filter(Boolean);
    return `[Запас] ${String(item?.itemType || "").trim()}${details.length ? ` · ${details.join(" · ")}` : ""}`;
  }

  function renderStudentExpenseTypeSelect({
    prefix,
    type,
    inventoryId,
    inventoryLink,
    typeOptions,
    index,
    direct = false,
    editor = false,
    disabled = false
  }) {
    const selectedInventoryId = String(inventoryId || "").trim();
    const inventoryOptions = getStudentExpenseInventoryOptions(selectedInventoryId);
    const selectedInventory = inventoryOptions.find((item) => String(item.id || "") === selectedInventoryId);
    const dataIndex = editor
      ? "data-student-expense-editor-type"
      : direct
        ? `data-direct-expense-index="${index}"`
        : `data-expense-index="${index}"`;
    const missingInventoryOption = selectedInventoryId && !selectedInventory
      ? `<option value="inventory:${escapeAttr(selectedInventoryId)}" data-inventory-id="${escapeAttr(selectedInventoryId)}" selected>[Запас недоступен] ${escapeHtml(inventoryLink || type || selectedInventoryId)}</option>`
      : "";
    return `
      <select
        name="${prefix}InventoryChoice"
        ${dataIndex}
        data-student-expense-inventory-choice
        data-expense-prefix="${escapeAttr(prefix)}"
        data-settings-dictionary="expenseTypes"
        aria-label="Вид затрат или запас"
        ${disabled ? "disabled" : ""}
      >
        <option value=""></option>
        <optgroup label="Виды затрат">
          ${typeOptions.map((option, optionIndex) => `
            <option
              value="type:${optionIndex}"
              data-expense-type="${escapeAttr(option)}"
              ${!selectedInventoryId && option === type ? "selected" : ""}
            >${escapeHtml(option)}</option>
          `).join("")}
        </optgroup>
        ${inventoryOptions.length || missingInventoryOption ? `
          <optgroup label="Запасы">
            ${missingInventoryOption}
            ${inventoryOptions.map((item) => {
              const itemId = String(item.id || "");
              const selected = itemId === selectedInventoryId;
              return `
                <option
                  value="inventory:${escapeAttr(itemId)}"
                  data-inventory-id="${escapeAttr(itemId)}"
                  ${selected ? "selected" : ""}
                  ${!selected && getInventoryBalance(item) <= 0 ? "disabled" : ""}
                >${escapeHtml(formatStudentExpenseInventoryOption(item))}</option>
              `;
            }).join("")}
          </optgroup>
        ` : ""}
      </select>
      <input name="${prefix}Type" type="hidden" value="${escapeAttr(type || "")}">
      <input name="${prefix}InventoryId" type="hidden" value="${escapeAttr(selectedInventoryId)}">
      <input name="${prefix}InventoryLink" type="hidden" value="${escapeAttr(inventoryLink || selectedInventory?.itemType || "")}">
    `;
  }

  function applyStudentExpenseInventoryChoice(select, options = {}) {
    const prefix = String(select?.dataset.expensePrefix || "").trim();
    const form = select?.form;
    if (!prefix || !form) return;
    const option = select.selectedOptions?.[0];
    const inventoryIdInput = form.elements[`${prefix}InventoryId`];
    const inventoryLinkInput = form.elements[`${prefix}InventoryLink`];
    const typeInput = form.elements[`${prefix}Type`];
    const amountInput = form.elements[`${prefix}Amount`];
    const inventoryId = String(option?.dataset.inventoryId || "").trim();
    if (inventoryId) {
      const inventoryItem = findInventoryItemById(inventoryId);
      if (!inventoryItem) return;
      const previousInventoryId = String(inventoryIdInput?.value || "").trim();
      if (inventoryId !== previousInventoryId && getInventoryBalance(inventoryItem) <= 0) {
        alert("Эта позиция запаса закончилась.");
        select.value = previousInventoryId ? `inventory:${previousInventoryId}` : "";
        return;
      }
      if (typeInput) typeInput.value = String(inventoryItem.itemType || "");
      if (inventoryIdInput) inventoryIdInput.value = inventoryId;
      if (inventoryLinkInput) inventoryLinkInput.value = String(inventoryItem.itemType || "");
      if (amountInput) amountInput.value = String(normalizeOptionalNumber(inventoryItem.amount) || 0);
    } else {
      if (typeInput) typeInput.value = String(option?.dataset.expenseType || "");
      if (inventoryIdInput) inventoryIdInput.value = "";
      if (inventoryLinkInput) inventoryLinkInput.value = "";
    }
    if (options.syncFinance !== false) syncStudentFinanceFields();
  }

  function getStudentInventoryAllocationCounts(record = {}) {
    const counts = new Map();
    const add = (inventoryId) => {
      const id = String(inventoryId || "").trim();
      if (id) counts.set(id, (counts.get(id) || 0) + 1);
    };
    Array.from({ length: 6 }, (_, index) => index + 1).forEach((index) => {
      if (expenseRowHasData(record, index)) add(record[`expense${index}InventoryId`]);
    });
    (Array.isArray(record.directExpenses) ? record.directExpenses : []).forEach((expense) => {
      add(expense?.inventoryId);
    });
    return counts;
  }

  function applyStudentInventoryAllocationChanges(previousRecord = {}, nextRecord = {}) {
    const previousCounts = getStudentInventoryAllocationCounts(previousRecord);
    const nextCounts = getStudentInventoryAllocationCounts(nextRecord);
    const ids = new Set([...previousCounts.keys(), ...nextCounts.keys()]);
    const changes = [...ids].map((id) => ({
      id,
      delta: (nextCounts.get(id) || 0) - (previousCounts.get(id) || 0)
    })).filter((change) => change.delta);
    for (const change of changes) {
      if (change.delta <= 0) continue;
      const item = findInventoryItemById(change.id);
      if (!item) {
        alert("Выбранная позиция запаса больше не существует. Обновите строку расхода.");
        return false;
      }
      if (getInventoryBalance(item) < change.delta) {
        alert(`Недостаточно запаса «${item.itemType || change.id}». Доступно: ${getInventoryBalance(item)}.`);
        return false;
      }
    }
    changes.forEach((change) => {
      const item = findInventoryItemById(change.id);
      if (!item) return;
      item.balance = Math.max(0, getInventoryBalance(item) - change.delta);
    });
    return true;
  }

  function getInventoryAllocationCount(inventoryId) {
    const id = String(inventoryId || "").trim();
    if (!id) return 0;
    const studentCount = (state.data.collections.students || []).reduce((total, student) => (
      total + (getStudentInventoryAllocationCounts(student).get(id) || 0)
    ), 0);
    const unlinkedCount = (state.data.collections.directExpenses || [])
      .filter((expense) => String(expense?.inventoryId || "").trim() === id)
      .length;
    return studentCount + unlinkedCount;
  }

  function getStudentExpenseNoteOptions(record = {}) {
    const studentNotes = (state.data.collections.students || []).flatMap((student) => (
      Array.from({ length: 6 }, (_, index) => student[`expense${index + 1}Note`])
    ));
    const currentNotes = Array.from({ length: 6 }, (_, index) => record[`expense${index + 1}Note`]);
    const directExpenseNotes = (state.data.collections.directExpenses || []).map((expense) => expense.note);
    const linkedDirectExpenseNotes = (state.data.collections.students || []).flatMap((student) => (
      Array.isArray(student.directExpenses) ? student.directExpenses.map((expense) => expense.note) : []
    ));
    const generalExpenseNotes = (state.data.collections.generalExpenses || [])
      .flatMap((expense) => [expense.description, expense.otherExpenses]);
    return unique([
      ...(state.data.dictionaries.expenseNotes || []),
      ...studentNotes,
      ...currentNotes,
      ...directExpenseNotes,
      ...linkedDirectExpenseNotes,
      ...generalExpenseNotes
    ].map((value) => String(value || "").trim()).filter(Boolean))
      .sort((a, b) => a.localeCompare(b, "ru", { numeric: true, sensitivity: "base" }));
  }

  function expenseRowHasData(record, index) {
    return Boolean(
      record[`expense${index}Date`] ||
      record[`expense${index}Type`] ||
      record[`expense${index}Amount`] ||
      record[`expense${index}Note`] ||
      record[`expense${index}InventoryId`]
    );
  }

  function getOpenExpenseRowIndexes() {
    return (state.openExpenseRows || [])
      .map((value) => Number(value))
      .filter((value) => Number.isInteger(value) && value >= 1 && value <= 6);
  }

  function getVisibleExpenseRowIndexes(record) {
    const openRows = new Set(getOpenExpenseRowIndexes());
    return Array.from({ length: 6 }, (_, index) => index + 1)
      .filter((index) => expenseRowHasData(record, index) || openRows.has(index));
  }

  function getNextAvailableExpenseRowIndex(record) {
    const openRows = new Set(getOpenExpenseRowIndexes());
    const hasOpenEmptyRow = [...openRows].some((index) => !expenseRowHasData(record, index));
    if (hasOpenEmptyRow) return "";
    return Array.from({ length: 6 }, (_, index) => index + 1)
      .find((index) => !expenseRowHasData(record, index) && !openRows.has(index)) || "";
  }

  function renderExpenseRows(record) {
    const typeOptions = getStudentExpenseTypeOptions(record);
    const noteOptions = getStudentExpenseNoteOptions(record);
    const manualRowIndexes = getVisibleExpenseRowIndexes(record);
    const directExpenses = Array.isArray(record.directExpenses) ? record.directExpenses : [];
    const rowCount = manualRowIndexes.length + directExpenses.length;
    return `
      <section class="form-section">
        <div class="payment-section-head">
          <h3>Расходы</h3>
          <div class="payment-section-actions">
            <button class="ghost-button payment-add-button" data-action="add-typical-expenses" type="button">Добавить типовые расходы</button>
            <button class="ghost-button payment-add-button" data-action="add-expense-row" type="button">Добавить</button>
          </div>
        </div>
        ${rowCount ? `<div class="editable-grid expense-grid" data-student-finance-grid="expenses">
          <div class="editable-grid-head">№</div>
          <div class="editable-grid-head">Дата</div>
          <div class="editable-grid-head">Вид затрат</div>
          <div class="editable-grid-head">Сумма</div>
          <div class="editable-grid-head">Примечание</div>
          <div class="editable-grid-head"></div>
          ${manualRowIndexes.map((n, rowIndex) => {
            const type = record[`expense${n}Type`] || "";
            const hasExpense = expenseRowHasData(record, n);
            const editLabel = `Редактировать расход ${rowIndex + 1}: ${type || "вид не указан"}, ${money(record[`expense${n}Amount`] || 0)}`;
            return `
              <div class="editable-grid-row expense-grid-row" data-student-finance-row data-finance-row-key="manual-${n}">
                <div class="editable-grid-cell row-number-cell finance-row-number-cell" data-label="№">
                  ${renderFinanceRowDragHandle(`Перетащить расход ${rowIndex + 1}`)}
                  <strong class="editable-grid-row-number" data-finance-row-number>${rowIndex + 1}</strong>
                </div>
                <label class="editable-grid-cell" data-label="Дата">
                  <input name="expense${n}Date" data-expense-index="${n}" type="date" value="${escapeAttr(record[`expense${n}Date`] || "")}">
                </label>
                <label class="editable-grid-cell" data-label="Вид затрат">
                  ${renderStudentExpenseTypeSelect({
                    prefix: `expense${n}`,
                    type,
                    inventoryId: record[`expense${n}InventoryId`],
                    inventoryLink: record[`expense${n}InventoryLink`],
                    typeOptions,
                    index: n
                  })}
                </label>
                <label class="editable-grid-cell" data-label="Сумма">
                  <input name="expense${n}Amount" data-expense-index="${n}" data-money-input type="number" step="${MONEY_INPUT_STEP}" value="${escapeAttr(record[`expense${n}Amount`] || "")}">
                </label>
                <div class="editable-grid-cell expense-note-cell" data-label="Примечание">
                  ${renderComboField({
                    name: `expense${n}Note`,
                    type: "search",
                    value: record[`expense${n}Note`] || "",
                    options: noteOptions,
                    dictionary: "expenseNotes",
                    attrs: `data-expense-index="${n}"`
                  })}
                </div>
                <div class="editable-grid-cell row-action-cell expense-row-actions" data-label="Действия">
                  <button
                    class="student-expense-edit-button"
                    data-action="edit-student-expense"
                    data-expense-index="${n}"
                    data-expense-row-number="${rowIndex + 1}"
                    type="button"
                    title="Редактировать расход во всплывающем окне"
                    aria-label="${escapeAttr(editLabel)}"
                    ${hasExpense ? "" : "disabled"}
                  >
                    <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">
                      <path d="M4 20h4l11-11-4-4L4 16v4z"></path>
                      <path d="M13.5 6.5l4 4"></path>
                    </svg>
                  </button>
                  <button
                    class="payment-row-duplicate"
                    data-action="duplicate-expense-row"
                    data-expense-index="${n}"
                    type="button"
                    title="Дублировать расход с текущей датой"
                    aria-label="Дублировать расход ${n} с текущей датой"
                    ${hasExpense ? "" : "disabled"}
                  >
                    <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">
                      <rect x="8" y="8" width="11" height="11" rx="2"></rect>
                      <path d="M16 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h3"></path>
                    </svg>
                  </button>
                  <button
                    class="payment-row-delete"
                    data-action="delete-expense-row"
                    data-expense-index="${n}"
                    type="button"
                    title="Удалить расход"
                    aria-label="Удалить расход ${n}"
                    ${hasExpense ? "" : "disabled"}
                  >
                    <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">
                      <path d="M3 6h18"></path>
                      <path d="M8 6V4h8v2"></path>
                      <path d="M6 6l1 15h10l1-15"></path>
                      <path d="M10 11v6"></path>
                      <path d="M14 11v6"></path>
                    </svg>
                  </button>
                </div>
              </div>
            `;
          }).join("")}
          ${directExpenses.map((expense, index) => {
            const rowNumber = manualRowIndexes.length + index + 1;
            const type = expense.type || "";
            const editLabel = `Редактировать расход ${rowNumber}: ${type || "вид не указан"}, ${money(expense.amount || 0)}`;
            return `
              <div class="editable-grid-row expense-grid-row" data-student-finance-row data-finance-row-key="direct-${index}">
                <div class="editable-grid-cell row-number-cell finance-row-number-cell" data-label="№">
                  ${renderFinanceRowDragHandle(`Перетащить расход ${rowNumber}`)}
                  <strong class="editable-grid-row-number" data-finance-row-number>${rowNumber}</strong>
                </div>
                <label class="editable-grid-cell" data-label="Дата">
                  <input name="directExpense${index}Date" data-direct-expense-index="${index}" type="date" value="${escapeAttr(expense.date || "")}">
                </label>
                <label class="editable-grid-cell" data-label="Вид затрат">
                  ${renderStudentExpenseTypeSelect({
                    prefix: `directExpense${index}`,
                    type,
                    inventoryId: expense.inventoryId,
                    inventoryLink: expense.inventoryLink,
                    typeOptions,
                    index,
                    direct: true
                  })}
                </label>
                <label class="editable-grid-cell" data-label="Сумма">
                  <input name="directExpense${index}Amount" data-direct-expense-index="${index}" data-money-input type="number" step="${MONEY_INPUT_STEP}" value="${escapeAttr(expense.amount || "")}">
                </label>
                <div class="editable-grid-cell expense-note-cell" data-label="Примечание">
                  ${renderComboField({
                    name: `directExpense${index}Note`,
                    type: "search",
                    value: expense.note || "",
                    options: noteOptions,
                    dictionary: "expenseNotes",
                    attrs: `data-direct-expense-index="${index}"`
                  })}
                </div>
                <div class="editable-grid-cell row-action-cell expense-row-actions" data-label="Действия">
                  <button
                    class="student-expense-edit-button"
                    data-action="edit-student-expense"
                    data-direct-expense-index="${index}"
                    data-direct-expense-id="${escapeAttr(expense.id || "")}"
                    data-expense-row-number="${rowNumber}"
                    type="button"
                    title="Редактировать расход во всплывающем окне"
                    aria-label="${escapeAttr(editLabel)}"
                  >
                    <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">
                      <path d="M4 20h4l11-11-4-4L4 16v4z"></path>
                      <path d="M13.5 6.5l4 4"></path>
                    </svg>
                  </button>
                  <button
                    class="payment-row-duplicate"
                    data-action="duplicate-direct-expense-row"
                    data-direct-expense-index="${index}"
                    type="button"
                    title="Дублировать расход с текущей датой"
                    aria-label="Дублировать расход ${rowNumber} с текущей датой"
                  >
                    <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">
                      <rect x="8" y="8" width="11" height="11" rx="2"></rect>
                      <path d="M16 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h3"></path>
                    </svg>
                  </button>
                  <button
                    class="payment-row-delete"
                    data-action="delete-direct-expense-row"
                    data-direct-expense-index="${index}"
                    type="button"
                    title="Удалить расход"
                    aria-label="Удалить расход ${rowNumber}"
                  >
                    <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">
                      <path d="M3 6h18"></path>
                      <path d="M8 6V4h8v2"></path>
                      <path d="M6 6l1 15h10l1-15"></path>
                      <path d="M10 11v6"></path>
                      <path d="M14 11v6"></path>
                    </svg>
                  </button>
                </div>
              </div>
            `;
          }).join("")}
        </div>` : `<p class="payment-empty">Расходы пока не добавлены.</p>`}
      </section>
    `;
  }

  function findStudentExpenseEditorDirectIndex(record = {}, editor = {}) {
    const directExpenses = Array.isArray(record.directExpenses) ? record.directExpenses : [];
    const sourceId = String(editor.id || "").trim();
    if (sourceId) {
      return directExpenses.findIndex((expense) => String(expense?.id || "").trim() === sourceId);
    }
    const fallbackIndex = Number(editor.fallbackIndex);
    return Number.isInteger(fallbackIndex) && fallbackIndex >= 0 && fallbackIndex < directExpenses.length
      ? fallbackIndex
      : -1;
  }

  function getStudentExpenseEditorContext() {
    const editor = state.studentExpenseEditor;
    const draft = state.modal?.config === "students" && state.modal?.draft
      ? state.modal.draft
      : null;
    if (!editor || !draft) return null;
    const kind = String(editor.kind || "");
    const rowNumber = Math.max(1, Number(editor.rowNumber) || 1);
    if (kind === "manual") {
      const slot = Number(editor.slot);
      if (!Number.isInteger(slot) || slot < 1 || slot > 6 || !expenseRowHasData(draft, slot)) return null;
      return {
        editor,
        draft,
        kind,
        slot,
        rowNumber,
        expense: {
          date: draft[`expense${slot}Date`] || "",
          type: draft[`expense${slot}Type`] || "",
          amount: draft[`expense${slot}Amount`] ?? "",
          note: draft[`expense${slot}Note`] || "",
          inventoryId: draft[`expense${slot}InventoryId`] || "",
          inventoryLink: draft[`expense${slot}InventoryLink`] || ""
        }
      };
    }
    if (kind !== "direct") return null;
    const directIndex = findStudentExpenseEditorDirectIndex(draft, editor);
    const expense = directIndex >= 0 ? draft.directExpenses[directIndex] : null;
    if (!expense) return null;
    return { editor, draft, kind, directIndex, rowNumber, expense };
  }

  function applyStudentExpenseEditorValues(record = {}, editor = {}, values = {}) {
    const normalizedValues = {
      date: String(values.date || ""),
      type: String(values.type || ""),
      amount: Number(values.amount || 0),
      note: String(values.note || ""),
      inventoryId: String(values.inventoryId || ""),
      inventoryLink: String(values.inventoryLink || "")
    };
    if (String(editor.kind || "") === "manual") {
      const slot = Number(editor.slot);
      if (!Number.isInteger(slot) || slot < 1 || slot > 6) return record;
      return {
        ...record,
        [`expense${slot}Date`]: normalizedValues.date,
        [`expense${slot}Type`]: normalizedValues.type,
        [`expense${slot}Amount`]: normalizedValues.amount,
        [`expense${slot}Note`]: normalizedValues.note,
        [`expense${slot}InventoryId`]: normalizedValues.inventoryId,
        [`expense${slot}InventoryLink`]: normalizedValues.inventoryLink
      };
    }
    if (String(editor.kind || "") !== "direct") return record;
    const directExpenses = Array.isArray(record.directExpenses) ? record.directExpenses : [];
    const sourceId = String(editor.id || "").trim();
    const fallbackIndex = Number(editor.fallbackIndex);
    const directIndex = sourceId
      ? directExpenses.findIndex((expense) => String(expense?.id || "").trim() === sourceId)
      : (Number.isInteger(fallbackIndex) && fallbackIndex >= 0 && fallbackIndex < directExpenses.length
        ? fallbackIndex
        : -1);
    if (directIndex < 0) return record;
    return {
      ...record,
      directExpenses: directExpenses.map((expense, index) => (
        index === directIndex ? { ...expense, ...normalizedValues } : expense
      ))
    };
  }

  function renderStudentExpenseEditor() {
    const context = getStudentExpenseEditorContext();
    if (!context) {
      return `
        <div class="modal-backdrop student-expense-editor-backdrop" data-student-expense-editor data-action="close-student-expense-editor">
          <section class="modal student-expense-editor" role="dialog" aria-modal="true" aria-labelledby="student-expense-editor-title">
            <header class="modal-head">
              <div><h2 id="student-expense-editor-title">Запись расхода не найдена</h2></div>
              <button class="icon-button" data-action="close-student-expense-editor" type="button" title="Закрыть" aria-label="Закрыть">×</button>
            </header>
            <div class="student-expense-editor-missing">Строка была удалена или перемещена.</div>
          </section>
        </div>
      `;
    }
    const { draft, expense, rowNumber } = context;
    const typeOptions = getStudentExpenseTypeOptions(draft);
    const noteOptions = getStudentExpenseNoteOptions(draft);
    const automaticHint = isAutomaticProgramAuthorExpense(expense)
      ? "Вид, сумма и получатель этого автоматического расхода пересчитываются по формуле образовательной программы."
      : "";
    return `
      <div class="modal-backdrop student-expense-editor-backdrop" data-student-expense-editor data-action="close-student-expense-editor">
        <section class="modal student-expense-editor" role="dialog" aria-modal="true" aria-labelledby="student-expense-editor-title">
          <form id="studentExpenseEditorForm">
            <header class="modal-head">
              <div>
                <p class="eyebrow">Расходы слушателя</p>
                <h2 id="student-expense-editor-title">Редактирование расхода</h2>
                <p>${escapeHtml(draft.name || "Слушатель")} · строка № ${rowNumber}</p>
              </div>
              <button class="icon-button" data-action="close-student-expense-editor" type="button" title="Закрыть" aria-label="Закрыть">×</button>
            </header>
            <div class="form-grid student-expense-editor-grid">
              <label data-field-key="studentExpenseEditorDate">
                <span>Дата</span>
                <input name="studentExpenseEditorDate" type="date" value="${escapeAttr(expense.date || "")}">
              </label>
              <label data-field-key="studentExpenseEditorAmount">
                <span>Сумма</span>
                <input name="studentExpenseEditorAmount" data-money-input type="number" step="${MONEY_INPUT_STEP}" value="${escapeAttr(expense.amount ?? "")}">
              </label>
              <label class="student-expense-editor-wide" data-field-key="studentExpenseEditorType">
                <span>Вид затрат или запас</span>
                ${renderStudentExpenseTypeSelect({
                  prefix: "studentExpenseEditor",
                  type: expense.type,
                  inventoryId: expense.inventoryId,
                  inventoryLink: expense.inventoryLink,
                  typeOptions,
                  index: context.kind === "manual" ? context.slot : context.directIndex,
                  direct: context.kind === "direct",
                  editor: true
                })}
              </label>
              <label class="student-expense-editor-wide" data-field-key="studentExpenseEditorNote">
                <span>Примечание</span>
                ${renderComboField({
                  name: "studentExpenseEditorNote",
                  type: "search",
                  value: expense.note || "",
                  options: noteOptions,
                  dictionary: "expenseNotes",
                  attrs: 'data-student-expense-editor-note'
                })}
              </label>
              ${automaticHint ? `<p class="student-expense-editor-hint">${escapeHtml(automaticHint)}</p>` : ""}
            </div>
            <footer class="modal-actions student-expense-editor-actions">
              <button class="ghost-button" data-action="close-student-expense-editor" type="button">Отмена</button>
              <button class="primary-button" type="submit">Сохранить расход</button>
            </footer>
          </form>
        </section>
      </div>
    `;
  }

  function getExpenseRowInputs(index) {
    return ["Date", "Type", "Amount", "IsPaid", "Note"]
      .map((suffix) => document.querySelector(`[name="expense${index}${suffix}"]`))
      .filter(Boolean);
  }

  function syncExpenseRowDeleteButton(index) {
    const button = document.querySelector(`[data-action='delete-expense-row'][data-expense-index="${index}"]`);
    if (!button) return;
    const draft = collectStudentFormDraft();
    button.disabled = !expenseRowHasData(draft, Number(index));
  }

  function syncExpenseAddButton() {
    const button = document.querySelector("[data-action='add-expense-row']");
    if (!button) return;
    button.disabled = false;
  }

  function compactStudentExpenses(record, deletedIndex) {
    const expenses = Array.from({ length: 6 }, (_, index) => index + 1)
      .filter((index) => index !== Number(deletedIndex))
      .map((index) => ({
        date: record[`expense${index}Date`] || "",
        type: record[`expense${index}Type`] || "",
        amount: record[`expense${index}Amount`] || "",
        isPaid: record[`expense${index}IsPaid`] || "",
        note: record[`expense${index}Note`] || "",
        inventoryId: record[`expense${index}InventoryId`] || "",
        inventoryLink: record[`expense${index}InventoryLink`] || ""
      }))
      .filter((expense) => (
        expense.date
        || expense.type
        || expense.amount
        || isChecked(expense.isPaid)
        || expense.note
        || expense.inventoryId
      ));
    Array.from({ length: 6 }, (_, index) => index + 1).forEach((index) => {
      const expense = expenses[index - 1] || {};
      record[`expense${index}Date`] = expense.date || "";
      record[`expense${index}Type`] = expense.type || "";
      record[`expense${index}Amount`] = expense.amount || "";
      record[`expense${index}IsPaid`] = expense.isPaid || "";
      record[`expense${index}Note`] = expense.note || "";
      record[`expense${index}InventoryId`] = expense.inventoryId || "";
      record[`expense${index}InventoryLink`] = expense.inventoryLink || "";
    });
    return record;
  }

  function clearStudentExpenseRow(index) {
    const inputs = getExpenseRowInputs(index);
    if (!inputs.length || !expenseRowHasData(collectStudentFormDraft(), Number(index))) return;
    if (!confirm("Удалить запись расхода?")) return;
    if (state.modal) {
      const draft = compactStudentExpenses(collectStudentFormDraft(), index);
      state.modal.draft = { ...draft, expenseTotal: sumStudentExpenses(draft) };
      state.modal.hasDraftChanges = true;
    }
    state.openExpenseRows = [];
    render();
  }

  function clearStudentDirectExpenseRow(index) {
    if (!state.modal) return;
    const draft = collectStudentFormDraft();
    const directExpenses = Array.isArray(draft.directExpenses) ? draft.directExpenses : [];
    const expenseIndex = Number(index);
    if (!Number.isInteger(expenseIndex) || !directExpenses[expenseIndex]) return;
    if (!confirm("Удалить запись расхода?")) return;
    const nextDraft = {
      ...draft,
      directExpenses: directExpenses.filter((expense, currentIndex) => currentIndex !== expenseIndex)
    };
    nextDraft.expenseTotal = sumStudentExpenses(nextDraft);
    state.modal.draft = nextDraft;
    state.modal.hasDraftChanges = true;
    render();
  }

  function duplicateStudentExpenseRow(index, direct = false) {
    if (!state.modal) return;
    const draft = collectStudentFormDraft();
    const directExpenses = Array.isArray(draft.directExpenses) ? draft.directExpenses : [];
    const expenseIndex = Number(index);
    const source = direct
      ? directExpenses[expenseIndex]
      : (Number.isInteger(expenseIndex) && expenseRowHasData(draft, expenseIndex)
        ? {
            type: draft[`expense${expenseIndex}Type`] || "",
            amount: draft[`expense${expenseIndex}Amount`] || "",
            isPaid: draft[`expense${expenseIndex}IsPaid`] || "",
            note: draft[`expense${expenseIndex}Note`] || "",
            inventoryId: draft[`expense${expenseIndex}InventoryId`] || "",
            inventoryLink: draft[`expense${expenseIndex}InventoryLink`] || ""
          }
        : null);
    if (!source) return;
    const nextIndex = directExpenses.length;
    const duplicate = {
      ...source,
      id: makeId("direct-expense"),
      uid: draft.uid || source.uid || "",
      date: todayIso()
    };
    state.modal.draft = {
      ...draft,
      directExpenses: [...directExpenses, duplicate]
    };
    state.modal.hasDraftChanges = true;
    render();
    requestAnimationFrame(() => {
      const amountInput = document.querySelector(`[name="directExpense${nextIndex}Amount"]`);
      amountInput?.scrollIntoView({ block: "nearest", inline: "nearest" });
      amountInput?.focus({ preventScroll: true });
      amountInput?.select();
    });
  }

  function addStudentExpenseRow() {
    if (!state.modal) return;
    const draft = collectStudentFormDraft();
    const directExpenses = Array.isArray(draft.directExpenses) ? draft.directExpenses : [];
    const nextIndex = directExpenses.length;
    state.modal.draft = {
      ...draft,
      directExpenses: [
        ...directExpenses,
        {
          id: makeId("direct-expense"),
          uid: draft.uid || "",
          date: formatOrdersSdoDate(new Date()),
          type: "",
          amount: "",
          isPaid: "",
          note: "",
          inventoryId: "",
          inventoryLink: ""
        }
      ]
    };
    state.modal.hasDraftChanges = true;
    render();
    requestAnimationFrame(() => {
      document.querySelector(`[name="directExpense${nextIndex}Amount"]`)?.focus({ preventScroll: true });
    });
  }

  function addStudentTypicalExpenses() {
    if (!state.modal) return;
    const draft = calculateStudentFinance(collectStudentFormDraft());
    const program = findProgramByName(draft.program);
    const result = addAutomaticStudentExpenses(draft, program);
    if (!result.additions.length) {
      alert("Новых типовых расходов не найдено. Проверьте оплаты, настройки программы и уже добавленные расходы.");
      return;
    }
    state.modal.draft = calculateStudentFinance(result.record);
    state.modal.hasDraftChanges = true;
    addAudit(
      "Добавлены типовые расходы",
      draft.name || "Карточка слушателя",
      `${result.additions.length} записей`,
      {
        entityType: "students",
        entityId: String(state.modal?.id || ""),
        entityLabel: draft.name || String(state.modal?.id || "")
      }
    );
    render();
  }

  function getStudentExpenseEditorButtonSelector(editor = {}) {
    if (String(editor.kind || "") === "manual") {
      return `[data-action='edit-student-expense'][data-expense-index="${Number(editor.slot)}"]`;
    }
    const sourceId = String(editor.id || "").trim();
    if (sourceId) {
      return `[data-action='edit-student-expense'][data-direct-expense-id="${CSS.escape(sourceId)}"]`;
    }
    return `[data-action='edit-student-expense'][data-direct-expense-index="${Number(editor.fallbackIndex)}"]`;
  }

  function setStudentExpenseEditorBackgroundInert(inert) {
    const cardBackdrop = document.querySelector("#recordForm[data-config='students']")
      ?.closest(".student-modal-backdrop");
    if (!cardBackdrop) return;
    if (inert) {
      cardBackdrop.setAttribute("inert", "");
      cardBackdrop.setAttribute("aria-hidden", "true");
    } else {
      cardBackdrop.removeAttribute("inert");
      cardBackdrop.removeAttribute("aria-hidden");
    }
  }

  function openStudentExpenseEditor(event) {
    const button = event.target.closest("[data-action='edit-student-expense']");
    if (!button || !state.modal || state.modal.config !== "students") return;
    const recordForm = document.querySelector("#recordForm[data-config='students']");
    if (!recordForm) return;
    state.modal.hasDraftChanges = state.modal.hasDraftChanges || hasUnsavedFormChanges(recordForm);
    state.modal.draft = collectStudentFormDraft();
    const direct = button.hasAttribute("data-direct-expense-index");
    state.studentExpenseEditor = direct
      ? {
          kind: "direct",
          id: String(button.dataset.directExpenseId || ""),
          fallbackIndex: Number(button.dataset.directExpenseIndex),
          rowNumber: Number(button.dataset.expenseRowNumber)
        }
      : {
          kind: "manual",
          slot: Number(button.dataset.expenseIndex),
          rowNumber: Number(button.dataset.expenseRowNumber)
        };
    if (!getStudentExpenseEditorContext()) {
      state.studentExpenseEditor = null;
      alert("Запись расхода не найдена.");
      return;
    }
    document.querySelector("[data-student-expense-editor]")?.remove();
    app.insertAdjacentHTML("beforeend", renderStudentExpenseEditor());
    bindMoneyInputStepControls(document.querySelector("[data-student-expense-editor]"));
    bindStudentExpenseEditorEvents();
    bindComboFieldEvents(document.querySelector("[data-student-expense-editor]"));
    initializeRecordFormSnapshot(document.getElementById("studentExpenseEditorForm"));
    enhanceSettingsLinkedDropdowns();
  }

  function closeStudentExpenseEditor() {
    if (!state.studentExpenseEditor) return;
    const form = document.getElementById("studentExpenseEditorForm");
    if (hasUnsavedFormChanges(form) && !confirm("Есть несохранённые изменения расхода. Закрыть без сохранения?")) return;
    const editor = { ...state.studentExpenseEditor };
    state.studentExpenseEditor = null;
    setStudentExpenseEditorBackgroundInert(false);
    document.querySelector("[data-student-expense-editor]")?.remove();
    requestAnimationFrame(() => {
      document.querySelector(getStudentExpenseEditorButtonSelector(editor))?.focus({ preventScroll: true });
    });
  }

  function bindStudentExpenseEditorEvents() {
    const backdrop = document.querySelector("[data-student-expense-editor]");
    if (!backdrop || backdrop.dataset.studentExpenseEditorBound === "true") return;
    backdrop.dataset.studentExpenseEditorBound = "true";
    backdrop.querySelectorAll("[data-action='close-student-expense-editor']").forEach((element) => {
      element.addEventListener("click", (event) => {
        if (element.matches("button") || event.target === element) closeStudentExpenseEditor();
      });
    });
    backdrop.addEventListener("click", (event) => {
      if (event.target === backdrop) closeStudentExpenseEditor();
    });
    backdrop.addEventListener("keydown", (event) => {
      if (event.key !== "Tab") return;
      const focusable = [...backdrop.querySelectorAll(
        "button:not([disabled]), [href], input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex='-1'])"
      )].filter((element) => !element.hidden && element.getClientRects().length);
      if (!focusable.length) return;
      const first = focusable[0];
      const last = focusable.at(-1);
      if (event.shiftKey && document.activeElement === first) {
        event.preventDefault();
        last.focus({ preventScroll: true });
      } else if (!event.shiftKey && document.activeElement === last) {
        event.preventDefault();
        first.focus({ preventScroll: true });
      }
    });
    const form = backdrop.querySelector("#studentExpenseEditorForm");
    form?.addEventListener("submit", saveStudentExpenseEditor);
    const inventoryChoice = form?.elements?.studentExpenseEditorInventoryChoice;
    inventoryChoice?.addEventListener("change", () => {
      applyStudentExpenseInventoryChoice(inventoryChoice, { syncFinance: false });
    });
    if (!backdrop.contains(document.activeElement)) {
      const focusTarget = backdrop.querySelector(
        "#studentExpenseEditorForm [name='studentExpenseEditorDate'], [data-action='close-student-expense-editor']"
      );
      document.activeElement?.blur?.();
      focusTarget?.focus({ preventScroll: true });
    }
    setStudentExpenseEditorBackgroundInert(true);
  }

  function saveStudentExpenseEditor(event) {
    event.preventDefault();
    const form = event.currentTarget;
    const context = getStudentExpenseEditorContext();
    if (!context || !state.modal) {
      state.studentExpenseEditor = null;
      setStudentExpenseEditorBackgroundInert(false);
      document.querySelector("[data-student-expense-editor]")?.remove();
      return;
    }
    const editor = { ...context.editor };
    const values = {
      date: form.elements.studentExpenseEditorDate?.value,
      type: form.elements.studentExpenseEditorType?.value,
      amount: form.elements.studentExpenseEditorAmount?.value,
      note: form.elements.studentExpenseEditorNote?.value,
      inventoryId: form.elements.studentExpenseEditorInventoryId?.value,
      inventoryLink: form.elements.studentExpenseEditorInventoryLink?.value
    };
    const nextDraft = calculateStudentFinance(
      applyStudentExpenseEditorValues(context.draft, editor, values)
    );
    nextDraft.expenseTotal = Math.round(sumStudentExpenses(nextDraft) * 100) / 100;
    state.modal.draft = nextDraft;
    state.modal.hasDraftChanges = true;
    state.studentExpenseEditor = null;
    render();
    requestAnimationFrame(() => {
      document.querySelector(getStudentExpenseEditorButtonSelector(editor))?.focus({ preventScroll: true });
    });
  }

  function reorderStudentPayments(rowKeys) {
    if (!state.modal) return;
    const draft = collectStudentFormDraft();
    const payments = rowKeys.map((key) => {
      const index = Number(key);
      if (!Number.isInteger(index) || index < 1 || index > 8) return null;
      return {
        date: draft[`payment${index}Date`] || "",
        amount: draft[`payment${index}Amount`] || "",
        note: draft[`payment${index}Note`] || ""
      };
    }).filter(Boolean);
    Array.from({ length: 8 }, (_, index) => index + 1).forEach((index) => {
      const payment = payments[index - 1] || {};
      draft[`payment${index}Date`] = payment.date || "";
      draft[`payment${index}Amount`] = payment.amount || "";
      draft[`payment${index}Note`] = payment.note || "";
    });
    state.openPaymentRows = payments
      .map((payment, index) => paymentRowHasData(draft, index + 1) ? "" : index + 1)
      .filter(Boolean);
    state.modal.draft = calculateStudentFinance(draft);
    state.modal.hasDraftChanges = true;
    render();
  }

  function reorderStudentExpenses(rowKeys) {
    if (!state.modal) return;
    const draft = collectStudentFormDraft();
    const directExpenses = Array.isArray(draft.directExpenses) ? draft.directExpenses : [];
    const orderedExpenses = rowKeys.map((key) => {
      const directMatch = /^direct-(\d+)$/.exec(key);
      if (directMatch) return directExpenses[Number(directMatch[1])] || null;
      const manualMatch = /^manual-(\d+)$/.exec(key);
      if (!manualMatch) return null;
      const index = Number(manualMatch[1]);
      if (!expenseRowHasData(draft, index)) return null;
      return {
        id: makeId("direct-expense"),
        uid: draft.uid || "",
        date: draft[`expense${index}Date`] || "",
        type: draft[`expense${index}Type`] || "",
        amount: draft[`expense${index}Amount`] || "",
        isPaid: draft[`expense${index}IsPaid`] || "",
        note: draft[`expense${index}Note`] || "",
        inventoryId: draft[`expense${index}InventoryId`] || "",
        inventoryLink: draft[`expense${index}InventoryLink`] || ""
      };
    }).filter(Boolean);
    Array.from({ length: 6 }, (_, index) => index + 1).forEach((index) => {
      draft[`expense${index}Date`] = "";
      draft[`expense${index}Type`] = "";
      draft[`expense${index}Amount`] = "";
      draft[`expense${index}IsPaid`] = "";
      draft[`expense${index}Note`] = "";
      draft[`expense${index}InventoryId`] = "";
      draft[`expense${index}InventoryLink`] = "";
    });
    draft.directExpenses = orderedExpenses;
    draft.expenseTotal = sumStudentExpenses(draft);
    state.openExpenseRows = [];
    state.modal.draft = draft;
    state.modal.hasDraftChanges = true;
    render();
  }

  function getStudentFinanceDragAfterRow(grid, y) {
    return [...grid.querySelectorAll("[data-student-finance-row]:not(.is-dragging)")].reduce((closest, row) => {
      const cell = row.querySelector(".editable-grid-cell");
      if (!cell) return closest;
      const box = cell.getBoundingClientRect();
      const offset = y - box.top - box.height / 2;
      return offset < 0 && offset > closest.offset ? { offset, row } : closest;
    }, { offset: Number.NEGATIVE_INFINITY, row: null }).row;
  }

  function updateStudentFinanceRowNumbers(grid) {
    grid.querySelectorAll("[data-student-finance-row]").forEach((row, index) => {
      const number = row.querySelector("[data-finance-row-number]");
      if (number) number.textContent = String(index + 1);
    });
  }

  function bindStudentFinanceRowDrag(grid) {
    if (!grid) return;
    grid.addEventListener("dragstart", (event) => {
      const handle = event.target.closest("[data-finance-row-drag]");
      const row = handle?.closest("[data-student-finance-row]");
      if (!row) {
        event.preventDefault();
        return;
      }
      grid.dataset.originalFinanceOrder = [...grid.querySelectorAll("[data-student-finance-row]")]
        .map((item) => item.dataset.financeRowKey)
        .join("|");
      row.classList.add("is-dragging");
      if (event.dataTransfer) {
        event.dataTransfer.effectAllowed = "move";
        event.dataTransfer.setData("text/plain", "");
      }
    });
    grid.addEventListener("dragover", (event) => {
      const dragging = grid.querySelector("[data-student-finance-row].is-dragging");
      if (!dragging) return;
      event.preventDefault();
      const afterRow = getStudentFinanceDragAfterRow(grid, event.clientY);
      if (afterRow) grid.insertBefore(dragging, afterRow);
      else grid.appendChild(dragging);
      updateStudentFinanceRowNumbers(grid);
    });
    grid.addEventListener("drop", (event) => event.preventDefault());
    grid.addEventListener("dragend", () => {
      const rows = [...grid.querySelectorAll("[data-student-finance-row]")];
      rows.forEach((row) => row.classList.remove("is-dragging"));
      updateStudentFinanceRowNumbers(grid);
      const rowKeys = rows.map((row) => row.dataset.financeRowKey);
      const originalOrder = grid.dataset.originalFinanceOrder || "";
      delete grid.dataset.originalFinanceOrder;
      if (rowKeys.join("|") === originalOrder) return;
      if (grid.dataset.studentFinanceGrid === "payments") reorderStudentPayments(rowKeys);
      if (grid.dataset.studentFinanceGrid === "expenses") reorderStudentExpenses(rowKeys);
    });
  }

