    document.querySelectorAll("[data-action='sort']").forEach((button) => {
      button.addEventListener("click", () => {
        const configId = button.dataset.config || state.view;
        const key = button.dataset.key;
        state.sort = {
          key,
          dir: state.sort.key === key && state.sort.dir === "asc" ? "desc" : "asc"
        };
        state.tablePages[configId] = 1;
        render();
      });
    });

    document.querySelectorAll("[data-action='sort-inventory-students']").forEach((button) => {
      button.addEventListener("click", () => {
        const key = String(button.dataset.key || "");
        if (!key) return;
        state.inventoryStudentSort = {
          key,
          dir: state.inventoryStudentSort?.key === key
            && state.inventoryStudentSort?.dir === "asc"
            ? "desc"
            : "asc"
        };
        render();
      });
    });

    document.querySelectorAll("[data-student-status-shortcut]").forEach((button) => {
      button.addEventListener("click", () => {
        if (button.dataset.wasDragged === "true" || Date.now() - lastDashboardStatusDragEndedAt < 180) return;
        const status = button.dataset.studentStatusShortcut || "Все";
        pushStudentStatusHistory(status);
        state.view = "students";
        state.search = "";
        state.statusFilter = status;
        state.studentProgramTypeFilter = [];
        state.studentImportedViewIds = [];
        state.sort = getStudentStatusTableSort(status);
        state.tablePages.students = 1;
        state.tableOptions = null;
        render();
      });
    });

    const issuedDocumentsRegister = document.querySelector("[data-issued-documents-register]");
    if (issuedDocumentsRegister) {
      let issuedDocumentFilterTimer = 0;
      const applyIssuedDocumentFilter = (control, restoreFocus = false) => {
        const key = String(control?.dataset.issuedDocumentFilter || "");
        if (!key || !Object.prototype.hasOwnProperty.call(state.issuedDocumentFilters, key)) return;
        state.issuedDocumentFilters[key] = control.value;
        if (key === "frdo") state.issuedDocumentAutoFallback = false;
        state.tablePages.issuedDocuments = 1;
        const selectionStart = Number(control.selectionStart);
        render();
        if (!restoreFocus) return;
        requestAnimationFrame(() => {
          const nextControl = document.querySelector(`[data-issued-document-filter="${CSS.escape(key)}"]`);
          nextControl?.focus({ preventScroll: true });
          if (nextControl instanceof HTMLInputElement && Number.isFinite(selectionStart)) {
            nextControl.setSelectionRange(selectionStart, selectionStart);
          }
        });
      };
      issuedDocumentsRegister.querySelector("[data-issued-document-filters]")?.addEventListener("input", (event) => {
        const control = event.target.closest("[data-issued-document-filter]");
        if (!(control instanceof HTMLInputElement) || control.type === "date") return;
        window.clearTimeout(issuedDocumentFilterTimer);
        issuedDocumentFilterTimer = window.setTimeout(() => applyIssuedDocumentFilter(control, true), 180);
      });
      issuedDocumentsRegister.querySelector("[data-issued-document-filters]")?.addEventListener("change", (event) => {
        const control = event.target.closest("[data-issued-document-filter]");
        if (!control) return;
        window.clearTimeout(issuedDocumentFilterTimer);
        applyIssuedDocumentFilter(control, false);
      });
      issuedDocumentsRegister.querySelectorAll("[data-action='sort-issued-documents']").forEach((button) => {
        button.addEventListener("click", () => {
          const key = String(button.dataset.sortKey || "issueDate");
          const current = state.issuedDocumentSort || { key: "issueDate", dir: "asc" };
          state.issuedDocumentSort = current.key === key
            ? { key, dir: current.dir === "desc" ? "asc" : "desc" }
            : { key, dir: ["issueDate", "frdoDate"].includes(key) ? "desc" : "asc" };
          state.tablePages.issuedDocuments = 1;
          render();
        });
      });
      issuedDocumentsRegister.querySelector("[data-action='reset-issued-document-filters']")?.addEventListener("click", () => {
        prepareIssuedDocumentsRegistryOnOpen();
        render();
      });
      issuedDocumentsRegister.querySelector("[data-action='export-issued-documents-frdo']")?.addEventListener("click", (event) => {
        exportIssuedDocumentsToFrdo(event.currentTarget);
      });
      issuedDocumentsRegister.querySelectorAll("[data-action='open-issued-document-student']").forEach((button) => {
        button.addEventListener("click", () => {
          const navigationIds = getVisibleIssuedDocumentRows().map((row) => row.studentId).filter(Boolean);
          openStudentCardById(button.dataset.studentId, navigationIds);
        });
      });
    }

    document.querySelectorAll("[data-action='table-page']").forEach((button) => {
      button.addEventListener("click", () => {
        state.tablePages[button.dataset.config] = Number(button.dataset.page || 1);
        render();
      });
    });

    document.querySelectorAll("[data-action='table-page-input']").forEach((input) => {
      const applyPage = () => {
        state.tablePages[input.dataset.config] = Number(input.value || 1);
        render();
      };
      input.addEventListener("change", applyPage);
      input.addEventListener("keydown", (event) => {
        if (event.key !== "Enter") return;
        event.preventDefault();
        applyPage();
      });
    });

    document.querySelectorAll("[data-action='table-page-size']").forEach((select) => {
      select.addEventListener("change", () => {
        const configId = select.dataset.config;
        const pageSize = Number(select.value);
        if (!TABLE_PAGE_SIZE_OPTIONS.includes(pageSize)) return;
        updateTableSettings(configId, (settings) => ({ ...settings, pageSize }));
        state.tablePages[configId] = 1;
        render();
      });
    });

    document.querySelectorAll("[data-action='create']").forEach((button) => {
      button.addEventListener("click", () => {
        if (button.dataset.config === "students") state.studentCardTab = "main";
        if (button.dataset.config === "programs") state.programCardTab = "main";
        if (button.dataset.config === "contracts") state.contractCardTab = "main";
        if (button.dataset.config === "students") state.openPaymentRows = [];
        if (button.dataset.config === "students") state.openExpenseRows = [];
        if (button.dataset.config === "students") state.discountPickerOpen = false;
        if (button.dataset.config === "students") state.discountPicker = null;
        if (button.dataset.config === "students") state.studentImportedViewIds = [];
        if (["students", "contracts"].includes(button.dataset.config)) resetCardWindowState();
        state.modal = { config: button.dataset.config, id: "" };
        render();
      });
    });

    document.querySelectorAll("[data-action='edit']").forEach((button) => {
      button.addEventListener("click", async () => {
        state.lastEditedRow = { config: button.dataset.config || "", id: button.dataset.id || "" };
        if (button.dataset.config === "documentTemplates") {
          await withCardLoadingIndicator("documentTemplates", button.dataset.id, () => (
            selectDocumentTemplate(button.dataset.id)
          ));
          return;
        }
        button.disabled = true;
        try {
          await withCardLoadingIndicator(button.dataset.config, button.dataset.id, async () => {
            const acquired = await acquireRecordLock(
              recordLockEntityType(button.dataset.config),
              button.dataset.id
            );
            if (!acquired) return;
            setTablePageForRow(button.dataset.config, button.dataset.id);
            if (button.dataset.config === "students") state.studentCardTab = "main";
            if (button.dataset.config === "programs") state.programCardTab = "main";
            if (button.dataset.config === "contracts") state.contractCardTab = "main";
            if (button.dataset.config === "students") state.openPaymentRows = [];
            if (button.dataset.config === "students") state.openExpenseRows = [];
            if (button.dataset.config === "students") state.discountPickerOpen = false;
            if (button.dataset.config === "students") state.discountPicker = null;
            if (["students", "contracts"].includes(button.dataset.config)) resetCardWindowState();
            state.modal = { config: button.dataset.config, id: button.dataset.id };
            render();
          });
        } finally {
          if (button.isConnected) button.disabled = false;
        }
      });
    });

    document.querySelectorAll(".mini-table-link-row").forEach((row) => {
      row.addEventListener("keydown", (event) => {
        if (!["Enter", " "].includes(event.key)) return;
        event.preventDefault();
        row.click();
      });
    });

