  function getEmployeeContractDocumentFields(documentTemplate = {}) {
    return employeeContractDocumentFieldDefinitions.map(([name, formula], index) => ({
      id: `employee-contract-field-${index + 1}`,
      position: index + 1,
      name,
      formula: name === "Срок с"
        ? (documentTemplate.useStartDateClause
          ? "=ЕСЛИ([Срок с]<[Дата договора];\"Договор распространяется на отношения сторон, возникшие с \" & [Срок с];\"Срок начала оказания услуг по Договору – \" & [Срок с])"
          : "=[Срок с]")
        : formula,
      hideEmpty: false
    }));
  }

  function getEmployeeContractDocumentTemplates() {
    const configuredTemplates = getDocumentTemplates();
    return employeeContractDocumentTemplates.map((definition) => {
      const configured = configuredTemplates.find((documentTemplate) => documentTemplate.id === definition.id);
      return {
        ...createEmployeeContractDocumentTemplate(definition),
        ...(configured || {}),
        fallbackTemplatePath: definition.fallbackTemplatePath,
        useStartDateClause: definition.useStartDateClause,
        defaultTemplate: definition.defaultTemplate
      };
    });
  }

  function getEmployeeActDocumentTemplate() {
    return getDocumentTemplates().find((documentTemplate) => (
      documentTemplate.id === employeeActDocumentTemplateDefinition.id
      || documentTemplate.documentKind === "employeeAct"
    )) || createEmployeeActDocumentTemplate();
  }

  function normalizeEmployeeActPersonName(value) {
    return String(value || "")
      .replace(/\u00a0/g, " ")
      .replace(/\s+/g, " ")
      .trim()
      .toLocaleLowerCase("ru-RU");
  }

  function formatEmployeeActAmount(value) {
    const amount = Math.round((Number(value) || 0) * 100) / 100;
    return amount.toLocaleString("ru-RU", {
      useGrouping: false,
      minimumFractionDigits: 0,
      maximumFractionDigits: 2
    });
  }

  function formatEmployeeActPaymentRows(rows) {
    return (Array.isArray(rows) ? rows : [])
      .filter((row) => String(row?.description || "").trim() && Number(row?.amount || 0))
      .map((row) => `${String(row.description).trim()}\t${formatEmployeeActAmount(row.amount)}`)
      .join("\n");
  }

  function getEmployeeActVariablePaymentRows(record) {
    const employeeName = normalizeEmployeeActPersonName(record?.name);
    if (!employeeName) return [];
    const studentsByUid = new Map((state.data.collections.students || []).map((student) => [
      String(student?.uid || "").trim(),
      student
    ]));
    const seen = new Set();
    const directRows = getAllDirectExpenses().reduce((rows, expense, index) => {
      if (normalizeEmployeeActPersonName(expense?.note) !== employeeName) return rows;
      if (isEmployeePaymentSettled(expense)) return rows;
      if (String(expense?.act || "").trim()) return rows;
      if (String(expense?.recommendation || "").trim() !== "+") return rows;
      const amount = Number(expense?.amount || 0);
      if (!amount) return rows;
      const identity = directExpenseIdentity(expense, index);
      if (seen.has(identity)) return rows;
      seen.add(identity);
      const student = studentsByUid.get(String(expense?.uid || "").trim());
      const description = String(expense?.additionalInfo || "").trim()
        || (student
          ? [
              `${String(expense?.type || "Работа").trim()} за слушателя ${String(student.name || "").trim()}`,
              String(student.program || "").trim() ? `программа обучения — «${String(student.program).trim()}»` : ""
            ].filter(Boolean).join(", ")
          : String(expense?.type || "Оказанные услуги").trim());
      rows.push({ description, amount });
      return rows;
    }, []);
    const generalRows = (state.data.collections.generalExpenses || []).reduce((rows, expense) => {
      if (normalizeEmployeeActPersonName(expense?.counterparty) !== employeeName) return rows;
      if (isEmployeePaymentSettled(expense)) return rows;
      if (String(expense?.act || "").trim()) return rows;
      const amount = Number(expense?.amount || 0);
      if (!amount) return rows;
      const date = formatContractDate(expense?.date);
      const description = String(expense?.workType || expense?.description || "Оказанные услуги").trim();
      rows.push({
        description: date ? `${description} (на дату ${date})` : description,
        amount
      });
      return rows;
    }, []);
    return [...directRows, ...generalRows];
  }

  function getEmployeeActPartnerPaymentRows(record) {
    const accounting = getEmployeePaymentAccounting(record, state.data.collections);
    const rows = accounting.partnerRows.reduce((result, row) => {
      if (!row.payable || row.slot !== "due") return result;
      const values = normalizeEmployeePaymentSourceRow("partner", row.source);
      const payableAmount = Number(row.calculation?.payableAmount ?? values.amount ?? 0);
      if (!values.recommendation || isEmployeePaymentSettled(values) || values.act || !(payableAmount > 0)) return result;
      result.push({
        description: [
          `Агентское вознаграждение за слушателя ${String(row.student.name || "").trim()}`,
          String(row.student.program || "").trim() ? `программа обучения — ${String(row.student.program).trim()}` : "",
          `ставка ${row.calculation.rate}% от поступлений ${formatEmployeeActAmount(row.calculation.receiptsTotal)}`
        ].filter(Boolean).join(", "),
        amount: payableAmount,
        source: row.source
      });
      return result;
    }, []);
    return rows;
  }

  function getEmployeeActPaymentSummary(record) {
    const accounting = getEmployeePaymentAccounting(record, state.data.collections);
    const hasDetailedExpenseSources = accounting.directEntries.length > 0 || accounting.generalEntries.length > 0;
    const hasDetailedPaymentSources = hasDetailedExpenseSources || accounting.partnerStudents.length > 0;
    let variableRows = getEmployeeActVariablePaymentRows(record);
    let variableTotal = variableRows.reduce((sum, row) => sum + Number(row.amount || 0), 0);
    if (!variableRows.length && !hasDetailedExpenseSources && Number(record?.paid || 0)) {
      variableTotal = Number(record.paid);
      variableRows = [{
        description: String(record?.subject || "Оказанные услуги").trim() || "Оказанные услуги",
        amount: variableTotal
      }];
    }
    const partnerRows = getEmployeeActPartnerPaymentRows(record);
    const partnerTotal = partnerRows.reduce((sum, row) => sum + Number(row.amount || 0), 0);
    let total = variableTotal + partnerTotal;
    if (
      !total
      && !hasDetailedPaymentSources
      && !Number(record?.agencyAmount || 0)
      && Number(record?.amount || 0)
    ) total = Number(record.amount);
    total = Math.round(total * 100) / 100;
    return {
      variableRows,
      variableTotal: Math.round(variableTotal * 100) / 100,
      partnerRows,
      partnerTotal: Math.round(partnerTotal * 100) / 100,
      total
    };
  }

  function formatEmployeeActCurrentDate(saveFormat = false) {
    const now = new Date();
    const day = String(now.getDate()).padStart(2, "0");
    const month = String(now.getMonth() + 1).padStart(2, "0");
    const year = String(now.getFullYear());
    return saveFormat ? `${year}.${month}.${day}` : `${day}.${month}.${year}`;
  }

  function prepareEmployeeActDocumentRecord(record) {
    const summary = getEmployeeActPaymentSummary(record);
    const nameParts = splitFullName(record?.name);
    const words = numberToRussianWords(summary.total);
    const actValues = {
      "ДатаДоговора": formatContractDate(record?.contractDate),
      "ФИО": String(record?.name || "").trim(),
      "Предмет": String(record?.subject || "").trim(),
      "Сумма": formatEmployeeActAmount(summary.total),
      "Сумма прописью": words ? `${words.charAt(0).toLocaleUpperCase("ru-RU")}${words.slice(1)}` : "",
      "ФИО сокр": formatEmployeeContractShortName(record?.name),
      "ТекДата": formatEmployeeActCurrentDate(false),
      "Договор": String(record?.contractNo || "").trim(),
      "Переменные выплаты": formatEmployeeActPaymentRows(summary.variableRows),
      "Итого по переменным выплатам": formatEmployeeActAmount(summary.variableTotal),
      "Email": String(record?.email || "").trim(),
      "ИО": [nameParts.firstName, nameParts.patronymic].filter(Boolean).join(" "),
      "ТекДата_Сохр": formatEmployeeActCurrentDate(true),
      "Фото": "",
      "СуммаЗач": formatEmployeeActAmount(Math.floor(summary.total * 0.87)),
      "Партнерская программа": formatEmployeeActPaymentRows(summary.partnerRows),
      "Итого по партнерской программе": formatEmployeeActAmount(summary.partnerTotal)
    };
    return {
      ...record,
      employeeActDocument: true,
      employeeActDocumentValues: actValues,
      employeeActPaymentTotal: summary.total,
      ...actValues
    };
  }

  function formatEmployeeContractShortName(name) {
    const { surname, firstName, patronymic } = splitFullName(name);
    const initials = [firstName, patronymic]
      .filter(Boolean)
      .map((part) => `${part.slice(0, 1).toLocaleUpperCase("ru-RU")}.`)
      .join("");
    return [surname, initials].filter(Boolean).join(" ");
  }

  function getEmployeeContractStartDateText(record, documentTemplate) {
    const startDate = formatContractDate(record?.startDate);
    if (!startDate || !documentTemplate?.useStartDateClause) return startDate;
    const startTimestamp = parseOrdersSdoDate(record?.startDate)?.getTime();
    const contractTimestamp = parseOrdersSdoDate(record?.contractDate)?.getTime();
    return Number.isFinite(startTimestamp) && Number.isFinite(contractTimestamp) && startTimestamp < contractTimestamp
      ? `Договор распространяется на отношения сторон, возникшие с ${startDate}`
      : `Срок начала оказания услуг по Договору – ${startDate}`;
  }

  function prepareEmployeeContractDocumentRecord(record, documentTemplate) {
    const { firstName, patronymic } = splitFullName(record?.name);
    const identityType = String(record?.identityDocumentType || "").trim();
    const prepared = {
      ...record,
      employeeDocumentName: String(record?.name || "").trim(),
      employeeDocumentSubject: String(record?.subject || "").trim(),
      employeeDocumentAmount: String(record?.paymentTerms || record?.amount || record?.paid || "").trim(),
      employeeDocumentIdentityNumber: String(record?.identityDocument || "").trim(),
      employeeDocumentIdentityIssuer: String(record?.identityIssuer || "").trim(),
      employeeDocumentSettlementAccount: String(record?.settlementAccount || "").trim(),
      employeeDocumentCorrespondentAccount: String(record?.correspondentAccount || "").trim(),
      employeeDocumentBic: String(record?.bic || "").trim(),
      employeeDocumentIdentityType: identityType,
      employeeDocumentShortName: formatEmployeeContractShortName(record?.name),
      employeeDocumentIdentityTypeLower: identityType.toLocaleLowerCase("ru-RU"),
      employeeDocumentIdentityIssueDate: formatContractDate(record?.identityIssueDate),
      employeeDocumentAddress: String(record?.address || "").trim(),
      employeeDocumentSnils: String(record?.snils || "").trim(),
      employeeDocumentInn: String(record?.inn || "").trim(),
      employeeDocumentBank: String(record?.bank || "").trim(),
      employeeDocumentContractNo: String(record?.contractNo || "").trim(),
      employeeDocumentBirthDate: formatContractDate(record?.birthDate),
      employeeDocumentPhoto: String(record?.photoPath || record?.photoUrl || record?.photoData || "").trim(),
      employeeDocumentFirstPatronymic: [firstName, patronymic].filter(Boolean).join(" "),
      employeeDocumentEmail: String(record?.email || "").trim(),
      employeeDocumentEndDate: formatContractDate(record?.endDate),
      employeeDocumentContractDate: formatContractDate(record?.contractDate),
      employeeDocumentStartDate: getEmployeeContractStartDateText(record, documentTemplate)
    };
    return {
      ...prepared,
      "Предмет": prepared.employeeDocumentSubject,
      "Сумма": prepared.employeeDocumentAmount,
      "ДокумСерияНомер": prepared.employeeDocumentIdentityNumber,
      "ДокумКемВыдан": prepared.employeeDocumentIdentityIssuer,
      "РасчСч": prepared.employeeDocumentSettlementAccount,
      "КорСчет": prepared.employeeDocumentCorrespondentAccount,
      "БИК": prepared.employeeDocumentBic,
      "ДокумВид": prepared.employeeDocumentIdentityType,
      "ДокумДатаВыдачи": prepared.employeeDocumentIdentityIssueDate,
      "Адрес": prepared.employeeDocumentAddress,
      "СНИЛСф": prepared.employeeDocumentSnils,
      "ИННф": prepared.employeeDocumentInn,
      "Банк": prepared.employeeDocumentBank,
      "ДатаРождения": prepared.employeeDocumentBirthDate,
      "Срок по": prepared.employeeDocumentEndDate,
      "Срок с": formatContractDate(record?.startDate)
    };
  }

  function getEmployeeContractDocumentRequiredFields(record) {
    return [
      { key: "name", label: "ФИО / контрагент" },
      { key: "contractNo", label: "Номер договора" },
      { key: "contractDate", label: "Дата договора" },
      { key: "startDate", label: "Срок с" },
      { key: "endDate", label: "Срок по" },
      { key: "subject", label: "Предмет договора" },
      { key: "paymentTerms", label: "Сумма / условия оплаты", value: record?.paymentTerms || record?.amount || record?.paid },
      { key: "birthDate", label: "Дата рождения" },
      { key: "identityDocumentType", label: "Вид документа" },
      { key: "identityDocument", label: "Серия и номер документа" },
      { key: "identityIssueDate", label: "Дата выдачи документа" },
      { key: "identityIssuer", label: "Кем выдан документ" },
      { key: "address", label: "Адрес регистрации" },
      { key: "snils", label: "СНИЛС" },
      { key: "inn", label: "ИНН" },
      { key: "bank", label: "Банк" },
      { key: "settlementAccount", label: "Расчётный счёт" },
      { key: "correspondentAccount", label: "Корреспондентский счёт" },
      { key: "bic", label: "БИК" }
    ];
  }

  function getMissingEmployeeContractDocumentFields(record) {
    return getEmployeeContractDocumentRequiredFields(record).filter((item) => (
      !String(item.value ?? record?.[item.key] ?? "").trim()
    ));
  }

  function getEmployeeContractDocumentFieldTab(fieldName) {
    if ([
      "contractNo", "contractDate", "startDate", "endDate", "subject", "paymentTerms",
      "bank", "settlementAccount", "correspondentAccount", "bic"
    ].includes(fieldName)) return "contract";
    if ([
      "birthDate", "identityDocumentType", "identityDocument", "identityIssueDate",
      "identityIssuer", "address", "snils", "inn"
    ].includes(fieldName)) return "documents";
    return "main";
  }

  function focusEmployeeContractDocumentField(fieldName, record) {
    const key = String(fieldName || "").trim();
    if (!key) return;
    const tabId = getEmployeeContractDocumentFieldTab(key);
    if (state.contractCardTab !== tabId) {
      if (state.modal) state.modal.draft = { ...(state.modal.draft || {}), ...record };
      state.contractCardTab = tabId;
      render();
    }
    requestAnimationFrame(() => {
      const input = document.querySelector(`[name="${CSS.escape(key)}"]`);
      input?.scrollIntoView({ block: "center", inline: "nearest", behavior: "smooth" });
      input?.focus({ preventScroll: true });
    });
  }

  function validateEmployeeContractDocumentFields(record, documentTemplate) {
    const missing = getMissingEmployeeContractDocumentFields(record);
    if (!missing.length) return true;
    alert(`Документ «${documentTemplate?.title || "Договор"}» не сформирован.\nНе заполнены поля:\n${formatStudentDocumentMissingFields(missing)}`);
    focusEmployeeContractDocumentField(missing[0].key, record);
    return false;
  }

  function checkEmployeeContractDocumentData(record, documentTemplate) {
    const missing = getMissingEmployeeContractDocumentFields(record);
    showStudentDocumentDataCheckDialog(record, documentTemplate, missing, {
      focusField: focusEmployeeContractDocumentField
    });
    return missing.length === 0;
  }

  function getEmployeeActDocumentRequiredFields(record) {
    const summary = getEmployeeActPaymentSummary(record);
    return [
      { key: "name", label: "ФИО / контрагент" },
      { key: "contractNo", label: "Номер договора" },
      { key: "contractDate", label: "Дата договора" },
      { key: "subject", label: "Предмет договора" },
      {
        key: "amount",
        label: "Сумма оказанных услуг",
        value: summary.total,
        positive: true
      }
    ];
  }

  function getMissingEmployeeActDocumentFields(record) {
    return getEmployeeActDocumentRequiredFields(record).filter((item) => {
      const value = item.value ?? record?.[item.key];
      return item.positive ? !(Number(value) > 0) : !String(value ?? "").trim();
    });
  }

  function validateEmployeeActDocumentFields(record, documentTemplate) {
    const missing = getMissingEmployeeActDocumentFields(record);
    if (!missing.length) return true;
    alert(`Документ «${documentTemplate?.title || "Акт оказанных услуг"}» не сформирован.\nНе заполнены поля:\n${formatStudentDocumentMissingFields(missing)}`);
    focusEmployeeContractDocumentField(missing[0].key, record);
    return false;
  }

  function checkEmployeeActDocumentData(record, documentTemplate) {
    const missing = getMissingEmployeeActDocumentFields(record);
    showStudentDocumentDataCheckDialog(record, documentTemplate, missing, {
      focusField: focusEmployeeContractDocumentField
    });
    return missing.length === 0;
  }

  function showEmployeeDocumentActionMenu(x, y, documentTemplate, options = {}) {
    if (!documentTemplate) {
      alert("Не найден соответствующий шаблон в Конструкторе документов.");
      return;
    }
    const documentKind = String(options.documentKind || documentTemplate.documentKind || "").trim();
    const relatedDocumentTemplateIds = documentKind === "employeeContract"
      ? getEmployeeContractDocumentTemplates().map((item) => item.id)
      : [];
    showStudentDocumentActionMenu(x, y, documentTemplate, {
      title: options.title || documentTemplate.title,
      recipientLabel: "сотруднику",
      relatedDocumentTemplateIds,
      collectDraft: collectContractFormDraft,
      checkData: documentKind === "employeeAct"
        ? checkEmployeeActDocumentData
        : checkEmployeeContractDocumentData
    });
  }

  async function openEmployeeContractDocument(event) {
    const button = event?.currentTarget;
    const record = collectContractFormDraft();
    const templates = getEmployeeContractDocumentTemplates();
    const documentTemplate = await chooseStudentContractDocument(templates, templates[0]?.id, {
      eyebrow: "Карточка сотрудника",
      note: "По умолчанию выбран шаблон договора на образовательные услуги."
    });
    if (!documentTemplate) return;
    if (!validateEmployeeContractDocumentFields(record, documentTemplate)) return;
    const generationRecord = prepareEmployeeContractDocumentRecord(record, documentTemplate);
    await downloadStudentDocumentFromTemplate(
      documentTemplate,
      generationRecord,
      button,
      `Не удалось сформировать документ «${documentTemplate.title}»`,
      {
        entityType: "contracts",
        auditArea: "Документы сотрудника",
        messageType: "Договор сотрудника",
        storageRequest: getEmployeeDocumentStorageRequest(record)
      }
    );
  }

  function markEmployeeActPaymentRowsAsSent(record) {
    const employeeName = normalizeEmployeeActPersonName(record?.name);
    if (!employeeName) return 0;
    let changed = 0;
    getDirectExpenseEntriesFromCollections(state.data.collections).forEach(({ expense }) => {
      if (normalizeEmployeeActPersonName(expense?.note) !== employeeName) return;
      if (isEmployeePaymentSettled(expense)) return;
      if (String(expense?.act || "").trim()) return;
      if (String(expense?.recommendation || "").trim() !== "+") return;
      expense.act = "+";
      expense.actStatus = "Отправлен";
      changed += 1;
    });
    (state.data.collections.generalExpenses || []).forEach((expense) => {
      if (normalizeEmployeeActPersonName(expense?.counterparty) !== employeeName) return;
      if (isEmployeePaymentSettled(expense) || String(expense?.act || "").trim()) return;
      expense.act = "+";
      expense.actStatus = "Отправлен";
      changed += 1;
    });
    getEmployeePaymentAccounting(record, state.data.collections).partnerRows.forEach((row) => {
      if (!row.payable || row.slot !== "due") return;
      const values = normalizeEmployeePaymentSourceRow("partner", row.source);
      if (!values.recommendation || isEmployeePaymentSettled(values) || values.act || !(values.amount > 0)) return;
      const student = row.student;
      student.agentPaymentAct = "+";
      student.agentPaymentActStatus = "Отправлен";
      changed += 1;
    });
    if (!changed) return 0;
    addAudit("Отправлен акт", "Выплаты сотрудникам", `${record.name}: ${changed} поз.`, {
      entityType: "contracts",
      entityId: String(record.id || state.modal?.id || ""),
      entityLabel: record.name || String(record.id || ""),
      source: "employee-act-email"
    });
    commitEmployeePaymentAccountingChange(record, {}, true);
    return changed;
  }

  async function openEmployeeActDocument(event) {
    const button = event?.currentTarget;
    const record = collectContractFormDraft();
    const documentTemplate = getEmployeeActDocumentTemplate();
    if (!documentTemplate) {
      alert("В Конструкторе документов не найден шаблон «Акт оказанных услуг».");
      return;
    }
    if (!validateEmployeeActDocumentFields(record, documentTemplate)) return;
    const generationRecord = prepareEmployeeActDocumentRecord(record);
    const result = await downloadStudentDocumentFromTemplate(
      documentTemplate,
      generationRecord,
      button,
      "Не удалось сформировать акт оказанных услуг",
      {
        entityType: "contracts",
        auditArea: "Документы сотрудника",
        messageType: "Акт оказанных услуг",
        storageRequest: getEmployeeDocumentStorageRequest(record)
      }
    );
    if (result?.emailed) markEmployeeActPaymentRowsAsSent(record);
  }

  function isStudentFundedByLegalEntity(record) {
    const fundingSource = String(record?.fundingSource || "")
      .replace(/\u00a0/g, " ")
      .replace(/\s+/g, " ")
      .trim()
      .toLocaleLowerCase("ru-RU");
    return /за\s+сч[её]т\s+организац/u.test(fundingSource)
      || /юр(?:идическ[\p{L}\p{N}_]*\s+лиц[\p{L}\p{N}_]*|лиц[\p{L}\p{N}_]*)/u.test(fundingSource);
  }

  function getAutomaticStudentContractTemplate(record) {
    return isStudentFundedByLegalEntity(record)
      ? getLegalEntityApplicationDocumentTemplate()
      : getPrimaryDocumentTemplate();
  }

  function chooseStudentContractDocument(documentTemplates, selectedDocumentId, options = {}) {
    document.querySelector("[data-student-document-choice-dialog]")?.closeStudentDocumentChoice?.();
    const templates = Array.isArray(documentTemplates) ? documentTemplates.filter(Boolean) : [];
    if (!templates.length) return Promise.resolve(null);
    const eyebrow = String(options.eyebrow || "Карточка слушателя").trim();
    const note = String(options.note || "Без Shift документ выбирается автоматически по источнику финансирования.").trim();
    return new Promise((resolve) => {
      const backdrop = document.createElement("div");
      backdrop.className = "modal-backdrop student-document-choice-backdrop";
      backdrop.dataset.studentDocumentChoiceDialog = "";
      backdrop.innerHTML = `
        <form class="modal student-document-choice-dialog">
          <header class="modal-head">
            <div>
              <p class="eyebrow">${escapeHtml(eyebrow)}</p>
              <h2>Сформировать документ</h2>
            </div>
            <button class="icon-button" data-action="close-student-document-choice" type="button" title="Закрыть" aria-label="Закрыть">×</button>
          </header>
          <div class="student-document-choice-body">
            <label>
              <span>Документ</span>
              <select name="documentTemplateId">
                ${templates.map((documentTemplate) => `
                  <option value="${escapeAttr(documentTemplate.id)}" ${documentTemplate.id === selectedDocumentId ? "selected" : ""}>
                    ${escapeHtml(documentTemplate.title)}
                  </option>
                `).join("")}
              </select>
            </label>
            ${note ? `<small>${escapeHtml(note)}</small>` : ""}
          </div>
          <footer class="modal-actions">
            <button class="ghost-button" data-action="close-student-document-choice" type="button">Отмена</button>
            <button class="primary-button" type="submit">Сформировать</button>
          </footer>
        </form>
      `;
      let settled = false;
      const finish = (documentTemplate = null) => {
        if (settled) return;
        settled = true;
        backdrop.remove();
        resolve(documentTemplate);
      };
      backdrop.closeStudentDocumentChoice = () => finish(null);
      backdrop.addEventListener("pointerdown", (dialogEvent) => {
        if (dialogEvent.target === backdrop) finish(null);
      });
      backdrop.querySelectorAll("[data-action='close-student-document-choice']").forEach((button) => {
        button.addEventListener("click", () => finish(null));
      });
      backdrop.querySelector("form")?.addEventListener("submit", (submitEvent) => {
        submitEvent.preventDefault();
        const selectedId = String(submitEvent.currentTarget.elements.documentTemplateId?.value || "");
        finish(templates.find((documentTemplate) => documentTemplate.id === selectedId) || null);
      });
      document.body.appendChild(backdrop);
      backdrop.querySelector("select")?.focus();
    });
  }

  async function openStudentContractDocument(event) {
    const button = event?.currentTarget;
    const record = collectStudentFormDraft();
    const automaticTemplate = getAutomaticStudentContractTemplate(record);
    const documentTemplate = event?.shiftKey
      ? await chooseStudentContractDocument(getStudentContractDocumentTemplates(), automaticTemplate.id)
      : automaticTemplate;
    if (!documentTemplate) return;
    if (!validateStudentDocumentRequiredFields(record, documentTemplate)) return;
    await downloadStudentDocumentFromTemplate(
      documentTemplate,
      record,
      button,
      `Не удалось сформировать документ «${documentTemplate.title}»`
    );
  }

  function evaluateContractTemplateFields(record, fields) {
    const formulaGraphError = validateContractTemplateFormulaGraph(fields);
    if (formulaGraphError) throw new Error(formulaGraphError);
    const normalizedFields = normalizeContractTemplateDocumentFields(fields);
    const fieldsByName = new Map(normalizedFields.map((field) => [field.name, field]));
    const values = {};
    const evaluating = [];
    const evaluateByName = (name) => {
      const fieldName = String(name || "").trim();
      if (!fieldName) return "";
      if (Object.prototype.hasOwnProperty.call(values, fieldName)) return values[fieldName];
      const field = fieldsByName.get(fieldName);
      if (!field) return "";
      const cycleStart = evaluating.indexOf(fieldName);
      if (cycleStart >= 0) {
        const cycle = [...evaluating.slice(cycleStart), fieldName];
        throw new Error(`Обнаружена рекурсия в формулах документа: ${cycle.join(" → ")}.`);
      }
      evaluating.push(fieldName);
      try {
        values[fieldName] = evaluateContractTemplateField(field, record, values, evaluateByName);
      } finally {
        evaluating.pop();
      }
      return values[fieldName];
    };
    normalizedFields.forEach((field) => {
      evaluateByName(field.name);
    });
    return values;
  }

  function collectContractTemplateSourceValues(record) {
    const values = {};
    contractTemplateSourceFieldNames.forEach((name) => {
      values[name] = getContractTemplateSourceValue(name, record);
    });
    return values;
  }

  function getOrderDocumentProgramPhrase(record, enrollment = false) {
    const type = getStudentProgramTypeCode(record);
    if (type === "ППП") return enrollment ? "программу профессиональной переподготовки: " : "программа профессиональной переподготовки: ";
    if (type === "КПК") return enrollment ? "программу повышения квалификации: " : "программа повышения квалификации: ";
    if (type === "ДОП") return enrollment ? "дополнительную общеобразовательную программу: " : "дополнительная общеобразовательная программа: ";
    if (type === "ПРО") return enrollment ? "программу профессионального обучения: " : "программа профессионального обучения: ";
    return enrollment ? "программу обучения: " : "программа обучения: ";
  }

  function getOrderDocumentProgramText(record) {
    const program = String(record.program || "").trim();
    const hours = String(getStudentProgramHours(record) || "").trim();
    if (!program) return hours ? `${hours} ч.` : "";
    if (hours && new RegExp(`\\b${escapeRegExp(hours)}\\b`).test(program)) return program;
    return hours ? `${program}, ${hours} ч.` : program;
  }

  function normalizeOrderDocumentNumber(value) {
    return String(value || "").replace(/\s+/g, " ").trim().toLowerCase();
  }

  function getStudentOrderDocumentRecords(record, orderFieldName) {
    const targetNumber = normalizeOrderDocumentNumber(record?.[orderFieldName]);
    if (!targetNumber) return [];
    const currentId = String(record?.id || state.modal?.id || "").trim();
    const rows = state.data.collections.students || [];
    const result = [];
    let currentRecordIncluded = false;
    rows.forEach((row) => {
      const isCurrent = currentId && String(row.id || "") === currentId;
      const item = isCurrent ? { ...row, ...record } : row;
      if (isCurrent) currentRecordIncluded = true;
      if (normalizeOrderDocumentNumber(item?.[orderFieldName]) === targetNumber) result.push(item);
    });
    if (!currentRecordIncluded && normalizeOrderDocumentNumber(record?.[orderFieldName]) === targetNumber) {
      result.push(record);
    }
    const seen = new Set();
    return result
      .filter((item, index) => {
        const key = item.id ? `id:${item.id}` : (item.uid ? `uid:${item.uid}` : `row:${index}`);
        if (seen.has(key)) return false;
        seen.add(key);
        return true;
      })
      .sort((left, right) => String(left.name || "").localeCompare(String(right.name || ""), "ru"));
  }

  function formatEnrollmentOrderStudentListItem(record) {
    const name = String(record.name || "").trim();
    const programText = getOrderDocumentProgramText(record);
    return [name, `на ${getOrderDocumentProgramPhrase(record, true)}${programText}`]
      .filter(Boolean)
      .join(" ");
  }

  function formatOrderDocumentNumberedList(records, formatItem) {
    return records
      .map(formatItem)
      .filter(Boolean)
      .join("\n");
  }

  function formatEnrollmentOrderStudentList(record) {
    return formatOrderDocumentNumberedList(
      getStudentOrderDocumentRecords(record, "enrollmentOrderNo"),
      formatEnrollmentOrderStudentListItem
    );
  }

  function hasStudentEducationDocumentIssued(record) {
    return Boolean(
      String(record.diplomaBlankNo || "").trim()
      || String(record.registrationNo || "").trim()
    );
  }

  function formatExpulsionOrderStudentListItem(record) {
    const name = String(record.name || "").trim();
    const programText = getOrderDocumentProgramText(record);
    return [name, `${getOrderDocumentProgramPhrase(record, false)}${programText}`]
      .filter(Boolean)
      .join(", ");
  }

  function getExpulsionOrderDocumentRecords(record, issuedFilter = null) {
    return getStudentOrderDocumentRecords(record, "expulsionOrderNo")
      .filter((item) => issuedFilter === null || hasStudentEducationDocumentIssued(item) === issuedFilter);
  }

  function formatExpulsionOrderStudentList(record, issuedFilter = null) {
    return formatOrderDocumentNumberedList(
      getExpulsionOrderDocumentRecords(record, issuedFilter),
      formatExpulsionOrderStudentListItem
    );
  }

  function evaluateContractTemplateField(field, record, values, evaluateByName = null) {
    const fieldName = String(field.name || "").trim();
    if (
      record?.employeeActDocument
      && record.employeeActDocumentValues
      && Object.prototype.hasOwnProperty.call(record.employeeActDocumentValues, fieldName)
    ) {
      return String(record.employeeActDocumentValues[fieldName] ?? "");
    }
    if (Object.prototype.hasOwnProperty.call(record || {}, "employeeDocumentName")) {
      const employeeValues = {
        "ФИО_сокр": record.employeeDocumentShortName,
        "ДокумВидНР": record.employeeDocumentIdentityTypeLower,
        "ИО": record.employeeDocumentFirstPatronymic,
        "Срок с": record.employeeDocumentStartDate
      };
      if (Object.prototype.hasOwnProperty.call(employeeValues, fieldName)) {
        return String(employeeValues[fieldName] || "");
      }
    }
    if (fieldName === "Прогр обуч факт") return getContractTemplateSourceValue("Прогр обуч факт", record);
    if (fieldName === "Вид курсов") return formatContractProgramTitle(record);
    if (fieldName === "Номер приказа зачисления") return getContractTemplateSourceValue("Номер приказа зачисления", record);
    if (fieldName === "Дата приказа зачисления") return getContractTemplateSourceValue("Дата приказа зачисления", record);
    if (fieldName === "Дата начала обучения") return getContractTemplateSourceValue("Дата начала обучения", record);
    if (fieldName === "Номер приказа отчисления") return getContractTemplateSourceValue("Номер приказа отчисления", record);
    if (fieldName === "Дата приказа отчисления") return getContractTemplateSourceValue("Дата приказа отчисления", record);
    if (fieldName === "Список") return formatEnrollmentOrderStudentList(record);
    if (fieldName === "СписокСвыдачей") return formatExpulsionOrderStudentList(record, true);
    if (fieldName === "СписокБезВыдачи") return formatExpulsionOrderStudentList(record, false);
    if (fieldName === "N2") {
      const withIssued = getExpulsionOrderDocumentRecords(record, true).length;
      const withoutIssued = getExpulsionOrderDocumentRecords(record, false).length;
      if (!withoutIssued) return "";
      return withIssued ? "2" : "1";
    }
    if (fieldName === "N3") {
      const withIssued = getExpulsionOrderDocumentRecords(record, true).length;
      const withoutIssued = getExpulsionOrderDocumentRecords(record, false).length;
      return withIssued && withoutIssued ? "3" : (withIssued || withoutIssued ? "2" : "1");
    }
    const defaultField = contractTemplateFieldDefaults.find((item) => item.name === field.name);
    const formula = String(field.formula || "").trim();
    if (isGetSqlQueryFormula(formula)) {
      return field.name === "УчебныйПлан" ? formatEducationDocumentTrainingPlan(record) : "";
    }
    if (fieldName === "ФИО_ENG" && /ТРАНСЛИТЕРАЦИЯ/i.test(formula)) {
      return String(record?.fullNameEnglish || record?.nameEnglish || record?.fioEnglish || "").trim()
        || transliterateStudentName(record?.name || "");
    }
    if (fieldName === "РегНомер_ENG" && /ТРАНСЛИТЕРАЦИЯ/i.test(formula)) {
      return transliterateStudentName(getContractTemplateRawSourceValue("РегНомер", record));
    }
    if (fieldName === "Дата выдачи" && /^\s*=\s*ТЕКСТ\(/i.test(formula)) {
      return formatContractDate(getContractTemplateRawSourceValue("Дата выдачи", record));
    }
    if (fieldName === "QRкод" && /^\s*=\s*QRкод\(/i.test(formula)) {
      const program = String(getContractTemplateSourceValue("Прогр обуч факт", record) || "").trim();
      const fullName = String(getContractTemplateSourceValue("ФИО", record) || record?.name || "").trim();
      return `${program}${program && fullName ? " " : ""}${fullName}https://edu-plus.ru`;
    }
    const isDefaultFormula = defaultField && formula === String(defaultField.formula || "").trim();
    if (!isDefaultFormula) return evaluateContractFormulaFallback(formula, record, values, evaluateByName);
    const source = (name) => getContractTemplateSourceValue(name, record);
    const raw = (name) => getContractTemplateRawSourceValue(name, record);
    const nameParts = splitFullName(record.name);
    switch (field.name) {
      case "N Договора": return source("Договор") || "__________";
      case "Вид курсов": return formatContractProgramTitle(record);
      case "Внесено (руб)": return formatContractMoneyWithWords(raw("Внесено (руб)"));
      case "ДатаДоговора": return formatContractDate(raw("Дата договора") || raw("Дата подачи заявки"));
      case "Имя": return nameParts.firstName;
      case "ИО": return [nameParts.firstName, nameParts.patronymic].filter(Boolean).join(" ");
      case "Отчество": return nameParts.patronymic;
      case "ПутьСохр": return raw("Фото") || "";
      case "СрокПо": return formatContractDate(raw("Дата окончания обучения"));
      case "СрокС": return formatContractDate(raw("Дата начала обучения"));
      case "Сумма": return formatContractMoneyWithWords(raw("Сумма  по договору (руб)"));
      case "Фамилия": return nameParts.surname;
      case "ФИО_обуч_род": return inflectFioGenitive(
        record.name || "",
        isChecked(record.noDeclension),
        record.gender || ""
      );
      case "Фото": return raw("Фото") || "";
      case "Стажировка": return isChecked(record.internship) ? "(со стажировкой)" : "";
      case "Форма обучения": return formatContractStudyForm(raw("Форма обучения"));
      default: return evaluateContractFormulaFallback(formula, record, values, evaluateByName);
    }
  }

  function evaluateContractFormulaFallback(formula, record, values, evaluateByName = null) {
    let result = String(formula || "").replace(/^=\s*/, "");
    const directField = /^\(?\s*\[([^\]]+)\]\s*\)?$/.exec(result.trim());
    if (directField) return getContractTemplateSourceValue(directField[1], record);
    result = result.replace(/#([^#]+)#/g, (match, fieldName) => {
      const normalizedName = String(fieldName || "").trim();
      if (typeof evaluateByName === "function") {
        const resolved = evaluateByName(normalizedName);
        return resolved === "" && !Object.prototype.hasOwnProperty.call(values, normalizedName) ? match : resolved;
      }
      return Object.prototype.hasOwnProperty.call(values, normalizedName) ? values[normalizedName] : match;
    });
    result = result.replace(/\[([^\]]+)\]/g, (match, fieldName) => getContractTemplateSourceValue(fieldName, record));
    return result.replace(/ПутьДокумента\(1\)\s*&\s*/gi, "").trim();
  }

  function isGetSqlQueryFormula(value) {
    return /Получить\s*SQL\s*запрос|ПолучитьSQLзапрос/i.test(String(value || ""));
  }

  function getContractTemplateRawSourceValue(name, record) {
    const normalized = String(name || "").replace(/\s+/g, " ").trim();
    if (normalized === "Количество часов") return getStudentProgramHours(record);
    if (normalized === "Часы") return getStudentProgramHours(record);
    if (normalized === "Вид программы ДПО") return getStudentProgramTypeCode(record);
    if ([
      "Дата отчисления",
      "Дата приказа отчисления",
      "Дата приказа Отчисл Док Обр"
    ].includes(normalized)) {
      return String(record?.expulsionDate || record?.expulsionOrderDate || "").trim();
    }
    if (normalized === "Пол") {
      const gender = String(record?.gender || inferStudentGender(record?.name) || "").trim().toLowerCase();
      if (gender.startsWith("ж")) return "Ж";
      if (gender.startsWith("м")) return "М";
      return "";
    }
    if (normalized === "ФИО_несклон") return isChecked(record.noDeclension) ? "+" : "";
    if (normalized === "Стажировка") return isChecked(record.internship) ? "+" : "";
    if (normalized === "Фото") return record.photoPath || record.photoUrl || record.photoData || "";
    if (normalized === "ИО") {
      const parts = splitFullName(record.name);
      return [parts.firstName, parts.patronymic].filter(Boolean).join(" ");
    }
    if (normalized === "Прогр обуч факт_ENG") {
      const program = findProgramByName(record.program);
      return String(record.programEnglish || program?.shortName || record.program || "").trim();
    }
    if (normalized === "Документ об образовании") return getIssuedEducationDocumentName(record);
    if (normalized === "Квалификация") {
      const program = findProgramByName(record.program);
      return String(record.qualification || program?.qualification || "").trim();
    }
    if (normalized === "УчебныйПлан") return formatEducationDocumentTrainingPlan(record);
    if (normalized === "СфераДеятельности") {
      const program = findProgramByName(record.program);
      return String(program?.qualification || record.qualification || program?.type || "").trim();
    }
    if (normalized === "Срок обучения_ENG") return formatEducationDocumentStudyPeriod(record);
    if (normalized === "QRкод") return String(record.qrCode || getProgramPromoUrl(findProgramByName(record.program)) || "").trim();
    const key = contractTemplateSourceFieldMap[normalized] || contractTemplateSourceFieldMap[name] || normalized;
    return record[key] ?? "";
  }

  function getIssuedEducationDocumentName(record) {
    const typeCode = getStudentProgramTypeCode(record);
    if (typeCode === "ППП") return "Диплом о профессиональной переподготовке";
    if (typeCode === "КПК") return "Удостоверение о повышении квалификации";
    if (typeCode === "ДОП" || typeCode === "ПРО") return "Сертификат";
    return "Документ об образовании";
  }

  function getTrainingPlanHours(value) {
    const text = String(value ?? "").replace(",", ".").trim();
    const direct = /^\d+(?:\.\d+)?$/.exec(text);
    if (direct) return Number(direct[0]);
    const inName = /\(\s*(\d+(?:[.,]\d+)?)\s*(?:ч|час|часа|часов)\s*\)\s*$/i.exec(text);
    return inName ? Number(inName[1].replace(",", ".")) : 0;
  }

  function findEducationDocumentProgram(record) {
    const programName = String(record?.program || "").trim();
    if (!programName) return null;
    const programs = getProgramRows();
    const exactName = normalizeProgramName(programName);
    const exactProgram = programs.find((program) => normalizeProgramName(program?.name) === exactName);
    if (exactProgram) return exactProgram;
    const comparableName = normalizeTrainingPlanProgramName(programName);
    const candidates = programs.filter((program) => (
      [program?.name, program?.shortName].some((name) => (
        normalizeProgramName(name) === exactName
        || normalizeTrainingPlanProgramName(name) === comparableName
      ))
    ));
    const requestedHours = getTrainingPlanHours(
      record?.hours || record?.programHours || record?.totalHours || programName
    );
    if (requestedHours) {
      const matchingHours = candidates.filter((program) => (
        getTrainingPlanHours(program?.hours || program?.name) === requestedHours
      ));
      if (matchingHours.length === 1) return matchingHours[0];
    }
    return candidates.length === 1 ? candidates[0] : null;
  }

  function getEducationDocumentTrainingPlanRows(record) {
    const rows = state.data.collections.trainingPlans || [];
    const programName = String(record?.program || "").trim();
    const program = findEducationDocumentProgram(record);
    const programId = String(program?.id || "").trim();
    if (programId) {
      const linkedRows = rows.filter((item) => String(item?.programId || "").trim() === programId);
      if (linkedRows.length) return linkedRows;
    }
    const exactNames = new Set([programName, program?.name]
      .map(normalizeProgramName)
      .filter(Boolean));
    const exactRows = rows.filter((item) => exactNames.has(normalizeProgramName(item?.programName)));
    if (exactRows.length) return exactRows;
    const comparableNames = new Set([programName, program?.name, program?.shortName]
      .map(normalizeTrainingPlanProgramName)
      .filter(Boolean));
    const comparableRows = rows.filter((item) => (
      comparableNames.has(normalizeTrainingPlanProgramName(item?.programName))
    ));
    const requestedHours = getTrainingPlanHours(
      record?.hours || record?.programHours || record?.totalHours || program?.hours || programName
    );
    if (requestedHours) {
      const matchingHours = comparableRows.filter((item) => (
        getTrainingPlanHours(item?.programName) === requestedHours
      ));
      if (matchingHours.length) return matchingHours;
    }
    const distinctPlans = new Set(comparableRows.map((item) => normalizeProgramName(item?.programName)));
    return distinctPlans.size <= 1 ? comparableRows : [];
  }

  function formatEducationDocumentTrainingPlan(record) {
    const programName = String(record?.program || "").trim();
    if (!programName) return "";
    const related = getEducationDocumentTrainingPlanRows(record);
    if (!related.length) return "";
    return related.map((item) => {
      const discipline = String(item.discipline || item.code || "").trim();
      const hours = String(item.totalHours || "").trim();
      const grade = isFinalAttestationPlanRow(item) ? String(record?.finalGrade || "").trim() : "Зачтено";
      return [discipline, hours, grade].join("\t");
    }).filter(Boolean).join("\n");
  }

  function normalizeTrainingPlanProgramName(value) {
    return normalizeProgramName(value)
      .replace(/\s*\(\s*\d+(?:[.,]\d+)?\s*(?:ч|час|часа|часов)\s*\)\s*$/i, "")
      .trim();
  }

  function isFinalAttestationPlanRow(item) {
    const text = [item?.discipline, item?.attestation, item?.content, item?.code]
      .map((value) => String(value || "").trim())
      .filter(Boolean)
      .join(" ");
    return /итогов|итоговая\s+аттестация|\bиа\b/i.test(text);
  }

  function formatEducationDocumentStudyPeriod(record) {
    const start = formatContractDate(record.startDate);
    const end = formatContractDate(record.endDate);
    if (start && end) return `${start} - ${end}`;
    return start || end || "";
  }

  function getContractTemplateSourceValue(name, record) {
    const value = getContractTemplateRawSourceValue(name, record);
    if (isContractDateSource(name)) return formatContractDate(value);
    return String(value ?? "");
  }

  function isContractDateSource(name) {
    return /Дата|Срок|ДР/i.test(String(name || ""));
  }

  function formatContractDate(value) {
    const text = String(value || "").trim();
    if (!text) return "";
    const iso = /^(\d{4})-(\d{2})-(\d{2})/.exec(text);
    if (iso) return `${iso[3]}.${iso[2]}.${iso[1]}`;
    const ru = /^(\d{2})\.(\d{2})\.(\d{4})$/.exec(text);
    if (ru) return text;
    const date = new Date(text);
    if (Number.isNaN(date.getTime())) return text;
    return `${String(date.getDate()).padStart(2, "0")}.${String(date.getMonth() + 1).padStart(2, "0")}.${date.getFullYear()}`;
  }

  function formatContractProgramTitle(record) {
    const program = String(record.program || "").trim();
    const hours = String(getStudentProgramHours(record) || "").trim();
    if (!program) return hours ? `(${hours} ч.)` : "";
    if (hours && new RegExp(`\\b${escapeRegExp(hours)}\\b`).test(program)) {
      return program.replace(/\s*ч\)/i, " ч)");
    }
    return hours ? `${program} (${hours} ч.)` : program;
  }

  function formatContractStudyForm(value) {
    const text = String(value || "").trim();
    if (!text) return "";
    const normalized = text.toLowerCase();
    if (normalized === "дистант") return "заочная дистанционная";
    return normalized;
  }

  function formatContractMoneyWithWords(value) {
    const number = Number(String(value ?? "").replace(/\s+/g, "").replace(",", "."));
    if (!Number.isFinite(number) || number === 0) return "";
    const integer = Math.round(number);
    return `${integer} (${numberToRussianWords(integer)}) рублей`;
  }

  function numberToRussianWords(value) {
    const number = Math.abs(Math.trunc(Number(value) || 0));
    if (!number) return "ноль";
    const units = [
      { forms: ["", "", ""], gender: "male" },
      { forms: ["тысяча", "тысячи", "тысяч"], gender: "female" },
      { forms: ["миллион", "миллиона", "миллионов"], gender: "male" },
      { forms: ["миллиард", "миллиарда", "миллиардов"], gender: "male" }
    ];
    const parts = [];
    let rest = number;
    let unitIndex = 0;
    while (rest > 0 && unitIndex < units.length) {
      const chunk = rest % 1000;
      if (chunk) parts.unshift(formatRussianNumberChunk(chunk, units[unitIndex]));
      rest = Math.floor(rest / 1000);
      unitIndex += 1;
    }
    return parts.join(" ").replace(/\s+/g, " ").trim();
  }

  function formatRussianNumberChunk(value, unit) {
    const hundreds = ["", "сто", "двести", "триста", "четыреста", "пятьсот", "шестьсот", "семьсот", "восемьсот", "девятьсот"];
    const tens = ["", "", "двадцать", "тридцать", "сорок", "пятьдесят", "шестьдесят", "семьдесят", "восемьдесят", "девяносто"];
    const teens = ["десять", "одиннадцать", "двенадцать", "тринадцать", "четырнадцать", "пятнадцать", "шестнадцать", "семнадцать", "восемнадцать", "девятнадцать"];
    const onesMale = ["", "один", "два", "три", "четыре", "пять", "шесть", "семь", "восемь", "девять"];
    const onesFemale = ["", "одна", "две", "три", "четыре", "пять", "шесть", "семь", "восемь", "девять"];
    const result = [];
    const h = Math.floor(value / 100);
    const t = Math.floor((value % 100) / 10);
    const o = value % 10;
    if (hundreds[h]) result.push(hundreds[h]);
    if (t === 1) result.push(teens[o]);
    else {
      if (tens[t]) result.push(tens[t]);
      const ones = unit.gender === "female" ? onesFemale : onesMale;
      if (ones[o]) result.push(ones[o]);
    }
    if (unit.forms[0]) result.push(unit.forms[getRussianPluralIndex(value)]);
    return result.join(" ");
  }

  function getRussianPluralIndex(value) {
    const mod10 = value % 10;
    const mod100 = value % 100;
    if (mod10 === 1 && mod100 !== 11) return 0;
    if (mod10 >= 2 && mod10 <= 4 && (mod100 < 12 || mod100 > 14)) return 1;
    return 2;
  }

  function splitFullName(name) {
    const [surname = "", firstName = "", patronymic = ""] = String(name || "").trim().split(/\s+/).filter(Boolean);
    return { surname, firstName, patronymic };
  }

  function normalizeFioGender(value) {
    const normalized = String(value || "").trim().toLocaleLowerCase("ru-RU");
    if (/^(?:ж|жен|женский|female|f)$/u.test(normalized)) return "Женский";
    if (/^(?:м|муж|мужской|male|m)$/u.test(normalized)) return "Мужской";
    return "";
  }

  function inflectFioGenitive(name, preserveSurname = false, genderHint = "") {
    const parts = splitFullName(name);
    const gender = normalizeFioGender(genderHint) || inferStudentGender(name) || "Мужской";
    return [
      preserveSurname ? parts.surname : inflectRussianNamePart(parts.surname, gender, "surname"),
      inflectRussianNamePart(parts.firstName, gender, "firstName"),
      inflectRussianNamePart(parts.patronymic, gender, "patronymic")
    ].filter(Boolean).join(" ");
  }

  function inflectRussianNamePart(value, gender, role) {
    if (!value) return "";
    return String(value).split("-").map((part) => inflectRussianSimpleNamePart(part, gender, role)).join("-");
  }

  function inflectRussianSimpleNamePart(value, gender, role) {
    const lower = value.toLowerCase();
    const replaceEnding = (pattern, ending) => value.replace(pattern, ending);
    if (gender === "Женский") {
      if (role === "patronymic" && /(?:вна|ична)$/i.test(value)) return value.replace(/а$/i, "ы");
      if (role === "surname" && /(ская|цкая)$/i.test(value)) return replaceEnding(/ая$/i, "ой");
      if (role === "surname" && /яя$/i.test(value)) return replaceEnding(/яя$/i, "ей");
      if (role === "surname" && /ая$/i.test(value)) return replaceEnding(/ая$/i, "ой");
      if (role === "surname" && /(ова|ева|ёва|ина|ына)$/i.test(value)) return replaceEnding(/а$/i, "ой");
      if (role === "firstName" && /^любовь$/i.test(value)) return matchNameLetterCase(value, "Любови");
      if (role === "firstName" && /ь$/i.test(value)) return replaceEnding(/ь$/i, "и");
      if (/ия$/i.test(value)) return replaceEnding(/ия$/i, "ии");
      if (/я$/i.test(value)) return replaceEnding(/я$/i, "и");
      if (/а$/i.test(value)) return replaceEnding(/а$/i, /[гкхжчшщ]а$/i.test(lower) ? "и" : "ы");
      return value;
    }
    if (role === "patronymic" && /ич$/i.test(value)) return `${value}а`;
    if (role === "firstName") {
      const irregular = {
        павел: "Павла",
        лев: "Льва",
        пётр: "Петра",
        илья: "Ильи"
      }[lower];
      if (irregular) return matchNameLetterCase(value, irregular);
      if (/ия$/i.test(value)) return replaceEnding(/ия$/i, "ии");
      if (/я$/i.test(value)) return replaceEnding(/я$/i, "и");
      if (/а$/i.test(value)) return replaceEnding(/а$/i, /[гкхжчшщ]а$/i.test(lower) ? "и" : "ы");
    }
    if (/(ский|цкий)$/i.test(value)) return value.replace(/ий$/i, "ого");
    if (/(ый|ой)$/i.test(value)) return value.replace(/[ыо]й$/i, "ого");
    if (/ий$/i.test(value)) return value.replace(/ий$/i, "ия");
    if (/[йь]$/i.test(value)) return value.replace(/[йь]$/i, "я");
    if (/[бвгджзклмнпрстфхцчшщ]$/i.test(value)) return `${value}а`;
    return value;
  }

  function matchNameLetterCase(source, replacement) {
    const value = String(source || "");
    const result = String(replacement || "");
    if (value && value === value.toLocaleUpperCase("ru-RU")) return result.toLocaleUpperCase("ru-RU");
    if (value && value === value.toLocaleLowerCase("ru-RU")) return result.toLocaleLowerCase("ru-RU");
    return result;
  }

  function applyContractTemplateMarkers(template, fieldValues) {
    return String(template || "").replace(/#([^#]+)#/g, (match, fieldName) => (
      Object.prototype.hasOwnProperty.call(fieldValues, fieldName) ? String(fieldValues[fieldName] || "") : match
    ));
  }

  function ensureGeneratedDocumentFileName(value, format = "pdf") {
    const extension = normalizeDocumentGenerationFormat(format);
    const cleaned = String(value || "договор")
      .trim()
      .replace(/\.(?:pdf|docx)$/i, "")
      .replace(/[\\/:*?"<>|]+/g, "")
      .replace(/\s+/g, "_")
      .replace(/^[_\-.]+|[_\-.]+$/g, "") || "договор";
    return `${cleaned}.${extension}`;
  }

  function downloadBlob(fileName, blob) {
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = fileName;
    document.body.appendChild(link);
    link.click();
    link.remove();
    window.setTimeout(() => URL.revokeObjectURL(url), 1000);
  }
  function getStudentAddressInput(key) {
    return Array.from(document.querySelectorAll("[data-address-field]")).find((input) => input.dataset.addressField === key);
  }

  function copyStudentAddressToField(sourceKey, targetKey) {
    const source = getStudentAddressInput(sourceKey);
    const target = getStudentAddressInput(targetKey);
    if (!source || !target) return;
    const value = source.value.trim();
    if (!value) {
      alert("Заполните адрес для копирования.");
      source.focus();
      return;
    }
    target.value = source.value;
    target.dispatchEvent(new Event("input", { bubbles: true }));
    target.dispatchEvent(new Event("change", { bubbles: true }));
    target.focus({ preventScroll: true });
  }

  function copyStudentPassportToCustomer() {
    const record = (state.data.collections.students || []).find((item) => item.id === state.modal?.id) || {};
    const fieldPairs = [
      ["name", "customer"],
      ["birthDate", "customerBirthDate"],
      ["phone", "customerPhone"],
      ["snils", "customerSnils"],
      ["inn", "customerInn"],
      ["passportType", "customerPassportType"],
      ["passportNumber", "customerPassportNumber"],
      ["passportDate", "customerPassportDate"],
      ["passportIssuer", "customerPassportIssuer"],
      ["passportCode", "customerPassportCode"]
    ];
    let copied = 0;
    fieldPairs.forEach(([sourceKey, targetKey]) => {
      const source = document.querySelector(`[name="${sourceKey}"]`);
      const target = document.querySelector(`[name="${targetKey}"]`);
      if (!target) return;
      target.value = source?.value ?? state.modal?.draft?.[sourceKey] ?? record[sourceKey] ?? "";
      if (!target.matches("[data-combo-input]")) {
        target.dispatchEvent(new Event("input", { bubbles: true }));
      }
      target.dispatchEvent(new Event("change", { bubbles: true }));
      copied += 1;
    });
    if (!copied) return;
    closeComboPanels();
  }

  function copyStudentSurnameToDocument() {
    const target = document.querySelector("[name='educationDocumentSurname']");
    if (!target) return;
    const surname = splitFullName(collectStudentFormDraft().name).surname;
    if (!surname) {
      alert("Сначала укажите ФИО слушателя.");
      return;
    }
    target.value = surname;
    target.dispatchEvent(new Event("input", { bubbles: true }));
    target.dispatchEvent(new Event("change", { bubbles: true }));
    state.modal.draft = collectStudentFormDraft();
    state.modal.hasDraftChanges = true;
    target.focus({ preventScroll: true });
    target.select();
  }

  async function checkStudentAddressPostIndex(sourceKey) {
    const input = getStudentAddressInput(sourceKey);
    const address = input?.value.trim() || "";
    if (!address) {
      alert("Заполните адрес для проверки индекса.");
      input?.focus();
      return;
    }
    const query = `Индекс ${address}`;
    const searchUrl = getYandexPostalIndexSearchUrl(query);
    removePostalIndexPopup();
    const parsedIndex = await findPostalIndexInYandexSearch(query);
    if (!parsedIndex) {
      openYandexPostalIndexSearch(searchUrl);
      return;
    }
    showPostalIndexPopup(input, parsedIndex, query);
  }

  function showPostalIndexPopup(input, index, query) {
    const popup = document.createElement("div");
    popup.className = "postal-index-popup";
    popup.innerHTML = `
      <button data-action="apply-postal-index" type="button">
        <span>Вариант индекса</span>
        <strong>${escapeHtml(index)}</strong>
      </button>
      <button data-action="open-postal-index-search" type="button">
        <span>Найти в интернете...</span>
      </button>
    `;
    document.body.appendChild(popup);
    positionFloatingElement(popup, input);
    popup.querySelector("[data-action='apply-postal-index']")?.addEventListener("click", () => {
      input.value = applyPostalIndexToAddress(input.value, index);
      input.dispatchEvent(new Event("input", { bubbles: true }));
      input.dispatchEvent(new Event("change", { bubbles: true }));
      removePostalIndexPopup();
      input.focus({ preventScroll: true });
    });
    popup.querySelector("[data-action='open-postal-index-search']")?.addEventListener("click", () => {
      removePostalIndexPopup();
      openYandexPostalIndexSearch(getYandexPostalIndexSearchUrl(query));
    });
    setTimeout(() => {
      document.addEventListener("pointerdown", closePostalIndexPopupOnOutsideClick, { capture: true, once: true });
    });
  }

  function closePostalIndexPopupOnOutsideClick(event) {
    if (event.target.closest(".postal-index-popup")) {
      document.addEventListener("pointerdown", closePostalIndexPopupOnOutsideClick, { capture: true, once: true });
      return;
    }
    removePostalIndexPopup();
  }

  function removePostalIndexPopup() {
    document.querySelector(".postal-index-popup")?.remove();
  }

  async function findPostalIndexInYandexSearch(query) {
    try {
      const response = await fetch(photoApiUrl(`/api/postal-index?query=${encodeURIComponent(query)}`));
      if (!response.ok) return "";
      const result = await response.json();
      return normalizePostalIndex(result.index || "");
    } catch (error) {
      return "";
    }
  }

  function parsePostalIndexFromSearchHtml(html) {
    const text = String(html || "")
      .replace(/<script[\s\S]*?<\/script>/gi, " ")
      .replace(/<style[\s\S]*?<\/style>/gi, " ")
      .replace(/<[^>]+>/g, " ")
      .replace(/&nbsp;|&#160;/gi, " ")
      .replace(/\s+/g, " ");
    const candidates = [...text.matchAll(/\b\d{6}\b/g)]
      .map((match) => match[0])
      .filter((value) => !/^0{6}$/.test(value));
    return candidates[0] || "";
  }

  function getYandexPostalIndexSearchUrl(query) {
    return `https://yandex.ru/search/?text=${encodeURIComponent(query)}`;
  }

  function openYandexPostalIndexSearch(url, targetWindow = null) {
    if (targetWindow && !targetWindow.closed) {
      targetWindow.location.href = url;
      return;
    }
    openExternalUrl(url);
  }

  function positionFloatingElement(element, anchor) {
    const rect = anchor?.getBoundingClientRect?.();
    if (!rect) return;
    const width = Math.min(270, window.innerWidth - 16);
    element.style.width = `${width}px`;
    element.style.left = `${Math.max(8, Math.min(window.innerWidth - width - 8, rect.right - width))}px`;
    element.style.top = `${Math.max(8, Math.min(window.innerHeight - 110, rect.bottom + 6))}px`;
  }

  function getPostalIndexFromAddress(address) {
    return String(address || "").match(/\b\d{6}\b/)?.[0] || "";
  }

  function normalizePostalIndex(value) {
    const digits = String(value || "").replace(/\D/g, "");
    return digits.length === 6 ? digits : "";
  }

  function applyPostalIndexToAddress(address, index) {
    const value = String(address || "").trim();
    const normalizedIndex = normalizePostalIndex(index);
    if (!normalizedIndex) return value;
    if (!value) return normalizedIndex;
    if (/^\d{6}\b/.test(value)) return value.replace(/^\d{6}\b/, normalizedIndex);
    return `${normalizedIndex}, ${value}`;
  }

  async function openMaxMessenger(url, phoneForCopy) {
    try {
      const response = await fetch(photoApiUrl("/api/max/search"), {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ url, phone: phoneForCopy })
      });
      if (response.ok) return;
    } catch (error) {
      // Direct file mode or disabled local server: use the browser-level fallback below.
    }
    if (phoneForCopy) copyTextToClipboard(phoneForCopy);
    openExternalUrl(url);
  }

  function getMessengerCustomUrl(messenger, value) {
    const url = parseMessengerUrl(value);
    if (!url) return "";
    const host = url.hostname.replace(/^www\./i, "").toLowerCase();
    const protocol = url.protocol.toLowerCase();
    const href = url.href;
    if (messenger === "max" && (protocol === "max:" || host === "max.ru" || host === "web.max.ru")) return href;
    if (messenger === "telegram" && (protocol === "tg:" || ["t.me", "telegram.me", "telegram.dog"].includes(host))) return href;
    if (messenger === "whatsapp") return getWhatsAppAppUrl(url);
    return "";
  }

  function getWhatsAppAppUrl(url) {
    const host = url.hostname.replace(/^www\./i, "").toLowerCase();
    const protocol = url.protocol.toLowerCase();
    if (protocol === "whatsapp:") return url.href;
    if (!["wa.me", "whatsapp.com", "api.whatsapp.com", "web.whatsapp.com"].includes(host)) return "";
    const pathPhone = host === "wa.me" ? normalizeMessengerPhone(url.pathname.replace(/^\/+/, "").split("/")[0]) : "";
    const queryPhone = normalizeMessengerPhone(url.searchParams.get("phone") || "");
    const phone = queryPhone || pathPhone;
    const text = url.searchParams.get("text") || "";
    if (!phone) return "";
    const params = new URLSearchParams({ phone });
    if (text) params.set("text", text);
    return `whatsapp://send?${params.toString()}`;
  }

  function parseMessengerUrl(value) {
    const text = String(value || "").trim();
    if (!text) return null;
    try {
      const url = new URL(text);
      const protocol = url.protocol.toLowerCase();
      if (["http:", "https:", "tg:", "whatsapp:", "max:"].includes(protocol)) return url;
    } catch (error) {
      return null;
    }
    return null;
  }

  function normalizeExternalUrl(value) {
    const text = String(value || "").trim();
    if (!text || /^(?:да|нет|yes|no|true|false)$/i.test(text)) return "";
    const candidate = /^[a-z][a-z\d+.-]*:/i.test(text) ? text : `https://${text}`;
    try {
      const url = new URL(candidate);
      if (["http:", "https:"].includes(url.protocol.toLowerCase())) return url.href;
    } catch (error) {
      return "";
    }
    return "";
  }

  function getMessengerPhoneUrl(messenger, phone) {
    if (messenger === "max") return phone ? `max://search?phone=${encodeURIComponent(`+${phone}`)}` : "max://";
    if (messenger === "telegram") return phone ? `tg://resolve?phone=${encodeURIComponent(phone)}` : "";
    if (messenger === "whatsapp") return phone ? `whatsapp://send?phone=${encodeURIComponent(phone)}` : "";
    return "";
  }

  function openExternalUrl(url) {
    const link = document.createElement("a");
    link.href = url;
    link.target = "_blank";
    link.rel = "noreferrer";
    document.body.appendChild(link);
    link.click();
    link.remove();
  }

  function unique(values) {
    return Array.from(new Set(values));
  }

  function clamp(value, min, max) {
    return Math.min(max, Math.max(min, value));
  }

  function makeId(prefix) {
    return `${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 7)}`;
  }

  function getNextUid() {
    const values = Object.values(state.data.collections || {})
      .flat()
      .map((row) => Number(row?.uid))
      .filter((value) => Number.isFinite(value));
    return String((values.length ? Math.max(...values) : 0) + 1);
  }

  function ensureRecordUid(config, record = {}) {
    if (state.modal?.id) return record;
    const recordWithDefaults = {
      ...record,
      ...(config.collection === "students"
        ? { additionalStatus: record.additionalStatus || DEFAULT_STUDENT_ADDITIONAL_STATUS }
        : {}),
      ...(config.collection === "contracts"
        ? { section: normalizeContractSection(record.section, record.status) }
        : {}),
      ...(config.collection === "generalExpenses"
        ? { section: normalizeGeneralExpenseSection(record.section, record.counterparty) }
        : {})
    };
    if (!config.fields?.some((item) => item.key === "uid")) return recordWithDefaults;
    return {
      ...recordWithDefaults,
      uid: record.uid || getNextUid()
    };
  }

  function download(filename, content, type) {
    const blob = new Blob([content], { type });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = filename;
    link.click();
    URL.revokeObjectURL(url);
  }

  function csvCell(value) {
    return `"${String(value ?? "").replaceAll('"', '""')}"`;
  }

